double func(double l,double r,double v,double x){
  if(x<=l){
    return v+(l-x);
  }else if(l<x && x<r){
    return v;
  }else{
    return v+(x-r);
  }
}

double getv(double x){
  double ret = func(0,0,0,x);
  double tt = 0.0;
  for(int i=0;i<n;++i){
    ret = min(ret, func(tt,tt+t[i],v[i],x));
    tt += t[i];
  }
  ret = min(ret, func(tt,tt,0,x));
  return ret;
}

