ll ri(){ll l;cin>>l;return l;} string rs(){string s;cin>>s;return s;}

double solve() {
	int n = ri();
	vector<int> T(n);
	rep(i, n) T[i] = ri();
	vector<int> V(n);
	rep(i, n) V[i] = ri();

	rep(i, 1, n) T[i] += T[i-1];
	out(n, T, V);

	int LAS = T.back();
	int MAS = *max_element(all(V));

	out(T);
	out(V);

	vi LIM(LAS+1);
	{
		rep(i, T[0]) {
			LIM[i+1] = V[0];
		}
		rep(i, 1, n) {
			rep(t, T[i-1], T[i]) {
				LIM[t+1] = V[i];
			}
		}
	}
	out(LIM);

	vvd dp(LAS+1, vd(MAS+1, -1));
	dp[0][0] = 0;

	rep(i, LAS) {
		int lim0 = LIM[i];
		int lim = LIM[i+1];
		rep(j, lim0+1) if (dp[i][j] >= 0) {
			if (lim >= j) {
        		amax(dp[i+1][j], dp[i][j] + j);
			}
			if (lim >= j && j > 0 && lim0 >= j - 1) {
				amax(dp[i+1][j-1], dp[i][j] + (j+j-1)/2.0);
			}
			if (lim >= j + 1) {
				amax(dp[i+1][j+1], dp[i][j] + (j+j+1)/2.0);
				amax(dp[i+1][j],   dp[i][j] + j + 0.25);
			}
		}
	}
	double ans = dp[LAS][0];
	return ans;
}

void Main() {
	cout << fixed << setprecision(10);
	cout << solve() << endl;
}

