		if (t[i] < v[i] - b[i + 1]) {
			b[i] = b[i + 1] + t[i];
		} else {
			b[i] = v[i];
		}
	}
	for (int i = 0; i < n + 1; i++) {
		m[i] = min(a[i], b[i]);
	}
	double s = 0;
	for (int i = 0; i < n; i++) {
		int l = v[i] - m[i];
		int r = v[i] - m[i + 1];
		double ss = t[i] * v[i] - l * l / 2.0 - r * r / 2.0;
		if (l + r > t[i]) {
			int d = l + r - t[i];
			ss += d * d / 4.0;
		}
		s += ss;
	}
	cout << fixed << setprecision(4) << s << endl;
	return 0;
}

