  vi T(1, 0);
  int T_sum = 0;
  REP(i, N) {
    SS(int, t);
    T.PB(t);
    T_sum += t;
  }

  SV(int,V,N);

  vector< tuple<int, int, int> > conditions;
  conditions.PB(MT(    0,     0, 0));
  conditions.PB(MT(T_sum, T_sum, 0));

  REP(i, N) T[i + 1] += T[i];
  REP(i, N) conditions.PB(MT(T[i], T[i + 1], V[i]));

  ld res = 0.0;
  double speed = 0.0;
  for (double time = 0.5; time <= T_sum; time += 0.5) {
    double next_speed[3] = {max(0.0, speed - 0.5), speed, speed + 0.5};
    bool flag[3] = {true, true, true};
    EACH(t, conditions) {
      int l, r, limit;
      tie(l, r, limit) = t;
      // debug(l,r,limit);
      if (0 <= time && time <= l) {
        REP(i, 3) {
          if (limit + (l - time) < next_speed[i]) flag[i] = false;
        }
      } else if (l <= time && time <= r) {
        REP(i, 3) {
          if (limit < next_speed[i]) flag[i] = false;
        }
      } else if (r <= time && time <= T_sum) {
        REP(i, 3) {
          if (limit + (time - r) < next_speed[i]) flag[i] = false;
        }
      }
    }
    double next = 0.0;
