        cin >> t[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> v[i];
    }
    int slim[N + 1], elim[N + 1];
    slim[0] = 0;
    elim[N] = 0;
    for (int i = 0; i < N; i++) {
        slim[i + 1] = min(slim[i] + t[i], v[i]);
