    for(int i = 0; i < N; ++i) {
        double vnow = v[i], vnext = v[i + 1];
        double tnow = t[i];
        if(vnow > vnext) {
            if(vnow * 2.0 - v0 - vnext > tnow) {
                double v_prime_d = (v0 + vnext + tnow) / 2.0;
                ans += (v_prime_d + v0)*(v_prime_d - v0)/2.0 + (vnext + v_prime_d)*(tnow - v_prime_d+v0)/2.0;
                if(v_prime_d < vnext)
                    v0 = v_prime_d;
                else
                    v0 = vnext;
            }else {
                ans += (v0 + vnow)*(vnow - v0)/2.0 + (vnext + vnow)*(vnow - vnext)/2.0 + vnow*(tnow - 2.0*vnow +(v0 + vnext));
                v0 = vnext;
            }
        }else if(vnow <= vnext) {
            if(vnow - v0 >= tnow){
                ans += (v0 + v0 + tnow) * tnow / 2.0;
                v0 = v0 + tnow;
            }else {
                ans += (v0 + vnow)*(vnow - v0)/2.0 + (tnow - (vnow - v0))*vnow;
                v0 = vnow;
            }
        }
    }
    printf("%.12f\n", ans);
