  vector<double> speed(N);
  cin >> time.at(0);
  if ( N != 1 ) {
    for(int i = 1 ; i < N ; i++) { 
      int x = 0;
      cin >> x ; 
      time.at(i) = time.at(i-1) + x;
    }  
  }

  for(int i = 0; i < N ; i++) { 
    cin >> speed.at(i); 
  } 
  int p = time.at(N-1)*2;  
  vector<double> limit(p); 
  vector<double> resp(p); 

  for(int i = 0; i < p ; i++) {
    limit.at(i) = 100;
    double ihalf = i * 0.5;
    for(int j = 0; j < N ; j++) {
      if ( ihalf > time.at(j) - 0.005 ) { 
        continue; 
      }

      double lim;
      if ( j == 0 ) {
        limit.at(i) = speed.at(j);
      }
      if ( j != 0 ) {
        if ( ihalf > time.at(j-1) - 0.005 ) {
          lim = speed.at(j);
        }
        else {
          lim = speed.at(j) + time.at(j-1) - ihalf - 0.5 ;
        }
        if ( lim < limit.at(i) - 0.005 ) {
          limit.at(i) = lim;
        }
      }
      if ( j == N - 1 ) {
        lim = time.at(j) - ihalf - 0.5;
        if ( lim < limit.at(i) - 0.005 ) {
          limit.at(i) = lim;
        }
      }
    }
  }

  double v = 0;
