    if ( v + 0.495 <= limit.at(i) ) {
      v += 0.5;
    }
    else if ( v >= limit.at(i) + 0.495 ) {
      v -= 0.5;
    }
    resp.at(i) = v;
  }

  double range2 = 0;
  for(int i = 0; i < p ; i++) {
    range2 += resp.at(i);
  }
  cout << range2 * 0.5 << endl;
}

