	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	ll n; cin >> n;
	vll t(n), v(n);
	cin >> t >> v;
	rep(i, 0, n) {
		t[i] *= 2;
		v[i] *= 2;
	}
	ll T = accumulate(all(t), 0LL);

	auto getH = [&](vll t) {
		vll Tacc(n, INF);
		rep(i, 0, n) {
			Tacc[i] = (i > 0 ? Tacc[i - 1] : 0) + t[i];
		}
		vll height(T + 1, INF);

		ll last_t = 0;
		height[0] = 0;
		height[T] = 0;
		rep(tt, 1, T) {
			chmin(height[tt],min(height[tt-1]+1, v[last_t]));
			if (tt == Tacc[last_t]) {
				last_t++;
				chmin(height[tt], last_t<v.size()? v[last_t]:INF);
			}
		}
		return height;
	};
	auto hei0 = getH(t);
	reverse(all(t));
	reverse(all(v));
	auto hei1 = getH(t);
	reverse(all(hei1));


	double res = 0;

	rep(tt, 0, T) {
		ll h0 = min(hei0[tt], hei1[tt]);
		ll h1 = min(hei0[tt+1], hei1[tt+1]);
		res += (h0 + h1) / 2.;
	}

	cout << res / 4. << endl;
	return 0;
}

