    }
    for(int i = 2; i <= t_sum; i++){
        for(int j = 0; j <= 100; j++){
            double l1, l2, l3;
            if(j > 0 && dp[i-1][j-1] > 0.0001){
                l1 = dp[i-1][j-1] + (double)(2*j-1)/(double)2;
            }else{
                l1 = 0;
            }
            if(dp[i-1][j+1] > 0.0001 && j+1 <= 100){
                l3 = dp[i-1][j+1] + (double)(2*j+1)/(double)2;
            }else{
                l3 = 0;
