int n,t[110],v[110];
int main(){
    cin >> n;
    for(int i=0;i<n;i++) cin >> t[i];
    for(int i=0;i<n;i++) cin >> v[i];
    int sum = 0;
    for(int i=0;i<n;i++){
        sum += t[i];
        v[i] = min(v[i],sum);
    }
    sum = 0;
    for(int i=n-1;i>=0;i--){
        sum += t[i];
        v[i] = min(v[i],sum);
    }
    v[n] = 0;
    double ans = 0;
    int before = 0;
    for(int i=0;i<n;i++){
        if(v[i+1]<=before){
            int tmp = (v[i]-before)+abs(v[i+1]-v[i]);
            if(tmp<=t[i]){
                ans += ((double)v[i]+before)*((double)v[i]-before)*0.5;
                ans += ((double)t[i]-tmp)*v[i];
                ans += abs((double)v[i+1]+v[i])*abs(v[i+1]-v[i])*0.5;
            }
            else {
                double x = ((double)t[i]+v[i+1]-before)*0.5;
                if(x>=0){
                    ans += ((double)before*2+x)*x*0.5;
                    ans += ((double)before+x+v[i+1])*(t[i]-x)*0.5;
                }
                else {
                    ans += ((double)before+v[i+1])*t[i]*0.5;
                }
            }
            before = v[i+1];
        }
        else {
            int tmp = (v[i]-before);
            if(tmp<=t[i]){
                ans += ((double)v[i]+before)*tmp*0.5;
                ans += (double)v[i]*(t[i]-tmp);
                before = v[i];
            }
            else {
                ans += ((double)before*2+t[i])*t[i]*0.5;
                before = before+t[i];
            }
        }
    }
    printf("%.9f\n",ans);
    return 0;
}

