/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vpl tv;
vl u;

void solve(){
    tv = vpl(n);
    rep(i, n) in1(tv[i].e1);
    rep(i, n) in1(tv[i].e2);

    tv[0].e2 = min(tv[0].e2, tv[0].e1);
    For(i, 1, n){
        ll t, v_pre, v_post;
        t = tv[i].e1; v_pre = tv[i - 1].e2; v_post = tv[i].e2;
        if (v_post - v_pre > t) tv[i].e2 = v_pre + t;
        else if (v_pre - v_post > t) tv[i - 1].e2 = v_post + t;
    }

    u = vl(n + 1);
    u[n] = 0; u[0] = 0;
    For(i, 1, n){
        ll t = tv[i - 1].e1;
        ll vo = tv[i - 1].e2; ll vd = tv[i].e2;
        u[i] = min(u[i - 1] + t, min(vo, vd));
    }

    ld ans = 0;
    rep(i, n){
        ll vo = u[i]; ll vd = u[i + 1];
        ll dv = abs(vd - vo);
        ll t = tv[i].e1;
        ans += ld(dv * dv) * 0.5;
        ans += ld(dv * min(vd, vo));
        ans += ld(t - dv) * max(vo, vd);
        if (max(vo, vd) < tv[i].e2 && t - dv > 0){
            ll res_t = t - dv;
            ll res_v2 = (tv[i].e2 - max(vo, vd)) * 2;
            if (res_t >= res_v2){
                ans += 0.25 * ld(res_v2 * res_v2);
                ans += ld((res_t - res_v2) * res_v2) * 0.5;
            }else ans += 0.25 * ld(res_t * res_t);
        }
    }

    prl_nd(ans, 10);
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();

    return 0;
}

