int main(){
    int N;
    cin >> N;
    double t[N + 2];// t[0] と t[N + 1] はダミー
    double v[N + 2];
    for(int i = 0; i < N; i++){
        cin >> t[i + 1];
    }
    for(int i = 0; i < N; i++){
        cin >> v[i + 1];
    }
    v[0] = 0;
    v[N + 1] = 0;
    double ans = 0;
    for(int i = 1; i <= N; i++){
        if(v[i] > v[i - 1] && v[i] > v[i + 1]){
            double extreme;
            if(v[i] * 2 - v[i - 1] - v[i + 1] >= t[i]){
                extreme = v[i];
            }else{
                extreme = (t[i] + v[i - 1] + v[i + 1]) / 2;
            }       
            ans += extreme * t[i] - pow(extreme - v[i - 1], 2) / 2 - pow(extreme - v[i + 1], 2) / 2;
            v[i] = v[i + 1];
        }else if(v[i] > v[i - 1] && v[i] <= v[i + 1]){
            if(v[i + 1] - v[i - 1] > t[i]){
                ans += v[i - 1] * t[i] + pow(t[i], 2) / 2;
                v[i] += t[i];
            }else{
                ans += v[i] * t[i] - pow(v[i] - v[i - 1], 2) / 2;
            }
        }else if(v[i] <= v[i - 1] && v[i] > v[i + 1]){
            ans += v[i] * t[i] - pow(v[i] - v[i + 1], 2) / 2;
            v[i] = v[i + 1];
        }else{
            ans += v[i] * t[i];
        }
        cout << i << " " << ans << endl;
    }
    cout << setprecision(12) << ans << endl;
}

