std::int64_t gcd(std::int64_t x, std::int64_t y) {
   if (x == 0 || y == 0) return 0;
   std::int64_t r;
   while ((r = x % y) != 0) {
      x = y;
      y = r;
   }
   return y;
}

std::int64_t lcm(std::int64_t x, std::int64_t y) {
   if (x == 0 || y == 0) return 0;
   return (x / gcd(x, y) * y);
}

std::int64_t mod(std::int64_t a, std::int64_t m) {
   return (a % m + m) % m;
}

