std::vector<bool> prime_table(int n) {
   if (n <= 1) return std::vector<bool>();
   std::vector<bool> prime(n + 1, true);
   prime[0] = prime[1] = false;
   for (int i = 2; i * i <= n; ++i) {
      if (!prime[i]) continue;
      for (int j = i + i; j <= n; j += i) {
         prime[j] = false;
      }
   }
   return prime;
}

// 素因数分解
template <typename T>
std::map<T, int> prime_factor(T n) {
   std::map<T, int> ret;
   for (T i = 2; i * i <= n; ++i) {
      while (n % i == 0) {
         ret[i]++;
         n /= i;
      }
   }
   if (n != 1) ret[n] = 1;
   return ret;
}

