   v.emplace_back(0);

   //for (int i = 1; i < N; ++i) t[i] += t[i - 1];

   double T = 0, V = 0;
   double ans = 0;
   for (int i = 0; i < N; ++i) {
      double mv = 0, cv = 0;
      if (v[i] - V > t[i]) cv = V + t[i];
      else cv = v[i];

      if (v[i + 1] < cv) {
         mv = (t[i] + V + v[i + 1]) / 2.0;
         if (mv > v[i]) mv = v[i];
         ans += (V + mv) * (mv - V) / 2.0;
         ans += (mv + v[i + 1]) * (mv - v[i + 1]) / 2.0;
         double rest = t[i] - (mv - V + mv - v[i + 1]);
         ans += mv * rest;
         V = v[i + 1];
      }
      else {
         ans += (V + cv) * (cv - V) / 2;
         double rest = t[i] - (cv - V);
         ans += cv * rest;
         V = cv;
      }
   }

   cout << fixed << ans << endl;
