signed main() {
  int n;
  cin >> n;

  vector<double> t(n + 1, 0), v(n + 1, 0);
  for (int i = 1; i <= n; ++i) {
    cin >> t[i];
    t[i] += t[i - 1];
  }
  for (int i = 1; i <= n; ++i) {
    cin >> v[i];
  }
  v.pb(0.0);

  double ans = 0;
  double s = 0.0;
  for (int i = 1; i <= n; ++i) {
    if (v[i] > v[i + 1]) {
      double d = v[i] - s;
      double b = v[i] - v[i + 1];

      if (t[i - 1] + d > t[i] - b) {
        // puts("1");
        double m = (t[i - 1] + d + t[i] - b) / 2.0;
        ans += (m - t[i - 1]) * s + (m - t[i - 1]) * (m - t[i - 1]) / 2.0;
        ans += (t[i] - m) * (t[i] - m) / 2.0 + (t[i] - m) * v[i + 1];
        s = v[i + 1];
      } else {
        // puts("2");
        ans += s * d + d * d / 2.0 + (t[i] - b - (t[i - 1] + d)) * v[i] + v[i + 1] * b + b * b / 2.0;
        s = v[i + 1];
      }
    } else {
      double b = t[i] - t[i - 1];
      double d = v[i] - s;
      if (d + eps > b) {
        // puts("3");
        ans += b * s + b * b / 2.0;
        s += b;
      } else {
        // puts("4");
        ans += s * d + d * d / 2.0 + (b - d) * v[i];
        s = v[i];
      }
    }
  }

  printf("%.10lf\n", ans);
}

