//const int MAX_N=2*100*200+1;
const int SIZE=1e6+10;
int t[SIZE],v[SIZE],a[SIZE],m;
int N;
const int MOD = 1e9+7;
void solve() {
  REP(i,SIZE) a[i]=MOD;
  int it=0;
  a[0]=0;
  REP(i,N) {
    mii(a[it],v[i]);
    REP(j,t[i]) it++,mii(a[it],v[i]);
//    cout<<i<<","<<t<<endl;
  }
  mii(a[it],0);
  int T=it;
  REPP(i,1,T+1) {
//    if(i==140)cout<<a[i]<<","<<a[i-1]+1<<endl;
    mii(a[i],a[i-1]+1);
  }
  for(int i=T-1; i>=0; --i) {
//    if(i==140)cout<<a[i]<<","<<a[i+1]+1<<endl;
    mii(a[i],a[i+1]+1);
  }
//  cout<<T<<endl;
//  REPE(i,T) cout<<i<<","<<a[i]<<endl;
  LL res=0;
  //REP(i,T) res+=(a[i]+a[i+1])*0.5;
  REP(i,T) res+=(a[i]+a[i+1]);
  double ans=res*0.125;
  cout<<ans<<endl;
}

