signed main() {
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		int tim;
		cin >> tim;
		t.push_back(tim);
	}

	tsum.push_back(t[0]);
	for (int i = 1; i < N; i++) {
		tsum.push_back(tsum[i - 1] + t[i]);
	}

	for (int i = 0; i < N; i++) {
		int vel;
		cin >> vel;
		v.push_back(vel);
	}
	//最初は0
	for (int i = 1; i <= tsum.back()*2; i++) {
		velocity[i] = i * 0.5;
	}
	//最後も0
	for (int i = tsum.back()*2; i > 0; i--) {
		velocity[i] = min((tsum.back()*2 - i)*0.5, velocity[i]);
	}

	for (int i = 0; i < (int)tsum.size();i++) {
		int l, r;
		if(i == 0){
			l = 0;
		}
		else {
			l = tsum[i - 1];
		}
		r = tsum[i];
		l *= 2;
		r *= 2;
		double velo = v[i];
		for (int j = 0; j < tsum.back() * 2; j++) {
			double nowVel;
			if (j <= l) {
				nowVel = velo + (l - j)*0.5;
			}
			else if (l <= j && j <= r) {
				nowVel = velo;
			}
			else {
				nowVel = velo + (j - r)*0.5;
			}
			velocity[j] = min(nowVel, velocity[j]);
		}
	}

	double ans = 0.0;
	for (int i = 0; i < tsum.back() * 2 + 2; i++) {
		ans += (velocity[i] + velocity[i + 1]) * 0.5 / 2.0;
	}

	cout << fixed << setprecision(1000000) << ans << "\n";

	return 0;
}

