  for (int64_t i = 1; i < n; i++) {
    t_e[i] = t_e[i - 1] + t[i];
  }
  const auto t_max = std::accumulate(t.cbegin(), t.cend(), 0);
  auto speed = [&] (auto time) {
    double ans = std::min(time, t_max - time);
    for (int j = 0; j < n; j++) {
      if (time < t_b[j]) {
        ans = std::min(ans, t_b[j] - time + v[j]);
      } else if (t_b[j] <= time && time <= t_e[j]) {
        ans = std::min<double>(ans, v[j]);
      } else {
        ans = std::min(ans, time - t_e[j] + v[j]);
      }
    }
    return std::max(ans, 0.0);
  };

  double l = 0;
  for (double i = 0; i < t_max; i += 0.5) {
    l += 0.25 * (speed(i) + speed(i + 0.5));
  }
  std::cout << l << std::endl;
  return 0;
}

