            ans += (vel + max_vel) * (max_time - time) / 2.0;
            ans += (v[i+1] + max_vel) * (time + t[i] - max_time) / 2.0;
            vel = v[i+1];
        }

        time += t[i];
    }
    cout << ans << endl;
}

