      for(Int i = 1; i <= n; ++i) {
         // update
         // if( vs[i-1] < vs[i] and vs[i] < vs[i+1] ) {
         if( vs[i] - vs[i-1] > ts[i] ) {
            vs[i] = vs[i-1] + ts[i];
         }
         // }
         // calc
         Int t1 = std::max((Int)0, vs[i]-vs[i-1]);
         Int t2 = ts[i] - std::max((Int)0, vs[i]-vs[i+1]);
         if( t1 <= t2 ) {
            // dumpl((Int)1);
            res += g(vs[i-1], vs[i], t1);
            res += g(vs[i], vs[i+1], ts[i]-t2);
            res += (t2 - t1) * vs[i];
         }
         else {
            // dumpl((Int)2);
            double th = std::max((double)0, std::min((t1 + t2) / 2.0, (double)ts[i]));;
            res += g(vs[i-1], th+vs[i-1], th);
            res += g(th+vs[i-1], vs[i+1], ts[i]-th);
         }
         // printf("%ld : %.20lf\n", i, res);
      }
      printf("%.20lf\n", res);
   }
};

