                dst += v * (b[i] - v) + 1.0 * (b[i] - v) * (b[i] - v) / 2;
                dst += b[i] * (b[i] - nv) - 1.0 * (b[i] - nv) * (b[i] - nv) / 2;
                dst += b[i] * (a[i] - b[i] + v - b[i] + nv);
            }
            else {
                long double speed = (1.0 * a[i] + v + nv) / 2;
                long double t1 = (speed - v);
                long double t2 = (speed - nv);
                dst += v * t1 + t1 * t1 / 2;
                dst += speed * t2 - t2 * t2 / 2;
            }
            f[i + 1][nv] = max(f[i + 1][nv], f[i][v] + dst);
        }
    }
    cout.precision(10);
    cout << fixed << f[n + 1][0] << "\n";
    return 0;
}

