		for(double j=0;j<T;j+=0.5){
			if(j<tsum-t[i]){
				f[i][(int)(j*2)]=v[i]+(tsum-t[i])-j;
			}else if(tsum-t[i]<=j && j<=tsum){
				f[i][(int)(j*2)]=v[i];
			}else{
				f[i][(int)(j*2)]=v[i]+j-tsum;
			}
		}
	}
	double sum=0;
	for(double j=0;j<T;j+=0.5){
		double min_v=1000000000;
		for(int i=0;i<n+2;i++){
			min_v=min(f[i][(int)(j*2)],min_v);
		}
		sum+=min_v*0.5;
	}
	printf("%.4f\n",sum);
	return 0;
}

