{
	//freopen("in.txt", "r", stdin);
	int i;
	scanf("%d", &N);
	for(i=0; i<N; i++)
		scanf("%d", &t[i]);
	for(i=0; i<N; i++)
		scanf("%d", &v[i]);
	solve();
	return 0;
}

