      }
      else{
	if(z<=w){//頭打ちにならず三角形になる場合
	  v0[i]=vmax[i];
	  res+=min(v0[i-1],v0[i])*x+z*z-y*y/2;
	}
	else{//頭打ちになって台形になる場合
	  v0[i]=vmax[i];
	  res+=min(v0[i-1],v0[i])*x+z*z-y*y/2-(z-w)*(z-w);
	}
      }
    }
  }
  return res;
}
