        t[i] = t[i - 1] + tt;
    }
    for (int i = 1; i <= n; i++)
        cin >> v[i];
    vector<line> lines;
    line l;
    for (int i = 1; i <= n; i++) {
        l.start = t[i - 1];
        l.end = t[i];
        l.velocity = v[i];
        lines.push_back(l);
    }
    l.start=0;
    l.end=0;
    l.velocity=0;
    lines.push_back(l);
    l.start=t[n];
    l.end=t[n]+1;
    l.velocity=0;
    lines.push_back(l);
    double res = 0;
