constexpr f80 DT = 1e-04;

i64 N;
vector<f80> T;
vector<f80> V;

void solve() {
    vector<f80> vls(N);
    vls[0] = 0;
    for(i64 i = 1; i < N; ++i) {
        vls[i] = min({
            vls[i-1] + T[i-1],
            V[i-1],
            V[i],
        });
    }

    vector<f80> vrs(N);
    vrs[N-1] = 0;
    for(i64 i = N-2; i >= 0; --i) {
        vrs[i] = min({
            vrs[i+1] + T[i+1],
            V[i+1],
            V[i],
        });
    }

    f80 ans = 0;
    for(i64 i = N-1; i >= 0; --i) {
        f80 v  = V[i];
        f80 vl = vls[i];
        f80 vr = vrs[i];

        f80 cur = 0;
        for(f80 t = 0; t < T[i]; t += DT) {
            f80 w = min({
                v,
                vl + t,
                vr + (T[i]-t),
            });
            cur += w * DT;
        }
        ans += cur;
    }

    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {
    RD(N);
    RD(T, N);
    RD(V, N);

    solve();

    EXIT();
}

