const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 110
#define MAX_T 40010
#define MAX_V 110

ll N;
ll T[MAX_N] = {};
ll V[MAX_N] = {};
ll Limit[MAX_T] = {};   // i 秒での限界速度
ll EndTime = 0;
double dp[MAX_T][MAX_V];

// i 秒時点で、現在の速度が j m/s のときの最大値
double dfs(int i = 0, int j = 0) {
    if(EndTime <= i) {
        if(j != 0) { dp[i][j] = -DINF; }
        else { dp[i][j] = 0; }
        return dp[i][j];
    }

    double& res = dp[i][j];
    if(res != DINF) { return res; }
    res = -DINF;

    if(j > Limit[i]) {
        // 条件違反
        return res;
    }
    if(j < Limit[i]) {
        // 速度を上げる
        double dist = static_cast<double>(j) + 0.5;
        res = max(res, dfs(i+1, j+1) + dist);
        // 速度を上げて戻す
        dist = static_cast<double>(j) + 0.25;
        res = max(res, dfs(i+1, j) + dist);
    }
    if(j > 0) {
        // 速度を下げる
        double dist = static_cast<double>(j-1) + 0.5;
        res = max(res, dfs(i+1, j-1) + dist);
    }
    // 速度維持
    res = max(res, dfs(i+1, j) + static_cast<double>(j));
    return res;
}

