	for(int i=0;i<N;i++) cin >> V[i];

	vector<int> H(N+1);
	int Inf = (int) 1e9;
	for(int i=1;i<N;i++) H[i] = Inf;
	for(int i=0;i<N;i++){
		H[i] = min(H[i], V[i]);
		H[i+1] = min(H[i+1], H[i] + T[i]);
		H[i+1] = min(H[i+1], V[i]);
	}
