int main() {
    int N;
    cin >> N;
    vector<int> T(N+1);
    vector<int> V(N+1);
    for (int i = 0; i < N; i++) {
        cin >> T[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> V[i];
    }

    dp[0][0] = 1;
    for (int i = 0; i < N; i++) {
        for (int cur = 0; cur < 105; cur++) {
            if (dp[i][cur] && cur <= V[i]) {
                for (int dst = 0; dst < 105; dst++) {
                    if (dst <= V[i]) {
                        int a = V[i] - cur;
                        int b = V[i] - dst;

                        if (a + b <= T[i]) {
                            double up = 1.0 * (cur + V[i]) * a / 2;
                            double mx = V[i] * (T[i] - a - b);
                            double down = 1.0 * (dst + V[i]) * b / 2;
                            dp[i+1][dst] = max(dp[i+1][dst], dp[i][cur] + up + mx + down);
                        } else if (T[i] < abs(dst - cur)) {
                            // do nothing (うごけない)
                        } else {
                            double t2acc = 1.0 * (dst - cur + T[i]) / 2;
                            double t2deacc = 1.0 * (T[i] - dst + cur) / 2;
                            double vmax = cur + t2acc;

                            double xup = 1.0 * (cur + vmax) * t2acc / 2;
                            double xdown = 1.0 * (dst + vmax) * t2deacc / 2;

                            dp[i+1][dst] = max(dp[i+1][dst], dp[i][cur] + xup + xdown);
                        }
                    }
                }
            }
        }
    }

    cout << fixed << setprecision(10) << dp[N][0] - 1 << endl;

    return 0;
}

