  vi t(N), v(N);
  for (ll i = 0; i < N; i++) {
    cin >> t[i];
  }
  for (ll i = 0; i < N; i++) {
    cin >> v[i];
  }

  vector<vector<double>> dp(N, vector<double>(101, -(double)INF));
  for (ll j = 0; j <= v[0]; j++) {
    if (N >= 2 && j > v[1]) {
      continue;
    }
    double x = (double)(j + t[0]) / 2;
    if (x < -EPS || x - EPS > t[0]) {
      continue;
    }
    if (x > v[0]) {
      dp[0][j] = max(dp[0][j], (double)t[0] * v[0] - (double)v[0] * v[0] / 2 - (double)(v[0] - j) * (v[0] - j) / 2);
    } else {
      dp[0][j] = max(dp[0][j], (double)x * x / 2 + (double)(t[0] - x) * (x + j) / 2);
    }
  }

  for (ll i = 1; i < N; i++) {
    for (ll k = 0; k <= min(v[i - 1], v[i]); k++) {
      for (ll j = 0; j <= v[i]; j++) {
        if (i < N - 1 && j > v[i + 1]) {
          continue;
        }
        double x = (double)(j - k + t[i]) / 2;
        if (x < -EPS || x - EPS > t[i]) {
          continue;
        }
        if ((double)k + x > v[i]) {
          dp[i][j] = max(dp[i][j], dp[i - 1][k] + t[i] * v[i] - (double)(v[i] - k) * (v[i] - k) / 2 - (double)(v[i] - j) * (v[i] - j) / 2);
        } else {
          dp[i][j] = max(dp[i][j], dp[i - 1][k] + (double)(x + k + k) * x / 2 + (double)(x + j + k) * ((double)t[i] - x) / 2);
        }
      }
    }
  }

  cout << fixed;
  cout << dp[N - 1][0] << endl;
}

