	rep2(i, 1, ri) {

		ll hi = 401;
		ll lo = 0;
		while(lo + 1 < hi)
		{
			ll j = (hi + lo) / 2;
			bool ok = true;
			ll p = 0;
			rep(k, n * 2 + 2) {
				if (p <= i && i <= p + t[k]) {
					if (v[k] < j) {
						p += t[k];
						ok = false;
						break;
					}
				}
				auto hi = j - abs(i - p);
				if (v[k] < hi) {
					p += t[k];
					ok = false;
					break;
				}
				hi = j - abs(i - (p+t[k]));
				if (v[k] < hi) {
					p += t[k];
					ok = false;
					break;
				}
				p += t[k];
			}
			if (ok) {
				lo = j;
			}
			else {
				hi = j;
			}
		}
		li[i] = lo;
	}

	double res = 0;
