signed main() {
    int N;
    cin >> N;
    vector<double> t(N), v(N);
    cin >> t >> v;
    t.push_back(0);
    v.push_back(0);
    auto calc = [](double v0, double t, double a) {
        return v0 * t + 0.5 * a * t * t;
    };
    auto middleCalc = [](double startHeight, double endHeight, double time) {
        double left = 0, right = time;
        while (right - left > 1e-8) {
            double mid = left + (right - left) / 2;
            double midHeight = startHeight + mid;
            if (midHeight - (time - mid) < endHeight) left = mid;
            else right = mid;
        }
        return right;
    };
    double ans = 0, before = 0;
    for (int i = 0; i < N; i++) {
        double difLeft = abs(before - v[i]);
        double difRight = abs(v[i] - v[i + 1]);
        double mid = middleCalc(before, v[i + 1], t[i]);
        if (before + mid > v[i]) {
            ans += calc(before, difLeft, 1);
            if (v[i] <= v[i + 1]) {
                ans += v[i] * (t[i] - difLeft);
                before = v[i];
            } else {
                ans += v[i] * (t[i] - difLeft - difRight);
                ans += calc(v[i], difRight, -1);
                before = v[i + 1];
            }
        } else {
            ans += calc(before, mid, 1);
            ans += calc(before + mid, abs(t[i] - mid), -1);
            before = v[i + 1];
        }
    }
    cout << fixed << setprecision(10) << ans << endl;
}

