        FOR(j,0,i-1) {
            chmax(now,v[j]+segt.query(j+1,i+1));
        }
        FOR(j,i+1,n+1) {
            chmax(now,v[j]+segt.query(i,j+1));
        }
        chmin(v[i],now);
    }

