        else if(v[i-1]>=v[i] && v[i]>=v[i+1]) {
            ans+=v[i]*t[i]-pow((v[i]-v[i+1]),2)/2;
        }
        else if(v[i-1]<v[i] && v[i]>v[i+1]) {
            double d=v[i+1]-v[i-1];
            ans+=t[i]*(v[i-1]+t[i]/2+d/2)-(pow(t[i]/2+d/2,2)+pow(t[i]/2-d/2,2))/2-pow(max(0.0,v[i-1]+t[i]/2+d/2-v[i]),2);
        }
        else {
