int main() {
  cout.setf(ios::fixed);
  cout.precision(9);
  int n;
  cin >> n;
  vector<int> t(n + 1);
  vector<int> v(n + 1);
  vector<int> starts(n + 1);
  copy_n(istream_iterator<int>(cin), n, t.begin());
  copy_n(istream_iterator<int>(cin), n, v.begin());
  t[n] = 1;
  v[n] = 0;
  vector<Line> lines;
  lines.push_back(Line{1, 0, 0});
  if(t[0] > v[0]){
    lines.push_back(Line{0, v[0], double(v[0])});
  }
  for(int i = 1; i <= n; ++i){
    starts[i] = starts[i - 1] + t[i - 1];
    while(lines.back().at(starts[i]) > v[i]){
      if(lines.back().k == -1){
        lines.pop_back();
      }else if(lines.back().k == 0){
        int pos = starts[i] + v[i] - lines.back().b;
        if(pos <= lines.back().start){
          lines.pop_back();
        }else{
          lines.push_back(Line{-1, starts[i] + v[i], double(pos)});
        }
      }else{
        double pos = (starts[i] + v[i] - lines.back().b) / 2.;
        if(pos <= lines.back().start){
          lines.pop_back();
        }else{
          lines.push_back(Line{-1, starts[i] + v[i], double(pos)});
        }
      }
    }
    if(lines.back().k == 0){
      lines.push_back(Line{1, v[i - 1] - starts[i], double(starts[i])});
    }
    if(lines.back().k == -1){
      lines.push_back(Line{0, v[i], double(starts[i])});
    }else if(lines.back().k == 1){
      if(lines.back().at(starts[i] + t[i]) > v[i]){
        lines.push_back(Line{0, v[i], double(starts[i] + v[i] - lines.back().at(starts[i]))});
      }
    }
  }
  double result = 0;
  for(size_t i = 0; i + 1 < lines.size(); ++i){
    double l = lines[i].start;
    double r = lines[i + 1].start;
    result += lines[i].k * (r * r - l * l) * 0.5 + lines[i].b * (r - l);
  }
  cout << result << endl;
}

