    Point cross_point = calc_cross_point(plus, minus);

    double area = 0.0;
    if(cross_point.second > v[i + 1])
    {
      //台形になる
      Point top_left = calc_cross_point(plus, v[i + 1]);
      Point top_right = calc_cross_point(minus, v[i + 1]);
      area = integral(plus, t[i], top_left.first);
