typedef long long ll;
int const inf = 1<<29;

int N;

struct F {
  double t1, t2, a, b;
};
vector<F> funcs;

double calc_b(double a, double y1, double x1) {
  // y1 = a * x1 + b;
  return y1 - a * x1;
}

void make_f_set(vector<double> const& ts, vector<double> const& vs) {
  rep(i, N) {
    if (i) {
      auto b = calc_b(-1, vs[i], ts[i - 1]);
      funcs.push_back(F{0, ts[i - 1], -1, b});
    }
    if (i < N - 1) {
      auto b = calc_b(+1, vs[i], ts[i]);
      funcs.push_back(F{ts[i], ts.back(), +1, b});
    }
    {
      auto b = vs[i];
      funcs.push_back(F{i ? ts[i - 1] : 0, ts[i], 0, b});
    }
  }
  funcs.push_back(F{0, ts[0], +1, 0});
  funcs.push_back(F{N > 1 ? ts[N - 2] : 0, ts.back(), -1, calc_b(-1, 0, ts.back())});
}

double calc_v(double t) {
  double ret = inf;
  for (auto f: funcs) {
    if (t < f.t1 || f.t2 < t) continue;
    minimize(ret, f.a * t + f.b);
  }
  return ret;
}

