constexpr int Nmax = 102;
int N;
int va[Nmax], vi[Nmax], ti[Nmax];

int dist(int va, int vi, int vb, int t) // 本来の4倍を出力
{
    int vmax_2 = va + vb + t; // 本来の2倍
    if (vmax_2 > vi * 2) return vi * t * 4 - 2 * (vi - va) * (vi - va) - 2 * (vi - vb) * (vi - vb); // 本来の4倍
    double t__2 = vmax_2 - va * 2; // 本来の2倍
    return ((va * 2 + vmax_2) * t__2 + (vb * 2 + vmax_2) * (t * 2 - t__2)) / 2; // 本来の4倍
}

int main()
{
    scanf("%d", &N);
    va[0] = va[N + 1] = vi[0] = vi[N + 1] = ti[0] = ti[N + 1] = 0;
    REP(i, N) scanf("%d", &ti[i + 1]);
    REP(i, N) scanf("%d", &vi[i + 1]);

    FOR(i, 1, N + 1) va[i] = min(min(vi[i], vi[i - 1]), va[i - 1] + ti[i - 1]);
    IFOR(i, 1, N + 1) va[i] = min(va[i], va[i + 1] + ti[i]);
    int ans = 0;
    FOR(i, 1, N + 1) ans += dist(va[i], vi[i], va[i + 1], ti[i]);
    cout << ans / 4.0 << endl;
}

