void solve(long long N)
{
  long long n_square = std::sqrt(N);
  long long min_count = 1e+12;
  for (long long i = 1; i < n_square; i++)
  {
    if(N%i == 0)
    {
      long long count = (i-1)+(N/i-1);
      if(count < min_count)
      {
        min_count = count;
      }
    }
  }
  std::cout << min_count << std::endl;
}

