int main() {

	int N; cin >> N;
	vector < int > t(N), v(N);
	REP(i,N) cin >> t[i];
	REP(i,N) cin >> v[i];

	int vel[21000] = {};
	int limit[21000] = {};
	int cnt = 1;
	REP(i,N) REP(j,t[i]) {
		limit[cnt] = v[i];
		cnt++;
	}

	cnt = 0;
	REP(i,N - 1) {
		cnt += t[i];
		limit[cnt] = min(v[i], v[i + 1]);
	}

	int sum = 0;
	REP(i,N) sum += t[i];

	limit[sum] = 0;

	REP(kai,200) for (int i = 1; i <= sum; i++) {
		int val = vel[i];
		val++;
		if (abs(val - vel[i - 1]) <= 1 && abs(val - vel[i + 1]) <= 1 && val <= limit[i]) {
			vel[i] = val;
		}
	}

	double ans_vel[21000];
	REP(i,21000) ans_vel[i] = (double) vel[i];

	double diff = 1.0;
	REP(kai,200) {
		diff /= 2.0;
		for (int i = 1; i <= sum; i++) {
			double val = ans_vel[i];
			val += diff;
			if (abs(val - ans_vel[i - 1]) <= 1.0 && abs(val - ans_vel[i + 1]) <= 1.0 && val <= (double) limit[i]) {
				ans_vel[i] = val;
			}
		}
	}

	double ans = 0.0;
	REP(i,sum) {
		double area = (ans_vel[i] + ans_vel[i + 1]);
		ans += area / 2.0;
	}

	//REP(i,sum + 1) cout << i << " " << vel[i] << " " << limit[i] << endl;

	cout << fixed << setprecision(10) << ans << endl;

	return 0;
}

