struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll n;
        long double et = 0;
        in >> n;
        vector<long double> t(n + 1), v(n);
        for (int i = 0; i < n; i++) {
            in >> t[i];
            t[i] += et;
            et = t[i];
        }
        for (int i = 0; i < n; i++) {
            in >> v[i];
        }
        int pos = 0;
        long double s = 0.0, d = 0.0;
        int cnt = 0;
        for (long double nt = 0; nt <= et; nt += 0.001) {
            d += s * 0.001;
            //cerr << nt << ' ' << d << ' ' << s << endl;
            if (pos + 1 == n && et - nt - 0.001 <= s) {
                s -= 0.001;
            }
            else if (abs(s - v[pos]) < EPS) {
            }
            else if (s < v[pos]) {
                s += 0.001;
            }
            else if (s > v[pos]) {
                s -= 0.001;
            }
            if (t[pos] <= nt) {
                pos++;
            }
        }
        out << d << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
