struct Tree{
    public:
    vector<map<lint,lint>> list;
    lint n;
    Tree(lint n):n(n){
        list.resize(n);
    }
    void unite(lint a,lint b,lint w){
        list[a].emplace(b,w);
        list[b].emplace(a,w);
    }
    void to(lint a,lint b,lint w){
        list[a].emplace(b,w);
    }
    vec dij(lint x){
        vec _diff(list.size(),INF);
        priority_queue<pair<lint,lint>,vector<pair<lint,lint>>,greater<pair<lint,lint>>>que;
        _diff[x]=0;
        que.push(make_pair(0,x));
        while(!que.empty()){
            lint diff = que.top().first;
            lint to =que.top().second;
            que.pop();
            if(_diff[to]<diff)continue;
            for(auto e:list[to]) {
                if (_diff[e.first] > _diff[to] + e.second) {
                    _diff[e.first] = _diff[to] + e.second;
                    que.push(make_pair(_diff[e.first],e.first));
                }
            }
        }
        return _diff;
    }
};
