    std::vector<std::tuple<int, int, int>> v(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &tmp);
        v[i] = std::make_tuple(0, tmp, 0);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &tmp);
        v[i] = std::make_tuple(tmp, totaltime, totaltime + std::get<1>(v[i]));
        totaltime = std::get<2>(v[i]);
    }
    std::vector<int> s(totaltime + 1, -1);
    std::deque<std::pair<double, double>> q;
    s[0] = 0;
    s[totaltime] = 0;
    q.push_back({ 0, 0 });
    q.push_back({ totaltime, 0 });

    std::sort(v.begin(), v.end(), [](std::tuple<int, int, int>& l, std::tuple<int, int, int>& r) { return std::get<0>(l) < std::get<0>(r); });

    for (auto& t : v) {
        //printf("%d %d %d\n", std::get<0>(v[i]), std::get<1>(v[i]), std::get<2>(v[i]));
        auto vel = std::get<0>(t);
        auto stime = std::get<1>(t);
        auto etime = std::get<2>(t);
        if (s[stime] == -1 && s[etime] == -1) {
            s[stime] = vel;
            s[etime] = vel;
            q.push_back({ stime, vel });
            q.push_back({ etime, vel });
        } else if (s[stime] > -1 && s[etime] == -1) {
            if (etime - stime > vel - s[stime]) {
                s[etime] = vel;
                s[vel - s[stime] + stime] = vel;
                q.push_back({ vel - s[stime] + stime, vel });
            } else {
                s[etime] = s[stime] + etime - stime;
            }
            q.push_back({ etime, s[etime] });
        } else if (s[stime] == -1 && s[etime] > -1) {
            if (etime - stime > vel - s[etime]) {
                s[stime] = vel;
                s[stime + vel - s[etime]] = vel;
                q.push_back({ stime + vel - s[etime], vel });
            } else {
                s[stime] = s[etime] + (etime - stime);
            }
            q.push_back({ stime, s[stime] });
        } else {
            if (etime - stime > (2 * vel - s[etime] - s[stime])) {
                s[stime + vel - s[stime]] = vel;
                s[etime - (vel - s[etime])] = vel;
                q.push_back({ stime + vel - s[stime], vel });
                q.push_back({ etime - (vel - s[etime]), vel });
            } else {
                auto maxvel = (abs(s[stime] - s[etime]) + etime - stime) * 1.0 / 2.0 + std::min(s[stime], s[etime]);
                q.push_back({ stime + (maxvel - s[stime]), maxvel });
            }
        }
    }

    std::sort(q.begin(), q.end(), [](std::pair<double, double>& l, std::pair<double, double>& r) { return l.first < r.first; });
    double ret = 0.0;
