using namespace std;
int N;
int t[100], s[100];
double dp[40001][202];

//2倍したtimeを入れて、その時の限界速度を返す
int getlimit(double time) {
	double sum = 0;
	time /= 2;
	for (int i = 0; i < N; i++) {
		sum += t[i];
		if (time <= sum) {
			if (time == sum) {
				if(i != N - 1)
					return min(s[i], s[i + 1]);
				return s[i];
			}
			return s[i];
		}
	}
	return s[N - 1];
}

int main() {
	int totalt = 0;
	cin >> N;
	for (int i = 0; i < N; i++)cin >> t[i], totalt += t[i];
	for (int i = 0; i < N; i++)cin >> s[i];
	for (int i = 0; i < totalt * 2; i++)for (int j = 0; j <= 200; j++)dp[i][j] = -1145141919;
	dp[0][0] = 0;
	//dp[i][j]:i / 2秒の時に速度がj / 2の時の距離の最大値
	for (int i = 0; i < totalt * 2; i++) {
		int limit = getlimit(i) * 2;
		for (int j = 0; j <= limit * 2; j++) {
			if (dp[i][j] < 0)continue;
			if (j + 1 <= getlimit(i + 1) * 2) {
				dp[i + 1][j + 1] = max(dp[i + 1][j + 1], dp[i][j] + (2 * j + 1) * 0.25 / 2);
				// 全速力で加速
			}
			if (j - 1 >= 0 && j - 1 <= getlimit(i + 1) * 2) {
				dp[i + 1][j - 1] = max(dp[i + 1][j - 1], dp[i][j] + (2 * j - 1) * 0.25 / 2);
				//全速力で減速
			}

			if(j <= getlimit(i + 1) * 2)
				dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + 0.5 * j / 2);
				//速度を維持
		}
	}
	cout << fixed << setprecision(10) << dp[totalt * 2][0] << endl;
	return 0;
}

