int main() {
    int N;
    cin >> N;
    vector<int> t(N), v(N);
    REP(i, N) {
        cin >> t[i];
        t[i] *= 2;
    }
    REP(i, N) {
        cin >> v[i];
        v[i] *= 2;
    }
    int T = accumulate(t.begin(), t.end(), 0);
    // maxv i t=iのときの最大
    vector<int> maxv(T + 1);
    int time = 0;
    REP(i, N) {
        for(int j = 0; j < t[i]; j++) {
            maxv[time++] = v[i];
        }
        //  cout << time << endl;
    }
    maxv[0] = 0;
    maxv[T] = 0;
    // cout << "T " << T << endl;
    for(int i = 1; i <= T; i++) {
        maxv[i] = min(maxv[i], maxv[i - 1] + 1);
    }
    for(int i = T - 1; i >= 0; i--) {
        maxv[i] = min(maxv[i], maxv[i + 1] + 1);
    }
    double ans = 0;
    for(int i = 0; i < T; i++) {
        ans += (double)(maxv[i] + maxv[i + 1]) / 2;
    }
    cout << ans / 4 << endl;
