constexpr ll LINF = 1LL << 60;
constexpr int IINF = 1 << 28;
constexpr ll mod =  1'000'000'007;
//constexpr ll mod = 998244353;

constexpr ld eps = 1e-8;

void solve(){
  int n; cin >> n;
  V<ll> ts(n+3), vs(n+3), tl(n+3), tr(n+3);
  FOR(i,0,n) cin >> ts[i+1];
  FOR(i,0,n) cin >> vs[i+1];
  FOR(i,0,n+2){
    tr[i] = tl[i]+ts[i];
    tl[i+1] = tr[i];
  }
  tl[0] = 0; tr[0] = 0;
  tr[n+1] = tl[n+1] + 100;
  auto f = [&](int tmain, int tsub)->ld{
    ld t = tsub;
    (t /= 2) += tmain;
    ld vret = LINF;
    FOR(i,0,n+2){
      if( t<=tl[i] ){
        vret = min<ld>(vret, -t+vs[i]+tl[i]);
      }
      else if(t>=tr[i] ){
        vret = min<ld>(vret, t+vs[i]-tr[i]);
      }
      else{
        vret = min<ld>(vret, vs[i] );
      }
    }
    return vret;
  };
  ld ans = 0;
  V<ld> vvv(tl[n+1]*2+20);
  FOR(i,0,tl[n+1]+2){
    FOR(j,0,2){
      vvv[2*i+j] = f(i,j);
    }
  }
  FOR(i,0,tl[n+1]*2){
    ans += (vvv[i]+vvv[i+1]);
  }
  ans /= 4;
  cout<<ans;
}



int main(void){
  std::cout << std::fixed << std::setprecision(20);
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
  //printf("%s", outst);
  return 0;
}

