double ans = 0;
int main() {
	cin >> N;
	vector<double> t(N), v(N+1), limit_v(N + 1);
	v[N] = 0;
	for (int i = 0; i < N; i++) {
		cin >> t[i];
	}
	for (int i = 0; i < N; i++) {
		cin >> v[i];
	}
	int tmp = 0;
	for (int i = 0; i < N; i++) {
		limit_v[i] = tmp + v[i];
		tmp += t[i];
	}
	limit_v[N] = tmp;
	double start = 0;
	for (int i = 0; i < N; i++) {
		auto it = min_element(limit_v.begin() + i + 1, limit_v.end());
		int ind = distance(limit_v.begin(), it);
		double goal_limit = min(limit_v[ind], v[i + 1]);
		if (start + t[i] > goal_limit) {
			double hoge=(start + t[i] + goal_limit) / 2;
			double surface = (start + hoge)*fabs(hoge - start)/2 + (hoge + goal_limit)*(t[i]-fabs(hoge - start))/2;
			if (hoge > v[i]) {
				if (v[i] > goal_limit) {
					ans += surface - (hoge - v[i])*(hoge - v[i]);
					start = goal_limit;
				}
				else {
					ans += v[i] * v[i] / 2 + v[i] * (t[i] - v[i]);
					start = v[i];
				}
			}
			else {
				ans += surface;
				start = goal_limit;
			}
		}
		else {
			ans += start * t[i] + t[i] * t[i] / 2;
			start = start + t[i];
		}
	}
	cout << ans << endl;
}

