	vector<vector<double>> dp(sum + 1, vector<double>(201, -1));
	dp[0][0] = 0;
	vi acum(n + 1);
	acum[0] = 0;
	REP(i, n)acum[i + 1] = acum[i] + t[i];
	int p = 1;
	REP(i, sum) {
		int ub=v[p-1];
		if (i == acum[p]) {
			p++;
			ub = min(v[p - 1], v[p - 2]);
		}
		FOR(j, 2 * ub + 1, 201) {
			dp[i][j] = -1;
		}

		REP(j, 201) {
			if (abs(dp[i][j] + 1)<EPS)continue;
			if (j != 0) {
				dp[i + 1][j - 1] = max(dp[i + 1][j - 1], dp[i][j] + (j - 1) + 0.5);
			}
			if (j != 200) {
				dp[i + 1][j + 1] = max(dp[i + 1][j + 1], dp[i][j] + j + 0.5);
			}
			dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + j);
		}

	}
	cout << fixed << setprecision(12) << dp[sum][0]/4 << endl;
}

