const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1}, dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};

int N;
int ts[200], vs[200];
int used[40100][210];
double dp[40100][210];

double rec(int t, int speed, int interval){
    if(used[t][speed]){
        return dp[t][speed];
    }

    if(t == ts[N] * 2){
        return speed == 0 ? 0 : -1e10;
    }

    if(t >= ts[interval] * 2){
        ++interval;
    }

    if(speed > vs[interval] * 2){
        return -1e10;
    }    

    // + 1m/s
    {
        int nextSpeed = min(speed + 1, vs[interval] * 2);
        dp[t][speed] = max(dp[t][speed], rec(t + 1, nextSpeed, interval) + 0.5 * 0.5 * 0.5 * (speed + nextSpeed));
    }

    // - 1m/s
    {
        int nextSpeed = max(speed - 1, 0);
        dp[t][speed] = max(dp[t][speed], rec(t + 1, nextSpeed, interval) + 0.5 * 0.5 * 0.5 * (speed + nextSpeed));
    }

    // no change
    {
        int nextSpeed = speed;
        dp[t][speed] = max(dp[t][speed], rec(t + 1, nextSpeed, interval) + 0.5 * 0.5 * 0.5 * (speed + nextSpeed));        
    }

    // printf("%d, %d: %.6f\n", t, speed, dp[t][speed]);

    used[t][speed] = true;
    return dp[t][speed];
}

