		amin(maxv[tt - 1], maxv[tt] + 1);
	}


	ll nowv = 0;
	ll ans = 0;
	for (int tt=0;tt<lastT;tt++)
	{
		if (nowv + 1 <= maxv[tt])
		{
			ans += (2 * nowv + 1);
			nowv++;
		}
		else if (nowv <= maxv[tt])
		{
			ans += (2 * nowv);
			nowv;
		}
		else if (nowv-1 <= maxv[tt])
		{
			ans += (2 * nowv - 1);
			nowv--;
		}
		else
		{
			assert(0);
		}

		assert(nowv >= 0);
	}

	printf("%.20f\n", (ans + 1) / 8.0);


	return 0;
}

