class section {
	private:
		double t;
		double start_v, max_v, next_v;
		double last_v;
		double dist;
		void calc_dist();
	public:
		section(double t, double start_v, double max_v, double next_v);
		double get_dist();
		double get_last_v();
};

section::section(double t, double start_v, double max_v, double next_v)
	:t(t),start_v(start_v),max_v(max_v),next_v(next_v)
{
	calc_dist();
}

double section::get_dist() {
	return dist;
}

double section::get_last_v() {
	return last_v;
}

void section::calc_dist() {
	double acc_t, dcc_t;
	double const_t;
	if (start_v < max_v) {
		acc_t = max_v - start_v;
	} 
	else {
		acc_t = 0;
	}

	if (max_v <= next_v) {
		dcc_t = 0;
	}
	else {
		dcc_t = max_v - next_v;
	}

	if (t >= acc_t + dcc_t){
		const_t = t -(acc_t + dcc_t);
		last_v = fmin(max_v, next_v);
		dist = 0.0;
		dist += (acc_t * (max_v - start_v)) / 2.0 + start_v * acc_t;
		dist += const_t * max_v;
		dist += (dcc_t *(max_v - last_v)) / 2.0 + last_v * dcc_t;


	}
	else {
		double new_max_v = fmin((start_v + next_v + t) / 2.0, t + start_v);

		double new_acc_t = new_max_v  - start_v;
		double new_dcc_t = fmax(t - new_acc_t, 0.0);
		last_v = fmin(t + start_v, next_v);

		dist = 0.0;
		dist += (new_acc_t * (new_max_v - start_v)) / 2.0 + start_v * new_acc_t;
		dist += (new_dcc_t *(new_max_v - last_v)) / 2.0 + last_v * new_dcc_t;

	}

}

