		std::cin >> t_str;
		T.push_back(std::stod(t_str));
	}
	for (int i = 0; i < N; i++) {
		std::cin >> v_str;
		V.push_back(std::stod(v_str));
	}


	double start_v = 0.0;
	double dist = 0.0;
	for (int i = 0; i < V.size(); i++) {
		double next_v;
		if (i + 1 < V.size()) {
			next_v = V[i + 1];
		}
		else {
			next_v = 0.0;
		}
		section s(T[i], start_v, V[i], next_v);
		dist += s.get_dist();
		start_v = s.get_last_v();
	}
	std::cout << std::fixed;
	std::cout << std::setprecision(5) << dist << "\n";
}

