pair<double,double> getSegAns(double a, double b, double c, double t){
    pair<double,double> ans(0.0,0.0);

    if(c>=b){
        double ts=min(a+t,b);
        ans.second=ts;
        double t0=ts-a;
        ans.first=t0*(ts+a)/2+ts*(t-t0);
    }
    else{
        double ts=min((a+c+t)/2,b);
        ans.second=c;
        double t0=ts-a, t1=t-(ts-c);
        ans.first=t0*(ts+a)/2+ts*(t-t0) + ts*(t1-t0)+(ts+c)/2*(t-t1);
    }
    return ans;
}

