        quo += 2;
      } else if (v_ans[j + 1] < v_ans[j]) {
        l += v_ans[j];
        quo -= 2;
      } else if (v_ans[j] < v[i]) {
        l += v_ans[j];
        quo += 1;
      } else {
        l += v_ans[j];
      }
    }
  }
  l += quo / 4;
  quo %= 4;
  std::cout << l + static_cast<double>(quo) * 0.25 << std::endl;
  return 0;
}

