        for (int j = 0; j < t.at(i); j++) {
            max_speed.push_back(v.at(i));
        }
    }
    max_speed.push_back(0);
    for (int i = max_speed.size() - 2; i >= 0; i--) {
        max_speed.at(i) = min(max_speed.at(i), max_speed.at(i + 1) + 1);
    }
    /*
