    */
    double ans = 0, speed = 0, x, y;
    for (int i = 0; i < max_speed.size() - 1; i++) {
        x = max_speed.at(i);
        y = max_speed.at(i + 1);
        if (x == speed) {
            if (y < speed) {
                ans += speed - 0.5;
                speed--;
            } else {
                ans += speed;
            }
