            if (y < speed) {
                ans += speed - 0.5;
                speed--;
            } else if (y > speed) {
                ans += speed + 0.5;
                speed++;
            } else {
                ans += speed + 0.25;
            }
        }
        //cout << ans << " ";
    }
    //cout << endl;
