    for (int i = 0; i < n; ++i) cin >> v[i];
    for (int i = 1; i < n; ++i) t[i] += t[i - 1];

    int idx = 0;
    double len = 0.0, vel = 0.0;
    for (double tm = 0.0; tm < t[n - 1]; tm += 0.5) {
        if (idx != n - 1 && t[idx] < tm + 0.5) ++idx;

        double ub = min(v[idx], -(tm + 0.5) + t[n - 1]);
        for (int i = idx + 1; i < n - 1; ++i)
            ub = min(ub, -(tm + 0.5) + t[i - 1] + v[i]);

        if (vel + 0.5 <= ub) { // 0.5 [m/s^2] 加速
            len += vel * 0.5 + 0.125;
            vel += 0.5;
        }
        else if (vel <= ub) { // 等加速度
            len += 0.5 * vel;
        }
        else { // 0.5 [m/s^2] 減速
            vel -= 0.5;
            len += vel * 0.5 + 0.125;
        }
    }

    cout << len << endl;

    return 0;
}

