    cin >> n;
    vector<int> t(n);
    vector<int> v(n);
    rep(i, n) cin >> t[i];
    rep(i, n) cin >> v[i];
    v.push_back(0);
    vector<int> st(n+1);
    rep(i, n) {
        st[i+1] = st[i] + t[i];
    }
    vector<int> speed(st.back()+1);
    rep(i, speed.size()) {
        if (i==0) continue;
        int res = speed[i-1] + 1;
        auto it = lower_bound(whole(st), i);
        it--;
        int num = it - st.begin();
        chmin(res, v[num]);
        for (int j=num+1; j<=n; j++) {
            int th = v[j] + (st[j]-i);
            chmin(res, th);
        }
        speed[i] = res;
        //cout << i << " " << res << endl;
    }
    double ans = 0.0;
    rep(i, speed.size()-1) {
        ans += 0.5 * (speed[i]+speed[i+1]);
        if (speed[i]==speed[i+1]) {
            auto it = upper_bound(whole(st), i);
            it--;
            int num = it - st.begin();
            if (speed[i]<v[num]) {
