    for(int i = 2*T-1; i >= 0; i--) {
        v_max[i] = min(v_max[i], v_max[i+1] + 0.5);
    }

    double ans = 0.0;
    irep2(i, 1, 2*T) {
        ans += (v_max[i] + v_max[i-1]) * 0.25;
        //cout << ans << "," << i << endl;
    }

    printf("%.7f\n", ans);
    return 0;
}
