			next_v = V[i + 1];
		}
		else {
			next_v = 0.0;
		}
		section s(T[i], start_v, V[i], next_v);
		dist += s.get_dist();
		start_v = s.get_last_v();
	}
	std::cout << dist << "\n";
}

