		for(int j = 0; j <= l[i]; j++) ub[j] = min(ub[j], v[i]+(l[i]-j));
		for(int j = r[i]; j <= sum; j++) ub[j] = min(ub[j], v[i]+(j-r[i]));
	}

	double ans = 0;
	for(int i = 1; i <= sum; i++){
		if(ub[i] == ub[i-1]) ans += ub[i];
		else ans += (ub[i]+ub[i-1]) / 2.0;
