using namespace ValLib;

int main()
{
	std::ios::sync_with_stdio(false);

	int N;
	cin >> N;
	vector<int> t(N), v(N);
	for (int i = 0; i < N; ++i) {
		cin >> t[i];
	}
	for (int i = 0; i < N; ++i) {
		cin >> v[i];
	}

	int T = accumulate(t);

	vector<double> maxy(T * 2 - 1);
	int time = 0;
	double vel = 0.0;
	for (int i = 0; i < N; ++i) { // 区間ごと
		for (double j = 0; j < t[i]; j = j + 0.5) { // 区間内で0.5s刻み
			if (time >= maxy.size()) {
				break;
			}
			maxy[time] = min((double)v[i], vel + 0.5);
			vel = min(vel + 0.5, (double)v[i]);
			++time;
		}
	}
	time = T * 2 - 2;
	vel = 0.0;
	for (int i = N - 1; i >= 0; --i) { // 区間ごと
		for (double j = 0; j < t[i]; j = j + 0.5) { // 区間内で0.5s刻み
			if (time < 0) {
				break;
			}
			maxy[time] = min(maxy[time], min((double)v[i], vel + 0.5));
			vel = min(vel + 0.5, (double)v[i]);
			--time;
		}
	}

	double result = 0.0;
	if (maxy[0] > 0) {
		result += 0.125;
	}
	for (int i = 1; i < maxy.size(); ++i) {
		double val = 0.0;
		if (maxy[i] > maxy[i - 1]) {
			val = (maxy[i] - 0.5) * 0.5 + 0.125;
		} else if (maxy[i] < maxy[i - 1]) {
			val = maxy[i] * 0.5 + 0.125;
		} else {
			val = maxy[i] * 0.5;
		}
		result += val;
	}
	if (maxy[T * 2 - 2] > 0) {
		result += 0.125;
	}


	cout << std::setprecision(18) << result << endl;

	getchar();
	getchar();
}

