float a[20100];
int b[20100];
int s;
float ans;

int main(){
	scanf("%d", &n);
	for(int i=1; i<=n; ++i){
		scanf("%d", &t[i]);
		s += t[i];
		t[i] += t[i-1];
	}
	++t[n+1];
	t[n+1] += t[n];
//	for(int i=0; i<=n+1; ++i) printf("%d\t", t[i]);
//	printf("\n");
	for(int i=1; i<=n; ++i){
		scanf("%d", &v[i]);
		for(int j=0; j<t[i]; ++j) b[j] = v[i];
	}
	for(int i=0; i<s; ++i) a[i] = std::min(i+0.5, s-i-0.5);
//	for(int i=0; i<s; ++i) printf("%.2f\t", a[i]);
//	printf("\n");
	for(int i=1; i<=n; ++i){
		for(int j=t[i-1]; j<t[i]; ++j) a[j] = std::min(a[j], (float)v[i]);
		for(int j=t[i-1]-1; j>=0; --j) a[j] = std::min(a[j], (float)(v[i]+t[i-1]-j-0.5));
		for(int j=t[i]; j<=s; ++j) a[j] = std::min(a[j], (float)(v[i]+j-t[i]+0.5));
	}
//	for(int i=0; i<s; ++i) printf("%d\t%.2f\n", i, a[i]);
	for(int i=0; i<s; ++i) ans += a[i];
	for(int i=1; i<s-1; ++i){
		if(a[i-1] + 0.7 < a[i] && a[i] > a[i+1] + 0.7) ans -= 0.25;
//		if(a[i-1] > a[i] + 0.7 && a[i] + 0.7 < a[i+1]) ans += 0.25;
		if(a[i-1] + 0.001 > a[i] && a[i-1] - 0.001 < a[i] && a[i] > a[i+1] + 0.7 && a[i] + 1 > b[i]) ans -= 0.125;
		if(a[i-1] + 0.7 < a[i] && a[i] + 0.001 > a[i+1] && a[i] - 0.001 < a[i+1] && a[i] + 1 > b[i]) ans -= 0.125;
	}
	if(s == 1) ans -= 0.25;
	printf("%.3f\n", ans);
}

