struct Bellman{
  ll INF=1000000000000000009;
  ll MAX_V;
  struct edge{ll from, to, cost;};
  vector<edge> es;
  vll d, pre;
  Bellman(ll n){
    MAX_V = n+1;
    d.resize(MAX_V, INF);
    pre.resize(MAX_V, -1);
  }
  void insert(ll a, ll b, ll c){
    es.push_back(edge{a, b, c});
  }
  void bellman(ll s){
    for(int i=0;i<MAX_V;i++) d[i] = INF;
    d[s] = 0;
    while(true){
      bool update = false;
      for(int i=0;i<es.size();i++){
        edge e = es[i];
        if(d[e.from]!=INF && d[e.to]>d[e.from]+e.cost){
          d[e.to] = d[e.from]+e.cost;
          pre[e.to] = e.from;
          update = true;
        }
      }
      if(!update) break;
    }
  }
  bool find_negative(){
    for(int i=0;i<MAX_V;i++) d[i] = 0;
    for(int i=0;i<MAX_V+10;i++){
      for(int j=0;j<es.size();j++){
        edge e = es[j];
        if(d[e.to] > d[e.from] + e.cost){
          d[e.to] = d[e.from] + e.cost;
          if(i==MAX_V+1) return true;
        }
      }
    }
    return false;
  }
};

int main(int argc, char const *argv[]) {
  ll x, y, z, n, m;std::cin >> n >> m;
  Bellman b(n);
  re(i, m){
    std::cin >> x >> y >> z;
    b.insert(x, y, -z);
  }
  if(b.find_negative()){
    std::cout << "inf" << '\n';
    return 0;
  }
  b.bellman(1);
  std::cout << -b.d[n] << '\n';
  return 0;
}

