  else if (i == n + 1)
    ret = t[n] - tm;
  else if (tm < t[i - 1])
    ret = -(tm - t[i - 1]) + v[i];
  else if (tm > t[i])
    ret = (tm - t[i]) + v[i];
  else
    ret = v[i];
  return ret;
}

