    int sum_t = 0;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        x *= 2;

        ss[i].begin = sum_t;
        ss[i].end = sum_t + x;

        sum_t += x;
    }

    for (int i = 0; i < n; i++) {
        int x;
