  l[n + 1] = r[n + 1] = r[n];
  double ans = .0;
  for (int i = 1; i <= n; ++i) {
    double ll = t[i] - l[i], rr = t[i] + r[i];
    for (int j = 0; j < i; ++j)
      ll = std::min(ll, (double)t[j] - r[j]);
    for (int j = i + 1; j <= n + 1; ++j)
      rr = std::min(rr, (double)t[j] + l[j]);
    // y <= x + ll, <= rr - x, <= t
    // x + ll = rr - x = (rr + ll) / 2, x = (rr - ll) / 2
#define q(x) std::min(t[i], std::min(ll + (x), rr - (x)))
#define add(x1, y1, x2, y2) ans += ((double)(y1) + (y2)) * ((double)(x2) - (x1))
    double xx0 = l[i], yy0 = q(xx0);
