    T[0] = 0;
    REP(i,N+1){
        if(i == 0) continue;
        int t;
        cin >> t;
        if(i != 0)
            T[i] = 2*t + T[i-1];
    }
    REP(i,N){
        int ve;
        cin >> ve;
        v[i] = 2*ve;
    }

    int ve = 0;
    float S = 0;
    REP(t, T[N]){
        int acc = 1;
        REP(i,N+1){
            int h = hantei(t+1, ve, i);
            acc = min(acc, h);
        }
        int tmp = ve;
        if(acc == 1) ve+=1;
        else if(acc == -1) ve-=1;
        S += tmp + (ve-tmp)*0.5;
        //printf("t:%d\tve:%d\n", t, ve);
    }
    cout << (S-1)/4 << endl;
