typedef long long ll;
int const inf = 1<<29;

int N;

struct F {
  double t1, t2, a, b;
};
vector<F> funcs;

double calc_b(double a, double y1, double x1) {
  // y1 = a * x1 + b;
  return y1 - a * x1;
}

void make_f_set(vector<double> const& ts, vector<double> const& vs) {
  rep(i, N) {
    if (i) {
      double a = -inf;
      if (vs[i] > vs[i - 1]) a = +1;
      if (vs[i] < vs[i - 1]) a = -1;
      if (vs[i] == vs[i - 1]) a = 0;
      double b = -inf;
      if (a > 0) {
        b = calc_b(a, vs[i - 1], ts[i - 1]);
        funcs.push_back(F{ts[i - 1], ts[i], a, b});
      }
      if (a < 0) {
        b = calc_b(a, vs[i], ts[i - 1]);
        funcs.push_back(F{i >= 2 ? ts[i - 2] : 0, ts[i - 1], a, b});
      }
      if (a == 0) {
        b = vs[i];
        funcs.push_back(F{ts[i - 1], ts[i], a, b});
      }
    }
    if (i == 0) {
      funcs.push_back(F{0, ts[0], +1, 0});
    }
    if (i == N - 1) {
      funcs.push_back(F{i ? ts[i - 1] : 0, ts[N - 1], -1, calc_b(-1, 0, ts[N - 1])});
    }
  }
  rep(i, N) {
    funcs.push_back(F{(i > 0 ? ts[i - 1] : 0), ts[i], 0, vs[i]});
  }
  funcs.push_back(F{0, 0, 0, 0});
  funcs.push_back(F{ts.back(), ts.back(), 0, 0});
}

double calc_v(double t, double limit) {
  double ret = limit;
  for (auto f: funcs) {
    if (t < f.t1 || f.t2 < t) continue;
    minimize(ret, f.a * t + f.b);
  }
  return ret;
}

int main() {
  cin >> N;
  vector<double> ts(N);
  rep(i, N) {
    cin >> ts[i];
    if (i) ts[i] += ts[i - 1];
  }
  vector<double> vs(N);
  rep(i, N) {
    cin >> vs[i];
  }
  make_f_set(ts, vs);
  double prevv = 0.0;
  double ans = 0.0;
  for (double t = 0; t <= ts.back(); t += 0.5) {
    auto currv = calc_v(t, prevv + 0.5);
    ans += (currv + prevv) * 0.5 / 2.0;
    prevv = currv;
  }
  printf("%.12f\n", ans);
}

