struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int n; scan(n);
      std::vector<Int> ts(n+2), vs(n+2);
      ts[0] = 0, vs[0] = 0;
      ts[n+1] = 0, vs[n+1] = 0;
      for(Int i = 1; i <= n; ++i) scan(ts[i]);
      for(Int i = 1; i <= n; ++i) scan(vs[i]);
      std::vector<Int> as, bs;
      std::vector<Int> ls, rs;
      Int st = 0;
      for(Int i = 0; i < n + 2; ++i) {
         //
         as.push_back(-1);
         bs.push_back(vs[i]+st);
         ls.push_back(-1e10);
         rs.push_back(st);
         //
         as.push_back(0);
         bs.push_back(vs[i]);
         ls.push_back(st);
         rs.push_back(st+ts[i]);
         //
         as.push_back(1);
         bs.push_back(vs[i]-(st+ts[i]));
         ls.push_back(st+ts[i]);
         rs.push_back(1e10);
         st += ts[i];
      }
      double res = 0.0;
      for(Int i = 0; i <= 2 * st; ++i) {
         double t = (double)i / 2;
         double z = 1e10;
         for(Int k = 0; k < (Int)as.size(); ++k) {
            if( ls[k] <= t and t <= rs[k] ) {
               z = std::min(z, as[k] * t + bs[k]);
            }
         }
         res += z;
      }
      printf("%.20lf\n", res / 2);
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

