int main() {
    int n;cin>>n;
    vector<double> t(n);cin>>t;
    vector<double> v(n);cin>>v;
    rep(i,n)t[i] *=2;
    rep(i,n)v[i] *=2;
    double vt = 0;
    double area = 0;
    v.push_back(0);
    vector<double>targ(n);
    double tot = t[0];
    targ[0] = t[0];
    repsg(i,1,n){
        tot+=t[i];
        targ[i] = targ[i-1]+t[i];
    }

    rep(i,n){
        double gl = v[i+1];
        for(auto k = i+1;k<n;k++){
            gl = min(gl,v[k]+targ[k-1] - targ[i]);
        }

        if(gl>=v[i]){
            if(vt + t[i] <= v[i]) {area += t[i]*t[i]/2.0 + t[i]*vt; vt = vt+t[i];}//最大加速し続けても制限に達しないケース。
            else {
                area += (v[i]-vt) * ((v[i]-vt)/2.0 + vt); //v[i]に達するまで加速し、その後キープ
                area += (t[i] - (v[i]-vt))*v[i]; vt = v[i];

            }
        }else{
            if(v[i]-vt + v[i] - gl<=t[i]){ // 途中でv[i]に達することができる場合。最大加速でv[i]にし、最大減速でglにする。
                area += (v[i]-vt)*(v[i]-vt)/2.0 + vt * (v[i]-vt) + gl*(v[i]-gl) +(v[i]-gl) *(v[i]-gl) /2.0 + v[i]*(t[i] -((v[i]-vt + v[i] - gl) ));
                vt = gl;
            }else{
                double dt = (gl-vt+t[i])/2.0; // v[i]に一度も達さない。

                area += vt * dt + (t[i]-dt) * gl;
                area += dt*dt/2.0 + (t[i]-dt)*(t[i]-dt)/2.0;
                vt = gl;
            }

        }

    }

    printf("%.10lf\n",area/4.0);
    return 0;
}

