const int MAX_NV = 110;
const int MAX_T = 210;

int N;
vector<int> T,V;
map<int, int> limits;
double dp[MAX_NV * MAX_T * 2][MAX_NV * 2];
int sum;
double memo(int pos, int v){
    if (v < 0){
      return -INF;
    }

    if (v > limits[pos]){
      return -INF;
    }
    if (pos >= sum){
      if (v == 0){
        return 0;
      }
      return -INF;
    }

    double &res = dp[pos][v];
    if (res > -2 * INF){
      return res;
    }
    res = -INF;
    res = max(res, memo(pos + 1, v) + v);
    if (v < limits[pos]){
      res = max(res, memo(pos + 1, v + 1) + v + 0.5);
    }
    res = max(res, memo(pos + 1, v - 1) + v - 0.5);
    return res;
}

int main() {
