    max_speed[j] = temp;
  }

  double ans = 0;
  rep(i, MAX_T) {
    int a = max_speed[i];
    int b = max_speed[i + 1];
    ans += ((double)(a + b)) / 2.0;
  }
  ans /= 4.0;
  printf("%.10f\n", ans);
}

