	REP(i, 2 * T + 1) vmax[i] = inf;
	REP(i, 2 * T + 1)
	{
		REP(j, n + 2) vmax[i] = min(vmax[i], fs[j](double(i) * 0.5));
	}
	double l = 0;
	REP(i, 2 * T)
	{
		l += (vmax[i] + vmax[i + 1]) * 0.5 * 0.5;
	}
	cout << l << endl;
	return 0;
}

