vector<double> t(200), v(200);

double minimum(int i){
	int ve = v[i+1], acc = 0;
	int j = i;
	while (ve > 0){
		i++;
		ve -= t[i];
		acc += t[i];
		if (ve > v[i+1])
			return acc + v[i+1];
	}

	return v[j+1];
}

int main(void){
	int N;

	cin >> N;

	for (int i = 0; i < N; i++){
		cin >> t[i];
	}
	for (int i = 0; i < N; i++){
		cin >> v[i];
	}

	double distance = 0, vel = 0;

	for (int i = 0; i < N - 1; i++){
		if (minimum(i) == v[i+1]){
			double a = (vel + v[i+1] + t[i])/2;
			if (v[i] > v[i+1]){
				if (t[i] < v[i] - vel + v[i] - v[i+1]){
					distance += t[i] * a - (a - vel)*(a - vel)/2 - (a - v[i+1]) * (a - v[i+1]) / 2;
					vel = v[i+1];
				}
				else {
					distance += t[i]*v[i] - (v[i] - vel)*(v[i] - vel)/2 - (v[i] - v[i+1])*(v[i] - v[i+1])/2;
					vel = v[i+1];

				}
			}
			else {
				if (vel + t[i] < v[i]){
					distance += t[i] * vel + t[i]*t[i]/2;
					vel = vel + t[i];
				}
				else {
					distance += t[i] * v[i] - (v[i] - vel)*(v[i] - vel)/2;
					vel = v[i];
				}
			}
		}
		else {
			double ve = minimum(i);
			double a = (vel + ve + t[i])/2;
			if (v[i] > v[i+1]){
				if (t[i] < v[i] - vel + v[i] - ve){
					distance += t[i] * a - (a - vel)*(a - vel)/2 - (a - ve) * (a - ve) / 2;
					vel = ve;
				}
				else {
					distance += t[i]*v[i] - (v[i] - vel)*(v[i] - vel)/2 - (v[i] - ve)*(v[i] - ve)/2;
					vel = ve;
				}
			}
			else {
				if (vel + t[i] < v[i]){
					distance += t[i] * vel + t[i]*t[i]/2;
					vel = vel + t[i];
				}
				else {
					distance += t[i] * v[i] - (v[i] - vel)*(v[i] - vel)/2;
					vel = v[i];
				}
			}

		}
	}


	if (2*v[N-1] - vel > t[N-1]){
		double a = (vel + t[N-1])/2;
		distance += t[N-1] * a - (a - vel)*(a - vel)/2 - (a) * (a) / 2;
	}
	else {
		distance += t[N-1]*v[N-1] - (v[N-1] - vel)*(v[N-1] - vel)/2 - v[N-1]*v[N-1]/2;
	}

	printf("%.5lf\n", distance);

	return 0;
}

#include <stdio.h>
