//計算
void calc()
{	
	int sumt = t.back() * 2;
	//各時刻の最小値  minv[t]:= 時刻 t/2の速度最小値
	vector<double> minv(sumt + 1, INF);

	//走行開始と終了の対応
	REP2(t, sumt)minv[t] = min(minv[t], t / 2.0);
	REP2(t, sumt)minv[t] = min(minv[t], abs(t - sumt) / 2.0);

	//各谷の対応
	REP(i, N) {
		//速度規制区間の左端と右端(時間は2倍に希釈)
		int tl = t[i] * 2;
		int tr = t[i + 1] * 2;
		//cout << "tl&tr " << tl << " " << tr << endl;
		//谷の左
		REP2(t, tl)minv[t] = min(minv[t], abs(t - tl) / 2.0 + v[i]);
		//谷の中央
		FOR2(t, tl, tr)minv[t] = min(minv[t], 1.0*v[i]);
		//谷の右
		FOR2(t, tr, sumt)minv[t] = min(minv[t], abs(t - tr) / 2.0 + v[i]);
	}
