	cout << "minv" << endl;
	REP2(t, sumt) {
		cout << "t:" << t << "  v:" << minv[t] << endl;
	}
	*/

	double ans = 0;
	REP(i, sumt) {
		ans += (minv[i] + minv[i + 1])*0.25;
	}
	cout << ans << endl;
}


