// 走行時間t,制限速度vmの区間に速度vで侵入したとき、
// 可能な最長移動距離lと抜けるときの速度vlを計算する.
// その次の区間の制限速度がvnであり、
// この区間を抜けるときの速度vlはvn以下でなければならない.
pair<double, double> calc_dis(double v, int t, int vm, int vn) {
	double l = 0.0;
	double vl = v;
	// この区間の制限速度より、次の区間の制限速度の方が
	// 大きい場合、加速できるだけ加速するのがよい.
	if (vm <= vn) {
		if (v + t <= vm) { // t秒間フルで加速して問題なし
			vl += t;
			l += (2 * (double)v + t) * t / 2.0;
			return make_pair(l, vl);
		}
		int t_a = vm - v; // 加速する時間
		t -= t_a; // 加速後の走行時間
		vl = vm;
		l = (2 * (double)v + t_a) * t_a / 2.0;
		l += (double)vm * t;
		return make_pair(l, vl);
	}
	// この区間の制限速度より、次の区間の制限速度の方が
	// 小さい場合、
	// i秒後の速度v(i)は
	//   min(vm,v+i,vn+(t-i))
	// であり、[i,i+0.5)の移動距離は
	//   (v(i) + v(i+0.5)) / 4.0
	// で計算される.
	double vi, vi1; // v(i)とv(i+1)
	for (double i = 0; i < t; i += 0.5) {
		vi = min({ (double)vm, v + i, vn + (t - i) });
		vi1 = min({ (double)vm, v + i + 0.5, vn + (t - i - 0.5) });
		l += (vi + vi1) / 4.0;
	}
	vl = vi1;
	return make_pair(l, vl);
}

signed main() {
	// 入力を受け取る
	int n; cin >> n;
	vector<int> t(n);
	for (int i = 0; i < n; ++i) cin >> t[i];
	vector<int> v(n);
	for (int i = 0; i < n; ++i) cin >> v[i];

	//   vnow := 現在の速度
	// として、上記の関数を用い、答えを計算.
	v.push_back(0); // 走行終了時を区間とみなす.
	double ans = 0.0;
	double vnow = 0;
	for (int i = 0; i < n; ++i) {
		auto lv = calc_dis(vnow, t[i], v[i], v[i + 1]);
		vnow = lv.second;
		ans += lv.first;
	}

	cout << setprecision(10) << ans << endl;

	return 0;
}

