int main()
{
    int N;
    std::cin >> N;
    std::vector<int> t(N), v(N);
    for(int i=0; i<N; i++) scanf(" %d", &t[i]);
    for(int i=0; i<N; i++) scanf(" %d", &v[i]);

    std::vector<int> sum_t(N);
    sum_t[0] = t[0];
    for(int i=0; i<N; i++) sum_t[i] = sum_t[i-1] + t[i];

    int T = sum_t[N-1];
    std::vector<int> speed(T), lim(T);
    for(int i=0; i<T; i++) speed[i] = std::min(i, T-i);
    for(int i=0; i<N; i++){
        for(int j=0; j<T; j++){
            int vi = 0;
            if(i!=N-1) vi = std::min(v[i], v[i+1]);
            speed[j] = std::min(vi+abs(sum_t[i]-j), speed[j]);
        }
    }
    int k=0;
    for(int i=0; i<N; i++){
        while(k < sum_t[i]){
            speed[k] = std::min(v[i], speed[k]);
            lim[k] = v[i];
            k++;
        }
    }

    double x = 0;
    for(int i=0; i<T-1; i++){
        x += 1.0 * (speed[i] + speed[i+1]) / 2.0;
        if(speed[i] == speed[i+1] && speed[i+1] < lim[i+1]) x += 0.25;
    }
    x += 1.0 * speed[T-1] / 2.0;
    printf("%lf\n", x);
}

