double lim[41000];

void update(int s, int len, double v) {
    s *= 2;
    len *= 2;
    for (int i = s; i <= s + len; i++) {
        chmin(lim[i], v);
    }
    double vel = v;
    for (int i = s - 1; i >= 0; i--) {
        vel += 0.5;
        chmin(lim[i], vel);
    }
    vel = v;
    for (int i = s + len + 1; i < 40000; i++) {
        vel += 0.5;
        chmin(lim[i], vel);
    }
}

