double memo[101][401][201];

double rec(int idx, int time, int v){
    if(memo[idx][time][v]!=0)return memo[idx][time][v];
    double res = -1e9;
    if(idx==N){
        if(v==0)res = 0;
    }else if(time==2*T[idx]){
        if(0<=v && v<=2*V[idx+1])res = rec(idx+1, 0, v);
    }else{
        if(0<=v+1 && v+1<=2*V[idx])res = max(res, v + 0.5 + rec(idx, time+1, v+1));
        if(0<=v-1 && v-1<=2*V[idx])res = max(res, v - 0.5 + rec(idx, time+1, v-1));
        if(0<=v   && v  <=2*V[idx])res = max(res, v + 0.0 + rec(idx, time+1, v+0));
    }
    memo[idx][time][v] = res;

    return res;
}

