		}
		vm=min(v[i],v0+tt/2.0);
		ans+=(v0+vm)*(vm-v0);
		tt-=(vm-v0)*2;
		ans+=tt*vm;
		if (fl) v0=g[i+1];//v0=vt; !!!!
	}
	printf("%.12f\n",ans);
	return 0;
}

