#include <bits/stdc++.h>
using namespace std;

int main()
{
    int N;
    cin >> N;
    vector<double> t(N), v(N);
    double sum = 0;
    for (int i = 0; i < N; i++) {
        cin >> t[i];
        sum += t[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> v[i];
    }
    //番兵
    v.push_back(INT_MAX);

    double now_time = 0, now_speed = 0;
    double ans = 0;
    for (int i = 0; i < N; i++) {
        //printf("i = %d\n", i);
        //now_timeからnow_time + t[i]までの時間を走る
        //t[i]は3つに分けられる
        //速度を上げている時間,そのままの時間,下げる時間
        double up_time, keep_time, down_time;

        //次の時間が始まるときの制限速度
        double next_start_limit = min(v[i + 1], sum - (now_time + t[i]));

        //速度を上げる時間は今の制限速度までを考慮したものと、次の制限速度を考慮したものの小さい方
        up_time = min(v[i] - now_speed, (next_start_limit + t[i] - now_speed) / 2);
        up_time = min(up_time, t[i]);

        down_time = max(0.0, now_speed + up_time - next_start_limit);

        keep_time = t[i] - up_time - down_time;

        assert(0 <= up_time && up_time <= t[i]);
        assert(0 <= keep_time && keep_time <= t[i]);
        assert(0 <= down_time && down_time <= t[i]);

        ans += 0.5 * (now_speed + now_speed + up_time) * up_time;
        ans += (now_speed + up_time) * keep_time;
        ans += 0.5 * (now_speed + up_time + now_speed + up_time - down_time) * down_time;

        now_time += t[i];
        now_speed += up_time;
        now_speed -= down_time;
        //printf("%f, %f, %f\n", up_time, keep_time, down_time);
        //printf("ans = %.4f\n", ans);
    }
    printf("%.6f\n", ans);
}

