        //等速か加速
        dp[speed+1][Time]=max(dp[speed+1][Time],dp[speed][Time-1]+(double)(speed+(speed+1))/2.0);
        dp[speed][Time]=max(dp[speed][Time],dp[speed][Time-1]+(double)(speed+(speed))/2.0);
      }
      else {
        //等速か減速
        dp[speed][Time]=max(dp[speed][Time],dp[speed][Time-1]+(double)(speed+(speed))/2.0);
        dp[speed-1][Time]=max(dp[speed-1][Time],dp[speed][Time-1]+(double)(speed+(speed-1))/2.0);
      }

