int N;
vector<int> cum(110, 0), v(110, 0);

double f(int i, double t){
    if(i == 0) return t;
    if(i == N+1) return cum[N]-t;

    if(t <= cum[i-1]) return v[i]+cum[i-1]-t;
    else if(t <= cum[i]) return v[i];
    else return v[i]+t-cum[i];
}   

int main(){
    cin >> N;
