        double h2 = 10000000;
        for(int i=0; i<=N+1; i++) h2 = min(h2, f(i, x));
        ans += (h1 + h2) * 0.5 / 2;
        h1 = h2;
    }

    printf("%.8lf\n", ans);
    return 0;
}

