constexpr int IINF = 1 << 28;
constexpr ll mod =  1'000'000'007;
//constexpr ll mod = 998244353;

constexpr ld eps = 1e-8;

void solve(){
  int n; cin >> n;
  V<ll> ts(n+1), vs(n+1);
  FOR(i,0,n) cin >> ts[i];
  FOR(i,0,n) cin >> vs[i];
  V<ll> vmb(n+1), vmf(n+1);
  FOR(i,0,n){
    if(vs[i]<=vmf[i] ) vmf[i+1] = vs[i];
    else vmf[i+1] = min(vs[i], vmf[i]+ts[i] );
  }
  FOR(i,0,n) vmf[i] = vmf[i+1];
  IFOR(i,0,n){
    if( vs[i]<=vmb[i+1]) vmb[i] = vs[i];
    else vmb[i] = min(vs[i], vmb[i+1]+ts[i]);
  }
  FOR(i,0,n) vs[i] = min({vs[i],vmf[i],vmb[i]});
  //coutn(vs);

  ld ans = 0, bv = 0;

  FOR(i,0,n){
    ld nv = min<ll>(vs[i+1],vs[i]);
    ld vy = (bv+nv+ts[i])/2, vx = (-bv+nv+ts[i])/2
      ,xl = vs[i]-bv, xr = nv+ts[i]-vs[i];
    if( xr-xl>=-eps ){
      ans += (bv+vs[i])*xl/2
            +(xr-xl)*vs[i]
            +(nv+vs[i])*(ts[i]-xr)/2;
    }
    else{
      ans += (bv+vy)*vx/2 + (vy+nv)*(ts[i]-vx)/2;
    }
    bv = nv;
  }
  cout<<ans;
}



