          if( t[i + 1] >= t[i] ) {
               if( s[i] >= t[i] - v ) {
                    double x = t[i] - v;
                    sum += v * x + x * x / 2;
                    v += x;
                    sum += ( s[i] - x ) * v;
               } else {
                    sum += v * s[i] + s[i] * s[i] / 2;
                    v += s[i];
               }
          }
          if( t[i + 1] < t[i] ) {
               if( v - s[i] < t[i + 1] ) {
                    double x = ( t[i + 1] - v + s[i] ) / 2;
                    if( v + x <= t[i] ) {
                         sum += v * x + x * x / 2;
                         v += x;
                         x = s[i] - x;
                         sum += v * x - x * x / 2;
                         v -= x;
                    } else {
                         x = t[i] - v;
                         sum += v * x + x * x / 2;
                         v += x;
                         x = s[i] - x - t[i] + t[i + 1];
                         sum += v * x;
                         x = t[i] - t[i + 1];
                         sum += v * x - x * x / 2;
                         v -= x;
                    }
               }
               else if(v-s[i]>=t[i+1])
               {
                    double x=v-t[i+1];
                    sum+=v*x-x*x/2;
                    v-=x;
               }
          }
     }
     printf( "%.12f\n", sum );
}

