void solve() {
    constexpr i64 SCALE = 10000;

    i64 N; RD(N);
    auto T = RD_ARRAY<i64>(N);
    auto V = RD_ARRAY<i64>(N);

    arrayn_foreach(T, [](i64& t) { t *= SCALE; });
    arrayn_foreach(V, [](i64& v) { v *= SCALE; });

    vector<i64> vl(N);
    vector<i64> vr(N);
    vl[0] = 0;
    vr[N-1] = 0;

    FOR(i, 1, N) {
        vl[i] = min({ V[i-1], V[i], V[i-1]+T[i-1] });
    }
    FOR(i, 0, N-1) {
        vr[i] = min({ V[i], V[i+1], V[i]+T[i] });
    }

    i64 area = 0;
    REP(i, N) {
        REP(t, T[i]) {
            i64 v = min({ V[i], vl[i]+t, vr[i]+(T[i]-t) });
            area += v;
        }
    }

    f80 ans = static_cast<f80>(area) / ipow(SCALE,2);

    PRINTLN(ans);

    // * 小さいケースで試した?
    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
