                len += ((vv * tt + 0.5 * tt * tt) + (vvv * ttt - 0.5 * ttt * ttt));
            } else {
                tt = v[i] - vv;
                double vvv = v[i], ttt = v[i] - v[i + 1];
                len += ((vv * tt + 0.5 * tt * tt) + (vvv * ttt - 0.5 * ttt * ttt) + v[i] * (t[i] - tt - ttt));
            }
            vv = v[i + 1];
        }
    }
    printf("%.8f\n", len);
    return 0;
}

