    {
        vEndMax[i] = 100.0;
        for (int j = N - 1; j > i; --j)
        {
            vEndMax[i] = min(vEndMax[i], vEndMax[j] + sumT[j] - sumT[i]);
        }
        vEndMax[i] = min(vEndMax[i], min(v[i], v[i + 1]));
    }
