int main() {
    int N;
    cin >> N;
    vector<int> t(N);
    vector<double> v(N);
    int T = 0;
    for (int i = 0; i < N; i++) {
        cin >> t.at(i);
        T += t[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> v.at(i);
    }

    vector<double> lim(2 * T + 1, 100000);
    int now = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < t[i]; j++) {
            chmin(lim[now], v[i]);
            chmin(lim[now + 1], v[i]);
            now += 2;
        }
    }

