std::int64_t gcd(std::int64_t x, std::int64_t y) {
   if (x == 0 || y == 0) return 0;
   std::int64_t r;
   while ((r = x % y) != 0) {
      x = y;
      y = r;
   }
   return y;
}

std::int64_t lcm(std::int64_t x, std::int64_t y) {
   if (x == 0 || y == 0) return 0;
   return (x / gcd(x, y) * y);
}

std::int64_t mod(std::int64_t a, std::int64_t m) {
   return (a % m + m) % m;
}

// n以下の素数テーブルを返す
// i番目の要素がtrueのときiが素数であることを表す
std::vector<bool> prime_table(int n) {
   if (n <= 1) return std::vector<bool>();
   std::vector<bool> prime(n + 1, true);
   prime[0] = prime[1] = false;
   for (int i = 2; i * i <= n; ++i) {
      if (!prime[i]) continue;
      for (int j = i + i; j <= n; j += i) {
         prime[j] = false;
      }
   }
   return prime;
}

// 素因数分解
template <typename T>
std::map<T, int> prime_factor(T n) {
   std::map<T, int> ret;
   for (T i = 2; i * i <= n; ++i) {
      while (n % i == 0) {
         ret[i]++;
         n /= i;
      }
   }
   if (n != 1) ret[n] = 1;
   return ret;
}

