const int MAX_V = 100;

int main() {
  auto start = high_resolution_clock::now();

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  cerr << "Total execution time : " << duration_cast<milliseconds>(high_resolution_clock::now() - start).count() << " ms" << endl;

  cout << fixed << setprecision(10);

  int n;
  cin >> n;

  vector<vector<double>> dp(n + 1, vector<double>(MAX_V + 1, -1));
  dp[0][0] = 0;

  vector<int> t(n);
  for (int i = 0; i < n; ++i)
    cin >> t[i];

  vector<int> v(n);
  for (int i = 0; i < n; ++i)
    cin >> v[i];

  for (int i = 0; i < n; ++i) {
    for (int prev_v = 0; prev_v <= v[i]; ++prev_v) {
      if (dp[i][prev_v] == -1)
        continue;
      for (int next_v = 0; next_v <= v[i]; ++next_v) {
        if (abs(next_v - prev_v) > t[i])
          continue;

        double _max = min(1.0 * v[i], (t[i] + prev_v + next_v) / 2.0);

        double dist = dp[i][prev_v];
        double t1 = _max - prev_v;
        double t2 = _max - next_v;

        dist += t1 * prev_v + t1 * t1 / 2.0 + _max * (t[i] - t1 - t2) + t2 * t2 / 2.0 + t2 * next_v;
        dp[i + 1][next_v] = max(dp[i + 1][next_v], dist);
      }
    }
  }

  cout << dp[n][0] << endl;

  return 0;
}

