			res += 0.5 + hi;
			hi++;
		}
		else if (check(i, hi)) {
			res += hi;
		}
		else if (check(i,hi-1)){
			hi--;
			res += 0.5 + hi;
		}
	}
	res /= 4;
	put_float(res);
}


