pair<double, int> solve(int v0, int v1, int t, int vcurr) {
  int vfin;
  double area;
  if(v0 <= v1) {
    if(vcurr + t < v0) {
      vfin = vcurr + t;
      area = (vcurr + vfin) * t * 0.5;
    }else{
      vfin = v0;
      area = v0 * t - pow(v0 - vcurr, 2) * 0.5;
    }
  }else{
    vfin = v1;
    if(2 * v0 - vcurr - v1 < t) {
      area = v0 * t - 0.5 * pow(v0 - vcurr, 2) - 0.5 * pow(v0 - v1, 2);
    }else{
      double vmid = 0.5 * (t + vcurr + v1);
      area = t * vmid - 0.5 * pow(vmid - vcurr, 2) - 0.5 * pow(vmid - v1, 2);
    }
  }
  return make_pair(area, vfin);
}

int main(){
  int N;
