  double ret = 0;
  int vcurr = 0;
  REP(i, N) {
    int vnext = (i < N - 1) ? v[i + 1] : 0;
    auto p = solve(v[i], vnext, t[i], vcurr);
    ret += p.first;
    vcurr = p.second;
  }

  cout << fixed << setprecision(10) << ret << endl;
  return 0;
}

