ld f(ld t, ld v, ld left, ld right) {
    if(v - left + v - right <= t) {
        return t * v - (v - left) * (v - left) / 2.0 - (v - right) * (v - right) / 2.0;
    }
    ld h = (t + left + right) / 2.0;
    return (left + h) * (h - left) / 2.0 + (right + h) * (h - right) / 2.0;
}

void solve() {
	int n; cin >> n;
    vector<ld> t(n + 2, 0), v(n + 2, 0);
    vector<ld> st(n + 3, 0);
    rep(i, n) {
        cin >> t[i + 1];
        st[i + 2] = st[i + 1] + t[i + 1];
    }
    rep(i, n) {
        cin >> v[i + 1];
    }
    ld ans = 0;
    rep(i, n + 2) {
        ld left = v[i], right = v[i];
        rep(j, n + 2) {
            if(j < i) {
                chmin(left, v[j] + st[i] - st[j + 1]);
                chmin(right, v[j] + st[i + 1] - st[j + 1]);
            } else if(i < j) {
                chmin(right, v[j] + st[j] - st[i + 1]);
                chmin(left, v[j] + st[j] - st[i]);
            }
        }
        ans += f(t[i], v[i], left, right);
    }
    cout << ans << endl;
}

