int main() {
	cin >> n;
	ll maxtime = 0;
	REP(i, n) {
		ll h;
		cin >> h;
		t.pb(h);
		maxtime += h;
	}
	REP(i, n - 1) { t[i + 1] += t[i]; }
	REP(i, n) {
		ll h;
		cin >> h;
		v.pb(h);
	}
	ll itr = 0;
	REP(i, maxtime) {
		if (t[itr] == i) {
			itr++;
