		speed[i] = v[itr];
	}
	// REP(i, maxtime) { cout << speed[i] << " " << i << endl; }
	fill_all(dp, (double)-1919191919);
	dp[0][0] = 0;
	REP(i, maxtime) {
		REP(j, 101) {
			for (ll k = -1; k < 2; k++) {
				if (j + k > speed[i + 1] || j + k < 0) {
					continue;
				}
				if (k == 1 && j + k > speed[i]) {
					continue;
				}
				if (k == -1 && j + k > speed[i]) {
					continue;
				}
				dp[i + 1][j + k] = max(dp[i + 1][j + k], dp[i][j] + j + k * 0.5);
			}
			if (speed[i] >= 1 + j&& speed[i+1] >= 1 + j) {
				dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + 0.25 + j);
			}
		}
	}
	printf("%.10f\n", dp[maxtime][0]);
}

