        T += t[i];
    }

    vector<double> maxV(2*T+1, (double)INF);
    int cT = 0;
    REP(i, N){
        REP(ti, t[i]){
            int t1 = cT + ti * 2;
            int t2 = cT + ti * 2 + 1;
            maxV[t1] = min(maxV[t1], v[i]);
            maxV[t2] = min(maxV[t2], v[i]);
        }
        cT += t[i] * 2;
        maxV[cT] = min(maxV[cT], v[i]);
    }

    maxV[0] = maxV[T*2] = 0.0;
    REP(ti, 2*T+1){
        maxV[ti+1] = min(maxV[ti+1], maxV[ti]+0.5);
    }
    RREP(ti, 2*T+1){
        maxV[ti] = min(maxV[ti], maxV[ti+1]+0.5);
    }
    double ans = 0.0;
    REP(i, 2*T+1){
        ans += (maxV[i] + maxV[i+1]) * 0.5 / 2.0;
    }
