int main()
{
    int N; cin >> N;

    vector<int> t(N), v(N);

    REP(i, N)
    {
        cin >> t[i];
    }

    REP(i, N)
    {
        cin >> v[i];
    }

    vector<int> ts(N);

    REP(i, N)
    {
        if( i == 0 ) ts[0] = t[i];
        else ts[i] = ts[i-1] + t[i];
    }

    int total_time = ts[N-1];

    vector<int> limit;

    int current_time = 0;
    REP(i, N)
    {
        REP(j, t[i])
        {
            current_time++;

            int current_min = min( total_time - current_time, v[i] );

            for( int k = i+1; k < N; k++ )
            {
                current_min = min( ts[k - 1] - current_time + v[k], current_min );
            }

            limit.push_back(current_min);
        }
    }

    int current_velocity = 0;
    int past_velocity = 0;
    double sum = 0;
    REP(i, limit.size())
    {
        past_velocity = current_velocity;

        if( current_velocity < limit[i] )
        {
            current_velocity++;
        }
        else if( limit[i] < current_velocity )
        {
            current_velocity--;
        }

        if( current_velocity == past_velocity && limit[i-1] == current_velocity + 1 )
            sum += 0.25;

        sum += current_velocity;
    }

    cout << sum << endl;

    return 0;
}

