        }
        time += T[i];
    }

    for (int i = N-1; i >= 0; i--)
    {
        for (int t = time; t > time-T[i]; t--)
        {
            right_vec[t-1] = min(right_vec[t]+0.5,V[i]);
        }
        time -= T[i];
    }
    for (int t = 0; t < MaxTime; t++)
    {
        max_vec[t] = min(left_vec[t],right_vec[t]);
