double speed_limit(int cond_j, double time, int* t, int* v) {
  if (time < t[cond_j-1]) {
    return v[cond_j] + t[cond_j-1] - time;
  } else if (time < t[cond_j]) {
    return v[cond_j];
  } else {
    return v[cond_j] + time - t[cond_j];
  }
}

int main() {
  int i, j;
  int N;
  int t[210] = {};
  int v[210] = {};
  cin >> N;
  for (i = 1; i < N+1; i++) {
    cin >> t[i];
    t[i] = t[i-1]+t[i];
  }
  for (i = 1; i < N+1; i++) {
    cin >> v[i];
  }
  double velocity[40010] = {};
  for (i = 0; i < 2*t[N]; i++) {
    velocity[i] = min(i*0.5, t[N] - i*0.5);
    for (j = 1; j < N+1; j++) {
      velocity[i] = min(velocity[i], speed_limit(j, i*0.5, t, v));
    }
  }
  //for (i = 0; i < 2*t[N]; i++) {
  //  cout << velocity[i] << endl;
  //}
  double ans = 0;
  for (i = 0; i < 2*t[N]; i++) {
    ans += 0.25*(velocity[i]+velocity[i+1]);
  }
  cout << ans << endl;
  return 0;
}

