signed main() {
    cin>>n;
    rep(i,n){
        scanf("%lf",&t[i]);
    }
    rep(i,n){
        scanf("%lf",&v[i]);
    }
    rep(i,n){
        if (v[i]>v[i+1]) {
            if (v[i]-now+v[i]-v[i+1]<=t[i]) {
                ans+=(v[i]+now)/2*(v[i]-now) + (v[i]+v[i+1])/2*(v[i]-v[i+1]) + v[i]*(t[i]-(v[i]-now)-(v[i]-v[i+1]));
                now=v[i+1];
            }else{
                double l=v[i+1],r=inf;
                while (l+0.0000001<=r) {
                    double m=(l+r)/2;
                    if (fabs(m-now)+fabs(m-v[i+1])<=t[i]) {
                        l=m;
                    }else{
                        r=m;
                    }
                }
                ans+=(l+now)/2*(l-now) + (l+v[i+1])/2*(l-v[i+1]);
                now=v[i+1];
            }
        }else{
            if (t[i]+now>=v[i]) {
                ans+=(now+v[i])/2*(v[i]-now)+v[i]*(t[i]-(v[i]-now));
                now=v[i];
            }else{
                ans+=(now+now+t[i])/2*t[i];
                now=now+t[i];
            }
        }
    }
