int main(void) {
    int n;
    cin >> n;
    Vec<int> t(n);
    Vec<int> v(n);
    int time = 0;
    FOR (loop, 0, n) {
        cin >> t[loop];
        time += t[loop];
    }
    FOR (loop, 0, n) {
        cin >> v[loop];
    }

    Vec<int> sped(100 * time + 1, 0);
    Vec<int> max_s(100 * time + 1);
    int rui = 0; // ruiseki_time
    max_s[0] = 0;
    FOR (i, 0, n) {
        FOR (j, 100 * rui, 100 * (rui + t[i])) {
            max_s[j] = v[i] * 100;
        }
        if (i != 0) {
            max_s[100 * rui] = min(v[i], v[i - 1]) * 100;
        }
        rui += t[i];
    }

    while (1) {
        bool change = false;
        // operation
        FOR (i, 1, 100 * time) {
            sped[i] += 1;
            if (abs(sped[i - 1] - sped[i]) > 1 || abs(sped[i + 1] - sped[i]) > 1 || sped[i] > max_s[i]) {
                sped[i] -= 1;
            } else {
                change = true;
            }
        }
        if (change == false) {
            break;
        }
    }
    /*
    FOR (i, 0, 100 * time) {
        cout << (double)(i) / 100 << " " << (double)(sped[i]) / 100 << " " << (double)(max_s[i]) / 100 << endl;
    }
     */

    double total = 0;
    FOR (i, 0, 100 * time) {
        int status = sped[i + 1] - sped[i];
        if (status == 1) {
            total += sped[i + 1] * 2 - 1;
        } else if (status == 0) {
            total += sped[i] * 2;
        } else {
            total += sped[i] * 2 - 1;
        }
    }
    total /= 20000;
    cout << std::fixed << setprecision(4) << total << endl;

    return 0;
}

