int main() {
 ios::sync_with_stdio ( false );
 cin.tie ( 0 );
    cin >> n;
    vector<ll> t,lv;
    rep(i, 0, n) {
        ll x; cin >> x;
        t.pb(x);
    }
    rep(i, 0, n) {
        ll x; cin >> x;
        lv.pb(x);
    }

    vector<ll> v;
    v.pb(0);
    rep(i, 0, n-1) {
        ll val = min(lv[i], lv[i+1]);
        v.pb(val);
    }
    v.pb(0);

    rep(i, 0, v.size()-1) {
        if (v[i] < v[i+1])
            v[i+1] = min(v[i]+t[i], v[i+1]);
    }
    eper(i, v.size()-1, 1) {
        if (v[i-1] > v[i])
            v[i-1] = min(v[i-1], v[i]+t[i-1]);
    }

    rep(i, 0, v.size()-1) {
        double l = v[i], r = v[i+1], limit = lv[i];
        if (l > r) swap(l, r);
        if (limit == r) {
            ans += (l + (l + t[i])) * t[i] * 0.5 - (l + t[i] - r) * (l + t[i] - r) * 0.5;
        } else {
            double x = 0.5 * (t[i] + r - l);
            double y = 0.5 * (t[i] - r + l);
            double peak = l + x - lv[i];
            if (peak < 0) peak = 0;
            x -= peak, y -= peak;
            peak *= 2;
            if (peak > 0)
                ans += ((l + l + x) * x * 0.5 + (r + r + y) * y * 0.5 + peak * lv[i]);
            else
                ans += ((l + l + x) * x * 0.5 + (r + r + y) * y * 0.5);
        }
    }
    printf("%.16f\n", ans);
    return 0;
}

