int N, t[110], v[110];
double ans, vmax[44000], vmaxR[44000];

int main() {
	rd(N);
	repi(i, 0, N) {
		int temp;
		rd(temp);
		i == 0 ? t[i] = temp : t[i] = t[i - 1] + temp;
	}
	repi(i, 0, N) rd(v[i]);

	vmax[0] = 0;

	repi(i, 0, N) {
		int cur_t;
		if (i == 0) cur_t = 1;
		else cur_t = t[i - 1] * 2 + 1;
		repi(j, cur_t, t[i] * 2 + 1) vmax[j] = min((double)v[i], vmax[j - 1] + 0.5);
	}

	vmaxR[t[N - 1]] = 0;

	repd(i, N - 1, -1) {
		int next_t;
		if (i == 0) next_t = -1;
		else next_t = t[i - 1] * 2 - 1;
		repd(j, t[i] * 2 - 1, next_t) vmaxR[j] = min((double)v[i], vmaxR[j + 1] + 0.5);
	}

	repi(i, 0, t[N - 1] * 2 + 1) {
		vmax[i] = min(vmax[i], vmaxR[i]);
	}

	repi(i, 1, t[N - 1] * 2 + 1) {
		ans += (double)(vmax[i] + vmax[i - 1]) / (double)4;
	}

	cout << fixed << setprecision(8) << ans << endl;

	return 0;
}

