using namespace std;
int main(){
    int n;
    double t[1000],v[1000],h[1000];
    cin>>n;
    for (int i=1;i<=n;i++){
        cin>>t[i];
    }t[0]=0;t[n+1]=0;
    for (int i=1;i<=n;i++){
        cin>>v[i];
        h[i]=v[i];
    }v[0]=0;v[n+1]=0;
    h[0]=0;v[n+1]=0;

    for (int i=n+1;i>=2;i--){
        if (v[i-1]>v[i])
            v[i-1]=min(v[i-1],v[i]+t[i-1]);

    }
    for (int i=0;i<=n-1;i++) {
        if (v[i + 1] > v[i])
            v[i + 1] = min(v[i + 1], v[i] + t[i + 1]);

    }
    //for (int i=1;i<=n;i++) cout<<v[i]<<" ";cout<<endl;

    double left,right,ans=0;

    for (int i=1;i<=n;i++){
        left=min(v[i-1],v[i]);
        right=min(v[i],v[i+1]);

        if (right>left) {
            double x = (t[i] + abs(right - left)) / 2.0;
            double y = (t[i] - abs(right - left)) / 2.0;
//            if (x<0||y<0)
//                cout<<left<<" "<<right<<" "<<t[i]<<endl;
//            double temp=x * x / 2.0 + y * y / 2.0 + y * (right - left) + t[i] * left;
//            cout<<temp<<"    ";
            //cout<<100.5*100.5<<" ";
            ans += x * x / 2.0 + y * y / 2.0 + y * (right - left) + t[i] * left;
            if (h[i] < left + x) {
                double l = x + left - h[i];
                ans -= l * l;
            }
        }else{

            double y = (t[i] + abs(right - left)) / 2.0;
            double x = (t[i] - abs(right - left)) / 2.0;
//            if (x<0||y<0)
//                cout<<left<<" "<<right<<" "<<t[i]<<endl;
//            double temp=x * x / 2.0 + y * y / 2.0 + y * (right - left) + t[i] * left;
//            cout<<temp<<"";
            //cout<<x<<" ";

            ans += x * x / 2.0 + y * y / 2.0 + x * (left - right) + t[i] * right;
            if (h[i] < left + x ){
                double l=x+left-h[i];
                ans-=l*l;
            }
        }
        //cout<<ans<<endl;
    }

    //cout<<ans;
    printf("%lf",ans);
}

