int main() {
    int n;
    while (cin >> n) {
        vector<double> t(n), v(n);
        rep(i, n) {
            cin >> t[i];
        }
        rep(i, n) {
            cin >> v[i];
        }
        t.push_back(0);
        v.push_back(0);

        double ans = 0;
        double cur_s = 0;
        double cur_t = 0;
        rep(i, n) {
            double end_s = min(v[i], cur_s + v[i] * t[i]);
            double p = cur_t;
            FOR(j, i, n) {
                p += t[j];
                // dump(p - (cur_t + t[i]));
                double x = v[j+1] + (p - (cur_t + t[i]));
                end_s = min(end_s, x);
            }
            dump(cur_s, end_s);
            // cur_s -> v[i] -> cur_s + t[i]
            double vm = v[i];
            double v1 = cur_s, v2 = end_s;
            double t1 = cur_t, t2 = cur_t + t[i];
            double ta = t1 + (vm - v1);
            double tb = t2 - (vm - v2);
            if (ta <= tb) {
                ans += (v1 + vm) * (ta - t1) / 2;
                ans += vm * (tb - ta);
                ans += (v2 + vm) * (t2 - tb) / 2;
            } else {
                double tc = (ta + tb) / 2;
                double vc = v1 + (tc - t1);
                dump(t1, tc, t2);
                dump(v1, vc, v2);
                ans += (v1 + vc) * (tc - t1) / 2;
                ans += (vc + v2) * (t2 - tc) / 2;
            }
            dump(ans);
            cur_t += t[i];
            cur_s = end_s;
        }
        print(ans);
    }
}

