int N;
double rec(int i,int cur) {
    if(i==N) {
        if(cur==0) return 0;
        return -INF;
    }

    if(vis[i][cur]) {
        return dp[i][cur];
    }
    vis[i][cur] = 1;
    double ans = -INF;
    double x,t1,t2,t3;
    for(int j=0;j<=v[i+1];j++) {
        int lim = min(j,v[i]);
        x = min((double)v[i],((double)(cur+lim+t[i]))/2);
        t1 = x-cur;
        t3 = x-lim;
        t2 = t[i]-t1-t3;
        if(t1>=0 and t2>=0 and t3>=0) {
            double val = 0;
            val += cur*t1+0.5*t1*t1;
            val += x*t2;
            val += x*t3-0.5*t3*t3;
            ans = max(ans,val+rec(i+1,lim));
        }
    }
    return dp[i][cur] = ans;
}
