void solve() {
  int N;
  cin >> N;
  vector<int> t(N), v(N);
  cin >> t;
  cin >> v;
  auto dp = vect(N + 1, vect(101, -1.0));
  dp[0][0] = 0.0;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j <= v[i]; j++) {
      if (dp[i][j] < 0.0) continue;
      for (int k = max(0, j - t[i]); k <= min(v[i], j + t[i]); k++) {
        if (j <= k) {
          double add = 0.0;
          double d = abs(j - k);
          double rem = (double)t[i] - d;
          double h = (double)(v[i] - k);
          add += (double)(j + k) * d / 2.0 + (double)k * rem;
          if (rem <= 2.0 * h) {
            add += rem * rem / 4.0;
          } else {
            add += h * h + (rem - h * 2.0) * h;
          }
          chmax(dp[i + 1][k], dp[i][j] + add);
        } else {
          double add = 0.0;
          double d = abs(j - k);
          double rem = (double)t[i] - d;
          double h = (double)(v[i] - j);
          add += (double)(j + k) * d / 2.0 + (double)j * rem;
          if (rem <= 2.0 * h) {
            add += rem * rem / 4.0;
          } else {
            add += h * h + (rem - h * 2.0) * h;
          }
          chmax(dp[i + 1][k], dp[i][j] + add);
        }
      }
    }
  }
  cout << dp[N][0] << endl;
  return;
}

