int main() {
    int N;
    cin >> N;
    vector<int> t(N), v(N);
    for(int i = 0; i < N; ++i) {
        cin >> t[i];
    }
    for(int i = 0; i < N; ++i) {
        cin >> v[i];
    }
    v.push_back(0);

    vector<double> dp(201, -1);
    dp[0] = 0;
    for(int i = 0; i < N; ++i) {
        vector<double> nxt(201, -1);
        for(int j = 0; j <= v[i]; ++j) {
            if(dp[j] == -1) {
                continue;
            }
            for(int nv = 0; nv <= min(v[i + 1], v[i]); ++nv) {
                if(abs(nv - j) > t[i]) {
                    continue;
                }
                double ma_v = 0;
                if(abs(v[i] - j) + abs(v[i] - nv) > t[i]) {
                    double tt = (nv - j + t[i]) * 0.5;
                    ma_v = j + tt;
                } else {
                    ma_v = v[i];
                }
                double t1 = (ma_v - j), t2 = (ma_v - nv);
                double move = (j + ma_v) / 2 * t1 + ma_v * (t[i] - t1 - t2) + (ma_v + nv) / 2 * t2;
                nxt[nv] = max(nxt[nv], dp[j] + move);
            }
        }
        dp = move(nxt);
    }
    cout << fixed << setprecision(10) << dp[0] << endl;
}

