#define ALL(obj) (obj).begin(), (obj).end()
#define INF 1e9
typedef long long ll;

vector<int> t;
vector<int> v;
vector<int> t_sum;
double ans;

void dfs(int l, int r, int h){//[l,r)はすでに速度hに達している
    //cout << l << ", " << r << ", " << h << endl;
    if(l>=r) return;

    int l_itr = upper_bound(ALL(t_sum), l) - t_sum.begin() - 1;//左端はどの区間か
    int r_itr = lower_bound(ALL(t_sum), r) - t_sum.begin() - 1;//右端はどの区間か
    //cout << "  " << l_itr << ", " << r_itr << endl;

    if(r_itr == l_itr){//[l,r)が同一区間内なら
        if(r-l >= 2*(v[r_itr]-h)){
            ans += ((r-l) - (v[r_itr]-h)) * (v[r_itr]-h);
            return;
        }else{
            ans += (r-l)*(r-l)/4.0;
            return;
        }
    }

    int min_v = INF;
    int min_itr = -1;
    FOR(i,l_itr,r_itr+1){//区間内の最小速度を求める
        if(min_v > v[i]){
            min_v = v[i];
            min_itr = i;
        }
    }
    //cout << "    " << min_v << ", " << min_itr << endl;

    if((r-l) <= 2*(min_v-h)){//台形にならないなら
        ans += (r-l)*(r-l)/4.0;
        return;
    }

    int next_l1,next_r1,next_l2,next_r2;
    next_l1 = l+min_v-h;
    next_r2 = r-min_v+h;
    next_r1 = t_sum[min_itr];
    next_l2 = t_sum[min_itr+1];
    if(next_r2 < next_r1){
        ans += ((r-l) - (r-next_r1))*(r-next_r1);
        dfs(r+l-next_r1, next_r1, h+r-next_r1);
    }else if(next_l2 < next_l1){
        //ans += ((r-l) - (next_l2-l))*(next_l2-l);
        dfs(next_l2, l-next_l2+r, h+next_l2-l);
    }else{
        ans += ((r-l) - (min_v-h))*(min_v-h);


        dfs(next_l1,next_r1,min_v);
        dfs(next_l2,next_r2,min_v);
    }
}

