int N;

vector<double> T;
vector<double> V;

vector<double> ts;
vector<double> vmax; // 区間開始時点での上限速度

pair<double,double> f(int i, double v0)
{
    // 始点を t0=0 とする

    double t1 = ts[i+1] - ts[i];

    double ta = V[i] - v0; // ずっと加速した場合に最高速度に達する時間
#ifdef DEBUG
    DBG(t1);
    DBG(ta);
#endif

    if(vmax[i+1] > V[i]) { // 減速不要な場合
        if(ta < t1) {
            double v = V[i];
            double dx = v0*ta + 0.5*(V[i]-v0)*ta + V[i]*(t1-ta);
            return make_pair(v, dx);
        }
        else {
            double v = v0 + t1;
            double dx = v0*t1 + 0.5*(v-v0)*t1;
            return make_pair(v, dx);
        }
    }

    // 減速タイミングを求める
    double lo = 0;
    double hi = t1;
    while(hi - lo > EPS) {
        double mid = (hi+lo) / 2.0;
        if(min(V[i], v0+mid) - (t1-mid) <= vmax[i+1]) { // OK
            lo = mid;
            //DBG(lo);
        }
        else { // NG
            hi = mid;
            //DBG(hi);
        }
    }
    double tb = lo;
#ifdef DEBUG
    DBG(tb);
#endif

    if(ta < tb) {
        double v = vmax[i+1];
        double dx = v0*ta + 0.5*(V[i]-v0)*ta +
                    V[i]*(tb-ta) +
                    vmax[i+1]*(t1-tb) + 0.5*(V[i]-vmax[i+1])*(t1-tb);
        return make_pair(v, dx);
    }
    else {
        double v = vmax[i+1];
        double dx = v0*tb + 0.5*tb*tb +
                    vmax[i+1]*(t1-tb) + 0.5*(v0+tb-vmax[i+1])*(t1-tb);
        return make_pair(v, dx);
    }
}

void solve()
{
    ts.resize(N+1);
    vmax.resize(N+1);

    ts[0] = 0.0;
    ALL(partial_sum, T, begin(ts)+1);
#ifdef DEBUG
    DBG(ts);
#endif

    V.emplace_back(0.0);
    vmax[N] = 0.0;

    FOR(i, 0, N) {
        vmax[i] = V[i];
        FOR(j, i+1, N+1) {
            double dt = ts[j] - ts[i];
            chmin(vmax[i], V[j] + dt);
        }
    }
#ifdef DEBUG
    DBG(vmax);
#endif

    double v = 0.0;
    double x = 0.0;
    FOR(i, 0, N) {
        double dx;
        tie(v,dx) = f(i, v);
        x += dx;
#ifdef DEBUG
        DBG(v);
        DBG(dx);
        DBG(x);
#endif
    }

    PRINTLN(x);
}

