double C(int n,double x) {
	if (x <= s[n]) return v[n] + s[n] - x;
	else if (x <= t[n]) return double(v[n]);
	else return v[n] + x - t[n];
}

void solve() {
	double ans = 0;
	double bv = 0; // 直前の速度
