    dp[0][0] = 0;
    REP(i, N) {
        REP(v_begin, v[i] + 1) {
            if (dp[i][v_begin] == -1) {
                continue;
            }
            FOR(v_end, max(0, v_begin - t[i]), min(v[i], v_begin + t[i]) + 1) {
                int t0 = abs(v_end - v_begin);
                int t1 = t[i] - t0;
                double x0 = (v_begin + v_end) * t0 * 0.5;
                int v0 = max(v_begin, v_end);
                double v1 = min((double)v[i], v0 + t1 * 0.5);
                double t2 = v1 - v0;
                double t3 = t1 - 2 * t2;
                double x1 = (v0 + v1) * t2 + v1 * t3;
                double x = x0 + x1;
                double dp_new = dp[i][v_begin] + x;
                assert(t1 >= 0 && t2 >= 0 && t3 >= 0);
                if (dp[i + 1][v_end] == -1 || dp[i + 1][v_end] < dp_new) {
                    dp[i + 1][v_end] = dp_new;
                }
            }
        }
    }
    cout << dp[N][0] << endl;

