int main() {
  int64_t n;
  std::cin >> n;
  std::vector<int64_t> t(n), v(n);
  for (auto &i : t) {
    std::cin >> i;
  }

  for (auto &i : v) {
    std::cin >> i;
  }

  std::vector<int64_t> t_b(n), t_e(n);
  t_b[0] = 0;
  for (int64_t i = 1; i < n; i++) {
    t_b[i] = t_b[i - 1] + t[i - 1];
  }
  t_e[0] = t[0];
  for (int64_t i = 1; i < n; i++) {
    t_e[i] = t_e[i - 1] + t[i];
  }
  const auto t_max = std::accumulate(t.cbegin(), t.cend(), 0);
  std::vector<double> v_ans(t_max * 2 + 1);

  for (int64_t i = 0; i < v_ans.size(); i++) {
    const double time = i * 0.5;
    v_ans[i] = std::min(time, t_max - time);
    for (int j = 0; j < n; j++) {
      if (time < t_b[j]) {
        v_ans[i] = std::min(v_ans[i], t_b[j] - time + v[j]);
      } else if (t_b[j] <= time && time <= t_e[j]) {
        v_ans[i] = std::min<double>(v_ans[i], v[j]);
      } else {
        v_ans[i] = std::min(v_ans[i], time - t_e[j] + v[j]);
      }
    }
  }
  double l = 0;
  for (int64_t i = 0; i < v_ans.size() - 1; i++) {
    l += 0.25 * (v_ans[i] + v_ans[i + 1]);
  }
  std::cout << l << std::endl;
  return 0;
}

