class line {
public:
    int velocity;
    int start;
    int end;

    double calc(double time) {
        if (time >= start && time <= end) {
            return velocity;
        } else if (time < start) {
            return (start - time) + velocity;
        } else if (time > end) {
            return (time - end) + velocity;
        } else {
            throw;
        }
    }
};

