            if(s < last)
                A[i][s] = v + (last-s);
            else if(s <= t)
                A[i][s] = v;
            else
                A[i][s] = v + (s - t);
        }
        last = t;
    }

    int v = 0;
    ll S = 0;
    for(int t = 1; t < T[N]; t++){
