#define REP(i, n) for(int i=0; i<n; i++)

int T[110];
int V[110];
#define TIME 200*100+1000
int A[110][TIME];

int main(){
    int N;
    cin >> N;
    REP(i,N){
        int t;
        cin >> t;
        //T[i] = 2*t;
        T[i] = 2*t;
        if(i != 0) T[i] += T[i-1];
    }
    T[N] = T[N-1];

    REP(i,N){
        int v;
        cin >> v;
        V[i] = 2*v;
    }
    V[N] = 0;

    int last = 0;
    REP(i,N+1){
        int t = T[i];
        int v = V[i];
        REP(s,TIME){
            if(s < last)
                A[i][s] = v + (last-s);
            else if(s <= t)
                A[i][s] = v;
            else
                A[i][s] = v + (s - t);
        }
        last = t;
    }

    int v = 0;
    double S = 0;
    for(int t = 1; t < T[N]+1; t++){
        int lim = 300;
        for(int i = 0; i < N+1; i++){
            lim = min(lim, A[i][t]);
        }
        int vv = v;
        if(v+1 <= lim) v++;
        else if(v > lim) v--;
        //S += min(vv, v) + 0.5*abs(vv-v);
        S += min(vv, v);
        if(v > vv) S += v-vv;
    }

    printf("%.20lf\n", S/4);
    return 0;
}

