    int goal[N + 2] = {};
    for (int i = 1; i <= N; i++)
    {
        cin >> t;
        goal[i] = start[i] + 2 * t;
        start[i + 1] = goal[i];
    }
    goal[N + 1] = goal[N];

    int v[N + 2] = {};
    for (int i = 1; i <= N; i++)
    {
        cin >> v[i];
        v[i] *= 2;
    }

    vector<int> x(goal[N] + 1, INT_MAX);
