    int ans = 0;
    for (int i = 1; i < goal[N] + 1; i++)
    {
        for (int j = 0; j < N + 2; j++)
        {
            if (i < start[j])
            {
                x[i] = min(x[i], v[j] + start[j] - i);
            }
            else if (goal[j] < i)
            {
                x[i] = min(x[i], v[j] + i - goal[j]);
            }
            else
            {
                x[i] = min(x[i], v[j]);
            }
        }
        ans += x[i - 1] + x[i];
    }
