typedef long long ll;

int main(){
    int N;  cin >> N;
    vector<int> t(N+1,0),v(N+2,0);
    for(int i=1; i<=N; i++) {
        cin >> t[i];
        t[i] += t[i-1];
    }
    int T = t[N];
    for(int i=1; i<=N; i++) cin >> v[i];

    vector<double> maxV(2*T+1,0);
    for(int i=1; i<=N; i++){
        int tl = t[i-1], tr = t[i];
        maxV[2*tl] = min(v[i-1],v[i]);
        for(int j = 2*tl+1; j < 2*tr; j++){
            maxV[j] = v[i];
        }
    }

    for(int i=0; i<N; i++){
        int tl = t[i];
        int vb = min(v[i],v[i+1]);
        for(int j=2*tl; j<=2*T; j++){
            maxV[j] = min(maxV[j], vb + 0.5*(j-2*tl));
        }
    }

    for(int i=N; i>0; i--){
        int tr = t[i];
        int vb = min(v[i], v[i+1]);
        for(int j=2*tr; j>=0; j--){
            maxV[j] = min(maxV[j], vb + 0.5*(2*tr-j));
        }
    }

    double ans = 0.0;
    for(int i=0; i<=2*T-1; i++){
        if(maxV[i]==maxV[i+1]) ans += maxV[i]*0.5;
        else ans += (maxV[i] + maxV[i+1])*0.5/2;
    }
    cout << setprecision(5) << ans << endl;
}

