struct I
{
	int l,r,v;
	I(int l, int r, int v) : l(l),r(r),v(v) {}
	double f(double t) {
		if(t>r) return v+t-r;
		if(t<l) return v+l-t;
		return v;
	}
};

signed main() {
	int n;
	std::cin >> n;
	std::vector<I> c;
	int tl=0;
	{
		std::vector<int> t(n),v(n);
		rep(i,n) std::cin >> t[i];
		rep(i,n) std::cin >> v[i];
		c.emplace_back(0,0,0);
		rep(i,n) {
			c.emplace_back(tl,t[i]+tl,v[i]);
			tl+=t[i];
		}
		c.emplace_back(tl,tl,0);
	}
	debug(tl);
	double sum=0;
	for(int ct2=0;ct2<tl*2;ct2++) {
		double ct=ct2*0.5;
		double dt=0.5;
		double min0=1e9,min1=1e9;
		for(auto x:c) {
			min0=std::min(min0,x.f(ct));
			min1=std::min(min1,x.f(ct+dt));
		}
		sum+=(min0+min1)*dt*0.5;
	}
