int main() {
  int n;
  scanf("%d", &n);
  n += 2;
  vector<ii> seg(n);
  vector<double> v(n);
  int sum = 0;
  vector<double> A;
  for (int i = 1; i < n - 1; ++i) {
    int x;
    scanf("%d", &x);
    seg[i].first = sum;
    sum += x;
    seg[i].second = sum;
    A.push_back(seg[i].first);
    A.push_back(seg[i].second);
  }
  for (int i = 1; i < n - 1; ++i) {
    scanf("%lf", &v[i]);
  }
  v[0] = v[n - 1] = 0;
  seg[0] = {-1, 0};
  seg[n - 1] = {sum, sum + 1};
  for (int i = 1; i < n - 1; ++i) {
    for (int j = 0; j < i; ++j) {
      if (v[j] >= v[i]) continue;
      int cur = v[i] - v[j] + seg[j].second;
      if (cur > seg[i].first && cur < seg[i].second) {
        A.push_back(cur);
      }
    }
    for (int j = i + 1; j < n; ++j) {
      if (v[j] >= v[i]) continue;
      int cur = seg[j].first - (v[i] - v[j]);
      if (cur > seg[i].first && cur < seg[i].second) {
        A.push_back(cur);
      }
    }
  }
  for (int i = 0; i < n; ++i) {
    for (int j = i + 1; j < n; ++j) {
      double cur = (seg[j].first + v[j] + seg[i].second - v[i]) * 0.5;
      if (cur > seg[i].first && cur < seg[j].second) {
        A.push_back(cur);
      }
    }
  }
  sort(A.begin(), A.end());
  A.erase(unique(A.begin(), A.end()), A.end());
  double ret = 0.0;
  for (int i = 1; i < A.size(); ++i) {
    double L = A[i - 1], R = A[i];
    double x = min(L, sum - L), y = min(R, sum - R);
    for (int j = 0; j < n; ++j) {
      if (L >= seg[j].first && R <= seg[j].second) {
        x = min(x, v[j]);
        y = min(y, v[j]);
      } else if (L >= seg[j].second) {
        x = min(x, v[j] + L - seg[j].second);
        y = min(y, v[j] + R - seg[j].second);
      } else {
        x = min(x, v[j] + seg[j].first - L);
        y = min(y, v[j] + seg[j].first - R);
      }
    }
    // trace(L, R, x, y);
    ret += 0.5 * (R - L) * (x + y);
  }
  printf("%.10f\n", ret);
  return 0;
}

