            } else if (j < nowt*2) {
                ld tt = (nowt*2-j)*0.5+v[i];
                chmin(a[j], tt);
            } else {
                ld tt = (j-(nowt+t[i])*2)*0.5+v[i];
                chmin(a[j], tt);
            }
        }
        nowt += t[i];
    }
    for(int i = 0; i < sumT*2+1; i++) {
        if(i <= sumT) {
            chmin(a[i], (ld)i*0.5);
        }else {
            chmin(a[i], sumT-(ld)i*0.5);
