                else if(dp[x-1][u]>=0)dp[x][u]=dp[x-1][u]+u;
                else if(dp[x-1][u-1]>=0)dp[x][u]=dp[x-1][u-1]+u-0.5;
                else dp[x][u]=-1;
            }
        }
        if(x==t[id]){
            vmax=v[++id];
        }
    }
    cout<<dp[t[n]][0]/4<<endl;
}

