//const int MAX_N=2*100*200+1;
const int MAX_N=1e6+10;
int N;
int V[100],T[100];
int v[MAX_N];
void solve() {
  REPE(i,MAX_N) v[i]=1e8;
  int t=0;
  v[0]=0;
  REP(i,N) {
    int vv=V[i];
    int du=T[i];
    SMIN(v[t],vv);
    REP(_,du) ++t,SMIN(v[t],vv);
//    cout<<i<<","<<t<<endl;
  }
  SMIN(v[t],0);
  int T=t;
  FORE(i,1,T) {
//    if(i==140)cout<<v[i]<<","<<v[i-1]+1<<endl;
    SMIN(v[i],v[i-1]+1);
  }
  for(int i=T-1; i>=0; --i) {
//    if(i==140)cout<<v[i]<<","<<v[i+1]+1<<endl;
    SMIN(v[i],v[i+1]+1);
  }
