        ans += (nv[i + 1] + ma) * (t[i] - tmp) / 2;
        if (ma > v[i]) {
            int d = t[i] - (2 * v[i] - nowv - nv[i + 1]);
            ans -= d * (ma - v[i]) / 2;
        }
        nowv = nv[i + 1];
    }

    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

