#include<iostream>
#include<algorithm>
using namespace std;

double v_max[40010];
double time_seq[105], v_seq[105];

int main() {
    int N;
    double dist_sum = 0.0;
    cin >> N;
    time_seq[0] = 0.0;
    v_seq[0] = 0.0;
    for (int i = 1; i <= N; i++) {
        cin >> time_seq[i];
        time_seq[i] += time_seq[i - 1];
    }
    for (int i = 1; i <= N; i++) cin >> v_seq[i];

    // 時間0から徐々に加速する場合の速度の書き込み
    for (int i = 0; i <= 2 * time_seq[N]; i++) v_max[i] = 0.5 * i;
    // 入力された各区間の最大速度を考慮した各時間における速度の書き込み
    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= 2 * time_seq[N]; j++) {
            if (0.5 * j <= time_seq[i - 1]) {
                v_max[j] = min(v_max[j], v_seq[i] + (time_seq[i - 1] - (double)0.5 * j)); 
            }
            else if (0.5 * j > time_seq[i - 1] && 0.5 * j <= time_seq[i]) {
                v_max[j] = min(v_max[j], v_seq[i]);
            }
            else {
                v_max[j] = min(v_max[j], v_seq[i] + ((double)0.5 * j - time_seq[i]));
            }
        }
    }
    // 時間0から徐々に減速していく場合の速度の書き込み
    for (int i = 0; i <= 2 * time_seq[N]; i++) v_max[i] = min(v_max[i], time_seq[N] - (double)0.5 * i);

    for (int i = 0; i < 2 * time_seq[N]; i++) {
        dist_sum += (double)0.25 * (v_max[i] + v_max[i + 1]);
    }

    cout << dist_sum << endl;

    return 0;

}

