	L[N+1] = R[N+1] = tot;
//	DD(L);DD(R);DD(V);

	auto f = [&](int i, double t) {
		if(L[i]<=t && t<=R[i]) return (double)V[i];
		return V[i]+min(abs(t-L[i]), abs(t-R[i]));
	};
	auto ff = [&](double t) {
		double v = 1e100;
		REP(i, L.size()) v = min(v, f(i, t));
