double speed_limit(int cond_j, double time, int* t, int* v) {
  if (time < t[cond_j-1]) {
    return v[cond_j] + t[cond_j-1] - time;
  } else if (time < t[cond_j]) {
    return v[cond_j];
  } else {
    return v[cond_j] + time - t[cond_j];
  }
}

