	rep(i, N) { in >> v[i]; }

	rep(i, N)
	{
		if (v[i] <= v[i + 1])
		{
			long double plus;
			auto sp_ = sp;
			if (v[i] - sp <= t[i])
			{
				plus = v[i] - sp;
				sp = v[i];
				ans += sp*(t[i] - plus);
			}
			else
			{
				sp += t[i];
				plus = t[i];
			}
			ans += sp_*plus + plus*plus / 2;
		}
		else
		{
			long double plus, minu;
			if (sp <= v[i + 1])
			{
				auto dis = t[i] - (v[i + 1] - sp);
				if ((v[i] - sp) + (v[i] - v[i + 1]) <= t[i])
				{
					ans += v[i] * ((t[i]) - ((v[i] - sp) + (v[i] - v[i + 1])));
					dis -= (t[i]) - ((v[i] - sp) + (v[i] - v[i + 1]));
				}
				plus = dis / 2 + (v[i + 1] - sp);
				minu = dis / 2;
				ans += sp*plus + plus*plus / 2 + v[i + 1] * minu + minu*minu / 2;
			}
			else
			{
				auto dis = t[i] - (sp - v[i + 1]);
				if ((v[i] - sp) + (v[i] - v[i + 1]) <= t[i])
