struct _f {
	ll v, l, r;
	_f() {}
	_f(ll v, ll l, ll r) :v(v), l(l), r(r) {}
};
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
	ll N; cin >> N;
	vector<ll> t(N), v(N);
	for (int i = 0; i < N;i++) cin >> t[i];
	for (int i = 0; i < N;i++) cin >> v[i];

	vector<_f> F; F.push_back(_f(0, 0, 0));
	ll t_sum = 0;
	for (int i = 0; i < N;i++) {
		F.push_back(_f(v[i], t_sum, t_sum + t[i]));
		t_sum += t[i];
	}
	F.push_back(_f(0, t_sum, t_sum));

	double res = 0.0;
	double pre_v = 0.0;
	for (double T = 0.5; T <= t_sum;T += 0.5) {
		double next_v = INF;
		for (auto _F : F) {
			if (T <= _F.l) {
				next_v = min(next_v, (double)(_F.v + (_F.l - T)));
			}
			else if (T >= _F.r) {
				next_v = min(next_v, (double)(_F.v + (T - _F.r)));
			}
			else {
				next_v = min(next_v, (double)_F.v);
			}
		}
		res += (pre_v + next_v)*0.5 / 2.0;
		pre_v = next_v;
	}
	cout << fixed << setprecision(10) << res << endl;
	return 0;
}

