			mi[j] = min(mi[j], v[i]), tmp[j] = mi[j];
	for (int i = 0; i <= t[n-1]; i++) mi[i] = min(mi[i], min(miF[i],miB[i]));
	for (int i = 0; i < t[n-1]; i++) {
		if (mi[i] == mi[i+1] && (mi[i] != tmp[i] || mi[i+1] != tmp[i+1]))
			ans++;
		ans += 2*(mi[i+1]+mi[i]);
	}
	printf("%.10f\n", (double)ans/4.);
