typedef long long ll;
int const inf = 1<<29;

int N;

struct F {
  double t1, t2, a, b;
};
vector<F> funcs;

double calc_b(double a, double y1, double x1) {
  // y1 = a * x1 + b;
  return y1 - a * x1;
}

void make_f_set(vector<double> const& ts, vector<double> const& vs) {
  rep(i, N) {
    if (i) {
      {
        auto b = calc_b(-1, vs[i], ts[i - 1]);
        funcs.push_back(F{0, ts[i - 1], -1, b});
      }
      {
        auto b = calc_b(+1, vs[i], ts[i]);
        funcs.push_back(F{ts[i], ts.back(), +1, b});
      }
      {
        auto b = vs[i];
        funcs.push_back(F{ts[i - 1], ts[i], 0, b});
      }
    }
    if (i == 0) {
      funcs.push_back(F{0, ts[0], +1, 0});
    }
    if (i == N - 1) {
      funcs.push_back(F{i ? ts[i - 1] : 0, ts[i], -1, calc_b(-1, 0, ts[N - 1])});
    }
  }
  rep(i, N) {
    funcs.push_back(F{(i > 0 ? ts[i - 1] : 0), ts[i], 0, vs[i]});
  }
  funcs.push_back(F{0, 0, 0, 0});
  funcs.push_back(F{ts.back(), ts.back(), 0, 0});
}

double calc_v(double t, F addf = {}) {
  double ret = inf;
  for (auto f: funcs) {
    if (t < f.t1 || f.t2 < t) continue;
    minimize(ret, f.a * t + f.b);
  }
  {
    if (t < addf.t1 || addf.t2 < t) return ret;
    minimize(ret, addf.a * t + addf.b);
  }
  return ret;
}

int main() {
  cin >> N;
  vector<double> ts(N);
  rep(i, N) {
    cin >> ts[i];
    if (i) ts[i] += ts[i - 1];
  }
  vector<double> vs(N);
  rep(i, N) {
    cin >> vs[i];
  }
  make_f_set(ts, vs);
  double prevv = 0.0;
  double ans = 0.0;
  for (double t = 0; t <= ts.back(); t += 0.5) {
    double currv = -inf;
    if (t >= 0.5) {
      currv = calc_v(t, F{t - 0.5, t, +1, calc_b(+1, prevv, t - 0.5)});
    } else {
      currv = calc_v(t);
    }
    ans += (currv + prevv) * 0.5 / 2.0;
    prevv = currv;
  }
  printf("%.12f\n", ans);
}

