  for (auto i : irange(1L, n + 1)) {
    auto dt1 = t1[i] - t[i - 1];
    auto dt2 = t2[i] - t1[i];
    auto dt3 = t[i] - t2[i];
    ans += vv[i - 1] * dt1 + dt1 * dt1 / 2.0;
    ans += (vv[i - 1] + dt1) * dt2;
    ans += vv[i] * dt3 + dt3 * dt3 / 2.0;
  }

  cout << setprecision(10) << ans << endl;
}

