        // 区間内で加速、等速、減速となる秒数を考える
        // なるべく減速区間を短くしたい
        float aTime, eTIme, dTime;
        int nextMaxV;
        if (i == N - 1)
        {
            nextMaxV = 0;
        }
        else
        {
            float nextNextV;
            if (i == N - 2)
            {
                nextNextV = 0;
            }
            else
            {
                nextNextV = v[i + 2];
            }
            if (v[i + 1] - nextNextV > t[i + 1])
            {
                nextMaxV = nextNextV + t[i + 1];
            }
            else
            {
                nextMaxV = v[i + 1];
            }
        }

        if (v[i] > nextMaxV)
        {
            if (v[i] - nextMaxV > t[i])
            {
                float maxV = (t[i] + stV + nextMaxV) / 2;
                aTime = maxV - stV;
                dTime = maxV - nextMaxV;
                ans += (maxV + stV) * aTime / 2 + (maxV + nextMaxV) * dTime /2;
            }
            else
            {
                aTime = v[i] - stV;
                dTime = v[i] - nextMaxV;
                eTIme = t[i] - aTime - dTime;
                ans += (v[i] + stV) * aTime / 2 + v[i] * eTIme + (v[i] + nextMaxV) * dTime / 2;
            }
            endV = nextMaxV;
        }
        else
        {
            aTime = v[i] - stV;
            eTIme = t[i] - aTime;
            ans += (v[i] + stV) * aTime / 2 + v[i] * eTIme;
            endV = v[i];
        }
    }

    printf("%.6f\n", ans);
}

