typedef long long ll;
int const inf = 1<<29;

int N;

struct F {
  double t1, t2, a, b;
};
vector<F> funcs;

double calc_b(double a, double y1, double x1) {
  // y1 = a * x1 + b;
  return y1 - a * x1;
}

void p(double t1, double t2, double a, double b) {
//  printf("%.f %.f %.f %.f\n", t1, t2, a, b);
  funcs.push_back(F{t1, t2, a, b});
}

void make_f_set(vector<double> const& ts, vector<double> const& vs) {
  rep(i, N) {
    if (i) {
      auto b = calc_b(-1, vs[i], ts[i - 1]);
      p(0, ts[i - 1], -1, b);
    }
    if (i < N - 1) {
      auto b = calc_b(+1, vs[i], ts[i]);
      p(ts[i], ts.back(), +1, b);
    }
    {
      auto b = vs[i];
      p(i ? ts[i - 1] : 0, ts[i], 0, b);
    }
  }
  p(0, ts[0], +1, 0);
  p(N > 1 ? ts[N - 2] : 0, ts.back(), -1, calc_b(-1, 0, ts.back()));
}

double calc_v(double t) {
  double ret = inf;
  for (auto f: funcs) {
    if (t < f.t1 - 0.001 || f.t2 + 0.001 < t) continue;
    minimize(ret, f.a * t + f.b);
  }
  return ret;
}

int main() {
  cin >> N;
  vector<double> ts(N);
  rep(i, N) {
    cin >> ts[i];
    if (i) ts[i] += ts[i - 1];
  }
  vector<double> vs(N);
  rep(i, N) {
    cin >> vs[i];
  }
  make_f_set(ts, vs);
  double prevv = 0.0;
  double ans = 0.0;
  for (double t = 0.5; t <= ts.back() + 0.001; t += 0.5) {
    double currv = calc_v(t);
    ans += (currv + prevv) / 4.0;
    prevv = currv;
  }
  printf("%.12f\n", ans);
}

