double epsilon = 1e-10;

using namespace std;

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    vector<double> time(N, 0), limit(N, 0);

    for (int i = 0; i < N; i++)
    {
        if (scanf("%lf", &time[i]) < 1) return 0;
    }

    for (int i = 0; i < N; i++)
    {
        if (scanf("%lf", &limit[i]) < 1) return 0;
    }

    double bk = 0.0;
    int idx = 0;

    int accTime = (signed int)accumulate(time.begin(), time.end(), 0.0);

    // 0.5 単位 制限
    vector<double> limitv(2 * accTime + 1, 0);

    for (int i = 1; i <= 2 * accTime; i++)
    {
        // i * 0.5 < bk + time[idx]
        if (epsilon < bk + time[idx] - i * 0.5) limitv[i] = limit[idx];
        // i * 0.5 = bk + time[idx]
        else if (fabs(bk + time[idx] - i * 0.5) <= epsilon)
        {
            if (idx == N - 1) limitv[i] = limit[idx];
            else
            {
                double dif = limit[idx + 1] - limit[idx];
                if (epsilon < dif) limitv[i] = limit[idx];
                else bk += time[idx], idx++, limitv[i] = limit[idx];
            }
        }
        else if (idx < N - 1) bk += time[idx], idx++, limitv[i] = limit[idx];
    }

    // 0.5 単位 速度
    vector<double> maxv(2 * accTime + 1, 0);

    // 上り 更新
    // 最終地点は zero 初期化した状態
    for (int i = 1; i <= 2 * accTime - 1; i++)
        maxv[i] = min(limitv[i], maxv[i - 1] + 0.5);

    // 下り 更新
    // 上り で更新した値が最小であるならば 採用
    for (int i = 2 * accTime - 1; 0 <= i; i--)
    {
        double tmp = min(maxv[i], limitv[i]);
        maxv[i] = min(tmp, maxv[i + 1] + 0.5);
    }

    // 0.5 単位 距離
    double ans = 0.0;

    // (上底 + 下底) * 高さ * 0.5(割る2)
    for (int i = 1; i <= 2 * accTime; i++)
        ans += (maxv[i - 1] + maxv[i]) * 0.5 * 0.5;

    printf("%f\n", ans);
    return 0;
}

