void solve() {
	cin >> N;
	rep(i, N) {
		cin >> t[i + 1];
		t[i + 1] *= 2;
		t[i + 1] += t[i];
	}
	rep(i, N) {
		cin >> v[i + 1];
		v[i + 1] *= 2;
