	rep(i, t[N]) mx[i + 1] = min(mx[i] + 1, mx[i + 1]);
	revrep(i, t[N]) mx[i] = min(mx[i + 1] + 1, mx[i]);
	rep(i, t[N]) {
		ans += (double)(mx[i] + mx[i + 1]) / 2;
	}
	ans /= 4;
	printf("%.5lf\n", ans);
}

