const long long INF = 1 << 29;
const double EPS = 1e-9;
const ll MOD = 1000000007;

const long long dx[] = {1, 0, -1, 0}, dy[] = {0, -1, 0, 1};
const long long MAX_NV = 110;
const long long MAX_T = 210;

long long N;
vector<long long> T,V;
map<long long, long long> limits;
long double dp[MAX_NV * MAX_T][MAX_NV * 2];
long long sum;
long double memo(long long pos, long long v){
    if (v < 0){
      return -INF;
    }

    if (v > limits[pos]){
      return -INF;
    }
    if (pos >= sum){
      if (v == 0){
        return 0;
      }
      return -INF;
    }

    long double &res = dp[pos][v];
    if (res > -2 * INF){
      return res;
    }
    res = -INF;
    res = max(res, memo(pos + 1, v) + v);
    if (v < limits[pos]){
      res = max(res, memo(pos + 1, v + 1) + v + 0.5);
    }

    res = max(res, memo(pos + 1, v - 1) + v - 0.5);
    return res;
}

int main() {
  cin >> N;
  T.resize(N);
  V.resize(N);
  for (long long i = 0; i < N; i++){
    cin >> T[i];
    T[i] *= 2;
    sum += T[i];
  }
  for (long long i = 0; i < N; i++){
    cin >> V[i];
    V[i] *= 2;
  }
  for (long long i = 1; i < N; i++){
    T[i] += T[i - 1];
  }
  long long pre = 0;
  for (long long i = 0; i < N; i++){
    for (long long j = pre; j <= T[i]; j++){
      limits[j] = V[i];
    }
    pre = T[i];
  }
  // double dp[MAX_NV * MAX_T][MAX_NV * 2];
  for (long long i = 0; i < MAX_NV * MAX_T; i++){
    for (long long j = 0; j < MAX_NV * 2; j++){
      dp[i][j] = -2 * INF;
    }
  }
  long double result = (long double)memo(0, 0) / 4;
  if (result <= 0){
    result = 0;
  }
  printf("%.20lf\n", result);
  return 0;
}

