using namespace std;

int main() {
	cin.tie(nullptr);
	ios_base::sync_with_stdio(false);

	int n;
	cin >> n;

	vector<int> seconds(n);
	vector<int> max_speeds(n);

	for (int i = 0; i < (int) seconds.size(); ++i) {
		cin >> seconds[i];
		if (i != 0)
			seconds[i] += seconds[i - 1];
	}

	for (int i = 0; i < (int) max_speeds.size(); ++i) {
		cin >> max_speeds[i];
	}

	int max_time = seconds[n - 1];

	const int INF = 1e9;
	vector<vector<double>> dp(max_time + 1);//dp[i][j] - distance at the end of i second, if we have speed j;

	for (int i = 0; i <= max_time; ++i) {
		dp[i].resize(101, -INF);
	}

	dp[0][0] = 0;

	for (int i = 1; i <= max_time; ++i) {
		int max_speed = max_speeds[0];
		for (int j = 1; j < (int) seconds.size(); ++j) {
			if (i > seconds[j - 1] && i <= seconds[j])
				max_speed = max_speeds[j];
		}
		for (int j = 0; j <= max_speed; ++j) {
			if (j != 0 && dp[i - 1][j - 1] != -INF) 
				dp[i][j] = max(dp[i - 1][j - 1] + (double)(j + (j - 1)) / 2, dp[i][j]);

			if (j != max_speed && dp[i - 1][j + 1] != -INF)
				dp[i][j] = max(dp[i - 1][j + 1] + (double)(j + j + 1) / 2, dp[i][j]);

			if (dp[i - 1][j] != -INF)
				dp[i][j] = max(dp[i - 1][j] + j, dp[i][j]);

			if (dp[i - 1][j] != -INF && j != max_speed) 
				dp[i][j] = max(dp[i - 1][j] + (j + j + 0.5f) / 2, dp[i][j]);
		}
	}

	cout << dp[max_time][0] << endl;

	return 0;
}

