using namespace std;

vector<double> solve(int n , vi t , vi v){
	int tot = 0;
	vi fr(n);
	rep(i , n){
		tot += t[i];
		fr[i] = tot;
	}
	vector<double> res(tot + 1);
	int k = 0;
	++tot;
	rep(i , tot){
		if(i > fr[k])++k;
		if(i == 0){
			res[0] = 0;
		}else{
			res[i] = min(1.0 * v[k] , res[i - 1] + 1);
		}
	}
	return res;
}

double f(int t1 , int t2 , double spd1 , double spd2 , double lim){
	if(abs(lim - spd1) < 1e-9)return spd1;
	if(spd2 > spd1)return spd1;
	if(spd2 < spd1)return spd1;
	double l = t1;
	double r = t2;
	rep(i , 200){
		double mid = (r + l) / 2;
		double cs1 = min(lim , spd1 + (mid - 1.0 * t1));
		double cs2 = min(lim , spd2 + (1.0 * t2 - mid));
		if(cs1 - 1e-7 <= cs2){
			l = mid;
		}else{
			r = mid;
		}
	}
	double spdl = min(lim , spd1 + (l - 1.0 * t1));
	double spdr = min(lim , spd2 + (1.0 * t2 - l));
//	cout << t1 << " " << spd1 << " " << lim << nl;
	return abs(l - 1.0 * t1) * (spdl + spd1) / 2.0 + abs(1.0 * t2 - r) * (spdr + spd2) / 2.0;
}

