const LL INF = 12345678901234;
LL memo[234*234][234];
LL dp(int sec, int sp) {
	if (sp < 0)return -INF;
	if (sec == 0) {
		if (sp != 0)return -INF;
		return 0;
	}
	if (memo[sec][sp] != -1)return memo[sec][sp];
	if (sp > tab[sec - 1])return -INF;
	LL a = dp(sec - 1, sp + 1) + (sp + sp + 1);//減速
	LL b = dp(sec - 1, sp) + (sp + sp);//等速
	LL c = dp(sec - 1, sp - 1) + (sp + sp - 1);//加速
	LL res = max(b, c);
	if (sp + 1 <= tab[sec - 1])res = max(res, a);
	return memo[sec][sp] = res;
}

