int hantei(int t, int ve, int i){
    int nv;
    if(t <= T[i]){
        nv = (v[i] + (T[i]-t)); 
    }
    else if(t > T[i+1]){
        nv = (v[i] + (t-T[i+1]));
    }
    else{
        nv = v[i]; 
    }
    if(nv > ve) return 1;
    else if(nv < ve) return -1;
    else return 0;
}

