int _main()
{
        ll n;
        llin(n);

        V<ll> tlist;
        llina(tlist, n);

        V<ll> vlist;
        llina(vlist, n);
        vlist.pb(0LL);

        V<ll> tsumlist;
        ll last = 0LL;
        rep (i, n) {
                tsumlist.pb(last + tlist[i]);
                last += tlist[i];
        }

        ll start_v = 0LL;
        ll last_v;
        double ans = 0.0;

        rep (i, n) {

                ll last_max_v = vlist[i];
                for (int j = i + 1; j < n + 1; ++j) {
                        ll aim_v = vlist[j] + (tsumlist[j-1] - tsumlist[i]);
                        last_max_v = min(last_max_v, aim_v);
                }

                last_v = min(last_max_v, start_v + tlist[i]);

                double border_time = ((double)(tlist[i] + last_v - start_v)) / 2.0;
                double get_max_time = vlist[i] - start_v;
                double brake_time = tlist[i] + last_v - vlist[i];

                double border_v = start_v + border_time;
                ans += ((double)((start_v + border_v) * border_time)) / 2.0;
                ans += ((double)((border_v + last_v) * (tlist[i] - border_time))) / 2.0;
                if (get_max_time < brake_time) {
                        ans -= ((brake_time - get_max_time) * (border_v - vlist[i])) / 2.0;
                }

                start_v = last_v;
        }

        cout << ans;

        return 0;
}

