  double prevv = 0.0;
  double ans = 0.0;
  for (double t = 0.5; t <= ts.back() + 0.001; t += 0.5) {
    double currv = calc_v(t);
    ans += (currv + prevv) / 4.0;
    prevv = currv;
  }
  printf("%.12f\n", ans);
}

