signed main(){
    cin >> n;
    rep(i, 0, n) cin >> t[i];
    rep(i, 0, n) cin >> v[i];
    v[n] = 0;
    double now = 0;
    double ans = 0;
    rep(i, 0, n){
        double tm = t[i];
        double limit = v[i] - now;
        double next = v[i + 1] - now;
        // cout << now << " " << tm << " " << limit << " " << next  << endl;
        if(limit < next) next = limit;        
        double tmp = now * tm;
        if(next >= 0){
            if(tm < next){
                tmp += 0.5 * tm * tm;
                now += tm;
            }else{
                tmp += 0.5 * next * next;
                now += next;
                double high = min(limit, next + (tm - next) * 0.5);
                tmp += next * (tm - next) + (high - next) * (tm - high);
            }
        }else{
            if(tm < abs(next)){
                tmp -= 0.5 * tm * tm;
                now -= tm;
            }else{
                tmp -= 0.5 * next * next;
                double high = min(limit, (tm - abs(next)) * 0.5);
                tmp += high * (tm - abs(next) - high);
                now += next;
            }
        }
        ans += tmp;
        // cout << tmp << " " << ans << endl;
    }
    printf("%.15lf\n", ans);
