void solve() {
    int n;
    cin >> n;
    vector<int> t(n);
    for (int i=0; i<n; ++i) {
        cin >> t.at(i);
    }
    vector<int> v(n);
    for (int i=0; i<n; ++i) {
        cin >> v.at(i);
    }
    v.push_back(0);

    vector<pair<double, double>> p;
    p.push_back({0, 0});
    double pre = 0, speed = 0;
    for (int i=0; i<n; ++i) {
        if (v.at(i) <= v.at(i+1)) {
            if (speed + t.at(i) <= v.at(i)) {
                pre += t.at(i);
                speed += t.at(i);
                p.push_back({pre, speed});
            } else {
                p.push_back({pre + v.at(i) - speed, v.at(i)});
                pre += t.at(i);
                speed = v.at(i);
                p.push_back({pre, speed});
            }
        } else {
            double top = (pre + t.at(i) + v.at(i+1) + pre - speed) / 2.0;
            if (speed + top - pre <= v.at(i)) {
                p.push_back({top, speed + top - pre});
                pre += t.at(i);
                speed = v.at(i+1);
                p.push_back({pre, speed});
            } else {
                p.push_back({pre + v.at(i) - speed, v.at(i)});
                p.push_back({pre + t.at(i) + v.at(i+1) - v.at(i), v.at(i)});
                pre += t.at(i);
                speed = v.at(i+1);
                p.push_back({pre, speed});
            }
        }
    }

    double res = 0.0;
    for (int i=0; i<(int)p.size()-1; ++i) {
        auto p1 = p.at(i), p2 = p.at(i+1);
        if (p1.second == p2.second) {
            res += (p2.first - p1.first) * p1.second;
        } else {
            res += (p2.first - p1.first) * max(p1.second, p2.second);
            res -= (p2.first - p1.first) * (max(p1.second, p2.second) - min(p1.second, p2.second)) / 2.0;
        }
    }

    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

