vector<ll> apply_condition(ll v, ll l, ll r, ll T_size){
    constexpr ll ACC = 2;
    vector<ll> ret(T_size);
    for (ll i = l; i <= r; i++){
        ret.at(i) = v;
    }
    for (ll i = l - 1; i >= 0; i--){
        ret.at(i) = ret.at(i + 1) + ACC;
    }
    for (ll i = r + 1; i < T_size; i++){
        ret.at(i) = ret.at(i - 1) + ACC;
    }
    return ret;
}



int main() {
    ll N;
    cin >> N;
    vector<ll> ts(N);
    for (auto && i: irange(0LL, N)){
        ll t;
        cin >> t;
        t *= 2;
        ts.at(i) = t;
    }
    vector<ll> vs(N);
    for (auto && i: irange(0LL, N)){
        ll v;
        cin >> v;
        v *= 4;
        vs.at(i) = v;
    }
    vector<ll> Ts(N+1, 0);
    for (auto && i: irange(1LL, N+1)){
        Ts.at(i) = Ts.at(i-1) + ts.at(i-1);
    }
    ll T_size = Ts.back() + 1;
    vector<vector<ll>> v_limit{};
    v_limit.emplace_back(apply_condition(0, 0, 0, T_size));
    v_limit.emplace_back(apply_condition(0, Ts.back(), Ts.back(), T_size));
    for (auto && i: irange(0LL, N)){
        v_limit.emplace_back(apply_condition(vs.at(i), Ts.at(i), Ts.at(i+1), T_size));
    }
    vector<ll> v_limits(T_size);
    for (auto && i: irange(0LL, T_size)){
        ll minimum = numeric_limits<ll>::max();
        for (auto && j: irange(0LL, N+2)){
            minimum = min(minimum, v_limit.at(j).at(i));
        }
        v_limits.at(i) = minimum;
    }
    ll val{0};
    for (auto && i: irange(0LL, T_size - 1)){
        val += (v_limits.at(i) + v_limits.at(i+1)) / 2;
    }
    double val_double = val;
    cout << val_double / 8 << endl;





    return 0;
}

