long long sum;
double memo(long long pos, long long v){
    if (v < 0){
      return -INF;
    }

    if (v > limits[pos]){
      return -INF;
    }
    if (pos >= sum){
      if (v == 0){
        return 0;
      }
      return -INF;
    }

    double &res = dp[pos][v];
    if (res > -2 * INF){
      return res;
    }
    res = -INF;
    res = max(res, memo(pos + 1, v) + v);
    if (v < limits[pos]){
      res = max(res, memo(pos + 1, v + 1) + v + 0.5);
    }

    res = max(res, memo(pos + 1, v - 1) + v - 0.5);
    return res;
}

