double eq(int speed1 , int time1,int speed2 , int time2){
  double time=time2-time1;

  double sp1=speed1,sp2=speed2;

  while(abs(sp1-sp2)>0.0001){
    if(sp1>sp2){
      sp2+=time;
      time=time/2;
    }
    else if(sp1<sp2){
      sp1-=time;
      time=time/2;
    }
  }
  nibun = ((double)speed1*(double)time*(double)time/2+(double)time) + ((double)speed2*((double)time2-(double)time1-(double)time)*((double)time2-(double)time1-(double)time)/2-((double)time2-(double)time1-(double)time));
  return nibun;
}

