int main(){
    int n, i;
    double sum = 0, pre_end = 0;
    cin >> n;
    vector<int> t(n + 2, 0);
    vector<int> v(n+2,0);
    for (i = 1; i <= n;i++){
        cin >> t[i];
    }
    for (i = 1; i <= n;i++){
        cin >> v[i];
    }
    for (i = n; i >= 1;i--){
        if(v[i] > v[i+1] + t[i])
            v[i] = v[i + 1] + t[i];

    }
        for (i = 1; i <= n; i++)
        {
            if (v[i] <= v[i + 1])
            {
                double de = v[i] - pre_end;
                if (de <= t[i])
                {
                    sum += (pre_end + v[i]) * de / 2 + v[i] * (t[i] - de);
                    pre_end = v[i];
                }
                else{
                sum += pre_end * t[i] + t[i] * t[i] / 2;
            }
        }
        else{
            double de1 = v[i] - pre_end, de2 = v[i] - v[i+1];
            if(de1+de2 > t[i]){
                double z = (t[i] + pre_end + v[i + 1]) / 2;
                sum += (pre_end + z) * (z - pre_end) / 2;
                sum += (v[i+1] + z) * (z - v[i+1]) / 2;
                pre_end = v[i + 1];
            }
            else{
                sum += v[i] * t[i];
                sum -= de1 * de1 / 2;
                sum -= de2 * de2 / 2;
                pre_end = v[i + 1];
            }
        }
    }
    cout << sum << endl;
    return 0;
}

