    for (int i = 0; i < n; i++){
        for (int j = 1; j <= t[i]*2; j++){
            if (!(crt+j))continue;
            if (speed[crt+j-1] + 0.5 <= v[i]) speed[crt+j] = speed[crt+j-1] + 0.5;
            else speed[crt+j] = v[i];
        }
        crt += t[i]*2;
    }
    total *= 2;
    crt = total;
    speed[crt] = 0;
    for (int i = n-1; i >= 0; i--){
        for (int j = 1; j <= t[i]*2; j++){
            if (speed[crt-j+1] + 0.5 <= v[i] && speed[crt-j+1] + 0.5 <= speed[crt-j]) speed[crt-j] = speed[crt-j+1] + 0.5;
            else speed[crt-j] = speed[crt-j]>v[i]?v[i]:speed[crt-j];
        }
        crt -= t[i]*2;
    }
    double ans = 0;

