double solve (int t1, int v1, int t2, int v2, int vmax) {
	double vmax_theory = min(v1,v2) + (t2-t1+abs(v2-v1))/2.0;
	double area1 = (vmax_theory-min(v1,v2))*(vmax_theory-min(v1,v2));
	double area2 = (abs(v1-v2)*abs(v1-v2))/2.0;
	double area3 = (t2-t1)*min(v1,v2);
	if (vmax_theory < vmax) {
		return area1-area2+area3;
	} else {
		double area4 = (vmax_theory-vmax)*(vmax_theory-vmax);
		return area1-area2+area3-area4;
	}
}

int ts[205]; int vs[205];
double dp[205][105];
int main(){
	ios_base::sync_with_stdio(false);cin.tie(NULL);
	int N;
	cin >> N;
	for(int i=1;i<=N;++i) {
		cin >> ts[i];
		ts[i] += ts[i-1];
	}
	for(int i=1;i<=N;++i) {
		cin >> vs[i];
	}
	for(int i=0;i<205;++i) 
		for(int j=0;j<105;++j)
			dp[i][j] = -inf;
	dp[0][0] = 0.0;

	for(int t_idx=1;t_idx<=N;++t_idx) {
		for(int v1=0;v1<vs[t_idx-1]+1;++v1)
			for(int v2=0;v2<vs[t_idx]+1;++v2)
			{
				if (dp[t_idx-1][v1] < 0.0 || abs(v2-v1) > ts[t_idx] - ts[t_idx-1])
					continue;
				dp[t_idx][v2] = max(dp[t_idx][v2],
					dp[t_idx-1][v1]+solve(ts[t_idx-1],v1,ts[t_idx],v2,vs[t_idx]));
			}
	}
	cout << std::fixed << std::setprecision(12) << dp[N][0] << endl;

}

