ll vel_max(ll t, ll start, ll end, ll limit){
  if(t<2*start){
    return 2*limit + 2*start - t;
  }else if(t<2*end){
    return 2*limit;
  }else{
    return 2*limit + t-2*end;
  }
}

int main() {
