// lib/variant.hpp
#ifndef VARIANT_HPP
#define VARIANT_HPP


// Source: https://qiita.com/ktokhrtk/items/9774208863f249007462
// Author: ktokhrtk ( https://qiita.com/ktokhrtk )
namespace tools {
  namespace detail {
    namespace variant {
      template <class...>
      struct variant_storage;

      template <class A, class... B>
      struct variant_storage<A, B...> : variant_storage<B...> {
        using base_t = variant_storage<B...>;
        static constexpr std::size_t size = sizeof(A) > base_t::size ? sizeof(A) : base_t::size;
        static constexpr std::size_t align = alignof(A) > base_t::align ? alignof(A) : base_t::align;
      };

      template <class Z>
      struct variant_storage<Z> {
        static constexpr std::size_t size = sizeof(Z);
        static constexpr std::size_t align = alignof(Z);
      };

      template <class... Types>
      using storage_t = typename std::aligned_storage<variant_storage<Types...>::size, variant_storage<Types...>::align>::type;

      template <class...>
      struct variant_typeid;

      template <class A, class... B>
      struct variant_typeid<A, B...> : variant_typeid<B...> {
        using base_t = variant_typeid<B...>;
        static constexpr std::size_t id = base_t::id + 1;

        template <class T, typename std::enable_if<std::is_same<A, typename std::decay<T>::type>::value, std::nullptr_t>::type = nullptr>
        static std::size_t assign(void* p, T&& t) {
          ::new(p) A(std::forward<T>(t));
          return id;
        }

        using base_t::assign;
      };

      template <class Z>
      struct variant_typeid<Z> {
        static constexpr std::size_t id = 1;

        template <class T, typename std::enable_if<std::is_same<Z, typename std::decay<T>::type>::value, std::nullptr_t>::type = nullptr>
        static std::size_t assign(void* p, T&& t) {
          ::new(p) Z(std::forward<T>(t));
          return id;
        }
      };

      template <class F, class T, class R>
      auto declfunc() -> R (*)(void*, F&&) {
        return [](void* p, F&& f) {
          return std::forward<F>(f)(*static_cast<T*>(p));
        };
      }

      template <class F, class T, class R>
      auto const_declfunc() -> R (*)(const void*, F&&) {
        return [](const void* p, F&& f) {
          return std::forward<F>(f)(*static_cast<const T*>(p));
        };
      }

      template <class...>
      struct contains;

      template <class T, class FirstType, class... Types>
      struct contains<T, FirstType, Types...> {
        static constexpr bool value = std::is_same<typename std::decay<T>::type, FirstType>::value || contains<T, Types...>::value;
      };

      template <class T>
      struct contains<T> {
        static constexpr bool value = false;
      };

      template <class FirstType, class... Types>
      struct first {
        using type = FirstType;
      };
    }
  }

  template <class... Types>
  struct variant {
  private:
    detail::variant::storage_t<Types...> m_storage;
    std::size_t m_id;

    struct deleter {
      template <class T>
      void operator()(T& p) {
        p.~T();
      }
    };

  public:
    ~variant() {
      this->visit<void>(deleter());
    }

    variant()
      : variant(detail::variant::first<Types...>::type()) {
    }

    template <
      class T,
      typename std::enable_if<detail::variant::contains<T, Types...>::value, std::nullptr_t>::type = nullptr
    >
    variant(T&& t)
      : m_id(detail::variant::variant_typeid<Types...>::assign(&this->m_storage, std::forward<T>(t))) {
    }

    template <class R, class F>
    R visit(F&& f) {
      static R (*ftbl[])(void*, F&&) = { detail::variant::declfunc<F, Types, R>()... };
      return ftbl[sizeof...(Types) - this->m_id](&this->m_storage, std::forward<F>(f));
    }

    template <class R, class F>
    R visit(F&& f) const {
      static R (*ftbl[])(const void*, F&&) = { detail::variant::const_declfunc<F, Types, R>()... };
      return ftbl[sizeof...(Types) - this->m_id](&this->m_storage, std::forward<F>(f));
    }
  };
}

#endif

// lib/extgcd.hpp
#ifndef EXTGCD_HPP
#define EXTGCD_HPP


/*
usage:

std::tuple<int, int, int> result = tools:extgcd(4, 5);
int gcd = std::get<0>(result);
int x0 = std::get<1>(result);
int y0 = std::get<2>(result);
*/

namespace tools {
  template <typename T>
  std::tuple<T, T, T> extgcd(T prev_r, T r) {
    T prev_s = 1;
    T prev_t = 0;
    T s = 0;
    T t = 1;
    while (r != 0) {
      const T q = quo(prev_r, r);
      const T next_r = prev_r - q * r;
      prev_r = r;
      r = next_r;
      const T next_s = prev_s - q * s;
      prev_s = s;
      s = next_s;
      const T next_t = prev_t - q * t;
      prev_t = t;
      t = next_t;
    }
    return std::make_tuple(prev_r, prev_s, prev_t);
  }
}

#endif

// lib/fraction.hpp
#ifndef FRACTION_HPP
#define FRACTION_HPP


/*
usage:

tools::fraction(5, 2) // => (5/2)
*/

namespace tools {
  class fraction {
  private:
    std::intmax_t m_numerator;
    std::intmax_t m_denominator;

    void reduct() noexcept {
      if (this->m_denominator < 0) {
        this->m_numerator *= -1;
        this->m_denominator *= -1;
      }
      if (this->m_numerator != 0) {
        const std::intmax_t gcd = std::get<0>(tools::extgcd(this->m_numerator, this->m_denominator));
        this->m_numerator /= gcd;
        this->m_denominator /= gcd;
      }
    }

    fraction(const std::intmax_t numerator, const std::intmax_t denominator, bool) noexcept :
      m_numerator(numerator),
      m_denominator(denominator) {
      this->reduct();
    }

  public:
    fraction() noexcept :
      fraction(0, 1, true) {
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    fraction(const T n) noexcept :
      fraction(n, 1, true) {
    }
    template <typename T1, typename T2, typename std::enable_if<std::is_integral<T1>::value && std::is_integral<T2>::value, std::nullptr_t>::type = nullptr>
    fraction(const T1 numerator, const T2 denominator) :
      m_numerator(numerator),
      m_denominator(denominator) {
      if (this->m_denominator == 0) throw std::domain_error("Denominator cannot be zero.");
      this->reduct();
    }

    std::intmax_t numerator() const noexcept {
      return this->m_numerator;
    }

    std::intmax_t denominator() const noexcept {
      return this->m_denominator;
    }

    explicit operator double() const noexcept {
      return static_cast<double>(this->m_numerator) / this->m_denominator;
    }

    fraction operator+() const noexcept {
      return *this;
    }

    fraction operator-() const noexcept {
      return fraction(-this->m_numerator, this->m_denominator, true);
    }

    friend fraction operator+(const fraction& lhs, const fraction& rhs) noexcept {
      return fraction(lhs.m_numerator * rhs.m_denominator + rhs.m_numerator * lhs.m_denominator, lhs.m_denominator * rhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator+(const fraction& lhs, const T rhs) noexcept {
      return fraction(lhs.m_numerator + static_cast<std::intmax_t>(rhs) * lhs.m_denominator, lhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator+(const T lhs, const fraction& rhs) noexcept {
      return fraction(static_cast<std::intmax_t>(lhs) * rhs.m_denominator + rhs.m_numerator, rhs.m_denominator, true);
    }

    friend fraction operator-(const fraction& lhs, const fraction& rhs) noexcept {
      return fraction(lhs.m_numerator * rhs.m_denominator - rhs.m_numerator * lhs.m_denominator, lhs.m_denominator * rhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator-(const fraction& lhs, const T rhs) noexcept {
      return fraction(lhs.m_numerator - static_cast<std::intmax_t>(rhs) * lhs.m_denominator, lhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator-(const T lhs, const fraction& rhs) noexcept {
      return fraction(static_cast<std::intmax_t>(lhs) * rhs.m_denominator - rhs.m_numerator, rhs.m_denominator, true);
    }

    friend fraction operator*(const fraction& lhs, const fraction& rhs) noexcept {
      return fraction(lhs.m_numerator * rhs.m_numerator, lhs.m_denominator * rhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator*(const fraction& lhs, const T rhs) noexcept {
      return fraction(lhs.m_numerator * static_cast<std::intmax_t>(rhs), lhs.m_denominator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator*(const T lhs, const fraction& rhs) noexcept {
      return fraction(static_cast<std::intmax_t>(lhs) * rhs.m_numerator, rhs.m_denominator, true);
    }

    friend fraction operator/(const fraction& lhs, const fraction& rhs) {
      if (rhs == 0) throw std::domain_error("Cannot divide by zero.");
      return fraction(lhs.m_numerator * rhs.m_denominator, lhs.m_denominator * rhs.m_numerator, true);
    }
    template <typename T, typename std::enable_if<std::is_integral<T>::value, std::nullptr_t>::type = nullptr>
    friend fraction operator/(const fraction& lhs, const T rhs) {
