class area {
public:
  tools::half_line_2d<tools::fraction> left;
  tools::directed_line_segment_2d<tools::fraction> center;
  tools::half_line_2d<tools::fraction> right;

  area(const tools::fraction& t_begin, const tools::fraction& t_end, const tools::fraction& v) :
    left(tools::vector2<tools::fraction>(t_begin, v), tools::vector2<tools::fraction>(-1, 1)),
    center(tools::vector2<tools::fraction>(t_begin, v), tools::vector2<tools::fraction>(t_end, v)),
    right(tools::vector2<tools::fraction>(t_end, v), tools::vector2<tools::fraction>(1, 1)) {
  }

  const tools::fraction& t_begin() const {
    return this->center.p1().x;
  }
  const tools::fraction& t_end() const {
    return this->center.p2().x;
  }
  const tools::fraction& velocity() const {
    return this->center.p1().y;
  }
};

class velocity_diagram {
public:
  std::vector<tools::directed_line_segment_2d<tools::fraction>> segments;
  tools::half_line_2d<tools::fraction> last_half_line;

  velocity_diagram() :
    segments(),
    last_half_line(tools::vector2<tools::fraction>(0, 0), tools::vector2<tools::fraction>(1, 1)) {
  }

  velocity_diagram& operator<<(const area& area) {
    const tools::vector2<tools::fraction> joint = *this->last_half_line.to_line().cross_point(tools::line_2d<tools::fraction>(1, 0, -area.t_begin()));
    if (joint.y < area.velocity()) {
      const tools::optional<tools::vector2<tools::fraction>> possible_cross_point = this->last_half_line.cross_point(area.center);
      if (possible_cross_point) {
        const tools::vector2<tools::fraction>& cross_point = *possible_cross_point;
        if (cross_point.x < area.t_end()) {
          this->segments.emplace_back(this->last_half_line.a(), cross_point);
          this->segments.emplace_back(cross_point, area.center.p2());
          this->last_half_line = area.right;
        } else {
          // do nothing
        }
      } else {
        // do nothing
      }
    } else if (joint.y == area.velocity()) {
      if (this->last_half_line.a().x < area.t_begin()) {
        this->segments.emplace_back(this->last_half_line.a(), joint);
      }
      this->segments.emplace_back(area.center.p1(), area.center.p2());
      this->last_half_line = area.right;
    } else {
      if (this->last_half_line.a().x < area.t_begin()) {
        const tools::optional<tools::vector2<tools::fraction>> possible_cross_point = this->last_half_line.cross_point(area.left);
        if (possible_cross_point) {
          const tools::vector2<tools::fraction>& cross_point = *possible_cross_point;
          if (this->last_half_line.a().x < cross_point.x) {
            this->segments.emplace_back(this->last_half_line.a(), cross_point);
          }
          this->segments.emplace_back(cross_point, area.left.a());
          this->segments.emplace_back(area.center.p1(), area.center.p2());
          this->last_half_line = area.right;
          goto MATCHED;
        }
      }
      for (std::int_fast64_t i = tools::to_signed(this->segments.size()) - 1; i >= 0; --i) {
        const tools::optional<tools::vector2<tools::fraction>> possible_cross_point = this->segments[i].cross_point(area.left);
        if (possible_cross_point) {
          const tools::vector2<tools::fraction>& cross_point = *possible_cross_point;
          if (cross_point.x == this->segments[i].p1().x) {
            this->segments.erase(this->segments.begin() + i, this->segments.end());
            this->segments.emplace_back(cross_point, area.left.a());
            this->segments.emplace_back(area.center.p1(), area.center.p2());
            this->last_half_line = area.right;
          } else {
            const tools::vector2<tools::fraction> p = this->segments[i].p1();
            this->segments.erase(this->segments.begin() + i, this->segments.end());
            this->segments.emplace_back(p, cross_point);
            this->segments.emplace_back(cross_point, area.left.a());
            this->segments.emplace_back(area.center.p1(), area.center.p2());
            this->last_half_line = area.right;
          }
          goto MATCHED;
        }
      }
    MATCHED:
      ;
    }
    return *this;
  }

  velocity_diagram& operator<<(const tools::fraction& last_t) {
    const tools::vector2<tools::fraction> last_point(last_t, 0);
    const tools::half_line_2d<tools::fraction> cut_line(last_point, tools::vector2<tools::fraction>(-1, 1));
    if (this->last_half_line.a().x < last_t) {
      const tools::optional<tools::vector2<tools::fraction>> possible_cross_point = this->last_half_line.cross_point(cut_line);
      if (possible_cross_point) {
        const tools::vector2<tools::fraction>& cross_point = *possible_cross_point;
        if (this->last_half_line.a().x < cross_point.x) {
          this->segments.emplace_back(this->last_half_line.a(), cross_point);
        }
        this->segments.emplace_back(cross_point, last_point);
        this->last_half_line = tools::half_line_2d<tools::fraction>(last_point, tools::vector2<tools::fraction>(1, 1));
        goto MATCHED;
      }
    }
    for (std::int_fast64_t i = tools::to_signed(this->segments.size()) - 1; i >= 0; --i) {
      const tools::optional<tools::vector2<tools::fraction>> possible_cross_point = this->segments[i].cross_point(cut_line);
      if (possible_cross_point) {
        const tools::vector2<tools::fraction>& cross_point = *possible_cross_point;
        if (cross_point.x == this->segments[i].p1().x) {
          this->segments.erase(this->segments.begin() + i, this->segments.end());
          this->segments.emplace_back(cross_point, last_point);
          this->last_half_line = tools::half_line_2d<tools::fraction>(last_point, tools::vector2<tools::fraction>(1, 1));
        } else {
          const tools::vector2<tools::fraction> p = this->segments[i].p1();
          this->segments.erase(this->segments.begin() + i, this->segments.end());
          this->segments.emplace_back(p, cross_point);
          this->segments.emplace_back(cross_point, last_point);
          this->last_half_line = tools::half_line_2d<tools::fraction>(last_point, tools::vector2<tools::fraction>(1, 1));
        }
        goto MATCHED;
      }
    }
  MATCHED:
    return *this;
  }

  tools::fraction distance() const {
    return std::accumulate(
      this->segments.begin(),
      this->segments.end(),
      tools::fraction(0, 1),
      [](const tools::fraction& sum, const tools::directed_line_segment_2d<tools::fraction>& segment) {
        const tools::fraction min_velocity = std::min(segment.p1().y, segment.p2().y);
        const tools::fraction diff_velocity = std::max(segment.p1().y, segment.p2().y) - min_velocity;
        const tools::fraction interval = segment.p2().x - segment.p1().x;
        return sum + interval * (min_velocity + diff_velocity / 2);
      }
    );
  }

  friend std::ostream& operator<<(std::ostream& os, velocity_diagram& self) {
    for (const tools::directed_line_segment_2d<tools::fraction>& segment : self.segments) {
      os << '[' << segment.p1() << ", " << segment.p2() << ']' << std::endl;
    }
    return os;
  }
};

int main() {
  std::int_fast64_t n;
  std::cin >> n;
  std::vector<std::int_fast64_t> t, v;
  t.reserve(n);
  v.reserve(n);
  std::copy_n(std::istream_iterator<std::int_fast64_t>(std::cin), n, std::back_inserter(t));
  std::copy_n(std::istream_iterator<std::int_fast64_t>(std::cin), n, std::back_inserter(v));

  std::vector<area> areas;
  areas.reserve(n);
  for (std::int_fast64_t i = 0; i < n; ++i) {
    const tools::fraction prev_t = i == 0 ? 0 : areas.back().t_end();
    areas.emplace_back(prev_t, prev_t + t[i], v[i]);
  }

  velocity_diagram diagram;
  for (const area& area : areas) {
    diagram << area;
  }
  diagram << areas.back().t_end();

  std::cout << std::fixed << std::setprecision(6) << static_cast<double>(diagram.distance()) << std::endl;
  return 0;
}

