using namespace std;
struct line{
    int e;
    int lim;
};
line make_line(int a,int b){
    line temp;
    temp.e=a;
    temp.lim=b;
    return temp;
}
struct cmp{
    bool operator()(const line &a,const line &b){
        return a.lim>b.lim;
    }
};
int main(){
    int n,t[1000],v[1000],s=0;
    double ans=0;
    priority_queue<line,vector<line>,cmp>pq;
    queue<line>q;
    scanf("%d",&n);
    t[0]=v[0]=0;
    for(int i=1;i<=n;i++){
        scanf("%d",&t[i]);
        t[i]+=t[i-1];
    }
    for(int i=1;i<=n;i++){
        scanf("%d",&v[i]);
        q.push(make_line(t[i],v[i]));
    }
    v[n+1]=0;
    pq.push(make_line(1000000,1000000));
    q.push(make_line(1000000,0));
    for(int i=1;i<=n;i++)pq.push(make_line(t[i],v[i+1]+t[i]));
    for(int i=0;i<t[n];i++){
        while(pq.top().e<=i)pq.pop();
        while(q.front().e<=i)q.pop();
        if(s+1<=q.front().lim&&s+i+2<=pq.top().lim){
            s++;
            ans+=(s+s-1)*5;
        }
        else if(s+1<=q.front().lim&&s+i+1<=pq.top().lim){
            ans+=s*10+2.5;
        }
        else if(s<=q.front().lim&&s+i+1<=pq.top().lim){
            ans+=s*10;
        }
        else{
            s--;
            ans+=(s+s+1)*5;
        }
    }
    printf("%lf\n",ans/10);
}

