  for (int i = 1; i <= n; i++) {
    cin >> t[i];
    t[i] += t[i-1];
  }
  v[0] = v[n+1] = 0;
  for (int i = 1; i <= n; i++) cin >> v[i];
  b[0] = 0;
  for (int i = 1; i <= n; i++) {
    b[i] = min(v[i+1],v[i]) + t[i];
  }
  for (int i = 0; i <= n; i++) {
    min_b[i] = *min_element(b+i,b+n+1);
  }

  double d = 0;
  for (int i = 1; i <= n; i++) {
    double vs = -t[i-1]+min_b[i-1];
    double ve = -t[i]+min_b[i];
    //printf("vs=%f ve=%f\n",vs,ve);
    double dt = t[i] - t[i-1];
    double p = (ve+dt-vs) / 2.0;
    if (v[i] <= vs + p) {
      double mdt = dt - (v[i] - vs) - (v[i] - ve);
      double v1 = (v[i]+vs)*(v[i]-vs)/2.0;
      double v2 = mdt*v[i];
      double v3 = (v[i]+ve)*(v[i]-ve)/2.0;
      //printf("v1=%f v2=%f v3=%f\n",v1,v2,v3);
      d += v1 + v2 + v3;
    } else {
      d += (2.0*vs+p)*p/2.0 + (2.0*ve+dt-p)*(dt-p)/2.0;
    }
    //printf("i=%d d=%f\n",i,d);
  }
  printf("%.6f\n", d);

  return 0;
}

