  int n;
  cin >> n;
  vi t(n);
  vi v(n);
  cin >> t >> v;
  auto dp = make_vector(n+1,101,-(double)MOD);
  dp[0][0] = 0;
  REP(i,n)REP(j,101)REP(k,101){
    if(j>v[i] || k>v[i]) continue;
    int time = t[i];
    double dist = 0;
    if(j+time < k || j-time > k){
      dist = -MOD;
    }else if(time>=v[i]-j+v[i]-k){
      double timel = v[i]-j;
      double timer = v[i]-k;
      double timem = time - timel - timer;
      dist += timel*timel/2.+j*timel;
      dist += -timer*timer/2.+v[i]*timer;
      dist += timem*v[i];
    }else{
      double timel = (time-j+k)/2.;
      double timer = time - timel;
      dist += timel*timel/2. + timel*j;
      dist += timer*timer/2. + timer*k;
    }
    dp[i+1][k] = max(dp[i+1][k],dist+dp[i][j]);
  }
  cout << dp[n][0] << endl;
}

