    REP(i,N) cin >> t[i];
    REP(i,N) cin >> v[i];

    REP(i,N) t_sum[i+1] += t_sum[i] + t[i];
    ans = 0.0;
    dfs(0,t_sum[N],0);
    cout << ans << endl;
    return 0;
}

