    v_limit.emplace_back(apply_condition(0, Ts.back(), Ts.back(), T_size));
    for (auto && i: irange(0LL, N)){
        v_limit.emplace_back(apply_condition(vs.at(i), Ts.at(i), Ts.at(i+1), T_size));
    }
    vector<double> v_limits(T_size);
    for (auto && i: irange(0LL, T_size)){
        ll minimum = numeric_limits<double>::max();
        for (auto && j: irange(0LL, N+2)){
            minimum = min(minimum, v_limit.at(j).at(i));
        }
        v_limits.at(i) = minimum;
    }
    double val{0};
    for (auto && i: irange(0LL, T_size - 1)){
        val += ((double)v_limits.at(i) + (double)v_limits.at(i+1)) / 2;
    }
    double val_double = val;
    cout << val_double / 8 << endl;





    return 0;
}

