ll V[MAX_N] = {};
ll Limit[MAX_T] = {};   // i 秒での限界速度
ll EndTime = 0;
double dp[MAX_T][MAX_V];

// i 秒時点で、現在の速度が j m/s のときの最大値
double dfs(int i = 0, int j = 0) {
    if(EndTime <= i) {
        if(j != 0) {
            dp[i][j] = -(std::numeric_limits<double>::infinity());
        } else {
            dp[i][j] = 0;
        }
        DBG("i: %lld j: %lld dp[i][j]: %.6f\n", i, j, dp[i][j]);
        return dp[i][j];
    }

    double& res = dp[i][j];
    if(res != std::numeric_limits<double>::infinity()) {
        return res;
    }
    res = -(std::numeric_limits<double>::infinity());

    double cand1 = -(std::numeric_limits<double>::infinity());;
    double cand2 = cand1;
    double cand3 = cand1;
    if(j > Limit[i]) {
        // 条件違反
        res = -(std::numeric_limits<double>::infinity());
        return res;
    }
    if(j < Limit[i]) {
        double dist = static_cast<double>(j) + 0.5;
        cand1 = dfs(i+1, j+1) + dist;
    }
    if(j > 0) {
        double dist = static_cast<double>(j-1) + 0.5;
        cand2 = dfs(i+1, j-1) + dist;
    }
    cand3 = dfs(i+1, j) + static_cast<double>(j);

    res = max({res, cand1, cand2, cand3});
    DBG("i: %lld j: %lld cand1: %.6f cand2: %.6f cand3: %.6f res: %.6f\n",
            i, j, cand1, cand2, cand3, res);

    return res;
}

signed main()
{
    cin >> N;
    REP(i, N) { cin >> T[i]; }
    REP(i, N) { cin >> V[i]; }
    REP(i, N) {
        for(int j = EndTime; j < EndTime + T[i]; ++j) {
            Limit[j] = V[i];
            //DBG("Limit[%lld]: %lld\n", j, Limit[j]);
        }
        EndTime += T[i];
    }
    bool isDouble = false;
    // EndTime が奇数だとうまく DP できないので横に引き延ばす
    if(EndTime % 2 != 0) {
        isDouble = true;
        EndTime = 0;
        REP(i, N) {
            T[i] *= 2;
            for(int j = EndTime; j < EndTime + T[i]; ++j) {
                Limit[j] = V[i];
            }
            EndTime += T[i];
        }
    }

    REP(i, MAX_T) {
        REP(j, MAX_V) {
            dp[i][j] = std::numeric_limits<double>::infinity();
        }
    }

    double ans = dfs();
    if(isDouble) { ans /= 4; }

    printf("%.10f\n", ans);
    return 0;
}

