int main() {
    int N; cin >> N;
    t.assign(N,0);
    v.assign(N,0);
    t_sum.assign(N+1,0);
    REP(i,N) cin >> t[i];
    REP(i,N) cin >> v[i];

    REP(i,N) t_sum[i+1] += t_sum[i] + t[i];
    ans = 0.0;
    vector<vector<long double>> g(N+2,vector<long double>(3,0));
    REP(i,N){
        g[i][0] = v[i] + t_sum[i];
        g[i][1] = v[i];
        g[i][2] = v[i] - t_sum[i+1];
    }

    for(long double x = 0.0; x<=t_sum[N]; x+=0.5){
        int itr = upper_bound(ALL(t_sum), x) - t_sum.begin()-1;
        long double num = INF;
        REP(i,N){
            if(i<itr){
                num = min(num, g[i][2]+x);
            }else if(i==itr){
                num = min(num, g[i][1]);
            }else{
                num = min(num, g[i][0]-x);
            }
            num = min(num, x);
            num = min(num, t_sum[N]-x);
        }
        ans += num;
    }
    cout << ans/2 << endl;
    return 0;
}

