using namespace std;

typedef long long ll;

int main()
{
    ll N;
    cin >> N;
    vector<double> t(N), v(N);
    REP(i, N) cin >> t[i];
    REP(i, N) cin >> v[i];

    vector<double> tA(N), tE(N), tD(N), vStart(N), sumT(N);
    vStart[0] = 0;
    sumT[0] = t[0];
    for (int i = 1; i < N; ++i) sumT[i] = sumT[i - 1] + t[i];
    REP(i, N)
    {
        double vEndMax = 100.0;
        if (i == N - 1)
        { 
            vEndMax = 0;
        }
        else
        {
            for (int j = i; j < N - 1; ++j)
            {
                vEndMax = min(vEndMax, min(v[j], v[j + 1]) + sumT[j] - sumT[i]);
            }
        }
        double vMax;
        for (int j = 0; 0.5 * j <= t[i]; ++j)
        {
            double ta = 0.5 * j;   
            double vT = vStart[i] + ta;
            if (vT < v[i] && vT < vEndMax + (t[i] - ta))
            {
                continue;
            }
            else
            {
                vMax = vT;
                break;
            }
        }
        tA[i] = vMax > vStart[i] ? (vMax - vStart[i]) : 0;
        tD[i] = vMax > vEndMax ? (vMax - vEndMax) : 0;
        tE[i] = t[i] - tA[i] - tD[i];
        if (i + 1 < N) vStart[i + 1] = min(vMax, vEndMax);
    }
    double ans = 0;
    REP(i, N)
    {
        ans += (vStart[i] + vStart[i] + tA[i]) * tA[i] / 2.0;
        ans += (vStart[i] + tA[i]) * tE[i];
        ans += (vStart[i] + tA[i] + vStart[i] + tA[i] - tD[i]) * tD[i] / 2.0;
    }

    cout << fixed;
    cout << setprecision(10) << ans << endl;
}

