                  	if (d < 0 || d > v[i]) continue;
                    chmax(nt[d], cr[k] + k + d);
                }
            }
          swap(cr, nt);
            memset(nt, 0xCF, sizeof dp[0]);
        }
    }

    printf("%.10lf\n", cr[0] / 8.0);

	return 0;
}

