					else if (v[i] <= j)
					{
						add += (v[i] - k) * (v[i] - k) / 2.0f;
						add += (v[i] - k) * (t[i] - v[i] + k);
					}
					else
					{
						auto remain = t[i] - (j - k);
						add += (j - k) * (j - k) / 2.0f;
						add += remain * (j - k);

						auto maxSpeed = remain / 2.0f + j;
						if (maxSpeed > v[i])
						{
							auto tempT = v[i] - j;
							add += tempT * tempT;
							add += tempT * (remain - 2.0f * tempT);
						}
						else
						{
							add += remain / 2.0f * remain / 2.0f;
						}
					}
				}
				else
				{
					if (k - t[i] > j)
					{
						continue;
					}

					add = j * t[i];

					if (k < v[i])
					{
						auto remain = t[i] - (k - j);
						add += (k - j) * (k - j) / 2.0f;
						add += remain * (k - j);

						auto maxSpeed = remain / 2.0f + k;
						if (maxSpeed > v[i])
						{
							auto tempT = v[i] - k;
							add += tempT * tempT;
							add += tempT * (remain - 2.0f * tempT);
						}
						else
						{
							add += remain / 2.0f * remain / 2.0f;
						}
					}
					else
					{
						auto remain = t[i] - (k - j);
						add += remain * (k - j);
						add += (k - j) * (k - j) / 2.0f;
					}
				}

				next[j] = max(next[j], prev[k] + add);
			}
		}

		minPrev = minNext;
		swap(prev, next);
	}

	cout << prev[0] << endl;

	return 0;
}

