ll mod = 1e09 + 7;

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll n;
	cin >> n;
	vll t(n), v(n);
	REP(i, n) cin >> t[i];
	REP(i, n) cin >> v[i];

	ll T = 0;
	// f[i] : 最高速度の条件(時刻[f[i][0], f[i][1]]においてはv[i])
	vvll f(n + 2, vll(3));
	REP(i, n){
		f[i][0] = T;
		f[i][1] = T + t[i];
		f[i][2] = v[i];
		T += t[i];
	}
	f[n] = {0, 0, 0};
	f[n + 1] = {T, T, 0};
	double cur = 0, res = 0;
	REP(i, 400010){
		if(i > 2 * T) break;
		double vm = 1000000, tmp;
		REP(j, n + 2){
			if(2 * f[j][0] <= i && 2 * f[j][1] >= i) tmp = f[j][2];
			else if(i < 2 * f[j][0]) tmp = f[j][2] + (2 * f[j][0] - i) * 0.5;
			else tmp = f[j][2] + (i - 2 * f[j][1]) * 0.5;
			vm = min(vm, tmp);
		}
		res += (vm + cur) * 0.5 * 0.5;
		cur = vm;
	}
	cout << res << endl;
}

