    auto N = read<i32>();
    auto ts = read<i32>(N);
    auto vs = read<i32>(N);

    REP (i, N) {
        if (i != 0) {
            ts[i] += ts[i - 1];
        }
    }

    double ans = 0;
    auto t_max = ts.back();

    double v = 0;
    i32 index = 0;

    double t = 0.5;

    while (t <= t_max) {
        // t/2の走行速度を求める
        while (ts[index] < t) {
            index += 1;
        }

        auto v_i = vs[index];

        // 加速できるか
        auto v_next = (v_i >= v + 0.5) ? v + 0.5 : v;

        // 停止できるか
        if (v > t_max - t) {
            v_next = v - 0.5;
        }

        // 減速が間に合うか
//        cout << t << " " << index << " ";
        FOR (j, index + 1, N) {
            auto t_j = ts[j - 1];
            auto v_j = vs[j];
