#include <iostream>

int t[100], v[101];
int n;


double calc_part(int part, double vel){

	if(part >= n){ return 0.0; }

	double meter = 0.0;

	// 1sずつタイムステップを進めていく
	for(int i = t[part] - 1; i >= 0; i--){

		// 次の区間に入るまでに減速が必要ならする
		if((vel - i) > v[part + 1]){
			vel -= 1.0;
		}
		else if((vel - i + 1) > v[part + 1]){

			// 小刻みにタイムステップを刻んでブレーキをかけるぎりぎりの時間をチェックする
			double di;
			for(di = 1.0; di >= 0.0; di -= 0.001){
				if(vel - i + di <= v[part + 1]){
					break;
				}
			}

			vel -= di;
		}
		else if(vel < v[part]){	// 現在区間のmax速度まであげる
			vel += 1.0;
		}

		meter += vel;

		//std::cout << t[part] - i << " : " << vel << std::endl;
	}

	return meter + calc_part(part + 1, vel);
}


