  }

  std::vector<int64_t> t_b(n), t_e(n);
  t_b[0] = 0;
  for (int64_t i = 1; i < n; i++) {
    t_b[i] = t_b[i - 1] + t[i - 1];
  }
  std::copy(std::next(t_b.cbegin()), t_b.cend(), t_e.begin());
  t_e.back() = t_b.back() + t.back();

  std::vector<int64_t> v_max(t_e.back() + 1, 100);

  for (int64_t i = 0; i < n; i++) {
    for (int64_t j = t_b[i]; j <= t_e[i]; j++) {
      v_max[j] = std::min(v[i], v_max[j]);
    }
  }
  v_max.back() = 0;
  for (int64_t i = v_max.size() - 1; 0 < i; i--) {
    if (v_max[i] + 1 < v_max[i - 1]) {
      v_max[i - 1] = v_max[i] + 1;
    }
  }

  std::vector<int64_t> v_ans(t_e.back() + 1);
  v_ans.front() = 0;

  for (int64_t i = 1; i < v_ans.size(); i++) {
    v_ans[i] = std::min(v_max[i], v_ans[i - 1] + 1);
    assert(std::abs(v_ans[i] - v_ans[i - 1]) <= 1);
  }
  int64_t l = 0, quo = 0;
  for (int64_t i = 0; i < n; i++) {
    for (int64_t j = t_b[i]; j < t_e[i]; j++) {
      assert(std::abs(v_ans[j] - v_ans[j + 1]) <= 1);
      if (v_ans[j] < v_ans[j + 1]) {
        l += v_ans[j];
        quo += 2;
      } else if (v_ans[j + 1] < v_ans[j]) {
        l += v_ans[j];
        quo -= 2;
      } else if (v_ans[j] < v[i]) {
        l += v_ans[j];
        quo += 1;
      } else {
        l += v_ans[j];
      }
    }
  }
  l += quo / 4;
  quo %= 4;
  std::cout << l + static_cast<double>(quo) * 0.25 << std::endl;
  return 0;
}

