ld u(ld t, int i) {
	if (i != 0)	if (t < ti[i - 1]) return vi[i] + ti[i - 1] - t;
	if (i != 0) if ((ti[i - 1] <= t) && (t <= ti[i])) return vi[i];
	if (i == 0) if (t == 0) return vi[i];
	if (ti[i] < t) return vi[i] + t - ti[i];
}

