const int N = 105;

int i, n, j, t[N], v[N];
double rs;
map<int, double> dp[N * N * 4];
set<pair<int, int>> S;
queue<pair<int, int>> q;
vector<int> h;

int main() {
  ios_base::sync_with_stdio(0);

  cin >> n;
  for(i = 1; i <= n; ++i) cin >> t[i];
  for(i = 1; i <= n; ++i) cin >> v[i];

  h.push_back(0);
  for(i = 1; i <= n; ++i)
    for(j = 0; j < t[i]; ++j)
      h.push_back(v[i]);

  h.push_back(0);
  dp[0][0] = 0; S.insert(make_pair(0, 0));
  for(q.push(make_pair(0, 0)); !q.empty(); q.pop()) {
    int x = q.front().first;
    int vit = q.front().second;
    S.erase(make_pair(x, vit));
    if(x == h.size()) continue;

    if(h[x + 1] >= vit && h[x] >= vit) {
      dp[x + 1][vit] = max(dp[x + 1][vit], dp[x][vit] + vit);
      if(!S.count(make_pair(x + 1, vit))) q.push(make_pair(x + 1, vit)), S.insert(make_pair(x + 1, vit));
    }

    if(h[x + 1] >= vit + 0.5 && h[x] >= vit + 0.5) {
      dp[x + 1][vit] = max(dp[x + 1][vit], dp[x][vit] + vit + 0.25);
      if(!S.count(make_pair(x + 1, vit))) q.push(make_pair(x + 1, vit)), S.insert(make_pair(x + 1, vit));
    }

    if(h[x + 1] >= vit + 1 && h[x] >= vit + 1) {
      dp[x + 1][vit + 1] = max(dp[x + 1][vit + 1], dp[x][vit] + vit + 0.5);
      if(!S.count(make_pair(x + 1, vit + 1))) q.push(make_pair(x + 1, vit + 1)), S.insert(make_pair(x + 1, vit + 1));
    }

    if(h[x + 1] >= vit - 1 && vit - 1 >= 0 && h[x] >= vit - 1) {
      dp[x + 1][vit - 1] = max(dp[x + 1][vit - 1], dp[x][vit] + vit - 0.5);
      if(!S.count(make_pair(x + 1, vit - 1))) q.push(make_pair(x + 1, vit - 1)), S.insert(make_pair(x + 1, vit - 1));
    }
  }

  cout << setprecision(3) << fixed << dp[h.size() - 1][0] << '\n';

  return 0;
}

