struct f
{
	double l_, r_, v_;
	f() {}
	f(double l, double r, double v): l_(l), r_(r), v_(v) {}
	double operator()(double x)
	{
		if (0 <= x && x <= l_) return v_ + l_ - x;
		else if (l_ <= x && x <= r_) return v_;
		else return v_ + x - r_;
	}
};

