			ret += 0.5 * (cur+most) * (most-cur);
			ret += 0.5 * (v[i+1]+most) * (most-v[i+1]);
		}
		else{
			ret += v[i] * t[i];
			ret -= 0.5 * max(0.0,v[i]-cur) * max(0.0,v[i]-cur);
			ret -= 0.5 * max(0.0,v[i]-v[i+1]) * max(0.0,v[i]-v[i+1]);
		}
		//cout<<ret<<endl;
		cur = min(v[i],min(cur+t[i],v[i+1]));
	}
	printf("%.12f\n",ret);
}

