//i is parameter(0-n+1)
int fni(int i, int tm) {
  int ret;
  if (i == 0)
    ret = tm;
  else if (i == n + 1)
    ret = t[n] - tm;
  else if (tm < t[i - 1])
    ret = -(tm - t[i - 1]) + v[i];
  else if (tm > t[i])
    ret = (tm - t[i]) + v[i];
  else
    ret = v[i];
  return ret;
}

int fn(int tm) {
  int ret = fni(0, tm);
  for (int i = 1; i <= n + 1; i++) {
    ret = min(ret, fni(i, tm));
  }
  return ret;
}

