double dist(ll start, ll goal, ll limit, ll length) {
    double res = 0;
    if (limit - start + limit - goal <= length) {
        res += (start + limit) * (limit - start) / double(2);
        res += (goal + limit) * (limit - goal) / double(2);
        res += (length - (limit - start + limit - goal)) * limit;
    } else {
        res +=
            (2 * start + goal + length) * (-start + goal + length) / double(8);
        res +=
            (start + 2 * goal + length) * (start - goal + length) / double(8);
    }
    // debug(res);
    return res;
}

