double V_in = 0;
int T_Sum = 0;
int t = 0;



	//進入速度、次の区間の制限速度、現在の区間の制限速度、区間のタイム
double Move(int V_out, int Limit, int Time) {
	//ある時点tで、v=SUM(T)-tを超えていたら、どうやっても間に合わない。
	V_out = min(V_out, T_Sum - (t + Time));
	if (V_out > Limit) {//次の区間の制限速度が今の区間より大きい。
		if (Time > Limit - V_in) {//最高速度到達
			double d = (V_in + Limit)*(Limit - V_in) / (double)2 + Limit * (Time - (Limit - V_in));
			V_in = Limit;
			return d;
		} else {//到達前に時間切れ
			double d = (V_in + V_in+Time)*(Time) / (double)2;
			V_in += Time;
			return d;
		}
	} else if(V_out>V_in){//最高速は下がるが、今の速度よりは大きい。
		if (Time >= V_out - V_in) {//余裕あり。
			if (Time > (Limit - V_in) + (Limit - V_out)) {//何秒か最高速を維持する
				double d = (V_in + Limit)*(Limit - V_in) / (double)2
					+ Limit * (Time - (Limit - V_in) - (Limit - V_out))
					+ (V_out + Limit)*(Limit - V_out) / (double)2;
				V_in = V_out;
				return d;
			} else {//あるところで加速から減速に向かうピークを持つ。
				double v = (Time + V_in + V_out) / (double)2;
				double d = (V_in + v)*(v - V_in) / (double)2 + (V_out + v)*(v - V_out) / (double)2;
				V_in = V_out;
				return d;
			}
		} else {//V_out到達前に時間切れ
			double d = (V_in + V_out + Time)*(Time) / (double)2;
			V_in += Time;
			return d;
		}
	} else {//今の速度が次の制限速度以上。
		if (Time >= V_in - V_out) {//余裕あり。
			if (Time > (Limit - V_in) + (Limit - V_out)) {//何秒か最高速を維持する
				double d = (V_in + Limit)*(Limit - V_in) / (double)2
					+ Limit * (Time - (Limit - V_in) - (Limit - V_out))
					+ (V_out + Limit)*(Limit - V_out) / (double)2;
				V_in = V_out;
				return d;
			} else {//あるところで加速から減速に向かうピークを持つ。
				double v = (Time + V_in + V_out) / (double)2;
				double d = (V_in + v)*(v - V_in) / (double)2 + (V_out + v)*(v - V_out) / (double)2;
				V_in = V_out;
				return d;
			}
		} else {//V_out到達前に時間切れ
			return 0;
		}
	}
}


