		cin >> t[i];
	}
	for(int i = 0; i < N; i++){
		cin >> v[i];
	}
	for(int i = 0; i < N; i++){
		for(int j = 0; j < t[i]; j++){
			vmax[cur_t + j] = v[i];
		}
		cur_t += t[i];
	}
	vmax[cur_t] = 0;
	vmax[0] = 0;

	int vm = 1000000;
	for(int i = 49999; i >= 0; i--){
		if(vmax[i] > vm){
			b1[i] = true;
		}
		vm = min(vmax[i], vm);
		v1[i] = vm;
		vm++;
	}

	vm = 0;
	for(int i = 49999; i >= 2; i--){
		vmax[i] = vmax[i - 1];
	}
	for(int i = 1; i <= cur_t; i++){
