                dp[j][i + 1] = max(dp[j][i + 1], dp[j + 1][i] + j + 1 / 2);
            if (j - 1 != -1 && dp[j - 1][i] != -BIG)
                dp[j][i + 1] = max(dp[j][i + 1], dp[j - 1][i] + j + 1 / 2);
            //cerr << i + 1 << " " << j << " " << dp[j][i + 1] << "\n";
        }
    }
    cout << fixed << setprecision(20);
    cout << dp[0][ts] / 4;
    return 0;
}

