# include <bits/stdc++.h>
using namespace std;
# define eps 1e-8
# define INF 1e20
# define pi  acos(-1.0)
# define MX  105
struct Node
{
    double t,v;
    double ev; //从终点的最大速度
}seg[MX];

int n;
double spd, ans;

void gogo(int x)
{
    double l=0, r=seg[x].t;
    double res = 0;
    while (l<r-eps) // <
    {
        double mid = (l+r)/2;
        if (mid + spd > seg[x].v-eps)
        {
            if ((seg[x].v - seg[x+1].ev) + mid < seg[x].t+eps)
            {
                res = mid;
                l = mid;
            }
            else r = mid;
        }
        else
        {
            if (mid + spd - (seg[x].t-mid) - seg[x+1].ev < -eps) //<=
            {
                res = mid;
                l = mid;
            }
            else r = mid;
        }
    }

    double jia, yun, jian;
    if (spd + res < seg[x].v)
    {
        jia = res;
        yun = 0;
        jian = seg[x].t - jia;
    }
    else
    {
        jia = seg[x].v - spd;
        yun = res - jia;
        jian = seg[x].t - jia - yun;
    }
    ans += 1.0/2.0*jia*jia + spd * jia;
    ans += yun * seg[x].v;

    if (res+spd < seg[x].v)
    {
        ans += -1.0/2.0*jian*jian +  (spd+jia) * jian;
        spd = spd + jia - jian;
    }
    else
    {
        ans += -1.0/2.0*jian*jian +  seg[x].v * jian;
        spd = seg[x].v - jian;
    }

}

int main()
{
    scanf("%d",&n);
    for (int i=1;i<=n;i++)
        scanf("%lf",&seg[i].t);
    for (int i=1;i<=n;i++)
        scanf("%lf",&seg[i].v);
    spd=0.0;
    for (int i=n;i>=1;i--)
    {
        if (spd+seg[i].t < seg[i].v+eps) //<=
            spd += seg[i].t;
        else
            spd = seg[i].v;
        seg[i].ev = spd;
    }
    ans = 0;
    spd = 0;
    seg[n+1] = (Node){0.0, 0.0, 0.0};

    for (int i=1;i<=n;i++)
    {
        gogo(i);
    }
    printf("%.5f\n",ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define REP(i, n) for(int i = 0; i < n; i++)
#define REPR(i, n) for(int i = n; i >= 0; i--)
#define FOR(i, m, n) for(int i = m; i < n; i++)
#define ALL(obj) (obj).begin(), (obj).end()
#define INF 1e9
typedef long long ll;

vector<int> t;
vector<int> v;
vector<int> t_sum;
double ans;

void dfs(int l, int r, int h){//[l,r)はすでに速度hに達している
    //cout << l << ", " << r << ", " << h << endl;
    if(l>=r) return;

    int l_itr = upper_bound(ALL(t_sum), l) - t_sum.begin() - 1;//左端はどの区間か
    int r_itr = lower_bound(ALL(t_sum), r) - t_sum.begin() - 1;//右端はどの区間か
    //cout << "  " << l_itr << ", " << r_itr << endl;

    if(r_itr == l_itr){//[l,r)が同一区間内なら
        if(r-l >= 2*(v[r_itr]-h)){
            ans += ((r-l) - (v[r_itr]-h)) * (v[r_itr]-h);
            return;
        }else{
            ans += (r-l)*(r-l)/4.0;
            return;
        }
    }

    int min_v = INF;
    int min_itr = -1;
    FOR(i,l_itr,r_itr+1){//区間内の最小速度を求める
        if(min_v > v[i]){
            min_v = v[i];
            min_itr = i;
        }
    }
    //cout << "    " << min_v << ", " << min_itr << endl;

    if((r-l) <= 2*(min_v-h)){//台形にならないなら
        ans += (r-l)*(r-l)/4.0;
        return;
    }

    int next_l1,next_r1,next_l2,next_r2;
    next_l1 = l+min_v-h;
    next_r2 = r-min_v+h;
    next_r1 = t_sum[min_itr];
    next_l2 = t_sum[min_itr+1];

    ans += ((r-l) - (min_v-h))*(min_v-h);

    if(next_r2 < next_r1 || next_l2 < next_l1){
        dfs(next_l1, next_r2, min_v);
    }else{
        dfs(next_l1,next_r1,min_v);
        dfs(next_l2,next_r2,min_v);
    }
}

int main() {
    int N; cin >> N;
    t.assign(N,0);
    v.assign(N,0);
    t_sum.assign(N+1,0);
    REP(i,N) cin >> t[i];
    REP(i,N) cin >> v[i];

    REP(i,N) t_sum[i+1] += t_sum[i] + t[i];
    ans = 0.0;
    dfs(0,t_sum[N],0);
    cout << ans << endl;
    return 0;
}

