        end_time += t[i];
        if(i < N -1) end_check[i] = end_time + v[i + 1];
        else end_check[i] = end_time;
    }

    double limit = 200000;
    double lc, rc;
    for(int i = 0;i < N;i++){
        cur_v = p_v;
