        rc = min(v[i] - limit, p_time);
        end_v = min(limit - p_time, p_time + cur_v - cur_time);
        cross_time = (cur_time - cur_v + limit) / 2;
        cross_v = limit - cross_time;
        if(p_time <= cross_time){
            ans += o_area(cur_time, p_time, cross_time, cross_v);
            if(lc <= cross_time && lc <= rc){
                ans -= i_area(lc, rc, cross_time, cross_v, v[i]);
            }
        }else if(cur_time >= cross_time){
            ans += o_area(cur_time, p_time, cross_time, cross_v);
        }else{
            ans += o_area(cur_time, p_time, cross_time, cross_v);
            if(lc <= cross_time && lc <= rc){
                ans -= i_area(lc, rc, cross_time, cross_v, v[i]);
            }
        }

    }

    printf("%lf\n", ans);
}

