void solve(ll N, vector<ll> t, vector<ll> v) {
  const int T = accumulate(ALL(t), 0LL);
  vector<int> limit(T), speed(T + 1, 1e9);
  int ti = 0;
  REP(i,N) {
    REP(j,t[i]) { limit[ti] = v[i]; ++ti; }
  }
  REP(i,T) {
    chmin(speed[i], limit[i]);
    chmin(speed[i+1], limit[i]);
  }
  speed[0] = speed[T] = 0;
  REP(i,T) chmin(speed[i+1], speed[i] + 1);
  REP(i,T) chmin(speed[T-i-1], speed[T-i] + 1);
  ld res = 0;
  REP(i,T) {
    // cout << speed[i] << endl;
    if (speed[i] == speed[i+1] && speed[i] < limit[i]) res += speed[i] + 0.25;
    else res += (speed[i] + speed[i+1]) / 2.0L;
  }
  cout << res << endl;
}

