double calc_min(double x) {
    double minn = inf;
    minn = min(minn, f(x, 0, 0, 0));
    minn = min(minn, f(x, T, T, 0));
    ll atime = 0;
    rep(i, N) {
        minn = min(minn, f(x, atime, atime + t[i], v[i]));
        atime += t[i];
    }
    return minn;
}

