double calc(ll t, ll v1, ll v2, ll vm) {
    vector<ll> V(t + 1);
    V[0] = v1, V[t] = v2;
    rep(i, 1, t){
        V[i] = min({V[i - 1] + 1, vm, v2 + t - i});
    }
    double ret = 0;
    rep(i, t){
        if(V[i] == V[i + 1] && V[i] < vm){
            ret += (double)V[i] + 0.25;
        }
        else{
            ret += (double)(V[i] + V[i + 1]) / 2.0;
        }

    }
    return ret;
}

