            }
            if ((curv + curr) <= v[i]) {
                ans += curv * curr + (curr * curr) / 2;
                ans += (curv + curr) * (t[i] - curr) - ((t[i] - curr) * (t[i] - curr)) / 2;
                curv = curv + curr - (t[i] - curr);
            }
