double solve (int t1, int v1, int t2, int v2, int vmax) {
	if (v1>vmax || v2 > vmax)
		return -1.0;
	double vmax_theory = min(v1,v2) + (t2-t1+abs(v2-v1))/2.0;
	double area1 = (vmax_theory-min(v1,v2))*(vmax_theory-min(v1,v2));
	double area2 = (abs(v1-v2)*abs(v1-v2))/2.0;
	double area3 = (t2-t1)*min(v1,v2);
	if (vmax_theory < vmax) {
		return area1-area2+area3;
	} else {
		double area4 = (vmax_theory-vmax)*(vmax_theory-vmax);
