#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;
#define rep(i,n) for(int i = 0; i < ((int)(n)); i++)   // 0-indexed昇順

int main() {
    int N; cin >> N;
    int tmax = 0;
    vector T(N+1,0);
    fprintf(stderr, "T: ");
    for (int i = 1; i <= N; i++) {
        int t; cin >> t;
        tmax += t;
        T.at(i) = tmax;
        fprintf(stderr, "%3d ", T[i]);
    }
    fprintf(stderr, "\n");
    vector V(N+1,0);
    using pi = pair<int,int>;
    priority_queue<pi, vector<pi>, greater<pi>> Q;
    rep(i,N) {
        cin >> V.at(i);
        if (i && V[i] - V[i-1] < 0) { // if it needs break
            int y = V[i] + T[i];
            Q.push({y, i});
        }
    }
    V[N] = 0;
    Q.push({T[N], N});

    int cbi = Q.top().second; Q.pop(); // current break index
    int ci = 0; // current index
    int cl = V[0]; // cuurent speed limit
    double v = 0; // current velocity
    double D = 0; // distance
    double x = 0; // current time (not delta)
    while (x < tmax) {
        double t; // t is absolute time
        if (cl > v) {
            double tf = x + cl - v; // time to change to fixed velocity
            t = (T[cbi] + V[cbi] - v + x) / 2; // time to hit while accelerating
            if (t <= T[ci + 1] && t < tf && cl >= (t - x) + v) { // HIT! Break!!
                fprintf(stderr, "After accelerating to %.2f, ", v + (t - x));
                fprintf(stderr, "Breaking at %f\n", t);
                // calc at
                // at += t - x; // D will be updated later
                D += (t-x) * (v + (v + (t-x))) / 2;
                D += (T[cbi]-t) * (v + t - x + V[cbi]) / 2;
                // forward to T[cbi]
                x = T[cbi];
                v = V[cbi];
                fprintf(stderr, "V down to %f at %f\n", v, x);
                cl = v;
                ci = cbi;
                // Update cbi
                while (!Q.empty() && cbi <= ci) cbi = Q.top().second, Q.pop();
                continue;
            }
            // accelerate to limit
            // at += tf - x; // D will be updated later
            if (tf > T[ci + 1]) { // Can't to accelerate to the limit
                tf = T[ci + 1];
                D += (tf - x) * (v + v + tf - x);
                ci++;
                v = v + tf - x;
                x = T[ci];
                cl = V[ci];
                continue;
            }
            D += (tf - x) * (v + cl) / 2;
            x = tf;
            v = cl;
            fprintf(stderr, "Accelerating V up to %f at %f\n", v, x);
            // else fall through
        }
        t = T[cbi] + V[cbi] - v; // When to HIT if go with fixed velocity
        if (x < t && t <= T[ci + 1]) { // Hit! Break!!
            fprintf(stderr, "Breaking at %f\n", t);
            D += (t - x) * v;
            D += (T[cbi] - t) * (v + V[cbi]) / 2;
            x = T[cbi];
            v = V[cbi];
            fprintf(stderr, "V down to %f at %f\n", v, x);
            cl = v;
            ci = cbi;
            while (!Q.empty() && cbi <= ci) cbi = Q.top().second, Q.pop();
            continue;
        } else { // Go!
            D += (T[++ci] - x) * v;
            x = T[ci];
            fprintf(stderr, "Go forward with velocity %f till %f\n", v, x);
            cl = V[ci];
        }
    }
    cout << fixed << setprecision(15);
    cout << D << endl;
}

