using namespace std;

class line {
public:
    double velocity;
    double start;
    double end;

    double calc(double time) {
        if (time >= start && time <= end) {
            return velocity;
        } else if (time < start) {
            return (start - time) + velocity;
        } else if (time > end) {
            return (time - end) + velocity;
        } else {
            throw;
        }
    }
};

int main(void) {
    throw;
    int n, t[102] = {0}, v[102] = {0};
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int tt;
        cin >> tt;
        t[i] = t[i - 1] + tt;
    }
    for (int i = 1; i <= n; i++)
        cin >> v[i];
    vector<line> lines;
    line l;
    for (int i = 1; i <= n; i++) {
        l.start = t[i - 1];
        l.end = t[i];
        l.velocity = v[i];
        lines.push_back(l);
    }
    l.start=-1;
    l.end=0;
    l.velocity=0;
    lines.push_back(l);
    l.start=t[n];
    l.end=t[n]+1;
    l.velocity=0;
    lines.push_back(l);
    double res = 0;
    for(double tt = 0;tt <= t[n];tt += 0.1) {
        double speed[2] = {10000,10000};
        for(auto& e:lines) {
            speed[0] = min(speed[0],e.calc(tt));
            speed[1] = min(speed[1],e.calc(tt+0.1));
        }
        res += (speed[0] + speed[1]) * 0.05;
    }
    cout << res << endl;
}

