  for (int i = 0; i < N; ++i) cin >> v[i];
  vector<int> vmax(N + 1, INT_MAX);

  for (int i = 0; i < N; ++i) {
    if (i > 0) vmax[i] = min(vmax[i], v[i - 1]);
    vmax[i] = min(vmax[i], v[i]);
  }


  vmax[0] = vmax[N] = 0;

  for (int tt = 0; tt <= N; ++tt) {
    for (int i = N; i >= 0; --i) {
      int tsum = 0;
      for (int j = i - 1; j >= 0; --j) {
        tsum += t[j];
        vmax[j] = min(vmax[j], vmax[i] + tsum);
      }
    }

    for (int i = 0; i <= N; ++i) {
      int tsum = 0;
      for (int j = i + 1; j <= N; ++j) {
        tsum += t[j - 1];
        vmax[j] = min(vmax[j], vmax[i] + tsum);
      }
    }
  }

  double ret = 0;
  for (int i = 0; i < N; ++i) {
    int yv = v[i];
    int x1 = 0;
    int x2 = t[i];
