    // cout<< "yv, y1, y2: " << yv << ' ' << y1 << ' ' << y2 << endl;
    // intersection 1, 2
    double xx = (x2 + y2 - y1) / 2.0;
    // 1, vertical
    double xv1 = yv - y1;
    xv1 = max(xv1, 0.0);
