double f(int vs, int vf, int t, int maxi) {
    double ret = 0.0;
    if(abs(vs-vf) > t) return -INF;
    if(vs > maxi || vf > maxi) return -INF;
    if(vs > vf) swap(vs, vf);
    double x = (vf-vs+t)/2.0;
    double y = t - x;
    double z = max(0.0, double(vs + x - maxi));
    return (double)vs * t + (double)x * x / 2.0 + (double)y * y / 2.0 - z*z + y*(x-y);
}

