    vs[i] = min(vs[i], vs[i - 1] + ts[i]);
  }
  for (int i = n; i >= 1; i--) {
    vs[i] = min(vs[i], vs[i + 1] + ts[i]);
  }
  double ans = 0;
  for (int i = 1; i <= n; i++) {
    double t = ts[i], d1 = vs[i] - vs[i - 1], d2 = vs[i] - vs[i + 1];
