      double vl = min(vs[i - 1], vs[i + 1]), vd = vl + t - max(vs[i - 1], vs[i + 1]);
      ans += (vl * 2 + t) * t / 2 - vd * vd / 4;
    } else {
      ans += vs[i] * ts[i];
      if (d1 > 0) ans -= d1 * d1 / 2;
      if (d2 > 0) ans -= d2 * d2 / 2;
    }
  }
