template<typename T,typename Compare>
class MonoQueue {
private:
    deque<pair<T,int>> que;
    Compare cmp;
public:
    void push(const T& val, int i) {
        while (!que.empty() && !cmp(que.back().first, val)) {
            que.pop_back();
        }
        que.emplace_back(val, i);
    }
    T get(int i) {
        while (que.front().second < i) {
            que.pop_front();
        }
        return que.front().first;
    }
};

