struct SegmentTree{
    int n;
    vector<double> node;

    double calc(double a,double b) {
        return a+b;
    }
    double e=0;

    SegmentTree(vector<double> v) {
        int sz=v.size();
        n=1;
        while(n<sz) {
            n*=2;
        }
        node.resize(2*n-1,e);
        for(int i=0;i<sz;i++) {
            node[i+n-1]=v[i];
        }
        for(int i=n-2;i>=0;i--) {
            node[i]=calc(node[2*i+1],node[2*i+2]);
        }
    }

    void update(int x,ll val) {
        x=n+x-1;
        node[x]=val;
        while(x>0) {
            x=(x-1)/2;
            node[x]=calc(node[2*x+1],node[2*x+2]);
        }
    }

    double query(int a,int b,int k=0,int l=0,int r=-1) {
        if(r<0) r=n;

        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return node[k];

        double vl=query(a,b,2*k+1,l,(l+r)/2);
        double vr=query(a,b,2*k+2,(l+r)/2,r);

        return calc(vl,vr);
    }

    ll at(int x) {
        return node[n+x-1];
    }
};

int main() {
    cout<<fixed<<setprecision(10);
    int n;
    cin>>n;
    vector<double> t(n+1),v(n+2);
    FOR(i,1,n) cin>>t[i];
    FOR(i,1,n) cin>>v[i];
    SegmentTree segt(t);

    FOR(i,1,n) {
        FOR(j,0,i-1) {
            chmin(v[i],v[j]+segt.query(j+1,i+1));
        }
        FOR(j,i+1,n+1) {
            chmin(v[i],v[j]+segt.query(i,j+1));
        }
    }

    double ans=0;
    FOR(i,1,n) {
        if(v[i-1]<=v[i] && v[i]<=v[i+1]) {
            ans+=v[i]*t[i]-pow((v[i]-v[i-1]),2)/2;
        }
        else if(v[i-1]>=v[i] && v[i]>=v[i+1]) {
            ans+=v[i]*t[i]-pow((v[i]-v[i+1]),2)/2;
        }
        else if(v[i-1]<v[i] && v[i]>v[i+1]) {
            double d=v[i+1]-v[i-1];
            ans+=t[i]*(v[i-1]+t[i]/2+d/2)-(pow(t[i]/2+d/2,2)+pow(t[i]/2-d/2,2))/2-pow(max(0.0,v[i-1]+t[i]/2+d/2-v[i]),2);
        }
        else {
            ans+=v[i]*t[i];
        }
        //cout<<ans<<endl;
    }
    cout<<ans<<endl;
}

