class Range{
public:
    float start;
    float end;
    float height;
    Range(float s, float e, float h){
        start = s;
        end = e;
        height = h;
    }

    float getCeil(float t){
        if(start <= t && t <= end){
            return height;
        }
        else if(t < start){
            float diff = start - t;
            return height + diff;
        }
        else if(t > end){
            float diff = t - end;
            return height + diff;
        }
    }

    string ToString(){
        return to_string(start) + " " + to_string(end) + " " + to_string(height);
    }
};

vector<int> T;
vector<int> V;
vector<Range> ranges;

float getHeight(float t){
    float minHeight = 100000;
    for(auto range : ranges){
        float height = range.getCeil(t);
        minHeight = min(minHeight, height);
    }
    return minHeight;
}

