    for (int i = 0; i <= 203; i++) {
        dp[0][i] = -1;
        dp[1][i] = -1;
    }
    dp[0][0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < t[i] * 2; j++) {
            for (int k = 0; k <= v[i] * 2; k++) {
                if (k < v[i] * 2 && dp[0][k + 1] != -1) {
                    dp[1][k] = max(dp[1][k], dp[0][k + 1] + (2 * k + 1) * 0.125);
                }
                if (dp[0][k] != -1) {
                    dp[1][k] = max(dp[1][k], dp[0][k] + k * 0.25);
                }
                if (k > 0 && dp[0][k - 1] != -1) {
                    dp[1][k] = max(dp[1][k], dp[0][k - 1] + (2 * k - 1) * 0.125);
                }
            }
            for (int k = 0; k <= 203; k++) {
                dp[0][k] = dp[1][k];
                dp[1][k] = -1;
            }
        }
    }
    cout << dp[0][0] << endl;
