double eps = 1e-4;
struct point {
	double x;
	double y;
};

struct line {
	point l;
	point r;
};

line getline(point p1, point p2) {
	if (p1.x > p2.x + eps)swap(p1, p2);
	return line{ p1,p2 };
}

double slope(line a) {
	return (a.r.y - a.l.y) / (a.r.x - a.l.x);
}

point crosspoint(line l1, line l2) {
	double a = slope(l1);
	double b = l1.l.y;
	double c = slope(l2);
	double d = l2.l.y;
	return { l1.l.x + (d - b) / (a - c), a * (d - b) / (a - c) + b };
}

int cross(line l1, line l2) {
	if (l1.l.y + eps < l2.l.y && l1.r.y + eps < l2.r.y) return 1;
	if (l2.l.y + eps < l1.l.y && l2.r.y + eps < l1.r.y) return 2;
	return 0;
}

double integ(line a) {
	return (a.r.y + a.l.y) * (a.r.x - a.l.x) / 2.0;
}

vector<line> minarea(line l1, line l2) {
	vector<line> ret;
	int c = cross(l1, l2);
	if (c == 1) {
		ret.push_back(l1);
		return ret;
	}
	else if (c == 2) {
		ret.push_back(l2);
		return ret;
	}
	point cp = crosspoint(l1, l2);
	ret.push_back({ {l1.l.x, min(l1.l.y, l2.l.y)}, cp });
	ret.push_back({ cp, {l1.r.x, min(l1.r.y, l2.r.y)} });

	return ret;
}

struct constraints {
	line l1, l2, l3;
};

point linepoint(line a, double x) {
	return { x, slope(a) * (x - a.l.x) + a.l.y };
}

vector<line> minarea(constraints c) {
	vector<line> ret;
	auto tmp = minarea(c.l1, c.l2);
	for (auto lin : tmp) {
		auto tmp2 = minarea(lin, getline(linepoint(c.l3, lin.l.x), linepoint(c.l3, lin.r.x)));
		ret.insert(ret.end(), tmp2.begin(), tmp2.end());
	}
	return ret;
}

line upline(point start, double t) {
	return line{ start, point{start.x + t, start.y + t} };
}

line downline(point goal, double t) {
	return line{ point{goal.x - t, goal.y + t},goal };
}

int main() {
	ll N; cin >> N;
	vector<double> T(N+2), V(N+2);
	vector<constraints> con;
	vector<line> area;
	T[0] = 0; V[0] = 0;
	REP(i, 1, N + 1) {
		cin >> T[i];
		T[i] += T[i - 1];
	}
	REP(i, 1, N+1) cin >> V[i];
	 T[N + 1] = T[N]; V[N + 1] = 0;
	REP(i, 1, N+1) {
		con.push_back(
			constraints{
				upline(point{T[i - 1], V[i - 1]}, T[i] - T[i - 1]),
				downline(point{T[i],V[i+1]}, T[i] - T[i - 1]),
				getline(point{T[i - 1], V[i]},point{T[i], V[i]})
			}
		);
	}
	for (auto c : con) {
		auto ret = minarea(c);
		area.insert(area.end(), ret.begin(), ret.end());
