double area(tuple<double, double, int> a, tuple<double, double, int> b) {
	double at, av, bt, bv;
	tie(at, av, ignore) = a;
	tie(bt, bv, ignore) = b;
	return (bt-at) * (av+bv) / 2;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	int n;
	cin >> n;
	vector<double> t(n), v(n);
	rep(i, n) cin >> t[i];
	rep(i, n) cin >> v[i];
	v.push_back(0);
	vi nt(n+1);
	rep(i, n) nt[i+1] = nt[i] + t[i];

	stack<tuple<double, double, int> > st; //time, velocity, up
	st.emplace(0, 0, 1);

	rep(i, n) {
		double time, vel;
		int up;
		double now = nt[i+1];
		tie(time, vel, up) = st.top();
		if(up) {
			if(vel-(now-time) > v[i+1]) {
				st.pop();
				i--;
				continue;
			}
			if(now-time + vel <= v[i]) {
				if(now-time + vel <= v[i+1]) continue;
				else {
					double tt = (now+v[i+1]-vel+time)/2;
					st.emplace(tt, now-tt+v[i+1], 0);
					st.emplace(now, v[i+1], 0);
				}
			}
			else {
				if(v[i] < v[i+1]) {
					st.emplace(v[i]-vel+time, v[i], 0);
					st.emplace(now, v[i], 1);
				} else {
					double tt = (now+v[i+1]-vel+time)/2;
					double vv = tt-time+vel;
					if(vv > v[i]) {
						st.emplace(v[i]-vel+time, v[i], 0);
						st.emplace(now-(v[i]-v[i+1]), v[i], 0);
						st.emplace(now, v[i+1], 0);
					} else {
						st.emplace(tt, now-tt+v[i+1], 0);
						st.emplace(now, v[i+1], 0);
					}
				}
			}
		} else {
			if(vel-(now-time) > v[i+1]) {
				st.pop();
				i--;
				continue;
			} else {
				if(v[i] < v[i+1]) {
					st.emplace(now, v[i], 1);
				} else {
					st.emplace(now-vel+v[i+1], vel, 0);
					st.emplace(now, v[i+1], 0);
				}
			}
		}
	}

	double ans = 0;
	while(st.size() != 1) {
		auto now = st.top();
		//cout << get<0>(now) << ' ' << get<1>(now) << ' ' << get<2>(now) << endl;
		st.pop();
		ans += area(st.top(), now);
	}

	cout << fixed << setprecision(6) << ans << endl;
}

