double maxSpeed(double speed, int index) {
    double ans = (double) min(speed + t[index], (double) v[index]);
    int cnt = 0;
    for (int i = index + 1; i < n; i++) {
        cnt += t[i - 1];
        x[index] = min(x[index], cnt - ans + v[i]);
    }
    cnt = 0;
    for (int i = index + 1; i < n; i++) {
        cnt += t[i - 1];
        double tmp = (cnt + speed + v[i]) / 2.;
        if (tmp < ans) {
            ans = tmp;
            x[index] = tmp - speed;
        }
    }
    return ans;
}

