    Rep(0, r, t) maxi[t] = min(t, r-t);

    rep(N, n) {
        Rep(0, r, t) {
            if (t < 2*tacc[n]) maxi[t] = min(maxi[t], (2*tacc[n]-t)+2*vs[n]);
            else if (t > 2*tacc[n+1]) maxi[t] = min(maxi[t], abs(2*tacc[n+1]-t)+2*vs[n]);
            else maxi[t] = min(maxi[t], 2*vs[n]);
        }
    }
    double ans = 0.;
    Rep(0, r-1, t) ans += (double)(maxi[t+1] + maxi[t])/2/4;

    printf("%.6lf\n", ans);
}

