double v_min(int*v, int* t, int size, double x){
  double ans=DBL_MAX;
  for(int i=1; i<=size; i++){
    ans = min(f((double)v[i], (double)t[i-1], (double)t[i], x), ans);
  }
  ans = min(f(0.0, 0.0, 0.0, x), ans);
  ans = min(f(0.0, (double)t[size], (double)t[size], x), ans);

  return ans;
}

double f(double v, double l, double r, double x){
  double ans;
  if(0<=x && x<=l) ans=v+(l-x);
  else if(l<=x && x<=r) ans=v;
  else ans=v+(x-r);
  return ans;
}

