    rep(i,n){
        double gl = min(v[i+1],tot-targ[i]);
        if(gl>=v[i]){
            if(vt + t[i] <= v[i]) {area += t[i]*(t[i] - vt)/2.0 + t[i]*vt; vt = t[i];}
            else {
                area += (v[i]-vt) * ((v[i]-vt)/2.0 + vt);
                area += (t[i] - (v[i]-vt))*v[i]; vt = v[i];

            }
        }else{

            if(v[i]-vt + v[i] - gl<=t[i]){
                area += (v[i]-vt)*(v[i]-vt)/2.0 + vt * (v[i]-vt) + gl*(v[i]-gl) +(v[i]-gl) *(v[i]-gl) /2.0 + v[i]*(t[i] -((v[i]-vt + v[i] - gl) ));
                vt = gl;
            }else{
                double dt = (gl-vt+t[i])/2.0;
                if (dt<0)dt = 0;
                area += vt * dt + (t[i]-dt) * gl;
                area += dt*dt/2.0 + (t[i]-dt)*(t[i]-dt)/2.0;
                vt = gl;
            }

        }

    }

    printf("%.10lf\n",area);
    return 0;
}

