    t[n]=0;
    v[n]=0;
    rep(i,n){
        t[i+1]=t[i+1]+t[i];
    }
    int id=0;
    double nv=0.0;
    bool ac=false;
    bool p=false;
    double ans=0.0;

    if(n==1&&t[0]<=v[0]){
        cout << (t[0]*t[0]/2.0)/2.0 << endl;
