            if(nv-v[id+1]>0){
                nv--;
                ac=true;
                p=true;
            }
        }else{
            if(nv<v[id]){
                nv++;
                ac=true;
            }
        }
        if(p){
            ans+=nv+1/2.0;
        }else if(ac){
            ans+=nv-1/2.0;
        }else{
            ans+=nv;
        }
    }
    cout << ans << endl;

