void fix(int idx) {
  if (idx > 0 && speed[idx] + 1 < speed[idx - 1]) {
    speed[idx - 1] = speed[idx] + 1;
    fix(idx - 1);
  }
  if (idx < sum && speed[idx] + 1 < speed[idx + 1]) {
    speed[idx + 1] = speed[idx] + 1;
    fix(idx + 1);
  }
}

int main() {
  int n;
  scanf("%d", &n);
