    for (int j = 0; j <= t[i]; j++) {
      if (j == 0) {
        limit[idx] = v[i];
        speed[idx] = min(v[i], speed[idx]);
      } else {
        limit[idx] = v[i];
        speed[idx] = v[i];
      }
      idx++;
    }
    idx--;
  }
  speed[0] = 0;
  speed[sum] = 0;
  for (int i = 0; i <= sum; i++) {
