	double res = 0;
	for (double i = 0; i <= T; i++)
	{
		double minu = INF;
		for (int j = 0; j < n; j++)
		{
			if (i <= ft[j]) {
				minu = min(minu,v[j] + (ft[j] - i));
			}
			else if (ft[j] <= i && i <= tt[j]) {
				minu = min(minu, v[j]);
			}else if(tt[j] <= i){
				minu = min(minu, v[j] + (i - tt[j]));
			}
		}
		double mih = INF;
		if (i == T) continue;
		double ni = i + 0.5;
		for (int j = 0; j < n; j++)
		{
			if (ni <= ft[j]) {
				mih = min(mih, v[j] + (ft[j] - ni));
			}
			else if (ft[j] <= ni && ni <= tt[j]) {
				mih = min(mih, v[j]);
			}
			else if (tt[j] <= ni) {
				mih = min(mih, v[j] + (ni - tt[j]));
			}
		}

		res += minu + mih;
	}
	cout << (res / 2.0) << endl;
}

