            if ( P[i].first >= time ) { v_limit = min( v_limit, P[i].first - time + P[i].second );  continue; }
            v_limit = P[i].second;
        }

        double v_new;
        if ( v+0.5 <= v_limit ) { v_new = v + 0.5; } 
        else if ( v > v_limit ) { v_new = v - 0.5; }

        ans += v*0.5;
        if ( v != v_new ) { ans += v < v_new ? (0.5*0.5)/2.0 : -(0.5*0.5)/2.0; }

        v = v_new;

        // cout << time << " " << v << endl;
    }


    printf( "%.7f", ans );

    return 0;
}

