using namespace std;

int N, t[101], v[101];
int p[101] = {}, checkP[101] = {}, now = 0;

float term(int n) {
	float cc, cv;
	float sum = 0;
	cv = v[n] - now;
	cc = (checkP[n] - now + t[n]) / 2;
	if (cv > cc) {
		sum += cc*(now + cc / 2);
		sum += (t[n] - cc)*(now + cc + checkP[n]) / 2;
	}
	else {
		cc = t[n] - (v[n] - checkP[n]);
		sum += cv*(v[n] + now)/2;
		sum += (cc-cv)*v[n];
		sum += (t[n] - cc)* (v[n] + checkP[n]) / 2;
	}
	now = checkP[n];
	return sum;
}

int main()
{
