	for (int i = 1; i < N; i++) 
		p[i] = min(v[i], v[i+1]);
	p[N] = 0;

	for (int i = N; i > 0; i--) {
		int minP = N;
		for (int j = i; j <= N; j++) {
			if (p[j] < p[minP]) {
				minP = j;
				checkP[i] = p[j];
			}
		}
		for (int j = i; j <= N; j++) {
			p[j] += t[i];
		}
	}

	int sum = 0;
	for (int i = 1; i <= N; i++)
		sum += term(i);

	cout << sum << endl;

	return 0;
}

