  for (double i=0; i<=dist+eps; i+=.5){
      if (cnt%2 == 0 && here[cnt/2].size() != 0){
          for (pair<double, double> p : here[cnt/2]){
              if (p.first == 1){
                  lowestpos.insert(p.second);
              }
          }
          curmax = v[cnt2];
