i64 N;
vector<f80> T;
vector<f80> V;

void solve() {
    const f80 DT = pow(2,-13);

    vector<f80> vls(N);
    vls[0] = 0;
    for(i64 i = 1; i < N; ++i) {
        vls[i] = min({
            vls[i-1] + T[i-1],
            V[i-1],
            V[i],
        });
    }

    vector<f80> vrs(N);
    vrs[N-1] = 0;
    for(i64 i = N-2; i >= 0; --i) {
        vrs[i] = min({
            vrs[i+1] + T[i+1],
            V[i+1],
            V[i],
        });
    }

    f80 ans = 0;
    for(i64 i = N-1; i >= 0; --i) {
        f80 v  = V[i];
        f80 vl = vls[i];
