            if(t[j] == s[i+j] or s[i+j] == '?') {
                match_count++;
            }
        }
        if(match_count == t.size()) {
            s.replace(i,t.size(),t);
            replace(s.begin(), s.end(), '?', 'a');            
            return s;
        }
    }
    return "UNRESTORABLE";
}

