using namespace std;

bool getCrossPoint(double *x, double *y, double grad1, double seg1, double grad2, double seg2) {
    if(grad1 - grad2 == 0)
        return false;
    *x = (seg2 - seg1) / (grad1 - grad2);
    *y = grad1 * *x + seg1;
}

int main() {
    int N;
    cin >> N;
    double t[N + 1];
    double v[N + 2];
    double vs = 0;
    double d = 0;
    t[0] = 0;
    for(int i = 1; i < N + 1; i++) cin >> t[i];
    v[0] = 0;
    for(int i = 1; i < N + 1; i++) cin >> v[i];
    v[N + 1] = 0;
    for(int i = 1; i < N + 1; i++){
        double x1, y1;
        if(v[i] < v[i + 1])
            getCrossPoint(&x1, &y1, 1, vs, -1, t[i] + v[i]);
        else
            getCrossPoint(&x1, &y1, 1, vs, -1, t[i] + v[i + 1]);
        if(v[i] < y1){
            double x2, y2;
            double x3, y3;
            getCrossPoint(&x2, &y2, 0, v[i], 1, vs);
            d +=  vs * x2;
            d += (y2 - vs) * x2 / 2.;
            if(v[i] < v[i + 1])
                getCrossPoint(&x3, &y3, 0, v[i], -1, t[i] + v[i]);
            else
                getCrossPoint(&x3, &y3, 0, v[i], -1, t[i] + v[i + 1]);
            d += v[i] * (x3 - x2);
            d += v[i + 1] * (t[i] - x3);
            d += (y3 - v[i + 1]) * (t[i] - x3) / 2.;
        }else{
            d +=  vs * x1;
            d += (y1 - vs) * x1 / 2.;
            d += v[i + 1] * (t[i] - x1);
            d += (y1 - v[i + 1]) * (t[i] - x1) / 2.;
        }
        if(v[i] < v[i + 1])
            vs = v[i];
        else
            vs = v[i + 1];
    }
    cout << d << endl;
    return 0;
}

