          right_v = tv.v;
          result_tv.push_back({tv.t - diff, right_v, horizontal});
        } else {
          result_tv.push_back({tv.t, right_v, up});
          right_v += tv.v;
        }
      } else {
        if (right_v + tv.t <= tv.v){
          result_tv.push_back({tv.t, right_v, up});
          right_v += tv.t;
        } else {
          result_tv.push_back({(tv.t- right_v + tv.v) / 2, right_v,up });
          result_tv.push_back({tv.t - (tv.t - right_v + tv.v) / 2, tv.v,up });
          right_v = tv.v;
        }
      }
    }
    reverse(result_tv.begin(), result_tv.end());

    double integral = 0;
    for(auto tv : result_tv) {
      integral += tv.t * tv.v; 
      if (tv.d == up){
        integral += tv.t * tv.t /2;
      }
    }

    cout << integral << endl;
    return 0;
}

