double speed(double x) {
	double f[102], t_t = 0, f_tmp;
	f[0] = x;
	f_tmp = f[0];
	f[1] = t_time - x;
	if (f_tmp > f[1])	f_tmp = f[1];
	for (int i = 0; i < N; i++) {
		t_t += t[i];
		if (t_t - t[i] >= x) {
			f[i + 2] = v[i] + (t_t - t[i] - x);
		}
		else if (t_t - t[i] < x && t_t >= x) {
			f[i + 2] = v[i];
		}
		else if (t_t < x) {
			f[i + 2] = v[i] + (x - t_t);
		}
		if (f_tmp > f[i + 2])	f_tmp = f[i + 2];
	}
	return f_tmp;
}

