    v.push_back(0);
    cumt.push_back(*(cumt.end() - 1));
    cumt.push_back(*(cumt.end() - 1) + INF);

    int T = *(cumt.end() - 2);

    int vs = 0.0;
    int ve;
    int ans = 0;
    for (int i = 0; i < T; i++)
    {
        int minv = INF;
        for (int j = 0; j < N + 2; j++)
        {
            int limv;
            int curt = i + 1;
            if (curt <= cumt[j])
            {
                limv = v[j] + cumt[j] - curt;
            }
            else if (cumt[j] <= curt && curt <= cumt[j + 1])
            {
                limv = v[j];
            }
            else
            {
                limv = v[j] + curt - cumt[j + 1];
            }

            minv = min(minv, limv);
        }
        if (vs + 1 <= minv)
        {
            ve = vs + 1;
        }
        else if (vs == minv)
        {
            ve = vs;
        }
        else
        {
            ve = vs - 1;
        }
        ans += vs + ve;
        vs = ve;
    }

    cout << ans / 8.0 << endl;

    return 0;
}

