void solve() {
  double currentV = 0;
  double sum = 0;
  for (int i=0;i<n;i++) {
    int timeToCurrentSpeed = abs(v[i] - currentV);
    int timeToNextSpeed = abs(v[i+1] - v[i]);
    if (t[i] > timeToCurrentSpeed + timeToNextSpeed) {
      sum += (currentV + v[i]) * timeToCurrentSpeed / 2.0 + v[i] * (t[i] - timeToCurrentSpeed - timeToNextSpeed) + (v[i] + min(v[i], v[i+1])) * timeToNextSpeed / 2.0;
    } else {
      double maxV = max(currentV, max(v[i] - (timeToCurrentSpeed + timeToNextSpeed - t[i]) / 2.0, min(v[i], v[i+1])));
      double timeToMaxSpeed = (maxV - currentV);
      sum += (currentV + maxV) * timeToMaxSpeed / 2.0 + (maxV + v[i+1]) * (t[i] - timeToMaxSpeed) / 2.0;
    }
    currentV = min(v[i], v[i+1]);
  }
  cout << setprecision(10) << sum << endl;
}

