signed main() {
  int n;
  cin >> n;
  int t[n + 1];
  t[0] = 0;
  for (int i = 1; i <= n; i++) {
    cin >> t[i];
    t[i] += t[i - 1];
  }

  int v[n];
  for (int i = 0; i < n; i++) {
    cin >> v[i];
  }
  int T = t[n] * 2;
  double f[n + 2][T + 1];
  for (int i = 0; i < n + 2; i++) {
    for (int j = 0; j < T + 1; j++) {
      if (i == 0) {
        f[i][j] = j / 2.0;
      } else if (i == n + 1) {
        f[i][j] = (T - j) / 2.0;
      } else {
        int l = t[i - 1] * 2;
        int r = t[i] * 2;
        if (j < l) {
          f[i][j] = v[i - 1] + (l - j) / 2.0;
        } else if (j > r) {
          f[i][j] = v[i - 1] + (j - r) / 2.0;
        } else {
          f[i][j] = v[i - 1];
        }
      }
    }
  }
  double V[T + 1];
  fill(V, V + T + 1, 1 << 29);
  for (int j = 0; j < T + 1; j++) {
    for (int i = 0; i < n + 2; i++) {
      V[j] = min(V[j], f[i][j]);
    }
  }
  double ans = 0.0;
  for (int i = 0; i + 1 < T + 1; i++) {
    ans += (V[i] + V[i + 1]) * 0.5 / 2;
  }
  cout << ans << endl;
  return 0;
}

