				}else if(ut+bt>t[i]){
					int uk=now-v[i+1];
					long double timeu=(long double)t[i]/2.0-(long double)uk/2.0;
					long double timed=(long double)t[i]/2.0+(long double)uk/2.0;
					ans+=(long double)timeu*((long double)now+now+timeu)/2.0;
					ans+=(long double)timed*((long double)v[i+1]+v[i+1]+timed)/2.0;
					now=v[i+1];
				}else{
					ans+=(long double)ut*(now+now+ut)/2.0;
					ans+=(long double)(t[i]-ut-bt)*v[i];
					ans+=(long double)bt*(v[i+1]+v[i+1]+bt)/2.0;
					now=v[i+1];
				}
			}
		}
	}
	printf("%.9f\n",(double)ans);
	return 0;
}

