inline double calc(li l, li r, li lim, li len) {
    //p4(l,  r,  lim, len);
    // 山のてっぺんがvに達しない場合
    if (l > r)swap(l, r);
    assert(l <= r);
    if (lim - l + lim - r > len) {
        double ll = (l + r) * (r - l) / 2.0;
        len -= (r - l);
        double len2 = len / 2.0;
        double yama = (r + len2 + r) * len2;
        return ll + yama;
    }
    double base = lim * len;
    base -= (lim - l) * (lim - l) / 2.0;
    base -= (lim - r) * (lim - r) / 2.0;
    return base;
}

