    repp(i, 1, n) {
        left_[i] = min(left_[i - 1] + t[i - 1], min(v[i - 1], v[i]));
        right_[i - 1] = left_[i];
    }
    right_[n - 1] = 0;
    for (li i = n - 2; i >= 0; i--) {
        right_[i] = min(right_[i + 1] + t[i + 1], min(v[i], v[i + 1]));
        right_[i] = min(right_[i], left_[i + 1]);
        left_[i + 1] = min(left_[i + 1], right_[i]);
    }
    double res = 0.0;
    rin{
        res += calc(left_[i], right_[i], v[i], t[i]);
    }
    printf("%.12f\n", res);


    return 0;
}

