    I end() { return itr; }
    //毎回コピーする
    operator vector<typename I::value_type>() {
        return vector<typename I::value_type>(itl, itr);
    }
};
template<class I, class J, require_t(is_integral_v<I>)>
vector<int> range(I l, J r){
    return iota(l, r-l);
