int N;
int nmax = 100;
vector<int> t(nmax);
vector<int> v(nmax);
vector<int> sum(nmax+1,0);

double solve(int ts, int tg, int vmin){
    int vm = 100;
    double ret;
    int is,ig;
    for(int i=1;i<=N;i++){
        if(ts>=sum[i-1]&&ts<sum[i]) is = i-1;
        if(tg>sum[i-1]&&tg<=sum[i]) ig = i-1;
    }
    //////
    //cout << ts <<" " << tg << " " << is << " "<<ig <<endl;
    //// 
    for(int i=is;i<=ig;i++) if(v[i]>vmin)vm = min(vm,v[i]);
    if(tg-ts<=(vm-vmin)*2) {
        ret = (double)(tg-ts)*(double)(tg-ts)/4.0;
    }else{
        ret = (double)((tg-ts)*(vm-vmin)-(vm-vmin)*(vm-vmin));
        ts += (vm-vmin);
        tg -= (vm-vmin);
        for(int i=1;i<=N;i++){
            if(ts>=sum[i-1]&&ts<sum[i]) is = i-1;
            if(tg>sum[i-1]&&tg<=sum[i]) ig = i-1;
        }
        bool f = false;
        int ts2,tg2;
        ///////ここの処理をがんばる
        for(int i=is;i<=ig;i++){
            if(f==false){
                if(v[i]>vm){
                    f  = true;
                    ts2 = max(ts,sum[i]);
                }
            }
            if(f== true){
                if(v[i]==vm){
                    f = false;
                    tg2 = min(tg,sum[i]);
                    ret+=solve(ts2,tg2,vm);
                }else if(i==ig){
                    tg2 = tg;
                    ret+=solve(ts2,tg2,vm);
                }
            }
        }
    }
    return ret;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N;
    sum[0]=0;
    REP(i,N) {
        cin >> t[i];
        sum[i+1] = sum[i]+t[i];
    }
    REP(i,N) cin >> v[i];
    double ans = 0.0;
    ans = solve(0,sum[N],0);
    cout << ans << endl;
    return 0;
}

