	fill_all(dp, (double)-1919191919);
	dp[0][0] = 0;
	REP(i, maxtime) {//time
		REP(j, 301) {//speed
			if (dp[i][j] == -1919191919) { continue; }
			for (ll k = -1; k < 2; k++) {//-1=down,0= straight,1= up
				if (j + k > speed[i + 1] || j + k < 0) {//speedが上限を超えているor0より下
					continue;
				}
				if (k == 1 && j  == speed[i]) {//上がっていく際に、はみ出してしまったらだめ（配列の作り方から考えてこうなる
					continue;
				}
				dp[i + 1][j + k] = max(dp[i + 1][j + k], dp[i][j] + j + k * 0.5);
			}
			if (speed[i] > j&&speed[i+1]>=j) {
				dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + 0.25 + j);
			}
		}
	}
	printf("%.10f\n", dp[maxtime][0]);
}

