class SEGMENT {
public:
  double in, out;
  double dist;
  SEGMENT() {}
  SEGMENT(double in, double out, double dist): in(in), out(out), dist(dist) {}
};

const double esp = 1e-8;

vector<double> T(105), V(105);
vector<SEGMENT> segs(105);

void rec(int i, double v) {
  if (i < 0) return;
  auto seg = segs[i];

  if (V[i]-seg.in + V[i]-v < T[i]) {
    seg.out = v;
    seg.dist = V[i] * T[i] - (V[i]-seg.in)*(V[i]-seg.in)/2.0 \
    - (V[i]-v)*(V[i]-v)/2.0;

    segs[i] = seg;
    return;
  } else if (v+T[i] > seg.in) {
    seg.out = v;

    double tmp_t =  (T[i] - (seg.in-v))/2.0;

    seg.dist = tmp_t * tmp_t + seg.in * tmp_t * 2.0 \
    + v * (seg.in-v) + (seg.in-v)*(seg.in-v)/2.0;

    segs[i] = seg;
    return;
  } else {
    seg.in = v + T[i];
    seg.out = v;
    seg.dist = v * T[i] + T[i]*T[i]/2.0;
    segs[i] = seg;
    rec(i-1, segs[i].in);
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n; cin >> n;
  rep(i, 0, n) {
    cin >> T[i];
  }

  rep(i, 0, n) {
    cin >> V[i];
  }

  V[n] = 0.0;

  SEGMENT first;
  if (T[0] > V[0]) {
    first.in = 0.0;
    first.out = V[0];
    first.dist = (T[0]+(T[0]-V[0]))*V[0]/2.0;
  } else {
    first.in = 0.0;
    first.out = T[0];
    first.dist = T[0]*T[0]/2.0;
  }

  segs[0] = first;

  rep(i, 1, n+1) {
    auto prev_seg = segs[i-1];
    auto cur_seg = segs[i];
    auto v = V[i];
    auto t = T[i];

    if (prev_seg.out > v) {
      // debug(i);
      cur_seg.in = cur_seg.out = v;
      cur_seg.dist = v * t;
      segs[i] = cur_seg;
      rec(i-1, v);
    } else {
      cur_seg.in = prev_seg.out;
      if ((v - cur_seg.in) > t) {
        cur_seg.out = cur_seg.in + t;
        cur_seg.dist = (cur_seg.in + cur_seg.out)*t/2.0;
      } else {
        cur_seg.out = v;
        cur_seg.dist = (cur_seg.in + v)*(v-cur_seg.in)/2.0 \
        + (t-(v-cur_seg.in))*v;
      }
      segs[i] = cur_seg;
    }
  }

  double ans = 0.0;
  rep(i, 0, n) {
    ans += segs[i].dist;
  }

  Decimal(ans);

  return 0;
};

