    REP(j,n+2){
      ll vj;
      if(j==0){
        vj = vel_max(i,t[j],t[j],v[j]);
      }else if(j==n+1){
        vj = vel_max(i,t[j-1],t[j-1],v[j]);
      }else{
        vj = vel_max(i,t[j-1],t[j],v[j]);
      }
      if(vj<vmin){
        vmin = vj;
      }
    }
    velocity[i]=vmin;
  }
  ll distance = 0;
  REP(j,2*tsum){
    distance += velocity[j]+velocity[j+1];
  }
  cout << setprecision(17) << distance/8.0 << endl;
}

