using namespace std;

double VM(double x, int i, vector<int> V, vector<int> L) {
	if (0 <= x && x <= L[i]) {
		return V[i] + (L[i] - x);
	}
	else if (L[i] < x && x <= L[i + 1]) {
		return V[i];
	}
	else return V[i] + (x - L[i + 1]);
}

int main() {
	int N;
	cin >> N;
	vector<int> T(N, 0), V(N, 0), L(N + 1, 0);
	for (int i = 0; i < N; i++) cin >> T[i];
	for (int i = 0; i < N; i++) cin >> V[i];
	for (int i = 0; i < N; i++) L[i + 1] = L[i] + T[i];
	vector<double> minV(2 * L[N] + 1, -1);
	for (int i = 0; i < 2 * L[N] + 1; i++) {
		for (int j = 0; j < N; j++) {
			if (minV[i] == -1) minV[i] = VM(i*0.5, j, V, L);
			else minV[i] = min(minV[i], VM(i*0.5, j, V, L));
		}
		minV[i] = min(minV[i], L[N] - i * 0.5);
		minV[i] = min(minV[i], i*0.5);
	}

	double Ans = 0;
	for (int i = 0; i < 2 * L[N]; i++) {
		Ans += (minV[i] + minV[i + 1]) / 4;
	}
	cout << Ans << endl;
}

