double calcDistance(int fs, int es, int et, int mv) {
    /*
    dump(fs);
    dump(es);
    dump(et);
    dump(mv);
    */
    const double diff = (double)et;
    int fpo = mv - fs, spo = es + diff - mv;
    double po = 0.5 * (es - fs + diff);
    double ret = 0;
    if (fpo <= spo) {
        ret += 0.5 * fpo * (mv + fs);
        ret += (spo - fpo) * mv;
        ret += 0.5 * (diff - spo) * (mv + es);
    } else {
        ret += 0.5 * po * (fs + fs + po);
        ret += 0.5 * (diff - po) * (es + es + (diff - po));
    }
    return ret;
}

