class Solver {
public:
	int H, W;

	bool grid_ok(int y, int x) {
		return 0 <= y && y < H && 0 <= x && x < W;
	}

	int N;
	vector<int> max_v2;
	vector<int> t2, v2;

	void set_max_v2() {
		max_v2.resize(N * 405);
		rep(i, max_v2.size()) max_v2[i] = INF;
		int cur_t = t2[0];
		rep2(i, 1, N) {
			rep(t2, 205) {
				int cur_t2 = cur_t - t2;
				if (cur_t2 < 0) break;
				chmin(max_v2[cur_t2], v2[i] + t2);
			}
			cur_t += t2[i];
		}
	}

	double ans() {
		int cur_t2 = 0;
		int cur_v2 = 0;
		double res = 0;
		int a[] = { 1, 0, -1 };
		rep(i, N) {	
			dumpl(v2[i]);
			rep(loop, t2[i]) {
				int next_v2 = -1;
				rep(j, 3) {
					int hoping_v2 = cur_v2 + a[j];
					if (hoping_v2 <= max_v2[cur_t2 + 1]
						&&hoping_v2 <= v2[i]) {
						chmax(next_v2, hoping_v2);
					}
				}
				res += (double)(cur_v2 + next_v2) / 8;
				cerr << next_v2 << " ";

				cur_t2 += 1;
				cur_v2 = next_v2;
			}
		}
		cerr << endl;
		return res;
	}

	void solve() {
		vector<int> t, v;
		cin >> N;
		t.resize(N + 1); rep(i, N) cin >> t[i];
		v.resize(N + 1); rep(i, N) cin >> v[i];
		N += 1;
		t[N - 1] = 1;
		v[N - 1] = 0;

		t2.resize(N); rep(i, N) t2[i] = t[i] * 2;
		v2.resize(N); rep(i, N) v2[i] = v[i] * 2;

		set_max_v2();

		for (auto& v : max_v2) cerr << v << " ";
		cerr << endl;

		cout << ans() << endl;
	}

};

