ld DP(int T, int V) {
	if (dp[T][V] != -1)return dp[T][V];
	if (V > tv[T]||V<0)return -INF;
	dp[T][V] = (double)(max({ DP(T - 1, V - 1) - 0.5, (V<tv[T] ? 0.25:0)+DP(T - 1, V), DP(T - 1, V + 1) + 0.5})+(double)V);

	return dp[T][V];
}
