int main() {

    int n;

    cin >> n;

    t[0] = 0;

    for(int i=1; i<=n; i++){
        cin >> t[i];
    }

    for(int i=1; i<=n; i++){
        t[i] += t[i-1];
    }

    for(int i=0; i<n; i++){
        cin >> v[i];
    }

    int end = t[n];

    for(int i=0; i<n; i++){
        for(int j=t[i]*2+1; j<=(t[i+1])*2; j++){
            maxv[j] = v[i];
        }
    }

    for(int i=0; i<n-1 ;i++){
        maxv[t[i+1]*2] = min(v[i],v[i+1]);
    }

    maxv[0] = 0;
    maxv[end*2] = 0;


    for(int i=1; i<=end*2; i++){
        maxv[i] = min(maxv[i],maxv[i-1] + 0.5);
    }

    for(int i=end*2-1; i>=0; i--){
        maxv[i] = min(maxv[i],maxv[i+1] + 0.5);
    }

    double ans = 0.0;

    for(int i=1; i<=end*2; i++){
        ans += (maxv[i] + maxv[i-1]) * 0.5 / 2.0;
    }

    cout << ans << endl;

    cin >> end;

    return 0;
}

