/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, T;
vl t, v, ub;

void solve(){
    t = vl(n);
    v = vl(n);
    rep(i, n) in1(t[i]);
    rep(i, n) in1(v[i]);
    rep(i, n) T += t[i];
    ub = vl(2 * T + 1, INF);
    ll x = 0;
    rep(i, n) rep(y, t[i]){
        ub[x] = min(ub[x], v[i] * 2);
        ub[x + 1] = min(ub[x + 1], v[i] * 2);
        ub[x + 2] = min(ub[x + 2], v[i] * 2);
        x += 2;
    }
    ub[0] = ub[T * 2] = 0;
    rep(x, 2 * T) ub[x + 1] = min(ub[x + 1], ub[x] + 1);
    revrep(x, T * 2 + 1) ub[x - 1] = min(ub[x - 1], ub[x] + 1);
    ld ans = 0;
    rep(x, 2 * T) ans += ld(ub[x] + ub[x + 1]) * 0.5;
    prl_nd(ans * 0.25, 10);
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();

    return 0;
}

