    FOR(i, 0, N)
    {
        cin >> T[i];
    }
    FOR(i, 0, N)
    {
        cin >> V[i];
    }
    int now = 0;
    vector<pair<int, int>> need(N + 1);
    need[0] = make_pair(0, 0);
    FOR(i,0,N-1){
        now += T[i];
        need[i + 1] = make_pair(now, min(V[i], V[i + 1]));
    }
    need[N] = make_pair(now + T[N - 1], 0);
    int TN = need[N].first;
