                if (need[j-1].first<=now && now<=need[j].first){
                    res[i] = min(res[i], V[j - 1]);
                }
            }
            res[i] = min(res[i], need[j].second + abs(need[j].first - now));
        }
    }
    double ans = 0;
    FOR(i,0,2*TN){
        ans += 0.25 * (res[i] + res[i + 1]);
    }
