  cin >> n;

  int t[n] = {0};
  int v[n] = {0};

  for (int i=0; i<n; i++){
      cin >> t[i];
  }
  for (int i=0; i<n; i++){
      cin >> v[i];
  }
  int dist = 0;

  here[0].push_back({1, yint(1, 0, 0)});
  multiset<double> lowestneg;
  for (int i=0; i<n; i++){
      here[dist].push_back({-1, yint(-1, dist, v[i])});
      lowestneg.insert( yint(-1, dist, v[i]));
      dist += t[i];
      here[dist].push_back({1, yint(1, dist, v[i])});
      // cout << dist << " " << yint(-1, dist, v[i]) << endl;
  }
  here[dist].push_back({-1, yint(-1, dist, 0)});

  lowestneg.insert( yint(-1, dist, 0));

  multiset<double> lowestpos;

  // go along decimal
  double lasth = 0;
  double curmax = 0;
  int cnt = 0;
  double sum = 0;
  int cnt2 = 0;
  lowestpos.insert(1000000000);
  for (double i=0; i<=dist+eps; i+=.5){
      if (cnt%2 == 0){
          for (pair<int, int> p : here[(int)i]){
              if (p.first == 1){
                  lowestpos.insert(p.second);
              }
          }
          if (here[(int)i].size() > 0){
              curmax = v[cnt2];
              cnt2++;
          }
      }
      double one = *(lowestpos.begin());
      double two = *(lowestneg.begin());

      double h = min(one+i, min(two-i, curmax));
      double ych = abs(lasth-h);
      sum += ych*.5/2+min(h, lasth)*.5;
      lasth = h;

      if (cnt%2 == 0){
          for (pair<int, int> p : here[(int)(i+eps)]){
              if (p.first == -1){

                  if (lowestneg.find(p.second) == lowestneg.end()){
                      //cout << i << " " << p.second << endl;
                      return 0;
                  }
                  lowestneg.erase(lowestneg.lower_bound(p.second));
              }
          }

      }
      cnt++;

  }
  printf("%.3lf", sum);
  return 0; 
}

