int N;

vector<int> T;
vector<int> V;

// i個目の区間終了時に速度vのときの最大移動距離
double dp[101][101];

void solve()
{
    ARRAY_FILL(dp, -1.0);

    dp[0][0] = 0;

    REP(i, N) REP(v, 101) {
        if(dp[i][v] == -1.0) continue;
        if(v > V[i]) continue;

        REP(vv, 101) { // vv:区間の終わりでの速度
            if(vv > V[i]) continue;
            int a = V[i] - v;
            int b = V[i] - vv;
            if(a + b <= T[i]) {
                // 速度 V[i] まで上げられる場合
                double up   = 1.0 * (v+V[i]) * a / 2;
                double stay = 1.0 * V[i] * (T[i]-a-b);
                double down = 1.0 * (vv+V[i]) * b / 2;
                chmax(dp[i+1][vv], dp[i][v] + up + stay + down);
            }
            else if(T[i] < abs(vv-v)) {
                // 加速度制限により不可
            }
            else {
                // 速度 V[i] まで上げられない場合
                //
                // 加速x秒、減速y秒とすると
                //   x + y = T[i]
                //   v + x = vv + y
                // これを解くと
                //   x = (T[i] - v + vv) / 2
                //   y = (T[i] + v - vv) / 2
                double x = 1.0 * (T[i] - v + vv) / 2;
                double y = 1.0 * (T[i] + v - vv) / 2;
                double vvv = v + x; // 区間内最高速度

                double up   = 1.0 * (v+vvv)  * x / 2;
                double down = 1.0 * (vv+vvv) * y / 2;

                chmax(dp[i+1][vv], dp[i][v] + up + down);
            }
        }
    }

    double ans = dp[N][0];

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    T.resize(N);
    V.resize(N);

    REP(i, N) {
        RD(T[i]);
    }

    REP(i, N) {
        RD(V[i]);
    }

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

