    for (int i = 0; i < t.size(); ++i) {
        T += t[i];
    }

    vector<int> tt(begin(t), end(t));
    for (int i = 0; i < tt.size()-1; ++i) {
        tt[i+1] += tt[i];
    }

    vector<double> maxv(2*T+1);

    maxv[0] = 0.0;
    maxv[2*T] = 0.0;

    int time_index = 0;
    for (int i = 1; i <= 2*T-1; ++i) {
        double current_time = i / 2.0;

        if (current_time == tt[time_index]) {
            maxv[i] = min(v[time_index], v[time_index+1]);
            ++time_index;
            continue;
        }

        if (current_time > tt[time_index]) {
            ++time_index;
        }

        maxv[i] = v[time_index];
            cout << i / 2.0 << ' ' << maxv[i] << endl;
    }

    for (int i = 1; i <= 2*T; ++i) {
        maxv[i] = min(maxv[i], maxv[i-1] + 0.5);
    }

    for (int i = 2*T-1; i >= 0; --i) {
        maxv[i] = min(maxv[i], maxv[i+1] + 0.5);
    }

    double ans = 0.0;

    for (int i = 0; i <= 2*T; ++i) {
        ans += (maxv[i] + maxv[i+1]) * 0.5 / 2.0;
