#include <bits/stdc++.h>
using namespace std;

const int MAX_N	= 100;
int t[ MAX_N + 5 ];
int v[ MAX_N + 5 ];
int A[ MAX_N + 5 ];

int main()
{
int i;
int j;
int N;
int T;
int L;
int R;
int iSum;
int iTop;

	ios::sync_with_stdio( false );
	cin.tie( 0 );

	cin >> N;

	for( i = 0; i < N; i++ )
	{
		cin >> t[ i ];

		t[ i ] *= 2;
	}

	A[ 0 ] = 0;
	for( i = 0; i < N; i++ )
	{
		cin >> v[ i ];

		v[ i ] *= 2;
		A[ i ] = min( A[ i ], v[ i ] );
		A[ i + 1 ] = min( A[ i ] + t[ i ], v[ i ] );
	}

	A[ N ] = 0;
	for( i = N - 1; i > 0; i-- )
		A[ i ] = min( A[ i ], A[ i + 1 ] + t[ i ] );

	iSum = 0;
	for( i = 0; i < N; i++ )
	{
		iTop = ( A[ i ] + t[ i ] + A[ i + 1 ] ) / 2;
		R = ( A[ i ] + t[ i ] - A[ i + 1 ] ) / 2;
		L = t[ i ] - R;
		iSum += ( L * ( A[ i ] * 2 + L ) + R * ( A[ i + 1 ] * 2 + R ) ) / 2;
		if( iTop > v[ i ] )
		{
			iTop -= v[ i ];
			iSum -= iTop * iTop;
		}
	}

	i = iSum % 4;
	if( i == 0 )
		cout << iSum / 4 << endl;
	else if( i == 1 )
		cout << iSum / 4 << ".25" << endl;
	else if( i == 2 )
		cout << iSum / 4 << ".5" << endl;
	else if( i == 3 )
		cout << iSum / 4 << ".75" << endl;

	return 0;
}

