signed main() {
	ll n;
	cin >> n;
	VD T(n);
	VD V(n);
	cin >> T >> V;
	T.emplace_back(0);
	V.emplace_back(0);

	RFOR(i, 1, n) {
		if (V[i+1] + T[i] < V[i]) {
			V[i] = V[i + 1] + T[i];
		}
	}
	double nowV = 0;
	double ans = 0;
	REP(i, n) {
		double t = T[i];
		double v = V[i];
		double nv = V[i + 1];
		double d = abs(nowV - nv);
		double max = std::min(std::max(nowV, nv) + (t - d) / 2.0, v);

		double a, b, c;
		a = max - nowV;
		c = std::max(0.0, max - nv);
		b = t - (a + c);
		ans += (nowV + max)*a / 2.0;
		ans += max * b;
		ans += (max + nv)*c / 2.0;

		nowV = std::min(max, nv);
	}
	print(ans);
}

