    FOR(i, 1, n - 1)l[i] = min(v[i], l[i - 1] + t[i]);
    rFOR(i, 1, n - 1)r[i] = min(v[i], r[i + 1] + t[i]);

    ld ans = 0;
    FOR(i, 1, n - 1) {
        ld a = min(l[i - 1], r[i]), b = min(l[i], r[i + 1]);
        if (a == b) {
            if (a == v[i]);
            else if (v[i] * 2 - a - b >= t[i]) {
                ans += t[i] * t[i] / 4;
            }
            else {
                ans += (t[i] - (v[i] * 2 - a - b)) * (v[i] - a);
                ans += (v[i] - a) * (v[i] - a);
            }
            ans += t[i] * a;
        }
        else if (a < b) {
            ld len = t[i] - (b - a);
            if (b == v[i]);
            else if (v[i] * 2 - b - b >= len) {
                ans += len * len / 4;
            }
            else {
                ans += (len - (v[i] * 2 - b - b)) * (v[i] - b);
                ans += (v[i] - b) * (v[i] - b);
            }
            ans += (b - a) * (b - a) / 2;
            ans += len * (b - a);
            ans += t[i] * a;
        }
        else {
            ld len = t[i] - (a - b);
            if (a == v[i]);
            else if (v[i] * 2 - a - a >= len) {
