  vector<Z> t(N), v(N);
  cin >> t >> v;
  vector<line_segment> restrictions;
  Z duration = 0, total_duration = accumulate(begin(t), end(t), 0);
  restrictions.push_back({0, total_duration, 1, 0});
  restrictions.push_back({0, total_duration, -1, total_duration});
  for (auto i = 0; i < N; i++) {
    if (i != 0)
      restrictions.push_back({0, duration, -1, v[i] + duration});
    restrictions.push_back({duration, duration + t[i], 0, v[i]});
    if (i != N - 1)
      restrictions.push_back({duration + t[i], total_duration, 1, v[i]});
    duration += t[i];
  }
  debug {
    for (auto&& e : restrictions) {
      dump(e.left);
      dump(e.right);
      dump(e.slant);
      dump(e.ly);
    }
    cerr << "-----------" << endl;
  }
  vector<line_segment> refined;
  for (auto&& e : restrictions) {
    bool merged = false;
    for (auto&& r : refined) {
      auto p = e.intersection(r);
      if (p.first != -10) continue;
      dump(e.left);
      dump(e.right);
      dump(e.slant);
      dump(e.ly);
      dump(r.left);
      dump(r.right);
      dump(r.slant);
      dump(r.ly);
      if (e.left < r.left) {
        r.left = e.left;
        r.ly = e.ly;
      }
      if (e.right > r.right)
        r.right = e.right;
      merged = true;
    }
    if (!merged) refined.push_back(e);
  }
  debug {
    for (auto&& e : refined) {
      dump(e.left);
      dump(e.right);
      dump(e.slant);
      dump(e.ly);
    }
  }
  double dist = 0, time = 0, speed = 0;
  line_segment edge = refined[0];
  while (time < total_duration) {
    dump(edge.left);
    dump(edge.right);
    dump(edge.slant);
    dump(edge.ly);
    line_segment crossed;
    double cross_time = total_duration, new_speed = 0;
    for (auto&& r : refined) {
      auto c = r.intersection(edge);
      if (c.first <= time) continue;
      if (c.first < cross_time ||
          (c.first == cross_time && r.slant < crossed.slant)) {
        dump(c);
        crossed = r;
        cross_time = c.first;
        new_speed = c.second;
      }
    }
    dist += (cross_time - time) * (speed + new_speed) / 2;
    dump(dist);
    edge = crossed;
    time = cross_time;
    speed = new_speed;
  }
  cout << setprecision(10) << dist << endl;
}

