template< int mod > struct ModInt {
    int x; ModInt() : x(0) {}
    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}
    ModInt &operator+=(const ModInt &p) {if((x += p.x) >= mod) x -= mod;return *this;}
    ModInt &operator-=(const ModInt &p) {if((x += mod - p.x) >= mod) x -= mod;return *this;}
    ModInt &operator*=(const ModInt &p) {x = (int) (1LL * x * p.x % mod);return *this;}
    ModInt &operator/=(const ModInt &p) {*this *= p.inverse();return *this;}
    ModInt operator-() const { return ModInt(-x); }
    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }
    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }
    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }
    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }
    bool operator==(const ModInt &p) const { return x == p.x; }
    bool operator!=(const ModInt &p) const { return x != p.x; }
    ModInt inverse() const {int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) { t = a / b; swap(a -= t * b, b); swap(u -= t * v, v); }return ModInt(u);}
    ModInt pow(int64_t n) const {ModInt ret(1), mul(x); while(n > 0) {if(n & 1) ret *= mul;mul *= mul;n >>= 1;}return ret;}
    friend ostream &operator<<(ostream &os, const ModInt &p) { return os << p.x;}
    friend istream &operator>>(istream &is, ModInt &a) { int64_t t; is >> t; a = ModInt< mod >(t); return (is); }
    static int get_mod() { return mod; }
}; using modint = ModInt< mod >;

void solve(long long N, std::vector<long long> t, std::vector<long long> v){
    vector<ll> tsum(N + 1, 0);
    rep(i, 0, N) tsum[i+1] = tsum[i] + t[i];
    int idx = 1;
    double time = 0, ans = 0, vel = 0;
    while(time < tsum[N]){
        if(time == tsum[idx]) idx++;
        if(vel > v[idx+1]){ // 今の速度が次の制限速度よりも早い
            if(tsum[idx] - time <= vel - v[idx+1]){ //　減速すべき
                vel -= 0.5;
                ans += (vel*2 + 0.5) / 4.0;  
            }else if(vel < v[idx]){ // 加速すべき
                vel += 0.5;
                ans += (vel*2-0.5) * 0.5 * 0.5;
            }else{ // 等速度
                ans += 0.5 * vel;
            }
        }else{ // 遅いから加速してok
            if(vel < v[idx]){
                vel += 0.5;
                ans += (vel*2-0.5) / 4.0;
            }else{
                ans += 0.5 * vel;
            }
        }
        time += 0.5;
        //if((int)time % 10 == 0) cerr << time << " " << vel << " " << ans << endl;
    }
    cout << ans << endl;
}

