ll t[500], v[5000],st[200000], s[200000], c[300], vis[200000];
int main()
{
    ios_base::sync_with_stdio(false); cin.tie(0);
    ll i,j,n,tt;
    tt=1;
    //cin>>tt;
    while(tt--)
    {
        ll sum=0;
        cin>>n;
        rep1(i,1,n)
        {
            cin>>t[i];
            sum+=t[i];
            st[i]=c[i-1];
            c[i]=c[i-1]+t[i];
        }

        rep1(i,1,n)
            cin>>v[i];
        v[n+1]=5000;
        s[0]=0;
        for(i=1;i<=sum;i++)
            s[i]=s[i-1]+1;

        s[sum]=0;
        for(i=sum-1;i>=0;i--)
            s[i]=min(s[i+1]+1, s[i]);

        for(i=1;i<=sum;i++)
        {
            for(j=1;j<=n;j++)
            {
                if(i<=st[j])
                {
                    s[i]=min(s[i], v[j] + st[j] - i);
                }
                else if(i>=c[j])
                {
                    s[i]=min(s[i], v[j] + i - c[j]);
                }
            }
        }

        int idx = 1;
//        cout<<c[idx]<<" "<<v[idx]<<endl;
        for(i=1;i<=sum;i++)
        {
            if(c[idx] <= i)
                idx++;
            if(v[idx] <= s[i])
            {
                s[i]=v[idx];
                vis[i]=1;
            }
        }

        lf ans=0;
        for(i=0;i<sum;i++)
        {
            if(s[i+1]<s[i])
                ans+=((lf)s[i+1] + 0.5);
            else if(s[i+1]>s[i])
                ans+=((lf)s[i] + 0.5);
            else if(s[i]==s[i+1])
            {
                if(vis[i]==0 and vis[i+1]==0)
                    ans+=((lf)s[i]+0.25);
                else
                    ans+=s[i];
            }
        }
        cout<<pset(6)<<ans<<endl;
    }
    return 0;
}

