int f(int p) {return p > 0 ? p : -p;}
int main()
{
	int i, j, k;
	cin >> n;
	for (i = 1; i <= n; i++) {
		scanf ("%d", &ti[i]);
	}
	for (i = 1; i <= n; i++) {
		scanf ("%d", &vi[i]);
	}
	for (i = 1; i <= n; i++) {
		for (j = 0; j <= vi[i]; j++) {
			mx = -1;
			for (k = 0; k <= vi[i - 1]; k++) {
				if (k > vi[i]) continue;
				if (f(j - k) > ti[i]) continue;
				num = vi[i] - k + vi[i] - j;
				if (num <= ti[i]) s =4 * vi[i] * ti[i] - (vi[i] - k) * (vi[i] - k) * 2 - (vi[i] - j) * (vi[i] - j) * 2;
				else {
					Y = (double)(ti[i] + j + k) / 2;
					s = Y * ti[i] * 4 - (Y - k) * (Y - k) * 2 - (Y - j) * (Y - j) * 2;
				}
				s += d[i - 1][k];
				if (mx == -1 || s > mx) mx = s;
			}
			d[i][j] = mx;
		}
	}
	printf("%.7f", (double)d[n][0] / 4);
    return 0;
}

