    {
        cin >> v.at(i + 1);
    }

    double ans = 0;
    for (int i = 1; i <= n; i++)
    {
        double v1 = min(v.at(i - 1), v.at(i));
        double v2 = min(v.at(i), v.at(i + 1));

        if ((v2 + t.at(i) + v1) / 2 > v.at(i))
        {
            ans += (v1 + v.at(i)) * (v.at(i) - v1) / 2 +
                   (v2 + t.at(i) - v.at(i) - (v.at(i) - v1)) * v.at(i) +
                   (v.at(i) + v2) * (t.at(i) - (v2 + t.at(i) - v.at(i))) / 2;
        }
        else
        {
            ans += (v1 + (v2 + t.at(i) + v1) / 2) * (v2 + t.at(i) - v1) / 2 / 2 + ((v2 + t.at(i) + v1) / 2 + v2) * (t.at(i) - (v2 + t.at(i) - v1) / 2) / 2;
        }
    }

    printf("%.5f\n", ans);
