void rec(int c = 0, int speed = 0, double sum = 0.0) {
    if (c == t.back()) {
        if (speed == 0) ans = max(ans, sum);
        return;
    }

    auto itr = lower_bound(t.begin(), t.end(), c);
    if (speed < 0 || 2 * v[itr - t.begin()] < speed) {
        return;
    }

    if (used[c][speed]) {
        return;
    }
    used[c][speed] = true;

    rec(c + 1, speed + 1, sum + (speed + speed + 1.0) * 1 / 2.0);
    rec(c + 1, speed, sum + speed);
    itr = lower_bound(t.begin(), t.end(), c + 1);
    if (2 * v[itr - t.begin()] >= speed) {
        rec(c + 1, speed - 1, sum + (speed + speed - 1.0) * 1 / 2.0);
    }

    return;
}

