double calcdist(double vi, double vf, double vm, double T){
    double dist;
    double vm2 = (T + vi + vf) / 2.0;
    if(vm2 > vm){
        dist = (vm + vi) * (vm - vi) / 2.0 + (vm + vf) * (vm - vf) / 2.0 + vm * (T - 2.0 * vm + vi + vf);
    }else{
        dist = (vm2 + vi) * (vm2 - vi) / 2.0 + (vm2 + vf) * (vm2 - vf) / 2.0;
    }
    return dist;
}

