  for (int i = 1; i < n; i++) {
    t_b[i] = t_b[i - 1] + t[i - 1];
  }
  std::copy(std::next(t_b.cbegin()), t_b.cend(), t_e.begin());
  t_e.back() = t_b.back() + t.back();

  std::vector<int> v_max(t_e.back() + 1, 100);

  for (int i = 0; i < n; i++) {
    for (int j = t_b[i]; j <= t_e[i]; j++) {
      v_max[j] = std::min(v[i], v_max[j]);
