    FOR(j,n) {
      if (tt[j+1]<=i) limit[i] = min((s64)limit[i], v[j]+abs(i-tt[j+1]));
      else if (tt[j]>=i) limit[i] = min((s64)limit[i], v[j]+abs(i-tt[j]));
      else limit[i] = min(limit[i], v[j]);
    }
    // cout << i << ":" << limit[i] << endl;
