struct line_segment {
  Z left, right, slant, ly;

  template <class T>
  T y_at(T x) const {
    assert(T(left) <= x && x <= T(right));
    return (x - T(left)) * T(slant) + T(ly);
  }

  pair<double, double> intersection(line_segment const& l) {
    Z common_l = max(left, l.left),
      common_r = min(right, l.right);
    if (common_l > common_r)
      return {-1, -1};
    Z tl = y_at(common_l), tr = y_at(common_r),
      ll = l.y_at(common_l), lr = l.y_at(common_r);
    if ((tl > ll && tr > lr) || (tl < ll && tr < lr))
      return {-1, -1};
    if (common_l == common_r)
      return {common_l, y_at(common_l)};
    double ldiff = abs(tl - ll), rdiff = abs(tr - lr);
    // well, well...
    if (ldiff == 0 && rdiff == 0)
      return {-10, -10};
    double x = (double(common_l) * rdiff + double(common_r) * ldiff) / (ldiff + rdiff);
    return {x, y_at(x)};
  }
};

