int main() {
    int N;
    cin >> N;

    int t[N];
    int v[N+1];
    for (int i = 0; i < N; i++) {
        cin >> t[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> v[i];
    }
    v[N] = 0;

    int next_upper[N+1];
    // next_upper[i]: 区間iに入る直前の速さの上限
    next_upper[N] = 0; // goalでは速さが0でなくてはならない
    for (int i = N - 1; i >= 0; i--) {
        next_upper[i] = min(v[i], v[i+1] + t[i]);
    }

    int velocity = 0;
    double sum = 0.0;

    for (int i = 0; i < N; i++) {
        if (v[i] > next_upper[i+1]) {
            if ((v[i] - velocity) + (v[i] - next_upper[i+1]) > t[i]) {
                double k = 1.0 * t[i] + velocity + next_upper[i+1];
                k /= 2.0;
                sum += (k + velocity) * (k - velocity) * (1.0/2) + (k + next_upper[i+1]) * (k - next_upper[i+1]) * (1.0/2);
            } else {
                sum += (t[i] - (2 * v[i] - next_upper[i+1] - velocity)) * v[i] + (velocity + v[i]) * (v[i] - velocity) * (1.0/2) + 1.0 * (v[i] + next_upper[i+1]) * (v[i] - next_upper[i+1]) * (1.0/2);
            }

            velocity = next_upper[i+1];
        } else if (v[i] <= next_upper[i+1]) {
            if (velocity + t[i] < v[i]) {
                sum += (velocity + velocity + t[i]) * t[i] * (1.0/2);
                velocity += t[i];
            } else {
                sum += 1.0 * (velocity + v[i]) * (v[i] - velocity) / 2 + (t[i] - (v[i] - velocity)) * v[i];
                velocity = v[i];
            }
        } else {
            throw;
        }
    }

    cout.precision(10);
    cout << fixed << sum << endl;

    return 0;
}

