pair<double, int> f(int t, int v, int vf, int vm) {
    vf = min(vf, vm);
    if (v + t < vf) {
        double ans = (v + v + t) * t / 2.;
        return make_pair(ans, v + t);
    }

    double ka = 0, ge = 0;
    if (v > vf)ge = v - vf;
    else ka = vf - v;
    t -= ge + ka;
    ka += t / 2.;
    ge += t / 2.;
    double to = 0;
    if (v + ka > vm) {
        //v+ka=vm
        to = (v + ka - vm);
        ka -= to;
        ge -= to;
        to *= 2;
    }
    double ans = (v + v + ka) * ka / 2. + (v + ka) * to + (v + ka + vf) * ge / 2.;
    return make_pair(ans, vf);
}

