bool memo[40001][201];
double dp[40001][201];

double rec(int idx, double v)
{
  if(v < 0) return (-1e20);
  if(v > f[idx]) return (-1e20);
  if(idx == t) return (0.0);
  if(memo[idx][(int) (v * 2)]++) return (dp[idx][(int) (v * 2)]);
  double ret = -1e20;
  ret = max(ret, rec(idx + 1, v) + v * 0.5);
  ret = max(ret, rec(idx + 1, v + 0.5) + v * 0.5 + 0.5 * 0.5 / 2);
  ret = max(ret, rec(idx + 1, v - 0.5) + v * 0.5 - 0.5 * 0.5 / 2);
  return (dp[idx][(int) (v * 2)] = ret);
}

