ll N, T[101], V[101];
double dp[20001][101];

int main(void) {
  cin >> N;
  REP(i, 0, N) cin >> T[i];
  REP(i, 0, N) cin >> V[i];

  T[N] = 0;
  REP(i, 0, N) T[i + 1] += T[i];
  V[N] = 0;

  REP(i, 0, 20001) REP(j, 0, 101) dp[i][j] = -1e20;
  dp[0][0] = 0;
  ll vi = 0;
  REP(t, 1, T[N] + 1) {
    ll vmax = V[vi], lvmax = V[vi];
    if(t >= T[vi]) {
      vmax = min(V[vi], V[vi + 1]);
      lvmax = V[vi];
      vi++;
    }
    REP(v, 0, vmax + 1) {
      dp[t][v] = max(dp[t][v], dp[t - 1][v] + v);
      if(v <= vmax && v + 1 <= lvmax) dp[t][v] = max(dp[t][v], dp[t - 1][v] + v + 0.25);
      if(v + 1 <= 100) dp[t][v] = max(dp[t][v], dp[t - 1][v + 1] + v + 0.5);
      if(v - 1 >= 0) dp[t][v] = max(dp[t][v], dp[t - 1][v - 1] + v - 0.5);
    }
  }
  printf("%.15lf\n", dp[T[N]][0]);
}

