double eps = .000000001;
double yint(double sl, double x, double y){
    // y = sl*x+b
    return y-sl*x;
}
vector<pair<double, double> > here[20001];
int main ()
{
  prep();
  int n;
  cin >> n;

  int t[n] = {0};
  int v[n] = {0};

  for (int i=0; i<n; i++){
      cin >> t[i];
  }
  for (int i=0; i<n; i++){
      cin >> v[i];
  }
  int dist = 0;

  here[0].push_back({1, yint(1, 0, 0)});
  multiset<double> lowestneg;
  for (int i=0; i<n; i++){
      here[dist].push_back({-1, yint(-1, dist, v[i])});
      lowestneg.insert(yint(-1, dist, v[i]));
      if (dist == 0){
        //cout << yint(-1, dist, v[i]) << endl;
      }
      dist += t[i];
      here[dist].push_back({1, yint(1, dist, v[i])});

  }
  here[dist].push_back({-1, yint(-1, dist, 0)});

  lowestneg.insert( yint(-1, dist, 0));

  multiset<double> lowestpos;

  // go along decimal
  double lasth = 0;
  double curmax = 0;
  int cnt = 0;
  double sum = 0;
  int cnt2 = 0;
  lowestpos.insert(1000000000);
  for (double i=0; i<=dist+eps; i+=.01){
      if (cnt%100 == 0){
          for (pair<int, int> p : here[cnt/100]){
              if (p.first == 1){
                  lowestpos.insert(p.second);
              }
          }
          if (here[cnt/100].size() > 0){
              curmax = v[cnt2];
              cnt2++;
          }
      }
      double one = *(lowestpos.begin());
      double two = *(lowestneg.begin());
      double h = min(one+i, min(two-i, curmax));
      double ych = abs(lasth-h);
      sum += ych*.01/2+min(h, lasth)*.01;
      lasth = h;

      if (cnt%100 == 0){
          for (pair<int, int> p : here[cnt/100]){

              if (p.first == -1){
                if (lowestneg.find(p.second) == lowestneg.end()){
                  //cout << "SDF" << endl;
                }
                  lowestneg.erase(lowestneg.lower_bound(p.second));
              }
          }

      }
      cnt++;

  }
  cout << sum;
  return 0; 
}

