int n;
vector<double> t, v;
int idx;
double pos, sp;

bool speedUp(){
	range(i,idx,n){
		if((sp + 0.5) - (t[i] - pos - 0.5) > v[i + 1]){
			return false;
		}
	}
	return true;
}

bool keep(){
	range(i,idx,n){
		if(sp - (t[i] - pos - 0.5) > v[i + 1]){
			return false;
		}
	}
	return true;
}

int main(){
	cin >> n;

	t = vector<double>(n);
	v = vector<double>(n);
	cin >> t >> v;
	range(i,1,n) t[i] += t[i - 1];
	v.emplace_back(0);

	double ans = 0;
	while(idx < n){
		if(speedUp()){
			sp = min(v[idx], sp + 0.5);
		}else if(keep()){
			;
		}else{
			sp -= 0.5;
		}
		pos += 0.5;
		ans += sp;
		//cout << sp << ' ' << pos << endl;
		if(t[idx] <= pos) idx++;
	}
	cout << fixed << setprecision(10) << ans / 2 << endl;
}

