int main() {
	int n;cin>>n;
	int t[n],v[n];
	int time[n];
	for(int i=0;i<n;i++){
		cin>>t[i];
		time[i]=t[i];
		if(i>0)time[i]+=time[i-1];
	}
	for(int i=0;i<n;i++)cin>>v[i];
	int k=2*time[n-1]+1;
	double f[n+2][k];
	for(int i=0;i<n+2;i++){
		int left,right,ve;
		if(i==n){
			left=right=ve=0;
		}else if(i==n+1){
			left=right=time[n-1];;
			ve=0;
		}else{
			if(i==0){
				left=0;
			}else{
				left=time[i-1];
			}
			right=time[i];
			ve=v[i];
		}
		for(int j=0;j<=2*time[n-1];j++){
			if(j<=2*left){
				f[i][j]=ve+left-double(j)/2;
			}else if(j>=2*right){
				f[i][j]=ve+double(j)/2-right;
			}else{
				f[i][j]=ve;
			}
//			cout<<f[i][j]<<' ';
		}
//		cout<<endl;
	}
	double speed[k];
	double ans=0;
	for(int j=0;j<=2*time[n-1];j++){
		speed[j]=f[0][j];
		for(int i=1;i<n+2;i++){
			if(speed[j]>f[i][j]){
				speed[j]=f[i][j];
			}
		}
//		cout<<speed[j]<<' ';
		if(j){
			ans+=(speed[j-1]+speed[j])/2/2;
		}
	}
//	cout<<endl;
	cout<<setprecision(15)<<ans<<endl;

	return 0;
}

