using namespace std;

const int MAX = 107;
double t[MAX];
double v[MAX];
int main() {
	int N;
	scanf("%d",&N);
	rep(i,1,N+1)scanf("%lf",&t[i]);
	rep(i,1,N+1)scanf("%lf",&v[i]);
	v[0]=0;v[N+1]=0;
	rep(i,0,N)v[N-i]=min(v[N-i],v[N+1-i]+t[N-i]);
	double nowspd=0;
	double ans=0; 
	rep(i,1,N+1)
	{
		double acc=min(min(v[i]-nowspd,(t[i]+abs(nowspd-v[i+1]))/2.0),t[i])*1.0;
		double dec=max(nowspd+acc-v[i+1],0.0);
		double con=t[i]-acc-dec;
		//printf("acc=%.1lf,dec=%.1lf,con=%.1lf\n",acc,dec,con);
		ans+=(nowspd*2+acc)*acc/2.0+(nowspd+acc)*con+(nowspd*2.0+acc*2.0-dec)*dec/2;
		nowspd+=acc-dec;
	}
	printf("%.10lf",ans);
	return 0;
}

