	for(ll i = 0; i < n; i++){cin >> v[i];}
	float dp[2][101];
	dp[0][0] = 0;
	for(ll i = 1; i <= 100; i++){dp[0][i] = -1;}

	for(ll i = 0; i < n; i++){
		ll ti = t[i];
		ll vi = v[i];
		for(ll j = vi+1; j <= 100; j++){
			dp[0][j] = -1;
		}
		for(ll j = 1; j <= ti; j++){
			for(ll vv = 0; vv <= 100; vv++){
				if(vv > vi){dp[1][vv] = -1;}
				else{
					if(vv == 0){dp[1][0] = (dp[0][1]+0.5 > dp[0][0])? dp[0][1]+0.5 : dp[0][0];}
					if(vv == 100 && dp[0][100] >= 0){dp[1][100] = dp[0][100]+100;}
					if(vv == 100 && !(dp[0][100] >= 0) && dp[0][99] >= 0){dp[1][100] = dp[0][99]+99.5;}
					if(vv == 100 && !(dp[0][100] >= 0) && !(dp[0][99] >= 0)){dp[1][100] = -1;}
					if(1 <= vv && vv <= 99){
						float buf = -1; 
						if(dp[0][vv] >= 0){buf = dp[0][vv]+vv;}
						if(dp[0][vv] >= 0 && vv+1 <= vi){buf = dp[0][vv]+vv+0.25;}
						if(dp[0][vv-1] >= 0 && dp[0][vv-1]+vv-0.5 > buf){buf = dp[0][vv-1]+vv-0.5;}
						if(dp[0][vv+1] >= 0 && dp[0][vv+1]+vv+0.5 > buf){buf = dp[0][vv+1]+vv+0.5;}
						dp[1][vv] = buf;
					}
				}
			}
			for(ll vv = 0; vv <= 100; vv++){dp[0][vv] = dp[1][vv];}
			//cout << dp[0][0] <<  " " << dp[0][1] << " " << dp[0][2] << endl;
		}
	}
	cout << dp[0][0];
	return 0;
}

