    using namespace debug;

    auto N = read<i32>();
    auto ts = read<i32>(N);
    auto vs = read<i32>(N);

    REP (i, N) {
        ts[i] *= 2;
        vs[i] *= 2;
    }

    using Range = pair<i32, i32>;
    auto xs = V<pair<Range, i32>>();
    xs.reserve(N + 2);

    xs.push_back({{0, 0}, 0});

    REP (i, N) {
        auto begin = xs[i].first.second;
        auto end = begin + ts[i];
        xs.push_back({{begin, end}, vs[i]});
    }
    xs.push_back({{xs.back().first.second, xs.back().first.second}, 0});

    auto get_max_vel = [&](i32 i, i32 t) {
        auto begin = xs[i].first.first;
        auto end = xs[i].first.second;
        auto v = xs[i].second;

        //cout << i << " " << t << " " << xs[i] << endl;

        if (begin <= t && t <= end) {
            return v;
        } else if (t < begin) {
            return v + (begin - t);
        } else {
            return v + (t - end);
        }
    };

    i64 ans = 0;
    i32 v = 0;
    FOR (t, 1, xs.back().first.second + 1) {
        // 時刻tでの速度を求める
        //cout << t << " ";
        i32 v_next = get_max_vel(0, t);
        //cout << v_next << " ";
        FOR (i, 1, N + 2) {
            //cout << get_max_vel(i, t) << " ";
            v_next = min(v_next, get_max_vel(i, t));
        }

        //cout << "\t" << v_next << endl;

        ans += (v + v_next);

        v = v_next;
    }

    cout << fixed << setprecision(3) << ans / 8.0 << endl;

    return 0;
}

