            if(vv > vm[tt]) {
                dp[tt][vv] = -1;
                continue;
            }
            dp[tt][vv] = -1;
            for(int nv = vv - 1; nv <= vv + 1; nv++) {
                if(nv < 0 || nv > vm[tt]) continue;
                if(tt == 0) {
                    dp[0][vv] = vv == 0 ? .25 : (vv == 1 ? .5 : -1);
