class section {
   public:
    ll begin;
    ll end;
    ll velocity;

    section() {}
    section(ll begin, ll end) : begin(begin), end(end) {}
};

int main() {
    ll n;
    cin >> n;

    vector<section> ss(n);
    ll sum_t = 0;
    for (ll i = 0; i < n; i++) {
        ll x;
        cin >> x;
        x *= 2;

        ss[i].begin = sum_t;
        ss[i].end = sum_t + x;

        sum_t += x;
    }

    for (ll i = 0; i < n; i++) {
        ll x;
        cin >> x;
        ss[i].velocity = 2 * x;
    }

    vector<ll> a(sum_t + 1, INF);
    a[0] = 0;
    a[sum_t] = 0;

    for (const section& s : ss) {
        for (ll i = s.begin; i <= s.end; i++) {
            a[i] = min(a[i], s.velocity);
        }
    }

    for (ll i = sum_t - 1; i >= 0; i--) {
        a[i] = min(a[i + 1] + 1, a[i]);
    }

    ll speed = 0;
    ll distance = 0;
    for (ll i = 0; i < sum_t; i++) {
        distance += speed;
        if (speed < a[i + 1]) {
