int main()
{
	std::ios::sync_with_stdio(false);

	int N;
	cin >> N;
	vector<int> t(N + 1), v(N + 1);
	for (int i = 0; i < N; ++i) {
		cin >> t[i];
	}
	t[N] = 1;
	for (int i = 0; i < N; ++i) {
		cin >> v[i];
	}
	v[N] = 0;
	vector<int> accT(N + 1);
	accT[0] = t[0];
	for (int i = 1; i <= N; ++i) {
		accT[i] = accT[i - 1] + t[i];
	}

	int state = -999;
	int lastState = -999;
	int lastT = 0;
	int lastVel = 0;
	double result = 0.0;
	int vel = 0;
	for (int i = 0; i < N + 1; ++i) { // 区間ごと
		for (int j = 0; j < t[i]; ++j) { // 区間内で１s刻み
			if (i < N ) {
				if (accT[i] - (i + j) < vel - v[i + 1] + 1) {
					// 停滞か下がらなければならない
					if (accT[i] - (i + j) < vel - v[i + 1]) {
						// 下がらなければならない
						state = -1;
					} else {
						// 停滞できる
						state = 0;
					}
				} else {
					// 次の状態だけ見れば上昇できるが
					if (vel < v[i]) {
						// 上限未満なので上昇できる
						state = 1;
					} else {
						// 上限に当たって上昇できない
						state = 0;
					}
				}
			} else {
				state = 0;
			}
			if (lastState > -99 && lastState != state || i == N) {
				// 動きが変化したタイミングで面積加算
				if (lastState < 0 || lastState > 0) {
					// 上昇・下降の面積
					double x1 = ((i + j) - lastT) * ((i + j) - lastT) / 2.0;
					double x2 = ((i + j) - lastT) * min(vel, lastVel);
					result += x1 + x2;
				} else {
					// 停滞の面積
					double x = ((i + j) - lastT) * lastVel;
					result += x;
				}
				lastT = (i + j);
				lastVel = vel;
			}

			if (state < 0) {
				vel -= 1;
			} else if (state > 0) {
				vel += 1;
			}
			lastState = state;
		}

	}

	cout << result << endl;

	getchar();
	getchar();
}

