        if(at_y < vm[i])tmp += 0.5 * at_t * (k + at_y) + 0.5 * (t[i] - at_t) * (j + at_y);
        else tmp += 0.5 * (vm[i] - k) * (vm[i] + k) + 0.5 * (vm[i] - j) * (vm[i] + j) + (t[i] - vm[i] + k - vm[i] + j) * vm[i];
        dp[i + 1][j] = max(dp[i + 1][j], tmp + dp[i][k]);
      }
      if(!flag)dp[i + 1][j] = -1.;
    }
  }
  cout << setprecision(12);
  cout << dp[n][0] << endl;
	return 0;
}

