int N;
double dp[110][110];
double calc(int j, int k, int V,int T) {
	if (abs(j - k) > T)return -((double)inf);
	if (j > k)swap(j, k);
	double S;
	if (k + j + T <= 2 * V) {
		S = (double)((k + T - j)*(k + 3 * j + T) + (j + T - k)*(3 * k + j + T));
		S /= 8.0;
		return S;
	}
	else {
		S = (double)(2 * V*T - (V - j)*(V - j) - (V - k)*(V - k));
		S /= 2.0;
		return S;
	}
}

int main() {
