	for (int i = 1; i <= N; i++) {
		for (int j = 0; j <= V[i-1]; j++) {
			for (int k = 0; k <= V[i - 1]; k++) {
				dp[i][j] = max(dp[i][j],dp[i-1][k]+calc(k,j,V[i-1],T[i-1]));
			}
		}
	}
