    }
    vector<ll> Ts(N+1, 0);
    for (auto && i: irange(1LL, N+1)){
        Ts.at(i) = Ts.at(i-1) + ts.at(i-1);
    }
    ll T_size = Ts.back() + 1;
    vector<vector<ll>> v_limit{};
    v_limit.emplace_back(apply_condition(0, 0, 0, T_size));
    v_limit.emplace_back(apply_condition(0, Ts.back(), Ts.back(), T_size));
    for (auto && i: irange(0LL, N)){
        v_limit.emplace_back(apply_condition(vs.at(i), Ts.at(i), Ts.at(i+1), T_size));
    }
    vector<ll> v_limits(T_size);
    for (auto && i: irange(0LL, T_size)){
        ll minimum = numeric_limits<ll>::max();
        for (auto && j: irange(0LL, N+2)){
