				lim = V[i] + L[i] - k;
			} else if(k > R[i]) {
				lim = V[i] + k - R[i];
			} else {
				lim = V[i];
			}
			if (mn > lim) {
				mn = lim;
			}
		}
		A[j] = mn;
	}

	double sum = 0;
