    double cv = 0.0;
    REP(i, N) {
        double rest = ts[i];
        double nv = vs[i + 1];
        double mv = min(vs[i],
            cv + max(nv - cv, 0.0) + (rest - abs(nv - cv)) / 2.0
        );
        if (nv >= mv) mv = vs[i];
        if (rest <= nv) {
            ans += rest * rest / 2.0;
            cv = rest;
        } else {
            double ncv;
            if (nv < mv) {
                double dt = mv - nv;
                rest = max(0.0, rest - dt);
                ans += dt * nv + dt * dt / 2.0;
                ncv = nv;
            } else
                ncv = mv;

            if (rest > 0.0) {
                double ut = mv - cv;
                rest = max(0.0, rest - ut);
                ans += ut * cv + ut * ut / 2.0;
            }

            ans += rest * mv;
            cv = ncv;
        }
    }

    out(ans);

    return 0;
}

