    int limit[41000] = {};
    int cnt = 1;
    REP(i,N) REP(j,t[i]) {
        limit[cnt] = v[i];
        cnt++;
    }

    cnt = 0;
    REP(i,N - 1) {
        cnt += t[i];
        limit[cnt] = min(v[i], v[i + 1]);
    }

    int sum = 0;
    REP(i,N) sum += t[i];

    limit[sum] = 0;

    REP(kai,400) for (int i = 1; i <= sum; i++) {
        int val = vel[i];
        val++;
        if (abs(val - vel[i - 1]) <= 1 && abs(val - vel[i + 1]) <= 1 && val <= limit[i]) {
            vel[i] = val;
        }
    }

    double ans_vel[41000];
    REP(i,41000) ans_vel[i] = (double) vel[i];

    double ans = 0.0;
    REP(i,sum) {
        double area = (ans_vel[i] + ans_vel[i + 1]);
        ans += area / 2.0;
    }

    ans /= 4.0;

    //REP(i,sum + 1) cout << i << " " << vel[i] << " " << limit[i] << endl;

    cout << fixed << setprecision(10) << ans << endl;

    return 0;
}

