int n, t[101], d[101], v[101];
int sp[40404];
void solve(){
	cin >> n;
	for(int i = 1; i <= n; ++i){
		cin >> t[i];
		t[i] *= 2;
		d[i] = d[i-1]+t[i];
	}
	for(int i = 1; i <= n; ++i){
		cin >> v[i];
		v[i] *= 2;
		fill(sp+d[i-1], sp+d[i], v[i]); //max
	}

	for(int i = 1; i <= n; i++){
		if(v[i] > v[i-1]){
			for(int j = d[i-1]; j < d[i]; ++j){
				chmin(sp[j], v[i-1]+j-d[i-1]);
			}
		}
		if(v[i] > v[i+1]){
			for(int j = d[i+1]; j >= d[i]; --j){
				chmin(sp[j], v[i+1]+d[i+1]-j);
			}
		}
	}
	for(int i = 1; i < 40000; ++i){
		chmin(sp[i], sp[i-1]+1);
	}
	for(int i = 40000; i > 0; --i){
		chmin(sp[i], sp[i+1]+1);
	}

	i64 ans = 0;
	for(int i = 1; i < 40000; i++){
		ans += sp[i];

	}
	printf("%.10f\n", ans/4.0);
}

