double ref(ll N, VI T, VI _V) {
	VI L(N+2), R(N+2), V(N+2);
	ll tot = 0;
	REP(i, N) {
		L[i] = tot;
		R[i] = tot+T[i];
		tot+=T[i];
	}
	REP(i, N) V[i] = _V[i];
	L[N+1] = R[N+1] = tot;
//	DD(L);DD(R);DD(V);

	auto f = [&](int i, double t) {
		if(L[i]<=t && t<=R[i]) return (double)V[i];
		return V[i]+min(abs(t-L[i]), abs(t-R[i]));
	};
	auto ff = [&](double t) {
		double v = 1e100;
		REP(i, L.size()) v = min(v, f(i, t));
		return v;
	};
//	REP(i, N+2) DD(f(i, 35));

	vector<double> w(tot*2+1);
	REP(i, w.size()) {
		double t = (double)i/2.0;
		w[i] = ff(t);
	}
//	DD(w);
//	REP(i, w.size()) {
//		cout<<i*0.5<<" "<<w[i]<<endl;
//	}
	double ans = 0;
	REP(i, w.size()-1) {
		ans += (w[i]+w[i+1])*0.5/2;
	}
	return ans;
}

double ref2(ll N, VI _T, VI _V) {
	VI L(N+2), R(N+2), V(N+2);
	ll tot = 0;
	REP(i, N) {
		L[i+1] = tot;
		R[i+1] = tot+_T[i];
		V[i+1] = _V[i];
		tot += _T[i];
	}
	L[N+1] = R[N+1] = tot;
//	DD(L);DD(R);DD(V);

	vector<double> limit(L.size()); // [i] ... i が始まる時の最大速度
	auto f = [&](int i) {
		double v = 1e100;
		RANGE(j, i, L.size()) {
			double lv = L[j] - L[i] + V[j];
			v = min(v, lv);
		}
		return v;
	};
	REP(i, L.size()) limit[i] = f(i);
//	DD(limit);

	double pv = 0;
	double ans = 0;
	RANGE(i, 1, L.size()-1) {
		// / - \
		// a   b
		double nv = limit[i+1];
		double l = R[i]-L[i];
		double a = (nv-pv+l)/2.0;
		double b = a;
//		DD(i);
//		DD(pv);
//		DD(nv);
//		DD(L[i]);
//		DD(V[i]);
//		DD(l);
//		DD(a);DD(b);
		a = min({a, V[i]-pv, l});
		a = max(0.0, a);
		b = max(b, nv+l-V[i]);
		b = min(l, b);
//		DD(a);DD(b);
		double lans = (pv+pv+a)*a*0.5 + V[i]*(b-a) + (nv+(l-b)+nv)*(l-b)*0.5;
		ans += lans;
		pv = pv+a-(l-b);
	}
	return ans;
}

