	ll n; cin >> n;
	vector<ll> t( n ), v( n );
	rep( i, n ) cin >> t[i];
	rep( i, n ) cin >> v[i];

	vector<ll> tt( n + 1 );
	rep( i, n ) tt[i + 1] = tt[i] + t[i];

	vector<ll> max_sp( n + 1, 1e18 );
	max_sp[0] = max_sp[n] = 0;
	rep( i, n )
	{
		chmin( max_sp[i], v[i] );
		chmin( max_sp[i + 1], v[i] );
	}
	rep( i, n + 1 )
		rep( j, n + 1 )
			chmin( max_sp[j], max_sp[i] + abs( tt[i] - tt[j] ) );

	double ans = 0;
	rep( i, n )
	{
		double tmpans = 0;
		double x = ( -max_sp[i] + max_sp[i + 1] + t[i] ) / 2.0;
		double y = ( max_sp[i] + max_sp[i + 1] + t[i] ) / 2.0;
		if ( y < v[i] )
		{
			tmpans += x * ( max_sp[i] + y ) / 2.0;
			tmpans += ( t[i] - x ) * ( max_sp[i + 1] + y ) / 2.0;
		}
		else
		{
			double x0 = v[i] - max_sp[i];
			double x1 = -v[i] + max_sp[i + 1] + t[i];
			tmpans += x0 * ( max_sp[i] + v[i] ) / 2.0;
			tmpans += ( x1 - x0 ) * v[i];
			tmpans += ( t[i] - x1 ) * ( v[i] + max_sp[i + 1] ) / 2.0;
		}
		ans += tmpans;
	}

	cout << setprecision( 20 ) << ans << endl;

	return ( 0 );
}

