#define ALL(obj) (obj).begin(), (obj).end()
#define INF 1e9
typedef long long ll;

vector<int> t;
vector<int> v;
vector<int> t_sum;
double ans;

void dfs(int l, int r, int h){//[l,r)はすでに速度hに達している
    //cout << l << ", " << r << ", " << h << endl;
    if(l>=r) return;

    int l_itr = upper_bound(ALL(t_sum), l) - t_sum.begin() - 1;
    int r_itr = lower_bound(ALL(t_sum), r-1) - t_sum.begin() - 1;
    //cout << "  " << l_itr << ", " << r_itr << endl;

    if(r_itr == l_itr){//最終ステップ
        if(r-l >= 2*(v[r_itr]-h)){
            ans += ((r-l) - (v[r_itr]-h)) * (v[r_itr]-h);
            return;
        }else{
            ans += (r-l)*(r-l)/4.0;
            return;
        }
    }

    int min_v = INF;
    int min_itr = -1;
    FOR(i,l_itr,r_itr){
        if(min_v > v[i]){
            min_v = v[i];
            min_itr = i;
        }
    }
    //cout << "    " << min_v << ", " << min_itr << endl;

    ans += ((r-l) - (min_v-h))*(min_v-h);

    int next_l1,next_r1,next_l2,next_r2;
    next_l1 = l+min_v-h;
    next_r2 = r-min_v+h;
    next_r1 = t_sum[min_itr];
    next_l2 = t_sum[min_itr+1];
    dfs(next_l1,next_r1,min_v);
    dfs(next_l2,next_r2,min_v);
}

