int main() {
    ll N;
    cin >> N;
    vector<ll> ts(N);
    for (ll i = 0; i < N; i++){
        ll t;
        cin >> t;
        t *= 2;
        ts.at(i) = t;
    }
    vector<ll> vs(N, 0);
    for (ll i = 0; i < N; i++){
        ll v;
        cin >> v;
        v *= 4;
        vs.at(i) = v;
    }
    vector<ll> Ts(N + 1, 0);
    for (ll i = 0; i < N; i++){
        Ts.at(i + 1) = Ts.at(i) + ts.at(i);
    }
    const ll T_size = Ts.back() + 1;
    vector<ll> as(T_size), ds(T_size);
    as.front() = 0; ds.back() = 0;
    vector<ll> as_dep_idx{0};
    for (ll i = 0; i < N; i++){
        ll t = ts.at(i);
        for (ll j = 0; j < t; j++){
            as_dep_idx.emplace_back(i); // as[i]を求めるときは，as[Ts[as_dep_idx[i]]]を参照する
        }
    }
    for (ll i = 1; i < T_size; i++){
        ll as_dep = as_dep_idx.at(i);
        ll v_idx = as_dep;
        as.at(i) = min(vs.at(v_idx), as.at(Ts.at(as_dep)) + 2 *  ((ll)i - Ts.at(as_dep)));
    }

    vector<ll> ds_dep_idx_proto{N};
    for (ll i = N - 1; i >= 0; i--){
        ll t = ts.at(i);
        for (ll j = 0; j < t; j++){
            ds_dep_idx_proto.emplace_back(i + 1);
        }
    }
    vector<ll> ds_dep_idx(ds_dep_idx_proto.rbegin(), ds_dep_idx_proto.rend()); // ds[i]を求めるときはds[Ts[ds_dep_idx[i]]]を参照する
    for (ll i = T_size - 1 - 1; i >= 0; i--){
        ll ds_dep = ds_dep_idx.at(i);
        ll v_idx = ds_dep - 1;
        ds.at(i) = min(vs.at(v_idx), ds.at(Ts.at(ds_dep)) + 2 * (Ts.at(ds_dep) - (ll)i));
    }
    vector<ll> Vs(T_size);
    for (ll i = 0; i < T_size; i++){
        Vs.at(i) = min(as.at(i), ds.at(i));
    }
    vector<ll> distances(T_size - 1);
    for (ll i = 0; i < T_size - 1; i++){
        assert((Vs.at(i) + Vs.at(i+1)) % 2 == 0);
        distances.at(i) = (Vs.at(i) + Vs.at(i+1)) / 2;
    }
    ll distance = 0;
    for (ll i = 0; i < T_size - 1; i++){
        distance += distances.at(i);
    }
    double d_double = distance;
    cout << d_double / 8 << endl;
    return 0;
}

