double calcdist(double vi, double vf, double vm, double T){
    double dist;
    double vm2 = (T + vi + vf) / 2.0;
    if(vm2 > vm){
        dist = (vm + vi) * (vm - vi) / 2.0 + (vm + vf) * (vm - vf) / 2.0 + vm * (T - 2.0 * vm + vi + vf);
    }else{
        dist = (vm2 + vi) * (vm2 - vi) / 2.0 + (vm2 + vf) * (vm2 - vf) / 2.0;
    }
    return dist;
}

signed main(){

    int N;
    cin >> N;
    vector<int> t(N), v(N);
    readvec(t);
    readvec(v);

    vector<int> v_max(N + 1);
    v_max[0] = 0;
    v_max[N] = 0;
    REP(i, N - 1){
        v_max[i + 1] = min(v[i], v[i + 1]);
    }

    while(true){
        bool c = false;
        REP(i, N){
            if(v_max[i + 1] > v_max[i] + t[i]){
                c = true;
                v_max[i + 1] = v_max[i] + t[i];
            }
        }
        REP(i, N){
            if(v_max[N - i - 1] > v_max[N - i] + t[N - i - 1]){
                c = true;
                v_max[N - i - 1] > v_max[N - i] + t[N - i - 1];
            }
        }
        if(!c) break;
    }

    double ans = 0.0;
    REP(i, N){
        ans += calcdist((double)v_max[i], (double)v_max[i + 1], (double)v[i], (double)t[i]);
    }

    cout << ans;

    return 0;
}


