struct SegmentTree{
    int n;
    vector<double> node;

    double calc(double a,double b) {
        return a+b;
    }
    double e=0;

    SegmentTree(vector<double> v) {
        int sz=v.size();
        n=1;
        while(n<sz) {
            n*=2;
        }
        node.resize(2*n-1,e);
        for(int i=0;i<sz;i++) {
            node[i+n-1]=v[i];
        }
        for(int i=n-2;i>=0;i--) {
            node[i]=calc(node[2*i+1],node[2*i+2]);
        }
    }

    void update(int x,ll val) {
        x=n+x-1;
        node[x]=val;
        while(x>0) {
            x=(x-1)/2;
            node[x]=calc(node[2*x+1],node[2*x+2]);
        }
    }

    double query(int a,int b,int k=0,int l=0,int r=-1) {
        if(r<0) r=n;

        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return node[k];

        double vl=query(a,b,2*k+1,l,(l+r)/2);
        double vr=query(a,b,2*k+2,(l+r)/2,r);

        return calc(vl,vr);
    }

    ll at(int x) {
        return node[n+x-1];
    }
};

int main() {
    cout<<fixed<<setprecision(10);
    int n;
    cin>>n;
    vector<double> t(n+1),v(n+2);
    FOR(i,1,n) cin>>t[i];
