//const int MAX_N=2*100*200+1;
const int MAX_N=1e6+10;
int N;
int V[100],T[100];
int v[MAX_N];
const int MOD = 1e9+7;
void solve() {
  REP(i,MAX_N) v[i]=MOD;
  int t=0;
  v[0]=0;
  REP(i,N) {
    SMIN(v[t],V[i]);
    REP(j,T[i]) t++,SMIN(v[t],V[i]);
//    cout<<i<<","<<t<<endl;
  }
  SMIN(v[t],0);
  int T=t;
  FORE(i,1,T) {
//    if(i==140)cout<<v[i]<<","<<v[i-1]+1<<endl;
    SMIN(v[i],v[i-1]+1);
  }
  for(int i=T-1; i>=0; --i) {
//    if(i==140)cout<<v[i]<<","<<v[i+1]+1<<endl;
    SMIN(v[i],v[i+1]+1);
  }
//  cout<<T<<endl;
//  REPE(i,T) cout<<i<<","<<v[i]<<endl;
  LL res=0;
  //REP(i,T) res+=(v[i]+v[i+1])*0.5;
  REP(i,T) res+=(v[i]+v[i+1]);
  double ans=res*0.125;
  cout<<ans<<endl;
}

