    chmin(vv,i);//始点からの影響
    chmin(vv,sum_t-i);//終点からの影響
    S.pb(vv);
  }
  double ans=0;
  rep(i,S.size()-1){
    ans+=(S[i]+S[i+1])*0.25;
  }
  cout<<ans;
}

