static double distance(int32_t start_v, int32_t end_v, int32_t duration, int32_t max_v)
{
	double max_dist = 0.0;
	for (double flat_start = 0; flat_start <= duration; flat_start += 0.5) {
		double flat_v = start_v + flat_start;
		if (flat_v > max_v)
			continue;

		double dist_inc = 0.0;
		dist_inc += start_v * flat_start + (flat_v - start_v) * flat_start / 2.0;

		for (double dec_start = flat_start; dec_start <= duration; dec_start += 0.5) {
			if (flat_v - (duration - dec_start) > end_v)
				continue;
			double dist_flat = flat_v * (dec_start - flat_start);
			double dist_dec = 0.0;
			if (flat_v > end_v) {
				dist_dec += end_v * (duration - dec_start);
				dist_dec += (flat_v - end_v) * (duration - dec_start) / 2.0;
			} else {
				dist_dec += flat_v * (duration - dec_start);
			}
			max_dist = max(max_dist, dist_inc + dist_flat + dist_dec);
		}
	}
	return max_dist;
}

