            st[j].insert(v[i] + d);
        }
    }

    rep(i, n+1) v2[i] = *st[i].begin();

    double ans = 0;

    for(int i = 1; i <= n; i++){
        int p = v[i] - v2[i-1];
        int q = v[i] - v2[i];
        if (p + q <= t[i]) ans += double(t[i] * v[i]) - double(p*p + q*q) / 2;
        else{
            double r = double(t[i] - v2[i-1] + v2[i]) / 2;
            double s = double(t[i] + v2[i-1] - v2[i]) / 2;
            ans += double(v[i-1] + r) * t[i] - double(r*r + s*s) / 2;
        }
    }

    cout << fixed << setprecision(10) <<  ans << endl;

    return 0;
}

