	vector<double> T;
	vector<double> V;
	for(int i = 0; i < N; i++){
		double t;
		cin >> t;
		T.push_back(t);
	}
	for(int i = 0; i < N; i++){
		double v;
		cin >> v;
		V.push_back(v);
	}

	for(int i = N-1; i > 0; i--){
		if(i == N-1){
			double maxspeed = T[i];
			V[i] = min(V[i], maxspeed);
		}
		else{
			double maxspeed = T[i]+V[i+1];
			V[i] = min(V[i],maxspeed);		
		}
	}

	double nowSpeed = 0;
	double distance = 0;
	for(int i = 0 ; i < N; i++){
		double nowmaxspeed = V[i];
		double endmaxspeed = (i==N-1)? 0:V[i+1];
		//int Tii = (i ==0)? 0:T[i-1];

		if(nowmaxspeed <= endmaxspeed){
			double acct = nowmaxspeed-nowSpeed;
			if(acct < 0) {cout << "error"; break;}
			if(acct >= (T[i])){
				distance += (2*nowSpeed+(T[i])) * (T[i]) /2;
				nowSpeed = nowSpeed+(T[i]);
			}
			else{
				distance += (2*nowSpeed+acct) * acct /2+ nowmaxspeed*(T[i]-acct);
				nowSpeed = nowmaxspeed;
			}				
		}
		else{
			if(nowSpeed +(T[i])<= endmaxspeed){
				distance += (2*nowSpeed+(T[i])) * (T[i]) /2;
				nowSpeed = nowSpeed+(T[i]);
			}
			else if(nowSpeed == nowmaxspeed){
				double dect = nowmaxspeed - endmaxspeed;
				distance += (endmaxspeed+nowmaxspeed)*dect/2 + (T[i]-dect)*nowmaxspeed;
				nowSpeed = endmaxspeed;
			}
			else if(endmaxspeed+T[i] == nowSpeed){
				distance += (endmaxspeed+nowSpeed)*(T[i])/2 ;
				nowSpeed = endmaxspeed;
			}
			else {
				double t1 = nowmaxspeed-nowSpeed;
				double t2 = nowmaxspeed - endmaxspeed;
				if((t1+t2)<T[i]){
					distance += (nowSpeed+nowmaxspeed)*t1/2 + (endmaxspeed+nowmaxspeed)*t2/2 + (T[i]-t1-t2)*nowmaxspeed;
					nowSpeed = endmaxspeed;
				}
				else{
					t2 = (nowSpeed+T[i]-endmaxspeed)/2;
					t1 = T[i]-t2;
					distance += (2*nowSpeed+t1)*t1/2+(2*endmaxspeed+t2)*t2/2;
					nowSpeed = endmaxspeed;
				}
			}

		}	

	}

	cout << distance << endl;
	return 0;
}

