class section{
    public:
        int begin;
        int end;
        int velocity;

        section(){}
        section(int begin, int end) : begin(begin), end(end){}
};

int main() {
    int N;
    cin >> N;

    vector<section> ss(N);
    int sum_t = 0;
    rep(i,N){
        int x;
        cin >> x;
        x *= 2;

        ss[i].begin = sum_t;
        ss[i].end = sum_t + x;
        sum_t += x;
    }

    rep(i,N){
        int x;
        cin >> x;
        ss[i].velocity = x*2;
    }

    vector<int> a(sum_t+1,INF);
    a[0] = 0;
    a[sum_t] = 0;

    for(const section& s:ss){
        for(int i=s.begin; i<=s.end; i++){
            a[i] = min( a[i], s.velocity );
        }
    }

    for(int i=sum_t-1; i>=0; i--){
        a[i] = min( a[i+1]+1, a[i]);
    }

    int speed = 0;
    int distance = 0;
    rep(i,sum_t){
        if( speed < a[i+1] ){
            speed++;
            distance += speed+1;
        }else if( speed > a[i+1] ) {
            speed--;
            distance += speed-1;
        }else{
            distance += speed;
        }
    }

    cout << std::fixed << std::setprecision(9) << (1.0 * distance / 4) << endl;
}

