struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   Int f(Int x, Int y, Int w) {
      Int diff = y - x;
      if( diff >= w ) {
         return (x + y) * diff / 2;
      }
      else {
         return (x + y) * diff / 2 + (w - diff) * y;
      }
   }
   double g(double x, double y, double w) {
      return (x + y) * w / 2.0;
   }
   void solve() {
      Int n; scan(n);
      std::vector<Int> ts(n+2), vs(n+2);
      ts[0] = 0, vs[0] = 0;
      ts[n+1] = 0, vs[n+1] = 0;
      for(Int i = 1; i <= n; ++i) {
         scan(ts[i]);
      }
      for(Int i = 1; i <= n; ++i) {
         scan(vs[i]);
      }
      double res = 0.0;
      Int prevV = 0;
      for(Int i = 1; i <= n; ++i) {
         // calc
         Int t1 = std::max((Int)0, vs[i]-prevV);
         Int t2 = ts[i] - std::max((Int)0, vs[i]-vs[i+1]);
         if( t1 <= t2 ) {
            // dumpl((Int)1);
            res += g(prevV, vs[i], t1);
            res += g(vs[i], vs[i+1], ts[i]-t2);
            res += (t2 - t1) * vs[i];
         }
         else {
            // dumpl((Int)2);
            double th = std::max((double)0, std::min((t1 + t2) / 2.0, (double)ts[i]));;
            res += g(prevV, th+prevV, th);
            res += g(th+prevV, vs[i+1], ts[i]-th);
         }
         // update
         if( vs[i] - prevV > ts[i] ) {
            prevV = prevV + ts[i];
         }
         else {
            prevV = std::min(vs[i], vs[i+1]);
         }
         // printf("%ld : %.20lf\n", i, res);
      }
      printf("%.20lf\n", res);
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

