	for (int i = 0; i < N; i++) {
		cin >> a;
		t[i] = a;
	}

	for (int i = 0; i < N; i++) {
		cin >> a;
		v[i] = a;
	}
	v[N] = 0;

	double v2 = 0;

	for (int i = 0; i < N; i++) {
		v2 = v[i + 1];
		if (v2 >= v[i]) {
			double time = v[i] - v1;
			if (time > t[i]) {
				distance += v1*t[i] + pow(t[i], 2) / 2;
				v1 = v1 + t[i];
			}
			else {
				distance += v1*time + pow(time, 2) / 2;
				distance += v[i] * (t[i] - time);
				v1 = v[i];
			}
		}
		else {
			double time1 = v[i] - v1;
			double time2 = abs(v2 - v[i]);
			if (v1-v2 >= t[i]) {
				distance += v1 * t[i] - pow(t[i], 2) / 2;
				v1 = v2;
			}
			else if (time1 > t[i] && v1 + time1 < v2) {
				distance += v1*t[i] + pow(t[i], 2) / 2;
				v1 = v1 + t[i];
			}
			else if (time1 + time2 > t[i]) {
				double time3 = (v2 + t[i] + v1) / 2;
				distance += v1*time3 + pow(time3, 2) / 2;
				v1 = v1 + time3;
				distance += v1*(t[i] - time3) - pow(t[i] - time3, 2) / 2;
				v1 = v2;
			}
			else {
				distance += v1*time1 + pow(time1, 2) / 2;
				distance += v[i] * (t[i] - time1 - time2);
				distance += v[i]*time2 - pow(time2, 2) / 2;
				v1 = v2;
			}
		}
	}

	cout << distance << endl;
}

