int main() {
	int N; int* T, * V;
	double *dp, * buf; cin >> N;
	T = new int[N];
	V = new int[N];
	dp = new double[101];
	buf = new double[101];

	for (int i = 0; i < N; i++) {
		cin >> T[i];
	}
	for (int i = 0; i < N; i++) {
		cin >> V[i];
	}

	for (int i = 0; i <= 100; i++) { dp[i] = -1000000000; }
	dp[0] = 0;
	for (int i = 0; i <= 100; i++) { buf[i] = -1000000000; }

	for (int i = 0; i < N; i++) {
		int left, right;
		if (i == 0) { left = 0; }
		else { left = min(V[i], V[i - 1]); }
		if (i == N - 1) { right = 0; }
		else { right = min(V[i], V[i + 1]); }

		for (int j = 0; j <= right; j++) {
			buf[j] = 0;
		}

		for (int x = 0; x <= left; x++) {
			if (dp[x] < 0) { continue; }
			for (int y = 0; y <= right; y++) {
				if (abs(x - y) > T[i]) { continue; }
				double m = (double)((double)T[i] - (double)abs(x - y)) / 2.0 + (double)max(x, y);
				double S = ((m + x) * (m - x) + (m + y) * (m - y)) / 2.0;
				if (m > V[i]) {
					S -= (m - V[i]) * (m - V[i]);
				}
				buf[y] = max(buf[y], dp[x] + S);
			}
		}
		for (int j = 0; j <= right; j++) {
			dp[j] = buf[j];
		}
		for (int j = right + 1; j <= 100; j++) {
			dp[j] = -1000000000;
		}
	}
	cout << setprecision(18) << dp[0] << endl;
	return 0;
}

