void solve() {
  int n;
  cin >> n;
  int maxT = 0;
  for(int a = 0; a <= 40000; a++) maxV[a] = 1e9;
  {
    vector<int> tt, vv;
    tt.resize(n);
    vv.resize(n);
    for(int i = 0; i < n; i++) cin >> tt[i];
    for(int i = 0; i < n; i++) tt[i] *= 2;
    for(int i = 0; i < n; i++) cin >> vv[i];
