#define REP(i, a, b) for (int i = int(a); i < int(b); i++)

using namespace std;

typedef long long int lli;

int main() {
    int N;
    cin >> N;
    vector<int> T(N + 1, 0);
    vector<int> V(N + 1, 0);

    REP (i, 0, N) cin >> T[i];
    REP (i, 0, N) cin >> V[i];
    for (int i = N; i > 0; i--) {
        int nxt = i - 1;
        V[nxt] = min(V[nxt], T[nxt] + V[i]);        
    }
    /*
    REP (i, 0, N) {
        cout << V[i] << endl;
    }
    //*/
    double ans = 0.0;
    double speed = 0.0;
    REP (i, 0, N) {
        int nxt = i + 1;
        if (V[i] < V[nxt]) {
            double diff = V[i] - speed;
            if (diff <= T[i]) {
                ans += diff * (speed + V[i]) / 2 + (T[i] - diff) * V[i];
                speed = V[i];
            } else {
                ans += T[i] * (2 * speed + T[i]) / 2;
                speed += T[i];
            }
        } else {
            int diff = V[i] - V[nxt];
            double diff2 = V[i] - speed;
            if (T[i] < diff2 + diff) {
                if (speed <= V[nxt]) {
                    double tmp = (T[i] - (speed - V[nxt])) / 2.0;
                    ans += tmp * (2 * speed + tmp) / 2.0 + (speed + tmp + V[nxt]) * (T[i] - tmp) / 2.0;
                } else {
                    double tmp = (T[i] - (V[i] - speed)) / 2.0;
                    ans += (V[nxt] + tmp + speed) * (T[i] - tmp) / 2.0 + (V[nxt] * 2 + tmp) * tmp / 2.0; 
                }
            } else {
                double tmp = T[i] - diff2 - diff;
                ans += diff2 * (2 * speed + diff2) / 2.0 + diff * (V[i] + V[nxt]) / 2.0 +  tmp * V[i];
            }
            speed = V[nxt];
        }
        //cout << ans << endl;
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

