    if(sta + jikan <=end){
        next[0]=sta + jikan;
        return (2 * sta + jikan) * jikan /float(2);
    }
    next[0]=end;
    if(ma - sta + ma - end <= jikan) return ma * jikan - (ma - sta) * (ma -sta) /float(2) - (ma - end) * (ma - end )/float(2);
    float tim;
    tim=(end - sta + jikan )/float(2);
    return tim / float(2) * (sta + sta + tim) + (sta + tim + end) *(jikan - tim) / float(2); 
}

