                    temp = max(temp, dp[prev][v-1] + 4 * v - 2);
                if (v < vmax && v < 100)
                    temp = max(temp, dp[prev][v+1] + 4 * v + 2);
                if (v <= vmax)
                    temp = max(temp, dp[prev][v] + 4 * v);
                dp[cur][v] = temp;
            }
            swap(cur, prev);
        }
    }
    cout << setprecision(12) << dp[prev][0] * 0.25 << endl;
