  for (int i = 0; i < N; i++) {
    R.push_back({sum, V[i]});
    for(double j = sum; j <= sum + T[i]; j += 0.5) {
      if (!m.count(j)) m[j] = V[i];
      else m[j] = min(m[j], (double)V[i]);
    }
    sum += T[i];
    R.push_back({sum, V[i]});
  }
  R.push_back({sum, 0});

  N = R.size();
  for(int i = 0; i < N; i++) {
    int t = R[i].first;
    int v = R[i].second;
    for(double j = 0; j <= t; j += 0.5) {
      if (!m.count(j)) m[j] = v + t - j;
      else m[j] = min(m[j], v + t - j);
    }
    for(double j = t; j <= sum; j += 0.5) {
      if (!m.count(j)) m[j] = v + j - t;
      else m[j] = min(m[j], v + j - t);
    }
  }

  vector<pair<double,double>> mm;
  for(auto &&e: m) {
    mm.push_back(e);
  }

  double ans = 0;
  for(int i = 0; i + 1 < mm.size(); i++) {
    double a = mm[i].second;
    double b = mm[i + 1].second;
    ans += (a + b) / 4.0;
  }
  cout << ans << endl;
}

int main() {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);
  cout.setf(ios::fixed);
  cout.precision(16);
  solve();
  return 0;
}

