            data.emplace_back(T, T + t[i], v[i]);
            T += t[i];
        }
    }
    data.emplace_back(T, T, 0);
    vector<int> V(T + 1, INF);
    for(int j = 0; j <= T; j++) {
        for(int i = 0; i < N + 2; i++) {
            int l, r, v;
            tie(l, r, v) = data[i];
            if(j < l) {
                V[j] = min(V[j], v + l - j);
            } else if(r < j) {
                V[j] = min(V[j], v + j - r);
            } else {
                V[j] = min(V[j], v);
            }
        }
    }
    double ans = 0;
    for (int j = 0; j < T; j++) {
        ans += V[j] + V[j + 1];
    }
    cout << ans / 8 << endl;
    return 0;
}

