        down_time = max(0.0, now_speed + up_time - next_start_limit);

        keep_time = t[i] - up_time - down_time;

        ans += 0.5 * (now_speed + now_speed + up_time) * up_time;
        ans += (now_speed + up_time) * keep_time;
        ans += 0.5 * (now_speed + up_time + now_speed + up_time - down_time) * down_time;

