        ss[i] = ss[i - 1] + t[i];
    }

    for(i = 1; i <= n; i ++)
        cin >> v[i];

    int vmax, tcr;

    vmax = 0;
    tcr = s;

    while(tcr >= 0)
    {
        vx[tcr] = vmax;
        vst[tcr] = vmax;

        vmax ++;
        tcr --;
    }

    vmax = 0;
     tcr = 0;
    while(tcr <= s)
    {
        vx[tcr] = min(vx[tcr], vmax);
        vdr[tcr] = vdr[tcr];

        vmax ++;
        tcr ++;
    }

    tcr = 0;
    int j;
    for(i = 1; i <= n; i ++)
    {
        for(j = tcr + 0; j <= tcr + t[i]; j ++)
        {
            vx[j] = min(vx[j], v[i]);

            if(vinit[j] != 0)
                vinit[j] = min(v[i], vinit[j]);

            else
                vinit[j] = v[i];
        }

        tcr += t[i];
    }

    for(int h = 1; h <= 100; h ++)
    for(i = n - 1; i >= 1; i --)
    {
        //cout << "AVEM " << i << " " << v[i] << " " << v[i + 1] << "\n";

        if(v[i] < v[i + 1])
        {
            int tcr = ss[i];
            int vmax = vx[tcr];

           // cout << tcr << " " << vmax << "\n";

            while(tcr <= s)
            {
                vx[tcr] = min(vx[tcr], vmax);

                vmax ++;
                tcr ++;
            }
        }

        else
            if(v[i] > v[i + 1])
            {
                int tcr = ss[i];
                int vmax = vx[tcr];

               // cout << tcr << " " << vmax << "\n";

                while(tcr >= 0)
                {
                    vx[tcr] = min(vx[tcr], vmax);

                    vmax ++;
                    tcr --;
                }
            }
    }

    ///1 sec
    ///vst given
    ///vdr given

    //cout << "SUMA " << s << "\n";

    for(i = 0; i < s; i ++)
    {
        //cout << i << " " << vx[i] << "\n";

        if(vx[i] == vx[i + 1])
        {
            //cout << "AVEM " << vinit[i + 1] << "\n";

            if(vinit[i + 1] > vx[i] && ((s % 2 == 1 && i == s / 2) || ok(i, vx[i])))
            {
                //cout << "PE" << i + 1 << " " << vinit[26] << "\n";

