                rez += (-0.5D) * (vx[i] * vx[i] - nv * nv);
            }

            else
                rez += vx[i];
        }

        if(vx[i] == vx[i + 1] - 1)
            rez += 0.5D * (vx[i + 1] * vx[i + 1] - vx[i] * vx[i]);

        if(vx[i] == vx[i + 1] + 1)
            rez += (-0.5D) * (vx[i + 1] * vx[i + 1] - vx[i] * vx[i]);
    }
    //cout << "\n";

    cout << fixed << setprecision(10) << rez << "\n";

    return 0;
