  double now_v = 0;
  double len = 0;
  int n;
  t.push_back(0);
  v.push_back(0);
  cin >> n;
  for(int i = 0; i < n ; i++){
    int a;
    cin >> a;
    t.push_back(a + t[i]);
  }
  for(int i = 0; i < n ; i++){
    int a;
    cin >> a;
    v.push_back(a);
  }
  v.push_back(0);

  int count = 0;
  while(now_t < t[n]){
    if(now_t >= t[count]) count++;
    double a = (now_t + 0.5 - t[count-1] + v[count-1]);
    double b = v[count];
    double c = (t[count] - now_t - 0.5 + v[count+1]);
    double next_v = min( min(a,b) , c);
    len += (now_v + next_v)*0.25;
    now_v = next_v;
    now_t += 0.5;
  }
  cout << len << endl;
}

