int main() {
    init();

    int n; cin >> n;
    vector<double> t(n + 2), v(n + 2);
    eFOR(i, 1, n)cin >> t[i];
    eFOR(i, 1, n)cin >> v[i];
    eFOR(i, 1, n)chmin(v[i], v[i - 1] + t[i]);
    erFOR(i, 1, n)chmin(v[i], v[i + 1] + t[i]);

    vector<pair<int, double>> sec;
    eFOR(i, 1, n) {
        if (v[i - 1] < v[i] && v[i] > v[i + 1]) {
            double z = t[i] - 2 * v[i] + v[i - 1] + v[i + 1];
            if (z < 0) {
                if (v[i - 1] < v[i + 1]) {
                    sec.emplace_back(1, v[i + 1] - v[i - 1]);
                    sec.emplace_back(1, (t[i] - v[i + 1] + v[i - 1]) / 2);
                    sec.emplace_back(-1, (t[i] - v[i + 1] + v[i - 1]) / 2);
                }
                else if (v[i - 1] > v[i + 1]) {
                    sec.emplace_back(1, (t[i] - v[i - 1] + v[i + 1]) / 2);
                    sec.emplace_back(-1, (t[i] - v[i - 1] + v[i + 1]) / 2);
                    sec.emplace_back(-1, v[i - 1] - v[i + 1]);
                }
                else {
                    sec.emplace_back(1, t[i] / 2);
                    sec.emplace_back(-1, t[i] / 2);
                }
            }
            else {
                sec.emplace_back(1, v[i] - v[i - 1]);
                sec.emplace_back(0, z);
                sec.emplace_back(-1, v[i] - v[i + 1]);
            }
        }
        else if (v[i - 1] < v[i]) {
            if (v[i] < v[i - 1] + t[i]) {
                sec.emplace_back(1, v[i] - v[i - 1]);
                sec.emplace_back(0, t[i] - v[i] + v[i - 1]);
            }
            else {
                sec.emplace_back(1, t[i]);
            }
        }
        else if (v[i] <= v[i + 1]) {
            sec.emplace_back(0, t[i]);
        }
        else {
            if (v[i] < v[i + 1] + t[i]) {
                sec.emplace_back(0, t[i] - v[i] + v[i + 1]);
                sec.emplace_back(-1, v[i] - v[i + 1]);
            }
            else {
                sec.emplace_back(-1, t[i]);
            }
        }
    }

    double ans = 0, speed = 0;
    for (auto i : sec) {
        int dir; double dis; tie(dir, dis) = i;

        if (dir == -1)speed -= dis;

        ans += speed * dis;
        if (dir != 0)ans += dis * dis / 2;

        if (dir == 1)speed += dis;
    }

    cout << ans << "\n";
}

