int n;
int V[100], T[100];
int dp[101][101];

int calc(int i, int v){
    if(v > V[i])
        return -1;
    if(v > T[i] && dp[i+1][v-T[i]] == -1)
        return -1;
    int vp = max(0, v-T[i]);
    int ve = min(V[i], v+T[i]);
    assert(dp[i+1][vp] != -1);
    while(vp < ve && dp[i+1][vp+1] != -1)
        ++vp;
    int x = T[i] + vp - v;
    int y = T[i] + vp + v;
    int area = x*(2*v+y) + (2*T[i]-x)*(2*vp+y);
    if(y <= 2*V[i])
        return dp[i+1][vp] + area;
    else {
        int d = y - 2*V[i];
        return dp[i+1][vp] + area - 2*d*d;
    }
}

void solve(){
    cin>>n;
    REP(i,n)
        cin>>T[i];
    REP(i,n)
        cin>>V[i];
    dp[n][0] = 0;
    fill(dp[n]+1, dp[n]+101, -1);
    for(int i=n-1;i>=0;--i)
        for(int v=0;v<=100;++v)
            dp[i][v] = calc(i,v);
    cout<<setprecision(9)<<fixed<<double(dp[0][0])/8<<'\n';
}

int main(){
#ifdef ONLINE_JUDGE
    ios_base::sync_with_stdio(0);
    cin.tie(0);
#endif
    solve();
    return 0;
}

