double maxV(int i, double x){
	if(0 <= x && x <= t[i].fi) return v[i]+(t[i].fi-x);
	if(t[i].fi <= x && x <= t[i].se) return v[i];
	if(t[i].se <= x && x <= T) return v[i]+(x-t[i].se);
	return -1;
}


