ld f(ld t, ld v, ld left, ld right) {
    if(v - left + v - right <= t) {
        return t * v - (v - left) * (v - left) / 2.0 - (v - right) * (v - right) / 2.0;
    }
    ld h = (t + left + right) / 2.0;
    return (left + h) * (h - left) / 2.0 + (right + h) * (h - right) / 2.0;
}

