        rep(j, n + 2) {
            if(j < i) {
                chmin(left, v[j] + st[i] - st[j + 1]);
                chmin(right, v[j] + st[i + 1] - st[j + 1]);
            } else if(i < j) {
                chmin(right, v[j] + st[j] - st[i + 1]);
                chmin(left, v[j] + st[j] - st[i]);
            }
        }
        //cerr << left << " " << right << endl;
        ans += f(t[i], v[i], left, right);
    }
    cout << ans << endl;
}

