inline int dist(int &va, int &vi, int &vb, int &t) // 本来の4倍を出力
{
    int vmax_2 = va + vb + t; // 本来の2倍
    if (vmax_2 > vi * 2) return vi * t * 4 - 2 * (vi - va) * (vi - va) - 2 * (vi - vb) * (vi - vb); // 本来の4倍
    int t__2 = vmax_2 - va * 2; // 本来の2倍
    return ((va * 2 + vmax_2) * t__2 + (vb * 2 + vmax_2) * (t * 2 - t__2)) / 2; // 本来の4倍
}

