#define rep(i, n) for(int i=0;i<n;++i)
#define rep2(i, x, n) for(int i=x;i<n;++i)

int main()
{   
    int n;
    cin >> n;
    vector<int> t(n);
    vector<int> v(n);
    rep(i,n) cin >> t[i];
    rep(i,n) cin >> v[i];

    int te = 0;
    rep(i,n) te += t[i];
    vector<int> v_sec(te);
    int ti = 0;
    int v_max = 0;
    rep(i,n)
    {
        rep(j,t[i])
            v_sec[ti+j] = v[i];
        ti += t[i];
        v_max = max(v_max,v[i]);
    }

    vector<int> v_limit(te+1);
    v_limit[0] = 0;
    v_limit[te] = 0;
    rep2(i,1,te)
        v_limit[i] = min(v_sec[i-1],v_sec[i]);

    vector<double> u(2*te+1,-1);
    u[0] = 0;
    u[2*te] = 0;
    double v_tmp = 0.5;
    while(v_tmp<=v_max)
    {
        rep2(j,1,2*te)
        {
            if(u[j]>=0) continue;

            double v_limit_j;
            if(j%2==0)
                v_limit_j = v_limit[j/2];
            else
                v_limit_j = max(v_limit[j/2],v_limit[j/2+1]);

            if(v_tmp>=v_limit_j) 
                u[j] = v_limit_j;
            else if(u[j-1]==v_tmp-0.5 || u[j+1]==v_tmp-0.5) 
                u[j] = v_tmp;
        }
        v_tmp += 0.5;
    }

    double d = 0;
    rep(i,2*te)
        d += double(u[i]+u[i+1])/2 * 0.5;    

    cout << d << endl;
    return 0;
}

#include <iostream>
