  for(int i=1;i<=n;i++){
    ji[i]=ji[i-1]+t[i-1];
  }
  vector<LL> tv(ji[n]+1,0),hi(ji[n]+1,0),mi(ji[n]+1,0);
  LL now=1;
  for(int i=1;i<ji[n];i++){
    tv[i]=v[now-1];
    if(i==ji[now]){
      now++;
      tv[i]=min(tv[i],v[now-1]);
    }
  }
  tv[0]=tv[ji[n]]=0;
  // for(int i=0;i<=ji[n];i++) cout << tv[i] << " ";
  // cout <<endl;
  hi[0]=0;
  mi[ji[n]]=0;
  for(int i=1;i<=ji[n];i++){
    hi[i]=min(hi[i-1]+1,tv[i]);
  }
  for(int i=ji[n]-1;i>=0;i--){
    mi[i]=min(mi[i+1]+1,tv[i]);
  }
  vector<LL> ansv(ji[n]+1,0);
  for(int i=0;i<=ji[n];i++){
    ansv[i]+=min(hi[i],mi[i]);
  }
