				if(k==1 and j==s[i]) continue;
				dp[i+1][j+k]=max(dp[i+1][j+k], dp[i][j]+j+k*0.5);
			}
			if(s[i]>j and s[i+1]>=j) dp[i+1][j]=max(dp[i+1][j], dp[i][j]+0.25+j);
		}
	}

	cout << fixed << setprecision(9);
	cout << dp[t[n]][0] << endl;
	return 0;
}

