double res_pl(double start_v, double time_sum) {
    return start_v * time_sum + (1.0 * time_sum * time_sum) / 2;
}

double res_mi(double start_v, double time_sum) {
    return start_v * time_sum - (1.0 * time_sum * time_sum) / 2;
}

double res_eq(double start_v, double time_sum) {
    return start_v * time_sum;
}

double time_cell[105], v_cell[105];

int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> time_cell[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> v_cell[i];
    }
    v_cell[N] = 0;

    double start_v = 0.0, res_sum = 0.0, res_time;
    for (int i = 0; i < N; i++) {
        if (v_cell[i] - start_v <= time_cell[i]) {
            if (v_cell[i] <= v_cell[i + 1]) {
                res_sum += res_pl(start_v, v_cell[i] - start_v);
                res_time = time_cell[i] - (v_cell[i] - start_v);
                start_v = start_v + 1.0 * (v_cell[i] - start_v);
                res_sum += res_eq(start_v, res_time);
            }
            else {
                if (start_v >= v_cell[i + 1]) {
                    if ((v_cell[i] - v_cell[i + 1]) + (v_cell[i] - start_v) <= time_cell[i]) {
                        res_sum += res_pl(start_v, v_cell[i] - start_v);
                        res_time = v_cell[i] - start_v;
                        start_v = start_v + 1.0 * res_time;
                        res_sum += res_mi(start_v, start_v - v_cell[i + 1]);
                        res_time += start_v - v_cell[i + 1];
                        res_sum += res_eq(start_v, time_cell[i] - res_time);
                        start_v = v_cell[i + 1];
                    }
                    else {
                        res_sum += res_mi(start_v, start_v - v_cell[i + 1]);
                        res_time = time_cell[i] - (start_v - v_cell[i + 1]);
                        res_sum += res_pl(start_v, res_time / 2);
                        start_v += 1.0 * (res_time / 2);
                        res_sum += res_mi(start_v, res_time / 2);
                        start_v = v_cell[i + 1];
                    }
                }
                else {
                    if (time_cell[i] - (v_cell[i + 1] - start_v) >= 2 * (v_cell[i] - v_cell[i + 1])) {
                        res_sum += res_pl(start_v, v_cell[i] - start_v);
                        res_sum += res_mi(v_cell[i], v_cell[i] - v_cell[i + 1]);
                        res_sum += res_eq(v_cell[i], time_cell[i] - ((v_cell[i] - start_v) + (v_cell[i] - v_cell[i + 1])));
                        start_v = v_cell[i + 1];
                    }
                    else {
                        res_sum += res_pl(start_v, v_cell[i + 1] - start_v);
                        res_time = time_cell[i] - (v_cell[i + 1] - start_v);
                        res_sum += res_pl(v_cell[i + 1], res_time / 2);
                        res_sum += res_mi(v_cell[i + 1], res_time / 2);
                        start_v = v_cell[i + 1];
                    }
                }
            }
        }
        else {
            if (v_cell[i] <= v_cell[i + 1]) {
                res_sum += res_pl(start_v, time_cell[i]);
                start_v += 1.0 * time_cell[i];
            }
            else {
                if (start_v < v_cell[i + 1]) {
                    if (v_cell[i + 1] - start_v < v_cell[i]) {
                        res_sum += res_pl(start_v, v_cell[i + 1] - start_v);
                        res_time = time_cell[i] - (v_cell[i + 1] - start_v);
                        res_sum += res_pl(v_cell[i + 1], res_time / 2);
                        start_v += 1.0 * (res_time / 2);
                        res_sum += res_mi(start_v, res_time / 2);
                        start_v = v_cell[i + 1];
                    }
                    else {
                        res_sum += res_pl(start_v, time_cell[i]);
                        start_v += 1.0 * time_cell[i];
                    }
                }
                else {
                    if (start_v - v_cell[i + 1] < v_cell[i]) {
                        res_sum += res_mi(start_v, start_v - v_cell[i + 1]);
                        res_time = time_cell[i] - (start_v - v_cell[i + 1]);
                        res_sum += res_pl(start_v, res_time / 2);
                        start_v += 1.0 * (res_time / 2);
                        res_sum += res_mi(start_v, res_time / 2);
                        start_v = v_cell[i + 1];
                    }
                    else {
                        res_sum += res_mi(start_v, time_cell[i]);
                        start_v = v_cell[i + 1];
                    }
                }
            }
        }
    }

    cout << res_sum << endl;

    return 0;

}

