      cin >> t[i]; t[i] *= 4;
   }
   rep(i, N) {
      cin >> v[i]; v[i] *= 4;
   }
   vector<int> s(N+1);
   rep(i, N) {
      s[i+1] = s[i] + t[i];
   }

   vector<BIND> bs;
   rep(i, N) {
      bs.push_back((BIND){s[i], s[i+1], v[i]});
   }
   bs.push_back((BIND){0,0,0});
   bs.push_back((BIND){s[N],s[N],0});

   int prev_v = 0; int dist = 0;
   for (int u=2;u<=s[N];u+=2) {
      int minval = 10000000;
      rep(i, N+2) {
         BIND b = bs[i];
         if (u < b.s) {
            minval = min(minval, b.v + b.s - u);
         } else if (u > b.t) {
            minval = min(minval, b.v + u-b.t);
         } else {
            minval = min(minval, b.v);
         }
      }
      dist += prev_v + minval;
      prev_v = minval;
   }
   printf("%.91f\n", dist/16.0);
}

