double solve(int s, int e, double upper, double tot) {

    if (s > e) {
        return solve(e, s, upper, tot);
    }
    double t1 = upper - s, t2 = upper - e;
    if (t1 + t2 > tot) {
        upper = 0.5 * (tot + s + e);
    }

    double len1 = upper - s, len2 = upper - e;
    double mid = max(0.0, tot - len1 - len2);
    return 0.5 * (s + upper) * len1 + upper * mid + 0.5 * (e + upper) * len2;
}

