void solve(){
    int N;cin>>N;
    vector<double> t(N);
    REP(i, N) cin >> t[i];
    vector<double> v(N);
    REP(i, N) cin >> v[i];
    double ans=0,vs=0;
    vector<double> S(N+1);
    REP(i,N) S[i+1]=S[i]+t[i];
    auto f =[&](int n,double x)->double{
        if(n==0) return x;
        if(n==N+1) return S[N]-x;
        if(0<=x&&x<=S[n-1]) return v[n-1]+S[n-1]-x;
        if(S[n-1]<=x&&x<=S[n]) return v[n-1];
        if(S[n]<=x&&x<=S[N]) return v[n-1]+x-S[n];
    };
    double now=0,next;
    REP(i,2*S[N]){
        next=1e9;
        REP(j,N+2) next=min(next,f(j,i/2.0+0.5));
        ans+=(now+next)/4.0;
        now=next; 
    }
    cout<<ans<<endl;
}

