using namespace std;

typedef long long ll;
typedef unsigned long long ull;
using P = pair<ll, ll>;
using V = vector<ll>;
#define rep(i, n) for(ll i=0;i<(ll)(n);i++)
#define rep1(i, n) for(ll i=1;i<=(ll)(n);i++)
#define rep2(i, m, n) for(ll i=m;i<(ll)(n);i++)
#define rrep(i, n, m) for(ll i=n;i>=(ll)(m);i--)
#define ALL(obj) (obj).begin(), (obj).end()
#define MOD 1000000007
#define INF 1000000000

void solve_abc_d() {
	ll n;
	float ans = 0;

	cin >> n;

	V t(n + 1), v(n + 1);
	rep(i, n) {
		cin >> t[i];
	}
	rep(i, n) {
		cin >> v[i];
	}
	t[n] = 0;
	v[n] = 0;

	double at, dt;
	double nv = 0;
	double tv = 0;
	double diff = 0;
	rep(i, n) {
		// acc
		at = (v[i] - nv) / 1;

		// dec
		dt = max(0LL, v[i] - v[i + 1]);

		diff = t[i] - (at + dt);
		if (diff >= 0) {
			// const
			tv = (double)v[i];
			ans += diff * v[i];
		}
		else {
			// no const
			if (i > 0) {
				tv = max((double)v[i - 1], v[i] + diff / 2.0f);
			}
			else {
				tv = max((double)0, v[i] + diff / 2.0f);
			}

			// new acc
			at = (tv - nv) / 1;

			// new dec
			dt = max((double)0, tv - v[i + 1]);
		}

		ans += (nv + tv) * at / 2.0f;
		ans += (tv + v[i + 1]) * dt / 2.0f;
		nv = min(tv, (double)v[i + 1]);
	}

	cout << fixed;
    cout << setprecision(7) << ans << "\n";
}

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	solve_abc_d();

	return 0;
}

