constexpr f80 DT = 1e-03;

i64 N;
vector<f80> T;
vector<f80> V;

void solve() {
    f80 ans = 0;
    for(i64 i = N-1; i >= 0; --i) {
        f80 v  = V[i];
        f80 vl = i == 0   ? 0 : V[i-1];
        f80 vr = i == N-1 ? 0 : V[i+1];

        f80 cur = 0;
        for(f80 t = 0; t < T[i]; t += DT) {
            f80 w = min({
                v,
                vl + t,
                vr + (T[i]-t),
            });
            cur += w * DT;
        }
        ans += cur;
    }

    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {
    RD(N);
    RD(T, N);
    RD(V, N);

    solve();

    EXIT();
}

