    v[0] = 0;
    t[n + 1] = 0;
    v[n + 1] = 0;
    for (int i = 1; i <= n; i++) cin >> t[i];
    for (int i = 1; i <= n; i++) cin >> v[i];
    int tsum = 0;
    for (int i = 0; i <= n + 1; i++) {
        for (int j = 0; j <= 102 - v[i]; j++) {
            table[tsum + t[i] + j][v[i] + j] = 1;
        }
        for (int j = 1; j <= 102 - v[i]; j++) {
            if (tsum - j < 0) break;
            table[tsum - j][v[i] + j] = -1;
        }
        for (int j = 0; j < t[i]; j++) {
            table[tsum + j][v[i]] = 2;
          	table[tsum + j][104] = v[i];
        }
        tsum += t[i];
    }
    table[tsum][0] = -1;
    int cv = 0;
    double ans = 0;
    for (int i = 0; i < tsum; i++) {
      	assert(cv <= table[i][104]);
        if (table[i][cv] == 1) {
            if (table[i + 1][cv] == -1 || table[i + 1][cv] == 2) {
                ans += double(cv + 0.25);
            } else {
                ans += double(cv * 2 + 1) / 2;
                cv++;
            }
        } else if (table[i][cv] == -1) {
            ans += double(cv * 2 - 1) / 2;
            cv--;
        } else {
            ans += double(cv);
        }
    }

    cout << ans << endl;
    return 0;
}

