		q.pop() ;
		if(ii==0){
			tmp = v[0];
			if(v[0]>t[0])
				tmp = t[0];
			if(tmp < val[1]){
				val[1] = tmp;
				q.push(1) ;
			}
		}
		else if(ii==n2-1){
			tmp = v[ii-1];
			if(v[ii-1]>t[ii-1])
				tmp = t[ii-1];
			if(tmp < val[n2-2]){
				val[n2-2] = tmp;
				q.push(n2-2);
			}
		}
		else{
			if(val[ii-1]>val[ii]){
				if(val[ii]+t[ii-1] >= v[ii-1]){
				}
				else{
					tmp = val[ii] + t[ii-1];
				}
				if(tmp < val[ii-1]){
					val[ii-1] = tmp;
					q.push(ii);
				}
			}
			if(val[ii+1]>val[ii]){
				if(val[ii]+t[ii] >= v[ii]){
				}
				else{
					tmp = val[ii] + t[ii];
				}
				if(tmp < val[ii+1]){
					val[ii+1] = tmp;
					q.push(ii);
				}
			}
		}
	}
	res = 0;
	double v1, v2;
	double tt;//double
	double d, d2;
	for(i=0; i<N; i++){
		v1 = min(val[i], val[i+1]);
		v2 = max(val[i], val[i+1]);
		tt = t[i];
		d = v2 + (tt-(v2-v1))/2;
		if(d > v[i]){
			d2 = (v[i]+v2)*(v[i]-v2)/2 + (v[i]+v1)*(v[i]-v1)/2 
					+ (tt-(v[i]-v2)-(v[i]-v1) )*v[i];
		}
		else{
			d2 = (d+v2)*(d-v2)/2 + (d+v1)*(d-v1)/2;
		}
		res += d2;
	}
	printf("%.6f\n", res);
}

