using namespace std;
using ll = long long;
template<typename T> inline bool chmax(T& a, T b) {if (a < b) {a = b; return true;} return 0;}
template<typename T> inline bool chmin(T& a, T b) {if (a > b) {a = b; return true;} return 0;}

const ll INF = 1LL << 50;

struct pos {
    double x, y;
    pos(double x, double y):x(x), y(y) {}
};

struct line {
    double slope, intercept;
    line(double slope, double intercept):slope(slope), intercept(intercept) {}
    double getX(double y) {
        return slope * (y - intercept);
    }
    double getY(double x) {
        return slope * x + intercept;
    }
    static pos getCrossPos(line l1, line l2) {
        double x = (l2.intercept - l1.intercept) / 2;
        double y = (l1.intercept + l2.intercept) / 2;
        return {x, y};
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<double> T(N), V(N);
    for (auto& t : T) {
        cin >> t;
    }
    for (auto& v : V) {
        cin >> v;
    }
    V.push_back(0);
    vector<double> cumsum(N, 0);
    rep(i, 0, N) {
        cumsum[i] = T[i] + (i ? cumsum[i - 1] : 0);
    }
    vector<line> L;
    rep(i, 1, N + 1) {
        L.emplace_back(-1, V[i] + cumsum[i - 1]);
    }
    double elapsed = 0;
    double now_v = 0;
    double ans = 0;
    rep(i, 0, N) {
        double max_v = INF;
        int idx = -1;
        double cross_x = -1;
        line now(1, now_v - elapsed);
        rep(j, i, N) {
            pos cross_pos = line::getCrossPos(now, L[j]);
            if (chmin(max_v, cross_pos.y)) {
                idx = j;
                cross_x = cross_pos.x;
            }
        }
        double x1 = min(cross_x, elapsed + T[i]);
        double x2 = x1;
        double next_v = min(now.getY(elapsed + T[i]), L[idx].getY(elapsed + T[i]));
        if (chmin(max_v, V[i])) {
            x1 = min(now.getX(max_v), elapsed + T[i]);
            x2 = min(L[idx].getX(max_v), elapsed + T[i]);
            chmin(next_v, max_v);
        }
        ans += (now_v + max_v) * (x1 - elapsed) / 2;
        ans += max_v * (x2 - x1);
        ans += (max_v + next_v) * (elapsed + T[i] - x2) / 2;
        now_v = next_v;
        elapsed += T[i];
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

