int main(){
    int n;
    cin >> n;
    vector<double> t(n), v(n);
    rep(i, n){
        cin >> t[i];
    }
    //  時間を累積和にしておく
    rep(i, n-1){
        t[i+1] += t[i];
    }
    int sum = t[n-1];
    rep(i, n){
        cin >> v[i];
    }
    //  合計時間以降の制限速度を0としておく
    v.push_back(0);
    vector<double> limit(sum);
    int j = 0;  //  時間と速度の関係を保持

    //  各時間ごとの制限速度表を作成
    rep(i, sum){
        if(i >= t[j]){
            j++;
        }
        //  起終点では止まっている必要があるため、その制限を設定
        if(i < sum/2){
            limit[i] = i+1;
        }else{
            limit[i] = sum-i-1;
        }
        // cout << i << " " << limit[i] << " ";

        //  その後、配列vによる制限速度と、次の制限速度までに減速の必要があるか否かの比較
        limit[i] = min({limit[i], v[j], v[j+1] + t[j] - i - 1});
        // cout << limit[i] << endl;
    }
    // cout << endl;
    double now = 0, ans = 0;
    j = 0;
    rep(i, sum){
        if(i >= t[j]){
            j++;
        }

        //  nowは現在の速度であり、とりあえず1秒間その速度で進んだことにする
        ans += now;
        if(now == limit[i]){
            //  次の制限と現在の速度が等しい場合で、かつ現在の制限より低い場合は0.5秒間加速し、0.5秒間減速したこととする
            if(now < v[j]){
                ans += 0.25;
            }
        }else if(now < limit[i]){
            //  次の制限よりも現在の速度のほうが低い場合は加速する
            ans += 0.5;
            now += 1;
        }else{
            //  現在の速度が高い場合は減速する
            ans -= 0.5;
            now -= 1;
        }
        // cout << i << " " << now << " " << ans << endl;
    }
    cout << fixed << setprecision(6) << ans << endl;
    return 0;
}

