const int MOD = 1e9+7;
const int SIZE=1e6+10;
int t[SIZE],v[SIZE],a[SIZE],m;

template <class T>
void mii(T& x,T y){
  if(x>y)x=y;
}

// $ g++ -std=c++14 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
//const int MAX_N=2*100*200+1;
int N;
void solve() {
  REP(i,SIZE) a[i]=MOD;
  int it=0;
  a[0]=0;
  REP(i,N) {
    mii(a[it],v[i]);
    REP(j,t[i]) {
      it++;
      mii(a[it],v[i]);
    }
  }
  mii(a[it],0);
  REPP(i,1,it+1) {
    mii(a[i],a[i-1]+1);
  }
  for(int i=it-1; i>=0; i--) {
    mii(a[i],a[i+1]+1);
  }
  LL an=0;
  REP(i,it) an+=(a[i]+a[i+1]);
  double ans=an*0.125;
  cout<<ans<<endl;
}

