    cin >> N;

    int t[N + 2];
    int v[N + 2];
    int T = 0; // 0.5幅のtime rangeがいくつあるか

    t[0] = 0;
    t[N + 1] = 0;
    v[0] = 0;
    v[N + 1] = 0;

    for (int i = 1; i <= N; i++) {
        int a;
        cin >> a;
        T += 2 * a;
        t[i] = 2 * a;
    }

    for (int i = 1; i <= N; i++) cin >> v[i];

    double table[N + 2][T + 1];

    int time_cnt = 0;

    for (int i = 0; i <= N + 1; i++) {
        for (int j = time_cnt; j <= time_cnt + t[i]; j++) {
            table[i][j] = v[i];
        }

        for (int j = time_cnt - 1; j >= 0; j--) {
            table[i][j] = table[i][j + 1] + 0.5;
        }

        for (int j = time_cnt + t[i] + 1; j <= T; j++) {
            table[i][j] = table[i][j - 1] + 0.5;
        }

        time_cnt += t[i];
    }

    double height[T + 1];

    for (int j = 0; j <= T; j++) {
        double min_h = 10000000.0;

        for (int i = 0; i <= N + 1; i++) {
            min_h = min(min_h, table[i][j]);
        }

        height[j] = min_h;
    }

    double ret = 0.0;

    for (int j = 0; j < T; j++) {
        ret += (height[j] + height[j + 1]) * 0.5 * 0.5;
    }

    cout << setprecision(5) << ret << endl;

    return 0;
}

