double eq(int speed1 , int time1,int speed2 , int time2){
  double time=time2-time1;

  double sp1=speed1,sp2=speed2;

  while(abs(sp1-sp2)>0.0001){
    if(sp1>sp2){
      sp2+=time;
      time=time/2;
    }
    else if(sp1<sp2){
      sp1-=time;
      time=time/2;
    }
  }
  nibun = (speed1*time*time/2+time) + (speed2*(time2-time1-time)*(time2-time1-time)/2-(time2-time1-time));
  return nibun;
}

