    vector<double> dp(201, -1);
    dp[0] = 0;
    for(int i = 0; i < N; ++i) {
        vector<double> nxt(201, -1);
        for(int j = 0; j <= v[i]; ++j) {
            if(dp[j] == -1) {
                continue;
            }
            for(int nv = 0; nv <= min(v[i + 1], v[i]); ++nv) {
                if(abs(nv - j) > t[i]) {
                    continue;
