double o_area(double lx, double rx, double cx, double cy){
    double lar, rar;
    lar = (cx - lx) * (cy + cy + lx - cx) / 2;
    rar = (rx - cx) * (cy + cy + rx - cx) / 2;
    return lar + rar;
}
double i_area(double lc, double rc, double cx, double cy, double v){
    double lar, rar;
        lar = (cx - lc) * (cx - lc) / 2;
        rar = (rc - cx) * (2 * cy + rc - cx - 2 * v) / 2;
