double get(double l, double r, double ts, double ms) {
    double ans = l * ts;
    r = r - l;
    ms = ms - l;
    l = 0;
    ans += r * r / 2.0 + r * (ts - r);
    if ((ts - r) / 2.0 + r <= ms) {
        ans += (ts - r) * (ts - r) / 4.0;
    } else {
        ans += (ms - r) * (ms - r) + (ms - r) * (ts - r - 2 * (ms - r));
    }
        //cout << ans << endl;
    return ans;
}


