const int MAX = 100;
int main() {
	int N, t[MAX + 2], v[MAX + 2]; // 始点と終点も走行時間0で制限速度0の区間と置いておく
	cin >> N;
	for (int i = 1;i <= N;i ++) cin >> t[i];
	for (int i = 1;i <= N;i ++) cin >> v[i];

	t[0] = 0;
	t[N + 1] = 0;
	v[0] = 0;
	v[N + 1] = 0;

	int m[MAX + 2]; // 更新された制限速度
	m[N + 1] = 0;
	for (int i = N;i >= 0;i --) {
		m[i] = min(m[i + 1] + t[i], v[i]); // i～i+1の地点における出していい限界速度
		// ここで、ある地点で次の地点の制限速度まで出しても常に大丈夫ということを成立させておく
		// これにより遠くの地点の制限速度を気にしなくてよくなるので問題が分割できる
		// 分割統治法が使えることは動的計画法の必要条件
	}
	int d = 0;

	int acc[MAX], con[MAX], dec[MAX], nowspd = 0;
	for (int i = 0;i < N;i ++) { // 最初の地点から順に動的計画法で求めていく
		acc[i] = min(min(2 * (m[i + 1] - nowspd), t[i + 1] + m[i + 2] - nowspd), t[i + 1] * 2); // i～i+1地点における加速時間の2倍
		dec[i] = max(nowspd * 2 + acc[i] - m[i + 2] * 2, 0); // i～i+1地点における減速時間の2倍
		con[i] = t[i + 1] * 2 - acc[i] - dec[i]; // i～i+1地点における等速時間の2倍
		d += (nowspd * 2 + nowspd * 2 + acc[i]) * acc[i]
			+ (nowspd * 2 + acc[i]) * con[i] * 2
			+ (nowspd * 2 + acc[i] + nowspd * 2 + acc[i] - dec[i]) * dec[i]; // i～i+1地点における移動距離の8倍
		nowspd += (acc[i] - dec[i]) / 2; // 現在の速度
	}
	cout << d / 8;
	if (d % 8) {
		cout << '.' << 125 * (d % 8);
	}
	return 0;
}
/* 
まず、最初にNから0に向かって制限速度の調整をして、制限速度一杯まで出してもセーフにしておく
そうすると、ある地点において初速sで入ったならなるべく次の区間の制限速度v[i+1]に近い値まで出せば良いということになる

次に、各区間について考える。
当然だが各区間では加速、等速、減速をこの順番で行うので、どれくらいの時間だけ加速/等速/減速するか求める。
これは各区間について初速s、制限速度v[i]、終速min(s+t[i],v[i+1])が分かっていれば求められる。
後は台形の公式で移動距離も分かるので、O(N)で求められるね！
*/

#include <bits/stdc++.h>
typedef long long ll;

using namespace std;

int main(){
	double N;
	cin >> N;
	vector<double> t(N+2, 0);
	vector<double> v(N+2, 0);
	for (int i = 1; i <= N; i++){
		cin >> t[i];
	}
	for (int i = 1; i <= N; i++){
		cin >> v[i];
	}

	vector<double> l(N+2, 0);
	vector<double> r(N+2, 0);
	for (int i = 2; i < N+2; i++){
		l[i] = l[i-1]+t[i-1];
	}
	for (int i = 1; i < N+2; i++){
		r[i] = r[i-1]+t[i];
	}

	vector<double> y;
	for (double x = 0; x <= r[N+1]; x += 0.5){
		double tmp = 1e9+1;
		for (int i = 0; i < N+2; i++){
			if (x < l[i]) tmp = min(tmp, v[i]+(l[i]-x));
			if ((l[i] <= x) && (x <= r[i])) tmp = min(tmp, v[i]);
			if (r[i] < x) tmp = min(tmp, v[i]+(x-r[i]));
		}
		y.push_back(tmp);
	}

	double res = 0;
	for (int i = 1; i < y.size(); i++){
		res += (y[i]+y[i-1])*0.25;
	}

	cout << res << endl;
	return 0;
}

