double solve(const V<ll> &tlist, const V<ll> &vlist, ll n, ll idx,
             V<double> &vborderlist)
{
    debug_printf("==== idx=%lld\n", idx);

    double vborder = (double)vlist[idx];

    double v1 = vborderlist[idx];
    double v2 = min(v1 + (double)tlist[idx], vborder);
    double t1 = 0.;
    rep (i, idx) t1 += (double)tlist[i];
    double t2 = t1 + (double)tlist[idx];

    double tsum = 0.;
    srep (i, idx+1, n) {
        v2 = min(v2, vlist[i] + tsum);
        tsum += tlist[i];
    }

    vborderlist.pb(v2);

    debug_printf("t1=%lf v1=%lf t2=%lf v2=%lf\n", t1, v1, t2, v2);

    double vma = max(v1, v2);
    double vmi = min(v1, v2);

    double tleft = t1;
    double tright = t2;
    double ttop;
    double vtop;
    rep (i, 100) {
        ttop = (tleft + tright) / 2.;
        double vleft = v1 + (ttop - t1);
        double vright = v2 + (t2 - ttop);
        vtop = vleft;
        //debug_printf("vleft=%lf vright=%lf\n", vleft, vright);
        if (vleft < vright) tleft = ttop;
        else tright = ttop;
    }

    debug_printf("ttop=%lf vtop=%lf\n", ttop, vtop);

    double retsub = 0.;
    if (vtop > vborder) retsub = (vtop - vborder) * (vtop - vborder);

    double h = vtop - vma;
    double ret1 = h * h;
    double ret2 = (2. * h + t2 - t1) * (vma - vmi) / 2.;
    double ret3 = (t2 - t1) * vmi;

    debug_printf("idx=%lld retsub=%lf ret1=%lf ret2=%lf ret3=%lf\n",
                 idx, retsub, ret1, ret2, ret3);

    return ret1 + ret2 + ret3 - retsub;
}

