double solve(double s, double g, double mv, double t){
  double rs = mv - s;
  double rg = t - (mv - g);
  double res = 0;
  if(rs <= rg){
    res = mv * t;
    res -= rs * rs / 2;
    res -= (t - rg) * (t - rg) / 2;
  }else{
    double x, y;
    x = (-s + g + t) / 2;
    y = (s + g + t) / 2;
    res = y * t;
    res -= x * x / 2;
    res -= (t - x) * (t - x) / 2;
  }
  return res;
}

