double f(double time, int id){
    if(id == 0) {
        if (time == 0) return 0;
        else return time;
    } else if (id == N+1) {
        if(time == cum[N]) return 0;
        else return cum[N]-time;
    }

    if (cum[id-1]<=time && time<=cum[id]) return v[id];
    else if(time <= cum[id-1]) return v[id]+cum[id-1]-time;
    else return v[id]+time-cum[id];
}

