    int32 n;
    cin >> n;
    vector<int32> t(n),v(n);
    REP(i,n)cin >> t[i];
    REP(i,n)cin >> v[i];
    vector<int32> w(n+1,inf);
    priority_queue<pii,vector<pii>,greater<pii>> que;
    REP(i,n){
        chmin(w[i], v[i]);
        chmin(w[i+1],v[i]);
    }
    REP(i,n+1){
        que.emplace(w[i],i);
    }
    w[0] = w[n] = 0;
    que.emplace(0,0);
    que.emplace(0,n);
    while(!que.empty()){
        int32 d,cur;
        tie(d,cur) = que.top();
        que.pop();
        if(w[cur] < d)continue;
        if(cur-1 >= 0 && chmin(w[cur-1], w[cur] + t[cur-1])){
            que.emplace(w[cur-1],cur-1);
        }
        if(cur+1 <= n && chmin(w[cur+1], w[cur] + t[cur])){
            que.emplace(w[cur+1],cur+1);
        }
    }
    // REP(i,n+1)cout << w[i] << " ";
    // cout << endl;

    double ans = 0;
    // 2 * x = 2 * v0 * t + a * t * t;
    REP(i,n){
