            ans += min<double>(w[i], w[i+1]) * t[i] + (double)t[i] * t[i] / 2;
        }else{
            double t0 = v[i] - w[i];
            double t1 = v[i] - w[i+1];
            if(t[i] - t0 - t1 < 0){
                double dt = -(t[i] - t0 - t1);
                t0 -= dt / 2;
                t1 -= dt / 2;
            }
            // cout << t0 << " " << t1 << endl;
            ans += w[i] * t0 + t0 * t0 / 2;
            ans += w[i+1] * t1 + t1 * t1 / 2;
            ans += v[i] * (t[i] - t0 - t1);
        }
    }
    cout << fixed << setprecision(15);
    ANS(ans);
    return 0;
}

