    cv = 0;
    for ( ll t = 2*t_max; t > 0 ; t-- ) {
        v[t] = cv;
        cv = min(cv+0.5, v[t-1]);
    }
    double ans = 0;
    for ( ll t = 0; t < 2*t_max; t++ ) {
        ans += v[t] + v[t+1];
    }
    ans /= 4;
    return ans;
}

