	seg[0] = 0;
	seg[s] = 0;

	f(i, s + 1){
		if (i == 0 || i == s)max[i] = 0;
		else{
			max[i] = min(max[i - 1] + 1, seg[i]);
			if (min(max[i - 1] + 1, seg[i]) != seg[i])c[i] = 0;
		}
	}

	for (int i = s; i >= 0; i--){
		max[i] = min(max[i + 1] + 1, max[i]);
		if (min(max[i + 1] + 1, max[i]) != max[i])c[i] = 0;
	}
	f(i, s){
		if (max[i] != max[i + 1])ans += min(max[i], max[i + 1]) + 0.5;
		else {
			if (c[i] == 0 || c[i + 1] == 0)ans += max[i] + 0.25;
			else ans += max[i];
		}
	}
	printf("%f\n", ans);

	return 0;
}

