int N;
vector<int> t(110, 0), v(110, 0), cum(110, 0);

double f(int i, double t){
    if(i == 0) return t;
    else if(i == N+1) return cum[N] - t;
    else if(cum[i-1] <= t && t <= cum[i]) return v[i];
    else if(t <= cum[i-1])                return v[i] + cum[i-1] - t;
    else if(cum[i] <= t)                  return v[i] + t - cum[i];

    return 0.0;
}

void input(){
    cin >> N;
    repr(i, 1, N+1) cin >> t[i];
    repr(i, 1, N+1) cin >> v[i];
    repr(i, 1, N+1) cum[i] = cum[i-1] + t[i];
}

void solve(){
    double ans = 0.0;
    double h1 = 0.0, h2 = 0.0;
    for(double t=0.5; t<=cum[N]; t+=0.5){
        h2 = 100000.0;
        rep(i, N+2) chmin(h2, f(i, t));
        ans += (h1 + h2) * 0.25;
        h1 = h2;
    }
    cout << setprecision(16) << ans << endl;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    input();
