void getbit(ll x, int bits[]) {
	int cnt = 0;
	while (x > 0) {
		if (x % 2 == 0)bits[cnt] = 0;
		else bits[cnt] = 1;
		x /= 2;
		cnt++;
	}
}
void addbit(ll x, int bits[]) {
	int cnt = 0;
	while (x > 0) {
		if (x % 2 == 0)bits[cnt] += 0;
		else bits[cnt] += 1;
		x /= 2;
		cnt++;
	}
}




