double func(double a){
    double minimum=100000;
    for(int i=0; i<N+2; i++) {
        if (a>=r[i]){
            minimum=min(minimum, a-r[i]+v[i]);
        }else if(a<=l[i]){
            minimum=min(minimum, l[i]-a+v[i]);
        }else{
            minimum=min(minimum,v[i]);
        }
    }
    return minimum;
}

