struct ST {
  int s, t;
  int v;
};
bool operator<(const ST& a, const ST& b){
  return a.v < b.v;
}

int main(){
  int N;
  vector<int> t, v;
  cin >> N;

  int allt = 0;
  rep(i,N){
    int a;
    cin >> a;
    t.push_back(a);
    allt += a;
  }
  rep(i,N){
    int a;
    cin >> a;
    v.push_back(a);
  }

  vector<ST> stv;
  int base = 0;
  rep(i,N){
    ST st;
    st.s = base;
    st.t = base + t[i];
    st.v = v[i];
    stv.push_back(st);
    base += t[i];
  }
  sort(ALLOF(stv));

  int M = allt * 2 + 1;
  vector<int> memo(M,0);
  rep(i,M){
    if(i > M-1-i) break;
    memo[i] = i;
    memo[M-1-i] = i;
  }

  rep(i,stv.size()){
    int ss = 2*stv[i].s;
    int tt = 2*stv[i].t;
    int vv = 2*stv[i].v;

    REP(i,ss,tt+1){
      if(memo[i] > vv){
        memo[i] = vv;
      }
    }
    int x = memo[ss];
    while(ss>0){
      ss--;
      x++;
      if(memo[ss] > x){
        memo[ss] = x;
      }else{
        break;
      }
    }
    x = memo[tt];
    while(tt<M){
      tt++;
      x++;
      if(memo[tt] > x){
        memo[tt] = x;
      }else{
        break;
      }
    }
  }


  double ret = 0;
  rep(i,M-1){
    //cout << i << " " << memo[i] << endl;
    int a = memo[i], b = memo[i+1];
    double h = min(a,b) / 2.0;

    if(a==b){
      ret += 0.5 * h;
    }else{
      ret += 0.5 * (h + 0.25);
    }
  }

  printf("%.16lf\n", ret);

  return 0;
}

