int N,T[maxn],V[maxn];
double ans;

double dfs(const int i, const double maxv2)
{
    const double a = 1;
    if (i == 0)
        return 0;
    double maxv1;
    if (maxv2 >= V[i] || maxv2+a*T[i] >= V[i])
        maxv1 = V[i];
    else
        maxv1 = maxv2+a*T[i];
    const double v1 = dfs(i-1,maxv1);
    double lo = v1, hi = min(maxv1, v1+a*T[i]);
    FOR(_,0,100) {
        const double mid = (lo+hi)/2;
        const double v2 = min(mid,maxv2);
        const double t1 = (mid-v1)/a;
        const double t2 = (mid-v2)/a;
        if (t1+t2 <= T[i])
            lo = mid;
        else
            hi = mid;
    }
    const double maxv = lo;
    const double v2 = min(maxv,maxv2);
    const double t1 = (maxv-v1)/a;
    const double t2 = (maxv-v2)/a;
    ans += (v1+maxv) * t1 / 2;
    ans += maxv * (T[i]-t1-t2);
    ans += (v2+maxv) * t2 / 2;
    return v2;
}

