int main(void){
    int n,i,j;
    double dt=0.5;
    cin>>n;
    vector<int> timetable = {0};
    vector<int> v_max;
    vector<double> v_table;
    for(i=0;i<n;i++){
        int tmp;
        cin>>tmp;
        timetable.push_back(tmp+timetable[i]);
    }
    for(i=0;i<n;i++){
        int tmp;
        cin>>tmp;
        v_max.push_back(tmp);
    }
    for(i=0;i<timetable.back()*2;i++){
        v_table.push_back((i<timetable.back())?i*0.5:(timetable.back()*2-i)*0.5);
    }
    for(i=0;i<n;i++){
        double t_s=timetable[i], t_e=timetable[i+1], v;
        for(j=0;j<v_table.size();j++){
            if(j*dt<t_s) v=v_max[i]+(t_s-j*dt);
            else if(t_s<=j*dt && j*dt<=t_e) v=v_max[i];
            else v=v_max[i]+(j*dt-t_e);
            v_table[j]=min(v_table[j],v);
        }
    }
    cout<<accumulate(v_table.begin(), v_table.end(), 0.0)*dt<<endl;
