		// t[i]～t[i + 1]
		for (ll curr_t = t[i]; curr_t < t[i + 1]; ++curr_t) {
			ll max_val = v[i + 1];
			vmax_table[curr_t] = max_val;
		}
	}

	double curr_v = 0.0;
	ll curr_time_index = 0;
	for (double curr_t = 0.0; curr_t < t[N]; curr_t += 0.5) {
		// calc square(curr_t, curr_t + 0.5)
		double next_t = curr_t + 0.5;
		double max_v = vmax_table[(ll)curr_t];
		double next_v = 0.0;
		double menseki = 0.0;

		if (curr_t >= t[curr_time_index + 1]) curr_time_index++;

		// limit
		double next_limit_t = (double)t[curr_time_index + 1];
		ll next_max_v = vmax_table[next_limit_t];
		if (next_max_v < curr_v && next_limit_t - curr_t <= curr_v - next_max_v) {
			next_v = curr_v - 0.5;
		}
		else {
			next_v = min(-next_t + t[N], curr_v + 0.5);
			next_v = min(next_v, max_v);
		}

		menseki = (curr_v + next_v) * 0.5 / 2.0;
		ans += menseki;
		//printf("time(%f-%f) : curr_v = %f, next_v = %f, menseki = %f \n", curr_t, next_t, curr_v, next_v, menseki);

		// next
		curr_v = next_v;
	}

	printf("%.20f\n", ans);

	return 0;
}

