const int maxn = 110;
int N,T[maxn],V[maxn];

typedef pair<double, double> PDD;

PDD dfs(const int i, const double maxend)
{
    if (i == 0)
        return PDD(0,0);
    const double t = T[i];
    const double v = V[i];
    const double m = min(v,maxend);
    /* y = v; y = m - (x-t)         => x = m+t-v */
    const double x0 = m+t-v;
    PDD res;
    if (x0 < 0)
        res = dfs(i-1,m+t);
    else
        res = dfs(i-1,v);
    const double s0 = res.first;
    const double y0 = res.second;
    /*
     * y = y0 + x; y = v            => x = v-y0
     * ..          y = m - (x-t)    => x = (m+t-y0)/2
     * ..          x = t            => x = t
     */
    /* check which 2 lines intersect first */
    const double x1 = v-y0;
    const double x2 = (m+t-y0)/2;
    const double x3 = t;
    if (x3 < x2) {
        const double y1 = y0+x3;
        const double s1 = (y0+y1)*x3/2;
        return PDD(s0+s1, y1);
    }
    else if (x2 < x1) {
        const double y1 = y0+x2;
        const double s1 = (y0+y1)*x2/2 + (y1+m)*(t-x2)/2;
        return PDD(s0+s1, m);
    }
    else {
        const double y1 = y0+x1;
        double s1 = (y0+y1)*x1/2 + y1*(t-x1);
        if (v > m)
            s1 -= (t-x0)*(t-x0)/2;
        return PDD(s0+s1, m);
    }
}

