            if(j>v[cnt]*2)continue;
            if(dp[i][j]==-INF)continue;
            cmax(dp[i+1][j],dp[i][j]+j);
            if(j+1<=2*v[cnt])
                cmax(dp[i+1][j+1],dp[i][j]+j+1);
            if(j-1>=0)
                cmax(dp[i+1][j-1],dp[i][j]+j-1);
        }
    }
    printf("%lf\n",(double)dp[allt][0]/(double)4);
}

