	REP(i, N) {
		//速度規制区間の左端と右端(時間は2倍に希釈)
		int tl = t[i] * 2;
		int tr = t[i + 1] * 2;
		//cout << "tl&tr " << tl << " " << tr << endl;
		//谷の左
		REP2(t, tl)minv[t] = min(minv[t], (tl - t) + v[i]);
		//谷の中央
		FOR2(t, tl, tr)minv[t] = min(minv[t], v[i]);
		//谷の右
		FOR2(t, tr, sumt)minv[t] = min(minv[t], (t - tr) + v[i]);
	}

	int ans = 0;
	REP(i, sumt) {
		ans += (minv[i] + minv[i + 1]);
	}
	cout << ans * 0.125l << endl;
}


