vector<ll> apply_condition(ll v, ll l, ll r, ll T_size){
    constexpr ll ACC = 2;
    vector<ll> ret(T_size);
    for (ll i = l; i <= r; i++){
        ret.at(i) = v;
    }
    for (ll i = l - 1; i >= 0; i--){
        ret.at(i) = ret.at(i + 1) + ACC;
    }
    for (ll i = r + 1; i < T_size; i++){
        ret.at(i) = ret.at(i - 1) + ACC;
    }
    return ret;
}



