ll mpow(ll x, ll n){
    ll ans = 1;
    while(n != 0){
    if(n&1) ans = ans*x % MOD;
    x = x*x % MOD;
    n = n >> 1;
    }
    return ans;
    }
    ll kj(ll x){
    ll s = 1;
    for(ll i = 1; i <= x; i++){
