vector<double> GetTim(double v0, double v1, double T, double LIMIT){
  double t1 = (T + v1 - v0) / 2;
  relaxMin(t1, LIMIT - v0);
  double t2 = t1 + v0 - v1;
  double t_mid = T - t1 - t2;

  if(t1 < -EPS || t2 < -EPS || t_mid < -EPS)
    return {};

  return {t1, t_mid, t2};
}

double OneDist(double v, double a, double t){
  return v * t + a * SQR(t) / 2;
}

double Dist(double v0, const vector<double>& tims){
  return OneDist(v0, +1, tims[0]) +
         OneDist(v0 + tims[0], 0, tims[1]) +
         OneDist(v0 + tims[0], -1, tims[2]);
}

