void solve() {
	int N; cin >> N;
	vector<int> T(N); for (auto& a : T) cin >> a;
	vector<int> V(N); for (auto& a : V) cin >> a;

	vector<int> Tsum(N+1);
	Tsum[0] = 0;
	FOR(i, 1, N+1) Tsum[i] = Tsum[i - 1] + T[i-1];

	vector<tuple<int, int, int> > Vtuple;

	REP(i, N) {
		int from = Tsum[i];
		int to = Tsum[i + 1];
		int v = V[i];
		Vtuple.emplace_back(from, to, v);
	}
	Vtuple.emplace_back(-1, 0, 0);
	Vtuple.emplace_back(Tsum.back(), Tsum.back()+1, 0);

	vector<double> tv;
	for (double t = 0.0; t <= Tsum.back(); t += 0.5) {
		double mi = inf;
		for (auto& a : Vtuple) {
			int from, to, v; tie(from, to, v) = a;
			if (from <= t and t <= to) {
				mi = min(double(v), mi);
			}
			else if (to <= t) {
				mi = min((t - to) + v, mi);
			}
			else if (t <= from) {
				mi = min((from - t) + v, mi);
			}
		}
		tv.emplace_back(mi);
	}

	double res = 0;
	REP(i, tv.size()-1) {
		res += (tv[i] + tv[i+1]) * 0.5 / 2.0;
	}
	cout << res << endl;
}

