    double ans = 0;
    int sum_t = 0;
    for (int j = 0; j < N; ++j) {
        double t0 = sum_t;
        double v0 = (j == 0) ? 0 : min(v[j-1], v[j]);
        double vz = min(v[j], v[j+1]);

        double tu = min(v[j] - v0 + t0, ((vz - v0) + (t0 + t0+t[j])) / 2);
        double td = max(tu, vz + t0+t[j] - v[j]);

        // cout << "-----" << endl;
        // cout << tu << " " << td << endl;
        // cout << (v0 * (tu - t0) + (tu - t0) * (tu - t0) / 2) << "  " << (v[j] * (td - tu)) << "  " << (sum_t+t[j]-td)*(sum_t+t[j]-td) / 2 << endl;



        ans += v0 * (tu - t0) + (tu - t0) * (tu - t0) / 2;
        ans += v[j] * (td - tu);
        ans += vz * (sum_t+t[j]-td) + (sum_t+t[j]-td)*(sum_t+t[j]-td) / 2;

        sum_t += t[j];
    }
    cout << fixed << setprecision(10) << ans << endl;

    return 0;
}

