            else {
                area += (v[i]-vt) * ((v[i]-vt)/2.0 + vt); //v[i]に達するまで加速し、その後キープ
                area += (t[i] - (v[i]-vt))*v[i]; vt = v[i];

            }
        }else{

            if(v[i]-vt + v[i] - gl<=t[i]){ // 途中でv[i]に達することができる場合。最大加速でv[i]にし、最大減速でglにする。
                area += (v[i]-vt)*(v[i]-vt)/2.0 + vt * (v[i]-vt) + gl*(v[i]-gl) +(v[i]-gl) *(v[i]-gl) /2.0 + v[i]*(t[i] -((v[i]-vt + v[i] - gl) ));
                vt = gl;
            }else{
                double dt = (gl-vt+t[i])/2.0; // v[i]に一度も達さない。
                if (dt<0)dt = 0;
                area += vt * dt + (t[i]-dt) * gl;
                area += dt*dt/2.0 + (t[i]-dt)*(t[i]-dt)/2.0;
                vt = gl;
            }

        }

