	TimeRate /= (512 * 4);
	//現在の枠N
	for (NowN = 0; NowN < N; NowN++) {

	//枠N内の経過時間
		for (Time = 0; Time < t[NowN]; Time += TimeRate) {

			AfterTime = 0;
			safeFlag = 1;

			for (int i = NowN; i <= N; i++) {

				AfterTime += t[i];
				if ((Speed - v[i + 1]) >= (AfterTime - Time)) {
					spBuffer = (Speed - v[i + 1]) / (AfterTime - Time);
					Speed -= spBuffer * TimeRate;

					safeFlag = 0;
					break;
				}

			}
			if ((Speed < v[NowN]) && safeFlag ) {
				if (Speed + TimeRate <= v[NowN])Speed += TimeRate;
				else Speed = v[NowN];
			}

			Run += Speed * TimeRate;


		}

		TimeRefine += t[NowN];

	}
	std::cout << Run;


	return 0;
}

