struct st {
	double lef;
	double rig;
	double hi;
};

vector<st> vv;

struct line {
	double A;
	double N;
	line(double A_, double N_) {
		A = A_;
		N = N_;
	}
	double get(double x) {
		return A*x + N;
	}
};
pair<double, double> intersect(line a, line b) {  // fraction{first/second}
	return make_pair(a.N - b.N, b.A - a.A);
}

int main() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		int a;
		scanf("%d", &a);
		t.push_back(a);
	}
	for (int i = 0; i < n; i++) {
		int a;
		scanf("%d", &a);
		v.push_back(a);
	}
	double S = 0;
	vv.push_back({ 0,0,0 });
	for (int i = 0; i < v.size(); i++) {
		vv.push_back({ S,S + t[i],(double)(v[i]) });
		S += t[i];
	}
	vv.push_back({ S,S,0 });
	bool update = true;
	if(update) {
		update = false;
		vector<int> er;
		for (int i = 0; i < vv.size(); i++) {
			for (int j = 0; j < vv.size(); j++) {
				if (i == j)continue;
				if (j < i) {
					double L = vv[j].rig;
					double R = vv[i].lef;
					double val = vv[j].hi + R - L;
					if (val >= vv[i].hi) {
						continue;
					}
					update = true;
					double val2 = vv[j].hi + vv[i].rig - L;
					if (val2 < vv[i].hi) {
						vv[i].lef = vv[i].rig;
						vv[i].hi = val2;
						break;
					}
					double X = vv[i].hi - vv[j].hi + vv[j].rig;
					vv[i].lef = X;
					continue;
				}
				double L = vv[i].rig;
				double R = vv[j].lef;
				double sa = vv[i].hi - vv[j].hi;
				double val = vv[j].lef - vv[i].rig+vv[j].hi;
				if (val >= vv[i].hi) {
					continue;
				}
				update = true;
				double val2 = vv[j].hi + vv[j].lef - vv[i].lef;
				if (val2 < vv[i].hi) {
					vv[i].rig = vv[i].lef;
					vv[i].hi = val2;
					break;
				}
				double X = R - sa;
				vv[i].rig = X;
				continue;
			}
		}
	}
	double ar = 0;
	for (int i = 0; i < vv.size(); i++) {
		ar += vv[i].hi*(vv[i].rig - vv[i].lef);
		if (i + 1 < vv.size()) {
			line lineA = line(1, vv[i].hi - vv[i].rig);
			line lineB = line(-1, vv[i+1].hi + vv[i+1].lef);
			pair<long long int, long long int> p = intersect(lineA, lineB);
			double ich = p.first;
			ich /= (double)(p.second);
			double hi = lineA.get(ich);
			ar += (vv[i].hi + hi) / 2.0*(ich - vv[i].rig);
			ar += (vv[i + 1].hi + hi) / 2.0*(vv[i+1].lef - ich);
		}
	}
	printf("%.16f\n", ar);
	return 0;
}

