                    double x = 1.0 * (k - j + T[i]) / 2;
                    double y = 1.0 * (T[i] - k + j) / 2;
                    double kj = j + x;

                    double up = 1.0 * (j + kj) * x / 2;
                    double down = 1.0 * (k + kj) * y / 2;

                    double c = up + down;
                    dp[i+1][k] = max(dp[i+1][k], dp[i][j]+ c);
