const long long int MOD = 1000000007;

long long int N, M, K, H, W, L, R;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<int>range(N+1);
	vector<int>speed(N+1);
	for (int i = 1; i <= N; i++) {
		cin >> range[i];
		M += range[i];
	}
	for (int i = 1; i <= N; i++) {
		cin >> speed[i];
	}
	speed.push_back(0);
	vector<vector<long double>>dp(N + 1, vector<long double>(101,-10000000));
	dp[0][0] = 0;
	for (int i = 1; i <= N; i++) {
		for (int j = 0; j <= min(speed[i], speed[i + 1]);j++) {
			for (int k = 0; k <= min(speed[i - 1], speed[i]); k++) {
				if (abs(j - k) > range[i]) {
					continue;
				}
				long double add = 0;
				add += (j + k)*abs(j - k) * 2;
				add += (4 * max(k,j) + range[i] - abs(j - k))*(range[i] - abs(j - k));
				if (2 * speed[i] < 2 * max(k,j) + range[i] - abs(j - k)) {
					add -= (2 * max(k,j) + range[i] - abs(j - k) - 2 * speed[i])*(2 * max(k,j) + range[i] - abs(j - k) - 2 * speed[i]);
				}
				add /= 4;
				dp[i][j] = max(dp[i][j], dp[i - 1][k] + add);
			}
		}
	}
	cout <<setprecision(15)<< dp[N][0] << endl;
	return 0;
}

