			tv[s + 1 + j] = v[i];
		}
		s = s+t[i];
	}
	fill((*dp), (*dp) + 20001 * 101, -1);
	rep(i, 101)dp[0][i] = -INF;
	dp[0][0] = 0;
	cout <<fixed<<setprecision(10)<< DP(s,0) << endl;
