double eq(int speed1 , int time1,int speed2 , int time2){
  double time=time2-time1;
  double nibun;
  double sp1=speed1,sp2=speed2;
  int flag=0;
  while(true){
    if(abs(sp1-sp2)<0.0001){
      break;
    }
    else if(sp1>sp2){
      sp2+=time;
      time=time/2;
    }
    else if(sp1<sp2){
      sp1-=time;
      time=time/2;

    }
  }
  return (double)(speed1*time*time/2+time)+(speed2*(time2-time1-time)*(time2-time1-time)/2-(time2-time1-time))
}

