int main(){
	int N;
	cin>>N;
	int t[101],v[101];
	rep1(i,N)cin>>t[i];
	rep1(i,N)cin>>v[i];

	int lim[101];
	lim[N]=0;
	for(int i=N-1;i>=1;i--){
		lim[i]=min(v[i+1],t[i+1]+lim[i+1]);
		lim[i]=min(v[i],lim[i]);
	}
	//ポイントごとの速度
	int p[101];
	//距離zは4倍して加算
	int z;
	p[0]=0;
	rep1(i,N){
		int dist;
		int x=v[i]-p[i-1];
		int y=v[i]-lim[i];
		if(x+y<=t[i]){
			dist=4*v[i]*t[i]-x*x*2-y*y*2;
			p[i]=lim[i];
		}
		else if(p[i-1]+t[i]<lim[i]){
			dist=2*t[i]*(2*p[i-1]+t[i]);
			p[i]=p[i-1]+t[i];
		}
		else{
			dist=4*v[i]*t[i]-x*x*2-y*y*2+(x+y-t[i])*(x+y-t[i]);
			p[i]=lim[i];
		}
		z+=dist;
	}
	double d=(double)z/4;
	cout<<d<<endl;
}

