ld calc(ld t, ld l, ld r, ld nex){
  ld L = -1, R = r;
  while(R-L>0.000000001){
    ld mid = (L+R)/2;
    ld A = max((ld)0, mid - l);
    ld B = max((ld)0, mid - nex);
    if(A+B<t) L = mid;
    else R = mid;
  }
  ld A = max((ld)0, R - l);
  ld B = max((ld)0, R - nex);
  ld C = t - A - B;
  ld x = (C*R);
  ld y = (A*l) + ((A*A)/2);
  ld z = (B*nex)+((B*B)/2);
  return x+y+z;
}

