class line {
public:
    double velocity;
    double start;
    double end;

    double calc(double time) {
        if (time >= start && time <= end) {
            return velocity;
        } else if (time < start) {
            return (start - time) + velocity;
        } else if (time > end) {
            return (time - end) + velocity;
        } else {
            throw;
        }
    }
};

