using namespace std;

const int inf = 1000000007;

int T[102], V[20004], dp[20004][102];

int solve(int x, int y)
{
    if(y < 0 || y > V[x])
        return -inf;

    if(x == 0)
        return 0;

    if(dp[x][y] != -1)
        return dp[x][y];

    int ans = solve(x-1, y) + y * 4;
    ans = max(ans, solve(x-1, y-1) + (y-1) * 4 + 2);

    if(y != V[x])
    {
        ans = max(ans, solve(x-1, y+1) + y * 4 + 2);
        ans = max(ans, solve(x-1, y) + y * 4 + 1);
    }

    return dp[x][y] = ans;
}

