double Abs(double x) { if (x > 0) return x; return -x; }

int main() {
	int i, j;

	cin >> n;
	for (i = 0; i < n; i++) cin >> t[i];
	for (i = 0; i < n; i++) cin >> v[i];

	//速度を下げきれない場合をなくす
	for (i = n; i > 0; i--) {
		int limitV = v[i];
		for (j = i - 1; j >= 0; j--) {
			limitV += t[j];
			v[j] = min(limitV, v[j]);
		}
	}

	//あとは各区間で独立に制限速度を守ればよい。
	double nowSpeed = 0;
	double ans = 0;

	for (i = 0; i < n; i++) {
		if (v[i] > v[i + 1]) {
			if (v[i] - nowSpeed + v[i] - v[i + 1] <= t[i]) {
				ans += (nowSpeed + v[i]) * 0.5 * (v[i] - nowSpeed);
				ans += v[i] * (t[i] - (v[i] - nowSpeed + v[i] - v[i + 1]));
				ans += (v[i] + v[i + 1]) * 0.5 * (v[i] - v[i + 1]);
				nowSpeed = v[i + 1];
			}
			else {
				double maxSpeed = v[i] + (t[i] - (v[i] - nowSpeed + v[i] - v[i + 1])) * 0.5;
				if (maxSpeed >= v[i + 1]) {
					ans += (nowSpeed + maxSpeed) * 0.5 * (maxSpeed - nowSpeed);
					ans += (maxSpeed + v[i + 1]) * 0.5 * Abs(maxSpeed - v[i + 1]);
					nowSpeed = v[i + 1];
				}
				else {
					ans += (nowSpeed + maxSpeed) * 0.5 * (maxSpeed - nowSpeed);
					nowSpeed = maxSpeed;
				}
			}
		}
		else {
			if (v[i] - nowSpeed <= t[i]) {
				ans += (nowSpeed + v[i]) * 0.5 * (v[i] - nowSpeed);
				ans += v[i] * (t[i] - (v[i] - nowSpeed));
				nowSpeed = v[i];
			}
			else {
				double maxSpeed = nowSpeed + t[i];
				ans += (nowSpeed + maxSpeed) * 0.5 * t[i];
				nowSpeed = maxSpeed;
			}
		}
	}
	printf("%.14f\n", ans);

	return 0;
}

