  vector<vector<double>> dp(tt+1, vector<double>(101*2, -(1ll<<50)));
  dp[0][0] = 0;

  int prevTopSpeed = 0;
  int topSpeed = v[0];
  int tIndex = 0;
  int tRem = t[0];
  for(int i=0; i<tt; i++){
    for(int s=0; s<=prevTopSpeed; s++){
      for(int d=-1; d<=+1; d++){
        int s_ = s+d;
        if(s_<0 || s_>topSpeed || ( (s+s_)*0.5 > topSpeed ) ) continue;
        dp[i+1][s_] = max(dp[i+1][s_], dp[i][s] + (s+s_)*0.5 );
      }
    }

    tRem--;
    prevTopSpeed = topSpeed;
    if(tRem == 0){
      tIndex++;
      if(tIndex < n){
        topSpeed = v[tIndex];
        tRem = t[tIndex];
      }
    }
  }

  printf("%.16f\n", dp[tt][0] / 4.0);

  return 0;
}

