struct state {
  double begin;
  double end;
  double v;
  state() {}
  state(double b, double e, double v): begin(b), end(e), v(v) {}
};

int main(void) {
  int n;
  cin >> n;

  vector<int> t(n + 2, 0), v(n + 2, 0);
  for (int i = 1; i <= n; i++) {
    cin >> t[i];
  }
  for (int i = 1; i <= n; i++) {
    cin >> v[i];
  }

  vector<state> vs(n + 2);
  vs[0] = state(0, 0, 0);
  for (int i = 1; i <= n + 1; i++) {
    state s = vs[i - 1];
    vs[i] = state(s.end, s.end + t[i], v[i]);
  }

  const double eps = 1e-10;
  int T = 2 * (int)vs[n + 1].end;
  vector<double> p(T + 1, 101.0);
  for (int i = 0; i <= T; i++) {
    double t = i / 2.0;
    for (int j = 0; j < n + 2; j++) {
      if (vs[j].begin - t > eps) {
        p[i] = min(p[i], vs[j].begin - t + vs[j].v);
      } else if (t - vs[j].end > eps) {
        p[i] = min(p[i], t - vs[j].end + vs[j].v);
      } else {
        p[i] = min(p[i], vs[j].v);
      }
    }
  }

  double ans = 0.0;
  for (int i = 0; i < T; i++) {
    ans += p[i] + p[i + 1];
  }
  printf("%.10f\n", ans / 4.0);

  return 0;
}

