	double tt[102];
	tt[0] = 0;
	int T = 0;
	for (size_t i = 1; i <= n; i++)
	{
		int t;
		cin >> t;
		//t *= 2;
		T += t;
		ft[i] = T - t;
		tt[i] = T;
	}
	tt[n + 1] = T;
	ft[n + 1] = T;
	double v[102];
	v[0] = 0;
	v[n + 1] = 0;
	for (size_t i = 1; i <= n; i++)
	{
		cin >> v[i];
	}
	n += 2;
	double res = 0;
	for (double i = 0; i <= T; i += 0.5)
	{
		double minu = INF;
		for (int j = 0; j < n; j++)
		{
			if (i <= ft[j]) {
				minu = min(minu,v[j] + (ft[j] - i));
			}
			else if (ft[j] <= i && i <= tt[j]) {
				minu = min(minu, v[j]);
			}else if(tt[j] <= i){
				minu = min(minu, v[j] + (i - tt[j]));
			}
		}
		res += minu;
	}
	cout << (res / 2) << endl;
}

