int main() {
    std::ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<double> t(n);
    for (int i = 0; i < n; i++) cin >> t[i];
    vector<double> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];

    vector<double> vv(n + 1);
    for (int i = 1; i < n; i++) {
        vv[i] = std::min(v[i - 1], v[i]);
    }

    for (int i = 1; i <= n - 1; i++) {
        vv[i] = std::min(vv[i], vv[i - 1] + t[i - 1]);
    }
    for (int i = n - 1; i >= 1; i--) {
        vv[i] = std::min(vv[i], vv[i + 1] + t[i]);
    }

    double s = 0;

    for (int i = 0; i < n; i++) {
        double v1 = std::min(vv[i], vv[i + 1]);
        double v2 = std::max(vv[i], vv[i + 1]);
        double t1 = v[i] - v1;
        double t2 = v[i] - v2;
        if (t1 + t2 < t[i]) {
            s += t1 * (v1 + v1 + t1) + t2 * (v2 + v2 + t2) + (t[i] - t1 - t2) * v[i] * 2;
        } else {
            s += (v2 - v1) * (v1 + v2);
            double tt = (t[i] - (v2 - v1));
            s += tt * (v2 + v2 + tt / 2);
        }
    }
    s *= 0.5;

    cout << std::setprecision(20);
    cout << s;

    return 0;
}

