ld calc(ld t, ld l, ld r, ld nex){
  ld L = -1, R = r+1;
  while(R-L>0.000000000001){
    ld mid = (L+R)/2;
    ld A = max((ld)0, mid-l);
    ld B = max((ld)0, mid - nex);
    if(A+B<=t) L = mid;
    else R = mid;
  }
  R = min(R, r);
  ld A = max((ld)0, R-l);
  ld B = max((ld)0, R-nex);
  ld C = max((ld)0, t - A - B);
  return (C*R)+(A*l) + ((A*A)/2) + (B*nex)+((B*B)/2);
}

