double epsilon = 1e-10;

using namespace std;

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    vector<double> time(N, 0), limit(N, 0);

    for (int i = 0; i < N; i++)
    {
        if (scanf("%lf", &time[i]) < 1) return 0;
    }

    for (int i = 0; i < N; i++)
    {
        if (scanf("%lf", &limit[i]) < 1) return 0;
    }

    vector<double> left(N, 0), right(N, 0);

    for (int i = 0; i < N; i++)
    {
        if (i != N - 1)
        {
            right[i] = min(limit[i], limit[i + 1]);
            left[i + 1] = right[i];
        }

        double mx = max(left[i], right[i]);
        double mn = min(left[i], right[i]);

        double top = (time[i] - (mx - mn)) / 2 + mx;

        if (top < limit[i]) limit[i] = top;
    }

    for (int i = N - 1; 0 <= i; i--)
    {
        if (i != 0)
        {
            left[i] = min(limit[i], limit[i - 1]);
            right[i - 1] = left[i];
        }

        double mx = max(left[i], right[i]);
        double mn = min(left[i], right[i]);

        double top = (time[i] - (mx - mn)) / 2 + mx;

        if (top < limit[i]) limit[i] = top;
    }

    double sum = 0.0;
    for (int i = 0; i < N; i++)
    {
        double timeLeft = 0.0;
        double timeRight = 0.0;

        double mx = max(left[i], right[i]);
        double mn = min(left[i], right[i]);

        if (limit[i] <= left[i] + time[i])
        {
            timeLeft = limit[i] - left[i];
            timeRight = time[i] - (limit[i] - right[i]);
            sum +=
                ((timeRight - timeLeft  // 台形上底
                    + time[i] - (mx - mn))      // 台形下底
                    * (limit[i] - mx)) / 2;

            if (epsilon < fabs(mx - mn))
            {
                sum +=
                    ((time[i] - (mx - mn)   // 台形上底
                        + time[i])                  // 台形下底
                        * (mx - mn)) / 2;
            }

            if (epsilon < (double)mn)
            {
                sum += time[i] * mn;
            }
        }
        else
        {
            double bottom = (time[i] - (mx - mn));

            double height = (time[i] - (mx - mn)) / 2;

            sum += bottom * height / 2;

            if (epsilon < fabs(mx - mn))
            {
                sum += (bottom + time[i]) * (mx - mn) / 2;
            }

            if (epsilon < (double)mn)
            {
                sum += time[i] * mn;
            }
        }
    }

    printf("%f\n", sum);
    return 0;
}

