void solve() {
    i64 N; RD(N);
    auto T = RD_ARRAY<i64>(N);
    auto V = RD_ARRAY<i64>(N);

    vector<i64> vl(N);
    vector<i64> vr(N);
    vl[0]   = 0;
    vr[N-1] = 0;
    for(i64 i = 1; i < N; ++i) {
        vl[i] = min({ V[i-1], V[i], vl[i-1]+T[i-1] });
    }
    for(i64 i = N-2; i >= 0; --i) {
        vr[i] = min({ V[i+1], V[i], vr[i+1]+T[i+1] });
    }
    DBG(vl);
    DBG(vr);

    i64 area4x = 0;
    REP(i, N) {
        i64 t  = T[i];
        i64 v  = V[i];
        i64 v0 = vl[i];
        i64 v1 = vr[i];

        i64 tl = v-v0;
        i64 tr = t - (v-v1);
        if(v0+t < min(v,v1)) {
            area4x += 4*v0*t + 2*t*t;
        }
        else if(v1+t < min(v,v0)) {
            area4x += 4*v1*t + 2*t*t;
        }
        else if(tl <= tr) {
            area4x += 4*v*t - 2*ipow(v-v0,2) - 2*ipow(v-v1,2);
        }
        else {
            area4x += t*t + 2*t*(v0+v1) - ipow(v0-v1,2);
        }
    }

    f64 ans = static_cast<f64>(area4x) / 4;

    PRINTLN(ans);

    // * 小さいケースで試した?
    // * 不可能なケースはチェックした?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
}

