void solve()
{
    ll n,i;
    cin >> n;
    vector<ld> v(n),t(n),tt(n+1);
    tt[0] = 0;
    rep(i,n)
    {
        cin >> t[i];
        tt[i+1] = t[i] + tt[i];
    }
    rep(i,n)  cin >> v[i];
    ld ans = 0,p = 0;
    for(ld d = 0.0 ; d <= tt[n] ; d += 0.5)
    {
        ld imin = min(d,tt[n]-d);
        rep(i,n)
        {
            ld k;
            if(d <= tt[i])  k = v[i] + (tt[i] - d);
            else if(d >= tt[i+1]) k = v[i] + (d - tt[i+1]);
            else k = v[i];
            imin = min(imin,k);
        }
        ans += (p + imin)/4;
        p = imin;
    }
    cout << setprecision(10) << fixed << ans << endl;
}

