int main(){
  int N;
  cin >> N;
  vector<int> t(N), v(N);
  REP(i,N) cin >> t[i];
  REP(i,N) cin >> v[i];

  ld ret = 0.;
  ld v_crr = 0.;
  REP(i,N) {
    int v_nxt = (i == N - 1) ? 0 : v[i + 1];
    if(v[i] <= v_nxt) {
      if(v_crr + t[i] < v[i]) {
        ret += (v_crr * 2 + t[i]) * t[i] / 2.0;
        v_crr += t[i];
      }else {
        ret += v[i] * t[i] - (v[i] - v_crr) * (v[i] - v_crr) / 2.0;
        v_crr = v[i];
      }
    }else {
      if(2 * v[i] - v_crr - v_nxt > t[i]) {
        ld tmp = (t[i] - v_crr + v_nxt) / 2.0;
        ret += (2 * v_crr + tmp) * tmp / 2.0;
        ret += (v_crr + tmp + v_nxt) * (t[i] - tmp) / 2.0;
        v_crr = v_nxt;
      }else{
        ret += v[i] * t[i] - IRT(v[i] - v_crr) - IRT(v[i] - v_nxt);
        v_crr = v_nxt;
      }
    }
  }
  cout << fixed << setprecision(10) << ret << endl;
  return 0;
