LL dp(LL ti, LL sp)
{
	if (sp < 0) { return -inf; }
	if (ti == 0) {
		if (sp != 0)return -inf;
		return 0;
	}
	if (memo[ti][sp] != -1) { return memo[ti][sp]; }
	if (sp > lim[ti - 1])return -inf;
	LL a = dp(ti - 1, sp + 1) + sp + (sp + 1);
	LL b = dp(ti - 1, sp) + sp + sp;
	LL c = dp(ti - 1, sp - 1) + sp + (sp - 1);
	LL res = std::max(b, c); 
	if (sp + 1 <= lim[ti - 1]) { res = std::max(res, a); }
	return memo[ti][sp] = res;
}

