    vector<double> V(N);
    for(int i=0; i<N; i++) cin >> T[i];
    for(int i=0; i<N; i++) cin >> V[i];

    double len = 0.0;
    double curV = 0.0;
    double nextV = 0.0;
    for(int i=0; i<N; i++){
        double maxV = V[i];
        if(i==N-1){
            nextV = 0;
        }else{
            nextV = min(maxV, V[i+1]);
        }
        double t = T[i];
        double t1, t2;
        while(true){
            t1 = maxV - curV;
            t2 = maxV - nextV;
            if(t >= (abs(t1)+abs(t2))){
                break;
            }
            maxV -= 0.5;
        }
        double len1 = t1 * min(maxV,curV) + (t1*abs(maxV-curV))/2.0;
        double len_ = maxV * (t-t1-t2);
        double len2 = t2 * min(maxV,nextV) + (t2*abs(maxV-nextV))/2.0;

        len += len1 + len_ + len2;
        curV = nextV;
    }

    printf("%.15lf\n", len);

    return;
}

