long long N;

struct data_t {
    double start;
    double end;
    double v;
};
long long t[105];
long long v[105];

struct data_t arr[105];

double cal(double time){
	double mini = INT_MAX;

	for(long long i = 0; i <= N + 1; i++){
		if(time < arr[i].start){
			mini = min(mini, -1 * time + arr[i].start + arr[i].v);
		}else if(arr[i].start<= time && time <= arr[i].end){
			mini = min(mini, arr[i].v);
		}else{
			mini = min(mini, time - arr[i].end + arr[i].v);
		}
	}
	return mini;
}

int main(){
	cin >> N;

	for(long long i = 0; i < N; i++){
		cin >> t[i];
	}

	for(long long i = 0; i < N; i++){
		cin >> v[i];
	}

	arr[0].start = 0;
	arr[0].end = 0;
	arr[0].v = 0;

	long long cur = 0;
	for(long long i = 0; i < N; i++){
		arr[i + 1].start = cur;
		arr[i + 1].end = cur + t[i];
		arr[i + 1].v = v[i];
		cur += t[i];
	}
	arr[N+1].start = cur;
	arr[N+1].end = cur;
	arr[N+1].v = 0;

	double ans = 0;
	double speed = 0;
	for(double time = 0; time <= cur; time += 0.5){
		double nextspeed = cal(time);
		ans += (speed + nextspeed)*0.25;
		speed = nextspeed;
	}
	printf("%.10f\n", ans);
}

