constexpr i64 SCALE = 10000;

i64 N;
vector<i64> T;
vector<i64> V;

void solve() {
    ALL(transform_self, T, [](i64 t) { return SCALE*t; });
    ALL(transform_self, V, [](i64 v) { return SCALE*v; });

    vector<i64> vls(N);
    vls[0] = 0;
    for(i64 i = 1; i < N; ++i) {
        vls[i] = min({
            vls[i-1] + T[i-1],
            V[i-1],
            V[i],
        });
    }

    vector<i64> vrs(N);
    vrs[N-1] = 0;
    for(i64 i = N-2; i >= 0; --i) {
        vrs[i] = min({
            vrs[i+1] + T[i+1],
            V[i+1],
            V[i],
        });
    }

    i64 sum = 0;
    for(i64 i = N-1; i >= 0; --i) {
        i64 v  = V[i];
        i64 vl = vls[i];
        i64 vr = vrs[i];

        i64 cur = 0;
        REP(t, T[i]) {
            i64 w = min({
                v,
                vl + t,
                vr + (T[i]-t),
            });
            cur += w;
        }
        sum += cur;
    }

    f64 ans = static_cast<f64>(sum) / static_cast<f64>(ipow(SCALE,2));

    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {
    RD(N);
    RD(T, N);
    RD(V, N);

    solve();

    EXIT();
}

