double one = 1;
double two = 2;
const double fast = (one / two) * (0.5 * 0.5);
double calc(double f, double t) {


	if (f < t) {
		return (f * 0.5) + fast;
	}
	else if (f > t) {
		return (f * 0.5) - fast;
	}
	else return (f * 0.5);

}

void solv() {
	cin >> n;
	t[n] = 0;
	v[n] = 0;
	for (size_t i = 0; i < n; i++)
	{
		cin >> t[i];
	}
	for (size_t i = 0; i < n; i++)
	{
		cin >> v[i];
	}

	double now = 0;
	double res = 0;
	double time = 0;
	double ls = 0;
	for (int i = 0; i < n; i++)
	{
		for (double j = 0; j < t[i]; j += 0.5)
		{

			if (check(now + 0.5,time + 0.5)) {
				res += calc(now, now + 0.5);
				now += 0.5;
			}
			else if (check(now, time + 0.5)) {
				res += calc(now, now);
			}
			else {
				double pt = calc(now, now - 0.5);
				res += pt;
				ls += pt;
				now -= 0.5;
			}
			time += 0.5;
		}
	}
	if (now == 0.5) {
		res += calc(now, 0);
	}
	cout << res << endl;
}

