    for(int i=0;i<N;i++){
        cin >> v[i+1];
        vm=max(vm,v[i+1]);
    }
    v[N+1]=0;
    double dp[2*t[N]+2][2*vm+2];
    for(int i=0;i<2*t[N]+2;i++){
        for(int j=0;j<2*vm+2;j++){
            dp[i][j]=0;
        }
    }
    int c=1;
    for(int i=1;i<=2*t[N];i++){
        if(i==2*t[c]&&v[c]>v[c+1]) c++;
