            double a=0,b=0,c=0;
            if((dp[i-1][j-1]!=0&&j!=0)||j==1)a=dp[i-1][j-1]+(double)(2*j-1)/8;
            if(dp[i-1][j]!=0)b=dp[i-1][j]+(double)j/4;
            if(dp[i-1][j+1]!=0)c=dp[i-1][j+1]+(double)(2*j+1)/8;
            dp[i][j]=max({a,b,c});
        }
