    v[i] = min(v[i], t[i + 1]);
  }
  double dis = 0;
  double cur_speed = 0;
  for (int i = 0; i < n; i++) {
    if (i == n - 1) {
      double mx_speed = t[i];
      mx_speed = min(mx_speed, (double)v[i]);
      double treq = t[i] - mx_speed - (mx_speed - cur_speed);
      dis += treq * mx_speed;
      dis += (pow(mx_speed, 2) - pow(cur_speed, 2)) / 2;
      dis += pow(mx_speed, 2) / 2;
    } else {
      int treq = v[i] - cur_speed;
      if (treq <= t[i]) {
	dis += (pow(v[i], 2) - pow(cur_speed, 2)) / 2;
	cur_speed = v[i];
	dis += cur_speed * (t[i] - treq);
      } else {
	double fin_speed = cur_speed + t[i];
	dis += (pow(fin_speed, 2) - pow(cur_speed, 2)) / 2;
	cur_speed = fin_speed;
      }
    }
    cout << dis << endl;
  }
  cout << dis << endl;
