    int ss = speeds.size();
    vector<double> dp(ss);
    rep(i, ss) dp[i] = speeds[i];
    rep(i, ss) if (i != 0) cmin(dp[i], dp[i - 1] + 0.5);
    for (int i = ss - 2; i > 0; i--) cmin(dp[i], dp[i + 1] + 0.5);

    double sum = 0;

    rep(i, ss) {
        if (i == 0) continue;
        double a = dp[i - 1], b = dp[i];
        double now = (a + b) / 2 * 0.5;
        sum += now;
    }

    cout << setprecision(20) << sum << endl;

}

