signed main(){
    int N;
    vector<double> ts;
    vector<double> vs;
    cin >> N;
    for (int i = 0; i < N; i++) {
      double t;
      cin >> t;
      ts.push_back(t);
    }

    for (int i = 0; i < N; i++) {
      double v;
      cin >> v;
      vs.push_back(v);
    }

    vector<tv> tvs;
    double left_v = 0;
    for (int i = 0; i < N ; i++)
    {
      if (vs[i] <= left_v) {
        tvs.push_back({ts[i], vs[i], horizontal});
        left_v = vs[i];
      } else if (vs[i] - left_v < ts[i]) {
        tvs.push_back({vs[i] - left_v,left_v, up});
        tvs.push_back({ts[i] - (vs[i] - left_v), vs[i], horizontal});
        left_v = vs[i];
      } else {
        tvs.push_back({ts[i], left_v, up});
        left_v += ts[i];
      }
    }

    vector<tv> result_tv;
    double right_v = 0;
    reverse(tvs.begin(), tvs.end());
    for(auto tv : tvs)
    {
      double diff = tv.v - right_v;
      if (tv.d == horizontal) {
        if (tv.v <= right_v) {
          result_tv.push_back({tv.t, tv.v, horizontal});
          right_v = tv.v;
        } else if (diff < tv.t) {
          result_tv.push_back({diff,right_v,up});
          right_v = tv.v;
          result_tv.push_back({tv.t - diff, right_v, horizontal});
        } else {
          result_tv.push_back({tv.t, right_v, up});
          right_v += tv.v;
        }
      } else {
        if (right_v + tv.t <= tv.v){
          result_tv.push_back({tv.t, right_v, up});
          right_v += tv.t;
        } else {
          result_tv.push_back({(tv.t- right_v + tv.v) / 2, right_v,up });
          result_tv.push_back({tv.t - (tv.t - right_v + tv.v) / 2, tv.v,up });
          right_v = tv.v;
        }
      }
    }
    reverse(result_tv.begin(), result_tv.end());

    double integral = 0;
    for(auto tv : result_tv) {
      integral += tv.t * tv.v; 
      if (tv.d == up){
        integral += tv.t * tv.t /2;
      }
    }

    cout << integral << endl;
    return 0;
}

