int dp[202][40003];
int tab[40003];
int sum;
double x[102];
double speed[102];
int INF = 1000000000;

int compute(int time, int speed) {
    if (speed < 0 || speed > 200) return -INF;
    if (time == sum) {
        if (speed == 0) return 0;
        else return -INF;
    }
    if (dp[speed][time] != -1) return dp[speed][time];
    int index = tab[time];
    if (speed > v[index]) return -INF;

    int ans = -INF;
    if (speed < v[index]) ans = max(ans, compute(time + 1, speed + 1));
    ans = max(ans, compute(time + 1, speed));
    if (speed > 0) ans = max(ans, compute(time + 1, speed - 1));
    ans += speed;
    //printf("%lld %lld %lld: %lld\n", index, speed, time, ans);
    return dp[speed][time] = ans;
}

double maxSpeed(double speed, int index) {
    double ans = (double) min(speed + t[index], (double) v[index]);
    int cnt = 0;
    for (int i = index + 1; i < n; i++) {
        cnt += t[i - 1];
        x[index] = min(x[index], cnt - ans + v[i]);
    }
    cnt = 0;
    for (int i = index + 1; i < n; i++) {
        cnt += t[i - 1];
        double tmp = (cnt + speed + v[i]) / 2.;
        if (tmp < ans) {
            ans = tmp;
            x[index] = tmp - speed;
        }
    }
    return ans;
}

