        //t[i] *= 2;
        x[i] = (double) INF;
        for (int j = sum; j < sum + t[i]; j++) {
            tab[j] = i;
        }
        sum += t[i];
    }
    for (int i = 0; i < n; i++) {
        scanf("%I64d", &v[i]);
        //v[i] *= 2;
