        speed[i] = maxSpeed((i == 0) ? 0: min(speed[i - 1], (double) v[i]), i);
    }

    double ans = 0;

    /*
    for (int i = 0; i < n; i++) {
        cout << speed[i] << " " << x[i] << "\n";
