        curSpeed = speed[i];
        //cout << ans << "\n";
        if (min(x[i], (double) t[i]) > diff) {
            ans += (min(x[i], (double) t[i]) - diff) * speed[i]; // second triangle
        }
        //cout << ans << "\n";
        if (x[i] < t[i]) {
            ans += (t[i] - x[i]) * (t[i] - x[i]) / 2. + (t[i] - x[i]) * (speed[i] - (t[i] - x[i]));
            curSpeed = curSpeed - (t[i] - x[i]);
        }
        //cout << ans << "\n";
    }

    printf("%.20lf\n", ans);
    //cout << compute(0, 0) / 4. << "\n";
