double calc(int start, int end, int max, int time) {
    if (max < start || max < end) {
        return -1.0;
    }
    if (time < abs(start-end)) {
        return -1.0;
    }

    if (start < end) {
        double tmp = (end - start) * start + double((end - start) * (end - start)) / 2;
        return tmp + calc(end, end, max, time - (end - start));
    }

    if (end < start) {
        double tmp = (start - end) * end + double((start - end) * (start - end)) / 2;
        return tmp + calc(start, start, max, time - (start - end));
    }

    assert(start == end);

    if (start*2 + time <= max * 2) {
        return double(time * time) / 4.0 + start * time; 
    } else {
        return (max - start) * (max - start) + (max - start) * 2 * start + (time - (max - start) * 2) * max;
    }

}

