    rep (i, 0, N) {
        rep (j, 0, MAX_N-1) {
            dp[i][j] = -1.0;
        }
    }
    dp[0][0] = 0.0;

    rep (i, 1, N) {
        rep (j, 0, v[i]) {
            rep (k, 0, v[i-1]) {
                if (dp[i-1][k] < 0) {
                    continue;
                }
                double tmp = calc(k, j, v[i], t[i]);
                if (0 <= tmp) {
                    dp[i][j] = std::max(dp[i][j], dp[i-1][k] + tmp);
                }
            }
        }
    }

