#define MAX_N (100)
#define MAX_T (200)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, ts[MAX_N], vs[MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    scanf("%d", &ts[i]);
  }
  for (int i = 0; i < N; i++) {
    scanf("%d", &vs[i]);
  }

  // calculate accumulated time
  int taccs[MAX_N + 1];
  taccs[0] = 0;
  for (int i = 0; i < N; i++) {
    taccs[i + 1] = taccs[i] + ts[i];
  }

  // calculate the maximum velocity for each time step
  int max_velocity[MAX_N * MAX_T + 1];
  int segment = N - 1;
  max_velocity[taccs[N]] = 0;
  for (int t = taccs[N] - 1; t >= 0; t--) {
    int limit_velocity;
    if (t == taccs[segment]) {
      limit_velocity = min(vs[segment], vs[segment - 1]);
      segment--;
    } else {
      limit_velocity = vs[segment];
    }
    max_velocity[t] = min(max_velocity[t + 1] + 1, limit_velocity);
  }

  // determine the velocity for each time step
  int velocities[MAX_N * MAX_T + 1], count = 0;
  velocities[0] = 0;
  for (int t = 1; t <= taccs[N]; t++) {
    velocities[t] = min(velocities[t - 1] + 1, max_velocity[t]);
    if (velocities[t - 1] + 1 == max_velocity[t - 1] &&
        velocities[t - 1] == max_velocity[t]) {
      count++;
    }
  }

  for (int t = 0; t <= taccs[N]; t++) {
    printf("t = %5d, v = %5d, max_v = %5d\n", t, velocities[t],
           max_velocity[t]);
  }

  // calculate the distance traveled
  double d = 0;
  for (int t = 1; t <= taccs[N]; t++) {
    d += velocities[t] + velocities[t - 1];
  }
  d /= 2.0;
  d += 0.25 * count;
  printf("%lf\n", d);

  return 0;
}

