int main(){
  int n;
  int used_count = 0;
  cin >> n;
  for (int i=0;i<n;i++) {
    cin >> t[i];
  }
  for (int i=0;i<n;i++) {
    cin >> v[i];
  }
  limit[0] = 0;
  for (int i=1;i<n;i++) {
    limit[i] = v[i-1] < v[i]?v[i-1]:v[i];
  }
  limit[n] = 0;
  for (int i=0;i<=n;i++) {
    used[i] = false;
  }
  while (used_count <= n) {
    int min_idx;
    int min_limit = 1000;
    for (int i=0;i<=n;i++) {
      if (limit[i] < min_limit && !used[i]) {
	min_idx = i;
      }
    }
    if (min_idx > 0) {
      int new_left = limit[min_idx] + t[min_idx - 1];
      limit[min_idx - 1] = limit[min_idx - 1] < new_left?limit[min_idx - 1]:new_left;
    }
    if (min_idx < n) {
      int new_right = limit[min_idx] + t[min_idx];
      limit[min_idx + 1] = limit[min_idx + 1] < new_right?limit[min_idx + 1]:new_right;
    }
    used[min_idx] = true;
    used_count++;
  }
  double max_dist = 0.0;
  for (int i=0;i<n;i++) {
    double t_ceiling_1, t_ceiling_2, t_cross, v_cross;
    t_ceiling_1 = (double)(v[i] - limit[i]);
    t_ceiling_2 = (double)(v[i] - limit[i+1]);
    t_cross = (double)(t[i] + limit[i+1] - limit[i])/2;
    v_cross = t_cross + (double)(limit[i]);
    if (v_cross <= v[i]) {
      max_dist += (double)((limit[i]+v_cross)*t_cross)/2 + (double)((limit[i+1]+v_cross)*(t[i]-t_cross))/2;
    } else {
      max_dist += (double)((limit[i]+v[i]) * t_ceiling_1)/2
	+ double(v[i] * (t[i] - t_ceiling_1 - t_ceiling_2))
	+ (double)((limit[i+1]+v[i]) * t_ceiling_2)/2;
    }
  }
  cout << max_dist << endl;
}

