double dp[MAX_NV * MAX_T][MAX_NV * 2];
int sum;
double memo(int pos, int v){
    if (v < 0){
      return -INF;
    }

    if (v > limits[pos]){
      return -INF;
    }
    if (pos >= sum){
      if (v == 0){
        return 0;
      }
      return -INF;
    }

    double &res = dp[pos][v];
    if (res > -2 * INF){
      return res;
    }
    res = -INF;
    res = max(res, memo(pos + 1, v) + v);
    if (v < limits[pos]){
      res = max(res, memo(pos + 1, v + 1) + v + 0.5);
    }

    res = max(res, memo(pos + 1, v - 1) + v - 0.5);
    return res;
}

int main() {
  cin >> N;
  T.resize(N);
  V.resize(N);
  for (int i = 0; i < N; i++){
    cin >> T[i];
    T[i] *= 2;
    sum += T[i];
  }
  for (int i = 0; i < N; i++){
    cin >> V[i];
    V[i] *= 2;
  }
  for (int i = 1; i < N; i++){
    T[i] += T[i - 1];
  }
  int pre = 0;
  for (int i = 0; i < N; i++){
    for (int j = pre; j <= T[i]; j++){
      limits[j] = V[i];
    }
    pre = T[i];
  }
  // double dp[MAX_NV * MAX_T][MAX_NV * 2];
  for (int i = 0; i < MAX_NV * MAX_T; i++){
    for (int j = 0; j < MAX_NV * 2; j++){
      dp[i][j] = -2 * INF;
    }
  }
  double result = (double)memo(0, 0) / 4;
  if (result <= 0){
    result = 0;
  }
  printf("%.20lf\n", result);
  return 0;
}

