constexpr i64 SCALE = 10000;

i64 N;
vector<i64> T;
vector<i64> V;

void solve() {
    ALL(transform_self, T, [](i64 t) { return SCALE*t; });
    ALL(transform_self, V, [](i64 v) { return SCALE*v; });

    i64 sum = 0;
    for(i64 i = N-1; i >= 0; --i) {
        i64 v  = V[i];
        i64 vl = i == 0   ? 0 : V[i-1];
        i64 vr = i == N-1 ? 0 : V[i+1];

        i64 cur = 0;
        REP(t, T[i]) {
            i64 w = min({
                v,
                vl + t,
                vr + (T[i]-t),
            });
            cur += w;
        }
        sum += cur;
    }

    f64 ans = static_cast<f64>(sum) / static_cast<f64>(ipow(SCALE,2));

    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {
    RD(N);
    RD(T, N);
    RD(V, N);

    solve();

    EXIT();
}

