			ta = MIN(ta, taa);
			tb = MIN(tb, tbb);
		}

		if (tflat < T[i] && tflat < ta)
		{
			if (tb < T[i]) // /-\'
			{
				len += v * (tflat - tc) + (tflat - tc) * (tflat - tc) / 2.0;
				v = v + (tflat - tc);

				len += v * (tb - tflat);

				v = v - (T[i] - tb);
				len += v * (T[i] - tb) + (T[i] - tb) * (T[i] - tb) / 2.0;
			}
