int n;
int t[N], l[N], m[N], r[N];
double ans;
int cur;

double f(int i) {
    double lm = l[i];
    double rm = r[i];
    double ll = min(l[i], r[i]), rr = m[i];
    double t1, t2;
    while (ll + 1e-6 < rr) {
        double mm = (ll + rr) / 2;
        t1 = abs(mm - l[i]);
        t2 = abs(mm - r[i]);
        if (t1 + t2 <= t[i]) {
            ll = mm;
        } else {
            rr = mm - 1e-6;
        }
    }
    // cout << lm << ' ' << m[i] << ' ' << rm << " # " << ll << endl;
    t1 = abs(ll - lm);
    t2 = abs(ll - rm);
    return (t[i] - t1 - t2) * ll + (ll + l[i]) / 2 * t1 + (ll + r[i]) / 2 * t2;
}

