    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> t[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> m[i];
        l[i] = r[i] = m[i];
    }
    r[n - 1] = 0;
    for (int i = n - 1; i >= 0; --i) {
