double get_s(double lx, double ly, double rx, double ry, double upper_y){

    // lxを0に合わせる
    rx -= lx;
    lx = 0;

    double cx = (ry + rx - ly) / 2.0;
    double cy = (ry + rx + ly) / 2.0;

    // cout << lx << " " << ly << endl;
    // cout << rx << " " << ry << endl;
    // cout << cx << " " << cy << endl;

    double s = (ly + cy) * cx / 2.0 + (cy + ry) * (rx - cx) / 2.0;


    // upper_yと交わる場合、引く
    if(cy > upper_y){
        double x1 = upper_y - ly;
        double x2 = ry + rx - upper_y;
        s -= (x2 - x1) * (cy - upper_y) / 2.0;
    }


    return s;
}

double rec(int pos, int src){
    if(used[pos][src]) return dp[pos][src];
    double res = 0;
    if(pos == N){
        res = 0;
    }
    else{
        // cout << pos << " " << src << endl;
        // [0, V[pos]]
        for(int dst = 0; dst <= min(V[pos], V[pos+1]); dst++){
            int time = T[pos];
            if(abs(src - dst) > time) continue;
            double s = get_s(0, src, time, dst, V[pos]);
            res = max(res, s + rec(pos + 1, dst));
        }
    }
    used[pos][src] = true;
    return dp[pos][src] = res;
}


