int getlimit(double time) {
	double sum = 0;
	time /= 2;
	for (int i = 0; i < N; i++) {
		sum += t[i];
		if (time <= sum) {
			if (time == sum) {
				if(i != N - 1)
					return min(s[i], s[i + 1]);
				return s[i];
			}
			return s[i];
		}
	}
	return s[N - 1];
}

