            if(tmp<=t[i]){
                ans += ((double)v[i]+before)*((double)v[i]-before)*0.5;
                ans += ((double)t[i]-tmp)*v[i];
                ans += abs((double)v[i+1]+v[i])*abs(v[i+1]-v[i])*0.5;
            }
            else {
                double x = ((double)t[i]+v[i+1]-before)*0.5;
