			for ( const int k : { j - 1, j, j + 1 } )
			{
				const double dv = abs( j - k ) / 2.;
				const double dx = min( j, k ) / 4. + dv / 4.;

				if ( 0 <= k && k <= min( limits[i], limits[ i + 1 ] ) * 2 )
				{
					chmax( dp[ i + 1 ][k], dp[i][j] + dx );
				}
			}
		}
	}

	cout << dp[L][0] << endl;

	return 0;
}

