#include <iomanip>

using namespace std;

typedef long long ll;

void go() {
	int n;
	cin >> n;
	vector<int> t(n),v(n);
	int T = 0;
	for(int i = 0; i < n; i++) {cin >> t[i];T+=t[i];}
	for(int i = 0; i < n; i++) cin >> v[i];
	vector<int> L(T+1,1e9),R(T+1,0),F(T+1,0);
	vector<int> RR,FF;
	F[0] = F[T] = 1;
	int k = 0;
	for(int i = 0; i < n; i++) {
		L[k] = min(L[k],v[i]);
		for(int j = 1; j <= t[i]; j++) {
			L[k+j] = v[i];
		}
		k+=t[i];
	}
	L[0] = L[T] = 1;

	for(int i = 1; i <= 100; i++) {
		RR = R; FF = F;
		for(int j = 1; j < T; j++) if(FF[j]==0) {
			int x = i;
			if(x>L[j]) {
				x = L[j];
				F[j] = 1;
			}
			if(FF[j-1] && x>RR[j-1]+1) {
				x = RR[j-1]+1;
				F[j] = 1;
			}
			if(FF[j+1] && x>RR[j+1]+1) {
				x = RR[j+1]+1;
				F[j] = 1;
			}
			R[j] = x;
		}
	}

	double res = 0;
	for(int j = 1; j <= T; j++) {
		double x = 0.5*(R[j]+R[j-1]);
		if(R[j]==R[j-1] && R[j]<L[j-1]) x += 0.25;
		res += x;
	}
	// for(int j = 1; j <= T; j++) cout << "(" << j<< "," << R[j] << ") "; cout << endl;
	cout << fixed << res << endl;


}

int main() {
	go();
	return 0;
}

