#define REPP(I, A, B) for (int I = (A); I < (B); ++I)
template <class T>
void mii(T& x,T y){
  if(x>y)x=y;
}

// $ g++ -std=c++14 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
//const int MAX_N=2*100*200+1;
const int SIZE=1e6+10;
int t[SIZE],v[SIZE],a[SIZE],m;
int N;
const int MOD = 1e9+7;
void solve() {
  REP(i,SIZE) a[i]=MOD;
  int it=0;
  a[0]=0;
  REP(i,N) {
    mii(a[it],v[i]);
    REP(j,t[i]) {
      it++;
      mii(a[it],v[i]);
    }
  }
  mii(a[it],0);
  REPP(i,1,it+1) {
//    if(i==140)cout<<a[i]<<","<<a[i-1]+1<<endl;
    mii(a[i],a[i-1]+1);
  }
  for(int i=it-1; i>=0; i--) {
//    if(i==140)cout<<a[i]<<","<<a[i+1]+1<<endl;
    mii(a[i],a[i+1]+1);
  }
//  cout<<T<<endl;
//  REPE(i,T) cout<<i<<","<<a[i]<<endl;
  LL an=0;
  //REP(i,T) res+=(a[i]+a[i+1])*0.5;
  REP(i,it) an+=(a[i]+a[i+1]);
  double ans=an*0.125;
  cout<<ans<<endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  cin>>N;
  REP(i,N) cin>>t[i],t[i]*=2;
  REP(i,N) cin>>v[i],v[i]*=2;
  solve();
  return 0;
}

#include <iostream>
