using namespace std;

int main(){
    int N;
    cin >> N;

    vector<int> t(N+3);
    t[0]=0;
    t[1]=0;
    int s;
    for(int i=0; i<N; i++){
        cin >> s;
        t[i+2]=t[i+1]+s*2;
    }
    t[N+2]=t[N+1];

    vector<int> v(N+2);
    v[0]=0;
    for(int i=0; i<N; i++){
        cin >> v[i+1];
    }
    v[N+1]=0;

    vector<float> limit(t[N+2]*2+1,100000);
    for(int i=0; i<N+2; i++){
        int t_0=t[i];
        int t_1=t[i+1];
        float vel = v[i];
        for(int j=t_0; j<=t_1; j++){
            if (limit[j]>vel){
                limit[j]=vel;
            }
        }
        for(int j=0; j<t[N+2]+1; j++){
            if (t_0>0){
                if (limit[t_0]>vel){
                    limit[t_0]=vel;
                }
                t_0--;
            }
            if(t_1<t[N+2]){
                if(limit[t_1]>vel){
                    limit[t_1]=vel;
                }
                t_1++;
            }
            vel+=0.5;
        }
    }
    float tmp=0;
    vector<float> velocity(t[N+2]*2+1,0);
    for(int i=0; i<t[N+2]; i++){
        if(limit[i]>tmp){
            tmp+=0.5;
            velocity[i]=tmp;
        }else if(limit[i]<tmp){
            tmp-=0.5;
            velocity[i]=tmp;
        }else{
            velocity[i]=tmp;
        }
    }
    float ans=0.0;
    for(int i=0; i<t[N+2]; i++){
        ans+=(limit[i]+limit[i+1]);
    }
    cout << ans/2*0.5 << endl;
}

