const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}


double solve(double s, double g, double mv, double t){
  double rs = mv - s;
  double rg = t - (mv - g);
  double res = 0;
  if(rs <= rg){
    res = mv * t;
    res -= rs * rs / 2;
    res -= (t - rg) * (t - rg) / 2;
  }else{
    double x, y;
    x = (-s + g + t) / 2;
    y = (s + g + t) / 2;
    res = y * t;
    res -= x * x / 2;
    res -= (t - x) * (t - x) / 2;
  }
  return res;
}


