using namespace std;

typedef long long ll;

int main()
{
    ll N;
    cin >> N;
    vector<double> t(N), v(N);
    REP(i, N) cin >> t[i];
    REP(i, N) cin >> v[i];

    vector<double> tA(N), tE(N), tD(N), vStart(N), vEndMax(N);
    vEndMax[N - 1] = 0;
    for (int i = N - 2; i >= 0; --i)
    {
        vEndMax[i] = min(v[i], min(v[i + 1], vEndMax[i + 1] + t[i + 1]));
    }

    vStart[0] = 0;
    REP(i, N)
    {
        double vMax;
        for (int j = 0; 0.5 * j <= t[i]; ++j)
        {
            double ta = 0.5 * j;   
            double vT = vStart[i] + ta;
            if (vT < v[i] && vT < vEndMax[i] + (t[i] - ta))
            {
                continue;
            }
            else
            {
                vMax = vT;
                break;
            }
        }
        tA[i] = vMax > vStart[i] ? (vMax - vStart[i]) : 0;
        tD[i] = vMax > vEndMax[i] ? (vMax - vEndMax[i]) : 0;
        tE[i] = t[i] - tA[i] - tD[i];
        if (i + 1 < N) vStart[i + 1] = min(vMax, vEndMax[i]);
    }
    double ans = 0;
    REP(i, N)
    {
        ans += (vStart[i] + vStart[i] + tA[i]) * tA[i] / 2.0;
        ans += (vStart[i] + tA[i]) * tE[i];
        ans += (vStart[i] + tA[i] + vStart[i] + tA[i] - tD[i]) * tD[i] / 2.0;
    }

    cout << fixed;
    cout << setprecision(10) << ans << endl;
}

