    in(n);

    auto t = vin<int>(n);
    auto v = vin<int>(n);

    vector<int> ts(n + 1);
    for (int i : rep(0, n)) {
        ts[i + 1] = ts[i] + t[i];
    }

    double ans = 0.0;
    double prev_y = 0.0;

    for (int i : rep(1, 2 * ts[n] + 1)) {
        double x = i / 2.0;

        double y = 1e10;

        y = min(y, f(x, 0, 0, 0));

        for (int j : rep(0, n)) {
            y = min(y, f(x, v[j], ts[j], ts[j + 1]));
        }

        y = min(y, f(x, 0, ts[n], ts[n]));

        ans += (y + prev_y) / 4.0;

        prev_y = y;
    }

    out(ans);
}

