    double left,right,ans=0;

    for (int i=1;i<=n;i++){
        left=min(v[i-1],v[i]);
        right=min(v[i],v[i+1]);

        if (right>left) {
            double x = (t[i] + abs(right - left)) / 2;
            double y = (t[i] - abs(right - left)) / 2;
            //if (x<0||y<0) cout<<left<<" "<<right<<" "<<t[i]<<endl;
            ans += x * x / 2 + y * y / 2 + y * (right - left) + t[i] * left;
            if (h[i] < left + x) {
                double l = x + left - h[i];
                ans -= l * l;
            }
        }else{

            double y = (t[i] + abs(right - left)) / 2;
            double x = (t[i] - abs(right - left)) / 2;
