    if(sta + jikan <=end){
        next[0]=sta + jikan;
        return (2 * sta + jikan) * jikan /float(2);
    }
    next[0]=end;
    if(ma - sta + ma - end <= jikan) return ma * jikan - (ma - sta) * (ma -sta) /float(2) - (ma - end) * (ma - end )/float(2);
