        }
        ld dist = 0;
        dist += (t[i] - up - down) * v[i];
        dist += (up * past) + 0.5 * up * up;
        dist += (down * min(v[i], past + up)) + (-0.5 * down * down);
        ans += dist;
        past = min({v[i], t[i] + past, v[i + 1]});
        //cerr << "dist : " << dist << " up : " << up << " down : " << down << " past : " << past << endl;
    }
    cout << fixed <<setprecision(12) << ans << endl; 
