int main()
{
	std::ios::sync_with_stdio(false);

	int N;
	cin >> N;
	vector<int> t(N + 1), v(N + 1);
	for (int i = 0; i < N; ++i) {
		cin >> t[i];
	}
	t[N] = 1;
	for (int i = 0; i < N; ++i) {
		cin >> v[i];
	}
	v[N] = 0;
	vector<int> accT(N + 1);
	accT[0] = t[0];
	for (int i = 1; i <= N; ++i) {
		accT[i] = accT[i - 1] + t[i];
	}

	int state = -999;
	int lastState = -999;
	double lastT = 0;
	double lastVel = 0;
	double result = 0.0;
	double vel = 0.0;
	double time = 0.0;
	for (int i = 0.0; i < N + 1; ++i) { // 区間ごと
		for (double j = 0; j < t[i]; j = j + 0.5) { // 区間内で１s刻み
			if (i == N) {
				// 動きが変化したタイミングで面積加算
				if (state < 0 || state > 0) {
					// 上昇・下降の面積
					double x1 = (accT[N - 1] - lastT) * (accT[N - 1] - lastT) / 2.0;
					double x2 = (accT[N - 1] - lastT) * min(vel, lastVel);
					result += x1 + x2;
				} else {
					// 停滞の面積
					double x = (time - lastT) * lastVel;
					result += x;
				}
				break;
			}
			if (accT[i] - time <= vel - v[i + 1] + 0.5 + 0.0000001) {
				// 停滞か下がらなければならない
				if (accT[i] - time <= vel - v[i + 1] + 0.0000001) {
					// 下がらなければならない
					state = -1;
				} else {
					// 停滞できる
					state = 0;
				}
			} else {
				// 次の状態だけ見れば上昇できるが
				if (vel < v[i] - 0.0000001) {
					// 上限未満なので上昇できる
					state = 1;
				} else {
					// 上限に当たって上昇できない
					state = 0;
				}
			}
			if (lastState > -99 && lastState != state || i == N) {
				// 動きが変化したタイミングで面積加算
				if (lastState < 0 || lastState > 0) {
					// 上昇・下降の面積
					double x1 = (time - lastT) * (time - lastT) / 2.0;
					double x2 = (time - lastT) * min(vel, lastVel);
					result += x1 + x2;
				} else {
					// 停滞の面積
					double x = (time - lastT) * lastVel;
					result += x;
				}
				lastT = time;
				lastVel = vel;
			}

			if (state < 0) {
				vel -= 0.5;
			} else if (state > 0) {
				vel += 0.5;
			}
			lastState = state;
			time = time + 0.5;
		}

	}

	cout << std::setprecision(18) << result << endl;

	getchar();
	getchar();
}

