class Section {
public:
	double firstSpeed, lastSpeed;
	double time;
};


signed main() {
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		int tim;
		cin >> tim;
		if(i == 0)t[i] = tim;
		else t[i] = t[i - 1] + tim;
	}
	for (int i = 0; i < N; i++) {
		int vel;
		cin >> vel;
		v[i] = vel;
	}
	double nowTime = 0.0;
	double nowVel = 0;
	for (int i = 0; i < N; i++) {
		int time = t[i];

		while (nowTime < time) {
			double rest = time - nowTime;
			if (v[i] < v[i + 1] + rest) {
				//今の速度が今の区間の最高速より小さかったら
				if (nowVel < v[i]) {
					//加速
					nowVel += 0.5;
					accel[(int)(nowTime*2)] = 1;
					velocity[(int)(nowTime * 2)] = nowVel;
				}
				else {
					accel[(int)(nowTime * 2)] = 0;
					velocity[(int)(nowTime * 2)] = nowVel;
				}
			}
			else if (nowVel < v[i+1]+rest) {
				//加速
				nowVel += 0.5;
				accel[(int)(nowTime * 2)] = 1;
				velocity[(int)(nowTime * 2)] = nowVel;
			}
			else {
				//減速フェーズ
				nowVel -= 0.5;
				velocity[(int)(nowTime * 2)] = nowVel;
				accel[(int)(nowTime * 2)] = -1;
			}
			nowTime+=0.5;
		}
	}
	double ans = 0;
	for (int i = 0; i < 200001; i++) {
		ans += velocity[i]/2;
		if (accel[i] == 1) ans += 0.25;
		if (accel[i] == -1) ans -= 0.25;
	}
	cout << std::setprecision(20)<<ans << "\n";
	return 0;
}

