  if (v > f[idx]) return (-1e20);
  if (idx == t) return (0.0);
  if (memo[idx][(int)(v * 2)]++) return (dp[idx][(int)(v * 2)]);
  double res = -1e20;
  res = max({res, rec(idx + 1, v) + v * 0.5, rec(idx + 1, v + 0.5) + v * 0.5 + 0.5 * 0.5 / 2,
             rec(idx + 1, v - 0.5) + v * 0.5 - 0.5 * 0.5 / 2});
  dp[idx][(int)(v * 2)] = res;

  return res;
}

