int main(){
  int N;cin>>N;
  vector <int> t;t.resize(N+2,0);
  vector <int> v;v.resize(N+2,0);
  for(int i=1;i<=N;i++) {cin>>t[i]; t[i] += t[i-1];}//時間軸がわかりやすくなるように累積和をとる
  for(int i=1;i<=N;i++) cin>>v[i];

   vector <int> original_v = v;

  v[0] = 0;v[N] = 0;
  t[N+1] += t[N];


  vector <int> v1 = v;// 初めから
  vector <int> v2 = v;//終わりから

//０s目からなるべく速度制約を守るように加速した時の最高速度
  for(int i=1;i<=N;i++){
    v1[i] =  v1[i-1] + t[i] - t[i-1];
    v1[i] = min(v1[i] , original_v[i+1]);
    v1[i] = min(v1[i],original_v[i]);
  }

//最後に速度がぜろになるように減速できるような最大の速度
  for(int i=1;i<=N;i++){
    v2[N+1-i] =v2[N+2-i] + (t[N+2-i] - t[N+1-i]);
    v2[N+1-i] = min(v2[N+1-i],original_v[N+1-i]);
    v2[N+1-i] = min(v2[N+1-i],original_v[N+2-i]);
  }

  //左から考えても右から考えても確かに実現できるような速度の中で最大のもの
  //初めからt[i]sのちの速度はv[i]になるようにできるしそれより大きいもので実現できるものはないので初めからt[i]sごは速度v[i]として良い
  for(int i=0;i<=N;i++) v[i] = min(v1[i],v2[i]);


  double ans = 0;


// 面積の算出
  for(int i=1;i<=N;i++){
    double vp = (double) original_v[i];
    double allTime = (double)(t[i]-t[i-1]);
    double vf= (double) v[i-1];
    double vl = (double) v[i];
    if(vf > vl) swap(vf,vl);
    double def = abs(vl - vf);
    ans += def * (vf + vl) / double(2.00);
    double remainTime = allTime - def;

    if(remainTime ==0) {continue;}
    if(remainTime <0)cout<<'#'<<endl;
    ans += remainTime * vl;
    double vm = vl + (remainTime/double(2.00));

    if(vm <= vp) {ans += remainTime * (vm-vl) / double(2.00);}
    else {
          ans -= remainTime * vl;
          ans += (vl + vp) * (vp-vl);
          ans += vp * (remainTime + vl - vp +vl - vp);

          }

  }

cout<<ans<<endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;
#define rep(i,n) for(int i = 0; i < ((int)(n)); i++)   // 0-indexed昇順

int main() {
    int N; cin >> N;
    int tmax = 0;
    vector T(N+1,0);
    fprintf(stderr, "T: ");
    for (int i = 1; i <= N; i++) {
        int t; cin >> t;
        tmax += t;
        T.at(i) = tmax;
        fprintf(stderr, "%3d ", T[i]);
    }
    fprintf(stderr, "\n");
    vector V(N+1,0);
    using pi = pair<int,int>;
    priority_queue<pi, vector<pi>, greater<pi>> Q;
    map<int,int> M;
    rep(i,N) {
        cin >> V.at(i);
        if (i && V[i] - V[i-1] < 0) { // if it needs break
            int y = V[i] + T[i];
            M[y] = i; // Overwrite: want maximum i
        }
    }
    V[N] = 0;
    M[T[N]] = N;
    for (auto [y, i] : M) Q.push({y,i});

    int cbi = Q.top().second; Q.pop(); // current break index
    int ci = 0; // current index
    int cl = V[0]; // cuurent speed limit
    double v = 0; // current velocity
    double D = 0; // distance
    double x = 0; // current time (not delta)
    while (x < tmax) {
        double t; // t is absolute time
        if (cl > v) {
            double tf = x + cl - v; // time to change to fixed velocity
            t = (T[cbi] + V[cbi] - v + x) / 2; // time to hit while accelerating
            if (t <= T[ci + 1] && t < tf && cl >= (t - x) + v) { // HIT! Break!!
                fprintf(stderr, "After accelerating to %.2f, ", v + (t - x));
                fprintf(stderr, "Breaking at %f\n", t);
                // calc at
                // at += t - x; // D will be updated later
                D += (t-x) * (v + (v + (t-x))) / 2;
                D += (T[cbi]-t) * (v + t - x + V[cbi]) / 2;
                // forward to T[cbi]
                x = T[cbi];
                v = V[cbi];
                fprintf(stderr, "V down to %f at %f\n", v, x);
                cl = v;
                ci = cbi;
                // Update cbi
                while (!Q.empty() && cbi <= ci) cbi = Q.top().second, Q.pop();
                continue;
            }
            // accelerate to limit
            // at += tf - x; // D will be updated later
            if (tf >= T[ci + 1]) { // Can't to accelerate to the limit
                tf = T[ci + 1];
                D += (tf - x) * (v + v + tf - x);
                ci++;
                v = v + tf - x;
                x = T[ci];
                cl = V[ci];
                continue;
            }
            D += (tf - x) * (v + cl) / 2;
            x = tf;
            v = cl;
            fprintf(stderr, "Accelerating V up to %f at %f\n", v, x);
            // else fall through
        }
        t = T[cbi] + V[cbi] - v; // When to HIT if go with fixed velocity
        if (x <= t && t <= T[ci + 1]) { // Hit! Break!!
            fprintf(stderr, "Breaking at %f\n", t);
            D += (t - x) * v;
            D += (T[cbi] - t) * (v + V[cbi]) / 2;
            x = T[cbi];
            v = V[cbi];
            fprintf(stderr, "V down to %f at %f\n", v, x);
            cl = v;
            ci = cbi;
            while (!Q.empty() && cbi <= ci) cbi = Q.top().second, Q.pop();
            continue;
        } else { // Go!
            D += (T[++ci] - x) * v;
            x = T[ci];
            fprintf(stderr, "Go forward with velocity %f till %f\n", v, x);
            cl = V[ci];
        }
    }
    cout << fixed << setprecision(15);
    cout << D << endl;
}

