  for (int t = M - 1, ix = N - 1; t >= 0; --t) {
    if (ix > 0 and t < T[ix - 1]) {
      lim = L[--ix];
    }
    V2[t] = min(V2[t + 1] + 0.5, lim);
  }

  vector<double> V(M + 5);
  for (int t = 0; t <= M; ++t) {
    V[t] = min(V1[t], V2[t]);
  }

  double ans = 0;
  for (int t = 1; t <= M; ++t) {
    ans += (V[t - 1] + V[t]) / 2.0;
  }
  ans /= 2.0;
  printf("%.9f\n", ans);
  return 0;
}

