	max_v[0] = 0;
	max_v[2 * T] = 0;

	for (int32_t i = 1; i < 2 * T + 1; i++)
		max_v[i] = min(max_v[i], max_v[i - 1] + 0.5);
	for (int32_t i = 2 * T - 1; i >= 0 ; i--)
		max_v[i] = min(max_v[i], max_v[i + 1] + 0.5);

	double res = 0;
	for (int32_t i = 0; i < 2 * T; i++) {
		res += min(max_v[i], max_v[i + 1]) * 0.5;
		if (max_v[i] != max_v[i + 1])
			res += 0.5 * 0.5 / 2;
	}

	printf("%.17f\n", res);

	return 0;
}

