int N;
int t[110], v[110];
double res;
int am[110];
int n2;
int idx[110];
queue<int> q;
int val[110];

bool cmp(int aa, int bb)
{
	if(am[aa] < am[bb])
		return true;
	else
		return false;
}

void solve()
{
	int i;
	n2 = N+1;
	//for(i=N; i>=1; i--){
	//	t[i] = t[i-1];
	//}
	//t[0] = 0;
	am[0] = 0;
	am[N] = 0;
	for(i=1; i<N; i++){
		if(v[i-1]<v[i])	
			am[i] = v[i-1];
		else
			am[i] = v[i];
	}
	for(i=0; i<n2; i++)
		idx[i] = i;
	sort(idx, idx+n2, cmp);
	for(i=0; i<n2; i++){
		q.push(idx[i]);
		val[idx[i]] = am[idx[i]];
	}
	int ii;
	int tmp;
	while(!q.empty() ){
		ii = q.front() ;
		q.pop() ;
		if(ii==0){
			tmp = v[0];
			if(v[0]>t[0])
				tmp = t[0];
			if(tmp < val[1]){
				val[1] = tmp;
				q.push(1) ;
			}
		}
		else if(ii==n2-1){
			tmp = v[ii-1];
			if(v[ii-1]>t[ii-1])
				tmp = t[ii-1];
			if(tmp < val[n2-2]){
				val[n2-2] = tmp;
				q.push(n2-2);
			}
		}
		else{
			if(val[ii-1]>val[ii]){
				if(val[ii]+t[ii-1] >= v[ii-1]){
					tmp = v[ii-1];
				}
				else{
					tmp = val[ii] + t[ii-1];
				}
				if(tmp < val[ii-1]){
					val[ii-1] = tmp;
					q.push(ii-1);
				}
			}
			if(val[ii+1]>val[ii]){
				if(val[ii]+t[ii] >= v[ii]){
					tmp = v[ii];
				}
				else{
					tmp = val[ii] + t[ii];
				}
				if(tmp < val[ii+1]){
					val[ii+1] = tmp;
					q.push(ii+1);
				}
			}
		}
	}
	res = 0;
	double v1, v2;
	double tt;//double
	double d, d2;
	for(i=0; i<N; i++){
		v1 = min(val[i], val[i+1]);
		v2 = max(val[i], val[i+1]);
		tt = t[i];
		d = v2 + (tt-(v2-v1))/2;
		if(d > v[i]){
			d2 = (v[i]+v2)*(v[i]-v2)/2 + (v[i]+v1)*(v[i]-v1)/2 
					+ (tt-(v[i]-v2)-(v[i]-v1) )*v[i];
		}
		else{
			d2 = (d+v2)*(d-v2)/2 + (d+v1)*(d-v1)/2;
		}
		res += d2;
	}
	printf("%.6f\n", res);
}

