# include <bits/stdc++.h>
using namespace std;
# define eps 1e-8
# define INF 1e20
# define pi  acos(-1.0)
# define MX  105
struct Node
{
    double t,v;
    double ev; //从终点的最大速度
}seg[MX];

int n;
double spd, ans;

void gogo(int x)
{
    double l=0, r=seg[x].t;
    double res = 0;
    while (l<r-eps) // <
    {
        double mid = (l+r)/2;
        if (mid + spd > seg[x].v-eps)
        {
            if ((seg[x].v - seg[x+1].ev) + mid < seg[x].t+eps)
            {
                res = mid;
                l = mid;
            }
            else r = mid;
        }
        else
        {
            if (mid + spd - (seg[x].t-mid) - seg[x+1].ev < -eps) //<=
            {
                res = mid;
                l = mid;
            }
            else r = mid;
        }
    }

    double jia, yun, jian;
    if (spd + res < seg[x].v)
    {
        jia = res;
        yun = 0;
        jian = seg[x].t - jia;
    }
    else
    {
        jia = seg[x].v - spd;
        yun = res - jia;
        jian = seg[x].t - jia - yun;
    }
    ans += 1.0/2.0*jia*jia + spd * jia;
    ans += yun * seg[x].v;

    if (res+spd < seg[x].v)
    {
        ans += -1.0/2.0*jian*jian +  (spd+jia) * jian;
        spd = spd + jia - jian;
    }
    else
    {
        ans += -1.0/2.0*jian*jian +  seg[x].v * jian;
        spd = seg[x].v - jian;
    }

}

int main()
{
    scanf("%d",&n);
    for (int i=1;i<=n;i++)
        scanf("%lf",&seg[i].t);
    for (int i=1;i<=n;i++)
        scanf("%lf",&seg[i].v);
    spd=0.0;
    for (int i=n;i>=1;i--)
    {
        if (spd+seg[i].t < seg[i].v+eps) //<=
            spd += seg[i].t;
        else
            spd = seg[i].v;
        seg[i].ev = spd;
    }
    ans = 0;
