						ans += (double)koux*(2*a[i]+koux)/2.0 + (double)(t[i]-koux)*(2*b[i]+t[i]-koux)/2.0;
					}
				}
			}
		}
	}
	//cout << ans << endl;
	printf("%.8f\n", ans);
	return 0;
}

