	for (int i = 0; i < num; i++)scanf("%d", &tim[i]);
	for (int i = 0; i < num; i++)scanf("%d", &ve[i]);
	int now = 0;
	maxi[0] = 0;
	for (int i = 0; i < num; i++)
	{
		now = min(now + tim[i], ve[i]);
		maxi[i + 1] = now;
	}
	now = 0;
	maxi[num] = 0;
	for (int i = num - 1; i >= 0; i--)
	{
		now = min(now + tim[i], ve[i]);
		maxi[i] = min(maxi[i], now);
