		double m = (maxi[i] + z)*(z - maxi[i]) / 2 + (maxi[i + 1] + z)*(z - maxi[i + 1]) / 2;
		if (z < ve[i])ans += m;
		else ans += m - (z - ve[i])*(z - ve[i]);
	}
	printf("%lf\n", ans);
