  return 0;
}

#include <iostream>
#include <iomanip>
#include <algorithm>
#include <vector>

using namespace std;

int t[100];
int v[100];
int endV[100];
int startV[100];
int tStart[100];
int tEnd[100];

vector<pair<double, double>> solutions;

double solve(double a0, double b0, double a1, double b1)
{
    int da = a0 - a1;
    int db = b0 - b1;
    return -(double)db / da;
}

void divide(double st, double et, double a0, double b0, double a1, double b1)
{
    if (a0 == a1)
    {
        throw runtime_error("a0 and a1 must be different.");
    }
    if (a0 < a1)
    {
        divide(st, et, a1, b1, a0, b0);
        return;
    }

    double t = et - st;
    double solution = solve(a0, b0, a1, b1);
    if (solution <= 0)
    {
        solutions.push_back(make_pair(et, b1 + a1 * t));
    }
    else if (solution >= t)
    {
        solutions.push_back(make_pair(et, b0 + a0 * t));
    }
    else
    {
        solutions.push_back(make_pair(st + solution, b0 + a0 * solution));
        solutions.push_back(make_pair(et, b1 + a1 * t));
    }
}

int main()
{
    int N;

    cin >> N;
    for (int i = 0; i < N; i++)
    {
        cin >> t[i];
    }
    for (int i = 0; i < N; i++)
    {
        cin >> v[i];
    }

    for (int i = N - 1; i >= 0; i--)
    {
        if (i == N - 1)
        {
            endV[i] = 0;
        }
        endV[i] = min(v[i + 1], endV[i + 1] + t[i + 1]);
    }

    for (int i = 0; i < N; i++)
    {
        if (i == 0)
        {
            startV[i] = 0;
        }
        startV[i] = min(v[i - 1], startV[i - 1] + t[i - 1]);
    }

    for (int i = 0; i < N; i++)
    {
        if (i == 0)
        {
            tStart[i] = 0;
            tEnd[i] = t[i];
            continue;
        }
        tStart[i] = tEnd[i - 1];
        tEnd[i] = tStart[i] + t[i];
    }

    solutions.push_back(make_pair(0, 0));

    for (int i = 0; i < N; i++)
    {
        double solution = solve(0, v[i], 1, startV[i]);

        if (solution <= 0)
        {
            divide(tStart[i], tEnd[i], 0, v[i], -1, endV[i] + t[i]);
        }
        else if (solution >= t[i])
        {
            divide(tStart[i], tEnd[i], 1, startV[i], -1, endV[i] + t[i]);
        }
        else
        {
            divide(tStart[i], tStart[i] + solution, 1, startV[i], -1, endV[i] + t[i]);
            divide(tStart[i] + solution, tEnd[i], 0, v[i], -1, endV[i] + t[i] - solution);
        }
    }

    double result = 0;
    for (int i = 0; i < solutions.size() - 1; i++)
    {
        double h = solutions[i + 1].second + solutions[i].second;
        double w = solutions[i + 1].first - solutions[i].first;
        double area = h * w / 2;
        result += area;
    }

    cout << fixed << result << endl;

    return 0;
}

