	}
	for(int i=0;i<n;i++)cin>>v[i];
	int k=2*time[n-1]+1;
	double f[n+2][k];
	for(int i=0;i<n+2;i++){
		int left,right,ve;
		if(i==n){
			left=right=ve=0;
		}else if(i==n+1){
			left=right=time[n-1];;
			ve=0;
