          bool good = true;
          // check next points
          for (int k=i+1; k<n+1; k++){
              double dep, diff;
              if (k == n){
                  dep = -mid;
                  diff = diffsum[k]-diffsum[i];
              }else{
                  dep = v[k]-mid;
                  double idist = diffsum[i];
                  double kdist = diffsum[k];
                  diff = kdist-idist;
              }
              double slope = dep/diff;
              if (slope < -1){
                  //cout << mid << " " << slope << endl;
                  good = false;
                  break;
              }

          }
          for (int k=i-2; k>=-1; k--){
              double dep, diff;

              if (k == -1){
                  dep = -mid;
                  diff = -diffsum[i];
              }else{
                  dep = v[k]-mid;
                  double idist = diffsum[i];
                  double kdist = diffsum[k];
                  diff = kdist-idist;
              }
              double slope = dep/diff;
              if (slope > 1){

                  good = false;
                  break;
              }

          }

          if (good){
              l = mid;
              lastgood = mid;

          }else{
              r = mid;
          }
      }

      realmax[i] = min(lastgood, (double)v[i-1]);
  }
  double sum = 0;
  for (int i=1; i<n+1; i++){
      double back = realmax[i-1];
      double now = realmax[i];
      double yint1 = yint(1, diffsum[i-1], back);
      double yint2 = yint(-1, diffsum[i], now);
      //cout << diffsum[i] << endl;
      double interceptx = intx(1, -1, yint1, yint2);
      double intercepty = interceptx+yint1;
      double width1 = interceptx-diffsum[i-1];
      double width2 = diffsum[i]-interceptx;
      double height1 = intercepty-realmax[i-1];
      double height2 = intercepty-realmax[i];
      double x1 = xint2(1, yint1, v[i-1]);
      double x2 = xint2(-1, yint2, v[i-1]);
      double smallwidth = max(x2-x1, 0.0);
      double smallheight = max(intercepty-v[i-1], 0.0);

      sum += width1*height1/2+width1*realmax[i-1];
      sum += width2*height2/2+width2*realmax[i];
      sum -= smallwidth*smallheight/2;
  }
  cout << sum;
  return 0; 
}

