	vector<int> L(T+1,1e9),R(T+1,0),F(T+1,0);
	vector<int> RR,FF;
	F[0] = F[T] = 1;
	int k = 0;
	for(int i = 0; i < n; i++) {
		L[k] = min(L[k],v[i]);
		for(int j = 1; j <= t[i]; j++) {
			L[k+j] = v[i];
		}
		k+=t[i];
	}
