	for(int i = 1; i <= 101; i++) {
		RR = R; FF = F;
		for(int j = 1; j < T; j++) {
			int x = i;
			if(x>=L[j]) {
				x = L[j];
				F[j] = 1;
			}
			if(FF[j-1] && x>=RR[j-1]+1) {
				x = RR[j-1]+1;
				F[j] = 1;
			}
			if(FF[j+1] && x>=RR[j+1]+1) {
				x = RR[j+1]+1;
				F[j] = 1;
			}
			R[j] = x;
		}
	}

	double res = 0;
	for(int j = 1; j <= T; j++) {
		double x = 0.5*(R[j]+R[j-1]);
