const int N = 205;
int t[N], v[N];

void solve() {
	int n;
    sc(n);
    fr(i, 1, n) {
        sc(t[i]);
    }
    fr(i, 1, n) {
        sc(v[i]);
    }
    f80 ans = 0;
    fr(i, 1, n) {
        int tp = 0;
        int z1 = 0;
        fr(j, 1, i) {
            int vc = min(v[j - 1], v[j]);
            z1 = max(z1, tp - vc);
            tp += t[j];
        }
        int z2 = 1e9;
        fr(j, i + 1, n + 1) {
            int vc = min(v[j - 1], v[j]);
            z2 = min(z2, tp + vc);
            tp += v[j];
        }
        tp = 0;
        fr(j, 1, i - 1) {
            tp += t[j];
        }
        f80 x = (z1 + z2) / 2.0;
        if(x > tp + t[i] || x < tp) continue;
        f80 y = z2 - x;
        f80 x1, x2, ar;
        if(y > v[i]) {
            x1 = x - (y - v[i]);
            x2 = x + (y - v[i]);
        }
        else {
            x1 = x2 = x;
        }
        f80 pr = ans;
        ar = (x1 * x1 - tp * tp) / 2 - z1 * (x1 - tp);
        ans += ar;
        tp += t[i];
        ar = z2 * (tp - x2) - (tp * tp - x2 * x2) / 2;
        ans += ar;
        ans += v[i] * (x2 - x1);
        debug(ans - pr);
    }
    cout << setprecision(10) << fixed << ans;
}

