int cur;

double f(int i) {
    double lm = l[i];
    double rm = r[i];
    double ll = max(l[i], r[i]), rr = m[i];
    double t1, t2;
    while (ll + 1e-8 < rr) {
        double mm = (ll + rr) / 2;
        t1 = abs(mm - lm);
        t2 = abs(mm - rm);
        if (t1 + t2 <= t[i]) {
            ll = mm;
        } else {
            rr = mm - 1e-8;
        }
    }
    // cout << lm << ' ' << m[i] << ' ' << rm << " # " << ll << endl;
    t1 = abs(ll - lm);
    t2 = abs(ll - rm);
    return (t[i] - t1 - t2) * ll + (ll + l[i]) / 2 * t1 + (ll + r[i]) / 2 * t2;
}

