  for(int i = 0; i < N; i++) std::cin >> va[i];

  std::vector<int> t_arr(N);
  std::unordered_map<int, int> tv_map, tl_map;
  int t_total = 0;
  tl_map[0] = 0;
  for(int i = 0; i < N; i++){
    int t=ta[i], v=va[i];
