// Main Code
ll func(ll left, ll mx, ll right, ll t) {
    left *= 2; mx *= 2; right *= 2; t *= 2;
    vector<ll> speed(t + 1);
    rep(i, t + 1) speed[i] = min({left + i, mx, right + (t - i)});
    ll res = 0;
    rep(i, t) res += speed[i] + speed[i + 1];
    return res;
}

void solve() {
    int n;
    cin >> n;
    vector<ll> t(n), v(n);
    rep(i, n) cin >> t[i];
    rep(i, n) cin >> v[i];
    vector<ll> left(n, 0), right(n, 0);
    for (int i = 1; i < n; ++i) left[i] = min(left[i - 1] + t[i - 1], v[i - 1]);
    for (int i = n - 2; i >= 0; --i) right[i] = min(right[i + 1] + t[i + 1], v[i + 1]);
    ll ans = 0;
    rep(i, n) ans += func(left[i], v[i], right[i], t[i]);
    cout << ans / 8. << "\n";
    return;
}

