bool speedUp(int idx, double sp, int n, vector<double>& t, vector<double>& v){
	range(i,idx,n){
		if((sp + 0.5) - (t[idx] - 0.5) > v[idx + 1]){
			return false;
		}
	}
	return true;
}

bool keep(int idx, double sp, int n, vector<double>& t, vector<double>& v){
	range(i,idx,n){
		if(sp - (t[idx] - 0.5) > v[idx + 1]){
			return false;
		}
	}
	return true;
}

int main(){
	int n;
	cin >> n;

	vector<double> t(n), v(n);
	cin >> t >> v;
	v.emplace_back(0);

	int idx = 0;
	double ans = 0, sp = 0;
	while(idx < n){
		if(speedUp(idx, sp, n, t, v)){
			sp = min(v[idx], sp + 0.5);
		}else if(keep(idx, sp, n, t, v)){
			;
		}else{
			sp -= 0.5;
		}
		t[idx] -= 0.5;
		ans += sp;
		if(t[idx] == 0) idx++;
	}
	cout << fixed << setprecision(10) << ans / 2 << endl;
}

