void calc(int s,int g,int t,int lim){
    //show(s);show(g);show(t);show(lim);
    double m=0.0;
    if((lim-s)+(lim-g)>t){//何はともあれlimまで加速できない場合
        double y = (s+t+g)/2.0;
        double mt=y-s;
        m+=(y-s)*mt/2 + s*mt;
        m+=(y-g)*(t-mt)/2 + g*mt;
    }else{
        double m1=lim-s;
        double m2=lim-g;
        //show(m1);show(m2);
        //真ん中
        m+=lim*(t-m2-m1);
        //加速
        m+=m1*s + m1*m1/2;
        //減速
        m+=m2*g + m2*m2/2;
    }
    //show(m);
    ans+=m;
}

