    vector<ll> VV(N + 1);
    VV[0] = VV[N] = 0;
    rep(i, 1, N){
        VV[i] = min(TT[i - 1], TT[N - 1] - TT[i - 1]);
        VV[i] = min(VV[i], min(V[i - 1], V[i]));
    }
    double ret = 0;
    rep(i, N){
        ret += calc(T[i], VV[i], VV[i + 1], V[i]);
    }

    output(ret, 10);

    return 0;
}

