            else v[j] = v_;
        }
        t_sum += t[i];
    }

    dp[1][1] = 0.5;
    if(t_sum == 1){
        cout << 0.25 << endl;
        return 0;
    }
    for(int i = 2; i <= t_sum; i++){
        for(int j = 0; j <= 100; j++){
            double l1, l2, l3;
            if(j-1 > 0 && dp[i-1][j-1] > 0.0001){
                l1 = dp[i-1][j-1] + (double)(2*j-1)/(double)2;
            }else{
                l1 = 0;
            }
            if(dp[i-1][j+1] > 0.0001 && j+1 <= 100){
                l3 = dp[i-1][j+1] + (double)(2*j+1)/(double)2;
            }else{
                l3 = 0;
            }
            if(j < v[i]){
                if(dp[i-1][j] > 0.0001){
                    l2 = dp[i-1][j] + (double)((double)2*j+(double)0.5)/(double)2;
                }else{
                    l2 = 0;
                }
                if(i == t_sum || j != 0)dp[i][j] = max(l1, max(l2, l3));
            }else if(j == v[i]){
                if(dp[i-1][j] > 0.0001 && j == v[i-1]){
                    l2 = dp[i-1][j] + (double)j;
                }else if(dp[i-1][j] > 0.0001 && j < v[i-1]){
                    l2 = dp[i-1][j] + (double)(2*j+(double)0.5)/(double)2;
                }else{
                    l2 = 0;
                }
                if(i == t_sum || j != 0)dp[i][j] = max(l1, max(l2, l3));
            }
        }
    }
    std::cout << std::fixed;
    std::cout << std::setprecision(3) << dp[t_sum][0] << endl;
