vector<double> makeTable(int n, int l, int r, double v, double a)
{
	vector<double> table(n, v);

	for(int i=0; i<n; i++){
		if(i < l)
			table[i] = v + a*(l - i);
		else if(i > r)
			table[i] = v + a*(i - r);
	}

	return table;
}

