using namespace::std;

void solve(){
	int N;
	cin >> N;
	vector<double> T(N+1),V(N+1);
	for(int i=0;i<N;++i){
		cin >> T[i];
	}
	for(int i=0;i<N;++i){
		cin >> V[i];
	}
	T[N] = 0;
	V[N] = 0;

	for(int i=N-1;i>=0;--i){
		V[i] = min(V[i],V[i+1]+T[i]);
	}
	double ans = 0.0;
	double v = 0.0;
	for(int i=0;i<N;++i){
		if( V[i] <= V[i+1] ){
			double h = V[i]-v;
			if( h <= T[i] ){
				ans += (double)((T[i]*2-h)*h)/2;
				ans += v*T[i];
			}else{
				ans += (double)((v*2+T[i])*T[i])/2;
			}
			v = min((double)V[i],v+T[i]);
		}else{
			if( v+T[i] <= V[i+1] ){
				ans += (double)(T[i]*T[i])/2;
				ans += v*T[i];
				v = v + T[i];
			}else{
				double T1,T2;
				T1 = V[i]-v;
				T2 = T[i] - (V[i]-V[i+1]);
				if( T1 <= T2 ){
					ans += (double)((v*2+T1)*T1)/2;
					ans += (T2-T1)*V[i];
					ans += (double)(V[i]+V[i+1])*(T[i]-T2)/2;
					v = V[i+1];
				}else{
					double Tcen = (V[i+1]-v+T[i])/2;
					ans += (double)(v*2+Tcen)*Tcen/2;
					ans += (double)(v+Tcen+V[i+1])*(T[i]-Tcen)/2;
					v = V[i+1];
				}
			}
		}
	}
	cout << ans << endl;
}

