	for (int i = 0; i < N; i++) {
		int tim;
		cin >> tim;
		t.push_back(tim);
	}

	tsum.push_back(t[0]);
	for (int i = 1; i < N; i++) {
		tsum.push_back(tsum[i - 1] + t[i]);
	}

	v.push_back(0.0);
	for (int i = 0; i < N; i++) {
		int vel;
		cin >> vel;
