			v.push_back(vel);
			vels.push_back(vector<double>(tsum.back()*2+1, 0.0));
		}
	}

	v.pop_back();
	v.push_back(0.0);
	vels.push_back(vector<double>(tsum.back() * 2 + 1, 0.0));

	for (int time : t) {
		if (time * 2 + 1 >= v.size()) break;
		v[time * 2] = min(v[time * 2], v[time * 2+1]);
	}

	//各vについて各地点での最小速度を求める
	for (int i = 0; i < (int)tsum.back()*2+1; i++) {
		vels[i];
		for (int j = 0; j + i < (int)tsum.back()*2+1; j++) {
			vels[i][i + j] = v[i] + 0.5*j;
		}

		for (int j = 0; j + i >= 0; j--) {
			vels[i][i + j] = v[i] - 0.5*j;
		}
	}

	for (int i = 0; i < (int)tsum.back() * 2+1; i++) {
		//時間ごとに最小値を求める
		double tmp = 1145141919.0;
		for (vector<double> nowv : vels) {

			if (nowv[i] < tmp) tmp = nowv[i];
		}
		vans.push_back(tmp);

	}

	double ans = 0.0;
	for (int i = 0; i < (int)vans.size()-1; i++) {
		ans += (vans[i] + vans[i + 1])*0.5*0.5;
	}
	cout << ans << "\n";

	return 0;
}

