	}
	if (sp > lim[ti - 1])return -inf;
	if (memo[ti][sp] != -1) { return memo[ti][sp]; }
	LL res = dp(ti - 1, sp) + sp + sp;
	{ res = std::max(res, dp(ti - 1, sp - 1) + sp + (sp - 1)); }
	if(sp+1<=lim[ti-1]){ res = std::max(res, dp(ti - 1, sp + 1) + sp + (sp + 1)); }
	return memo[ti][sp] = res;
}

