        if(i == 0) {
            point[i].side_speed[0] = 0;
        }

        point[i+1].side_speed[0] = v;
    }
    point[N].side_speed[1] = 0;

    for(int i=0;i<point.size();i++) {
        point[i].id = i;
        point[i].visited[0] = false;
        point[i].visited[1] = false;
        point[i].speed_max = min(point[i].side_speed[1], point[i].side_speed[0]);
        if(i==0) {
            point[i].next[0] = 0;
            point[i].next[1] = &point[i+1];
        } else if(i == (point.size()-1)) {
            point[i].next[0] = &point[i-1];
            point[i].next[1] = 0;
        } else {
            point[i].next[0] = &point[i-1];
            point[i].next[1] = &point[i+1];
        }
    }

    // 両端とtの境目にポイントがあるとすると
    // 一番低いところから隣のノードまで加速,等速を行えば良い
    // 右向きの探索なら加速、左向きなら減速

    sort(point.begin(), point.end());
    for(int i=0;i<point.size();i++) {
        for(int j=LEFT;j<NEXTMAX;j++) { 
        // パターンは以下の５通りを左と右でそれぞれ行う
        // 等速 辺のspeed == speed == 次のspeed
        // 加速継続 : 横 <= (次のspeed-speed) && 辺が次のspeed
        // 加速、等速 : 横 > (次のspeed -speed) && 辺が次のspeed
        // 加速、等速、減速 辺のspeed != 次のspeed 
        //  && ((辺のspeed -speed) + (辺のspeed -次のspeed)) < 横
        // 加速、減速 辺のspeed != 次のspeed && (辺-cur) + (辺-next) >= 横

        point[i].visited[j] = true;
        if(!point[i].speed) {
            point[i].speed = point[i].speed_max;
        }
        if(!point[i].next[j]) continue;
        if(point[i].next[j]->visited[1]) continue;

        if((point[i].speed == point[i].next[j]->speed_max)
            && (point[i].speed == point[i].side_speed[j])) {
            // 等速
            distance += (point[i].speed * point[i].side[j]);
        } else if((point[i].side[j] <= (point[i].next[j]->speed_max - point[i].speed))
                && (point[i].next[j]->speed_max > point[i].speed)) {
            // 加速のみ
            distance += ((double)(point[i].side[j] * point[i].side[j])) / (double)2;

            // 次の節の制限!= 
        } else if((point[i].side[j] > (point[i].next[j]->speed_max - point[i].speed))
                && (point[i].next[j]->speed_max == point[i].side_speed[j])) {
            // 加速+等速
            distance += (((double)((point[i].next[j]->speed_max - point[i].speed)
                             * (point[i].next[j]->speed_max - point[i].speed)))/2) // 開始三角
                        + (double)((point[i].next[j]->speed_max - point[i].speed) * point[i].speed) // 開始下
                        + ((point[i].side[j] - (point[i].next[j]->speed_max - point[i].speed))
                            * point[i].side_speed[j]);
        } else if((point[i].side[j] > (point[i].next[j]->speed_max - point[i].speed))
                    && (point[i].next[j]->speed_max != point[i].side_speed[j])
                    && (((point[i].side_speed[j] - point[i].speed)
                        + (point[i].side_speed[j] - point[i].next[j]->speed_max))  
                        < point[i].side[j])) {
                    // sortしてあるので-は考慮不要 
            // 加速、等速、減速
            distance += ((((double)((point[i].side_speed[j] - point[i].speed)
                            * (point[i].side_speed[j] - point[i].speed)))/(double)2)  // 開始側三角
                        + ((point[i].side_speed[j] - point[i].speed) * point[i].speed) // 開始側下
                        + (((double)((point[i].next[j]->speed_max - point[i].side_speed[j])
                            * (point[i].next[j]->speed_max - point[i].side_speed[j])))/(double)2) // 終点側三角
                        + ((point[i].side_speed[j] - point[i].next[j]->speed_max) * point[i].next[j]->speed_max) //終点側下
                        + ((point[i].side[j] - (point[i].side_speed[j] - point[i].speed)
                                            - (point[i].side_speed[j] - point[i].next[j]->speed_max))
                                        * point[i].side_speed[j])); // 真ん中
        } else {
            // 加速、減速         
            // 始点0 終点side としたとき a + b = side, b- a = 次のspeed - 今のspeed
            // b = 次sp - sp + a, a + (次sp - sp + a) = side ,a = (side - (次sp - sp)) / 2
            double a = ((double)(point[i].side[j] - (point[i].next[j]->speed - point[i].speed)))/(double)2;
            double b = (double)point[i].side[j] - a;
            distance += ((((a * a) / 2) + ((b * b) / 2)) // 三角部分
                        + (a * point[i].speed) + (b * point[i].next[j]->speed));

        }
    }}

    cout << distance << "\n";
    return 0;
}

