double calcDistance(int fs, int es, int et, int mv) {
    /*
    dump(fs);
    dump(es);
    dump(et);
    dump(mv);
    */
    const double diff = (double)et;
    int fpo = mv - fs, spo = es + diff - mv;
    double po = 0.5 * ((double)es - (double)fs + diff);
    double ret = 0;
    if (fpo <= spo && ((double)fs + (double)fs + po) >= (double)mv) {
        ret += 0.5 * fpo * (mv + fs);
        ret += (spo - fpo) * mv;
        ret += 0.5 * (diff - spo) * (mv + es);
    } else {
        ret += 0.5 * po * ((double)fs + (double)fs + po);
        ret += 0.5 * (diff - po) * ((double)es + (double)es + (diff - po));
    }
    cerr << "pos: " << fpo << " " << spo << " " << po << endl;
    return ret;
}

void resolve() {
    int n;
    cin >> n;
    VI t(n), v(n);
    REP(i,0,n) cin >> t[i];
    REP(i,0,n) cin >> v[i];

    VI ml(n);
    ml[0] = min(t[0], v[0]);
    ml[0] = min(ml[0], v[1]);
    REP(i,1,n-1) {
        // ml[i-1] = min(ml[i-1], v[i]);
        ml[i] = min(ml[i-1] + t[i], v[i]);
        REP(j,0,i) {
            /*
            if (ml[i-1-j] - t[i-j] > ml[i-j]) {
                ml[i-1-j] = t[i-j] + ml[i-j];
            }
            */
            ml[i-1-j] = min(ml[i-1-j], t[i-j] + ml[i-j], v[i]);
        }
    }
    ml[n-1] = 0;
    int i = n - 1;
    REP(j,0,i) {
        if (ml[i-1-j] - t[i-j] > ml[i-j]) {
            ml[i-1-j] = t[i-j] + ml[i-j];
        }
    }
    REP(i,0,n) cout << i << ": " << ml[i] << endl;
    double ans = calcDistance(0,ml[0],t[0],v[0]);
    REP(i,1,n) ans += calcDistance(ml[i-1],ml[i],t[i],v[i]);
    cout << (double)ans << endl;

    cerr << "ml0: " << calcDistance(0,ml[0],t[0],v[0]) << endl;
    REP(i,1,n) cerr << "ml" << i << ": " << calcDistance(ml[i-1],ml[i],t[i],v[i]) << endl;
}

int main() {
    resolve();

    return 0;
}

