    int addr=0;
    for(int i=1;i<=N;i++){
        for(int j=0;j<=t[i]*2;j++){
            vmax[addr]=min(vmax[addr],min(v[i],v[i+1]+0.5*(t[i]*2.0-j)));
            addr++;
        }addr--;
    }

    double x=0.0,v0=0.0;
    for(addr=0;addr<tt*2;addr++){
        double v1=min(v0+0.5,vmax[addr+1]);
        x+=0.5*(v0+v1)*0.5;
        v0=v1;
    }

    cout << fixed << x << endl;

    delete[] vmax;

    return 0;
}

