int N;
int t[110], v[110];
int l[110], r[110];

double f(int idx, double x) {
  if (x < l[idx]) return v[idx] + (l[idx] - x);
  if (x > r[idx]) return v[idx] + (x - r[idx]);
  return v[idx];
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N;
  for (int i = 0; i < N; i++) {
    cin >> t[i];
  }
  for (int i = 0; i < N; i++) {
    cin >> v[i];
  }
  int sum = 0;
  for (int i = 0; i < N; i++) {
    l[i] = sum;
    sum += t[i];
    r[i] = sum;
  }
  v[N] = v[N + 1] = 0;
  l[N] = r[N] = 0;
  l[N + 1] = r[N + 1] = sum;
  double ans = 0;
  for (int i = 0; i < sum * 2; i++) {
    double x = i / 2.0;
    double a = 110, b = 110;
    for (int j = 0; j < N + 2; j++) {
      a = min(a, f(j, x));
      b = min(b, f(j, x + 0.5));
    }
    ans += (a + b) * 0.25;
  }
  cout << ans << endl;

  return 0;
}

