int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N;
  cin >> N;
  vll t(N+2), v(N+2);
  t[0] = 0; v[0] = 0;
  REP(i, N) cin >> t[i+1];
  REP(i, N) cin >> v[i+1];
  t[N+1] = 0; v[N+1] = 0;

  ll t_sum=0;
  REP(i, N+2) t_sum += t[i];

  vll v_max(t_sum+1, 0);

  ll t_now=0;
  REP(i, N+1){
    REP(j, t[i]-1){
      v_max[t_now] = v[i];
      t_now++;
    }
    v_max[t_now] = min(v[i], v[i+1]);
    t_now++;
  }

  vll v_limit_backward(t_sum+1);
  ll v_now=0;
  for(ll t_=t_sum; t_>=0; --t_){
    if(v_now<v_max[t_]){
      v_now++;
    }else if(v_now>v_max[t_]){
      v_now = v_max[t_];
    }
    v_limit_backward[t_] = v_now;
  }

  v_now = 0;
  double ans=0.0;
  for(ll t_=0; t_<t_sum; ++t_){
    ll v_tmp = v_now;
    if(v_now < v_limit_backward[t_] && v_now == v_limit_backward[t_+1]) ans += 0.25;
    if(v_now < v_limit_backward[t_+1]) v_now++;
    else if(v_now > v_limit_backward[t_+1]) v_now = v_limit_backward[t_+1];
    ans += ((double)(v_now+v_tmp))/2.0;
  }

  cout << ans << "\n";

  return 0;
}

