  }
  funcs.push_back(F{0, ts[0], +1, 0});
  funcs.push_back(F{N > 1 ? ts[N - 2] : 0, ts.back(), -1, calc_b(-1, 0, ts.back())});
}

double calc_v(double t) {
  double ret = inf;
  for (auto f: funcs) {
    if (t < f.t1 || f.t2 < t) continue;
    minimize(ret, f.a * t + f.b);
  }
  return ret;
}

