float f(int t, int vs, int ve, int vmax)
{
	float ret = 0.0;
	int v = vs;
	For(i, 1, t + 1){
		int vv;
		vv = min(vs + i, ve + t - i);
		vv = min(vv, vmax);
		ret += float(vv + v) / 2.0;
		if(vv == v && v < vmax) ret += 0.25;
		v = vv;
	}
	return ret;
}

