template<typename T, typename U>
std::enable_if_t<std::rank<T>::value == 0> fill_all(T& arr, const U& v) {
	arr = v;
}
template<typename ARR, typename U>
std::enable_if_t<std::rank<ARR>::value != 0> fill_all(ARR& arr, const U& v) {
	for (auto& i : arr) {
		fill_all(i, v);
	}
}
int32_t N;
int32_t speed_max[20000];
int32_t speed_Vmax[20000];
int32_t T[200];
int32_t V_max[200];

int main()
{
	fill_all(speed_Vmax, 20000);
	fill_all(speed_max, 20000);
	using std::endl;
	in.sync_with_stdio(false);
	out.sync_with_stdio(false);
	in.tie(nullptr);
	out.tie(nullptr);

	in >> N;
	for (int32_t i = 0; i < N; i++)
	{
		in >> T[i];
	}
	for (int32_t i = 0; i < N; i++)
	{
		in >> V_max[i];
	}

	//加速制限
	int32_t time = 0;
	for (int32_t i = 0; i < N; i++)
	{
		for (int32_t t = 0; t <= T[i]; ++t,++time)
		{
			speed_Vmax[time] = std::min(speed_Vmax[time], V_max[i]);
			if (time == 0) {
				speed_max[time] = 0;
				continue;
			}
			speed_max[time] = std::min({ speed_max[time], V_max[i], speed_max[time - 1] + 1 });
		}
		--time;
	}
	int32_t time_max = time;
	//減速制限
	for (int32_t i = N-1; i >= 0; --i)
	{
		for (int32_t t = 0; t <= T[i]; t++, --time)
		{
			if (time == time_max) {
				speed_max[time] = 0;
				continue;
			}
			speed_max[time] = std::min(speed_max[time], speed_max[time+1] + 1);
		}
		++time;
	}

	//移動距離
	int32_t dist4 = 0;
	for (int32_t i = 0; i <= time_max-1; i++)
	{
		dist4 += std::min(speed_max[i], speed_max[i + 1]) * 4;
		if (speed_max[i] == speed_max[i + 1]) {
			if (speed_max[i] < std::max(speed_Vmax[i], speed_Vmax[i+1])) {
				dist4 += 1;
			}
		}
		else {
			dist4 += 2;
		}
	}


	out << std::fixed << std::setprecision(88) << (double)(dist4) / 4.0 << endl;

	return 0;
}
