    A a;B b;C c;D d;
    F2() { a = 0, b = 0, c = 0, d = 0; }
    F2(A a, B b, C c, D d) : a(a), b(b), c(c), d(d) {}
    bool operator<(const F2 &r) const { return a != r.a ? a < r.a : b != r.b ? b < r.b : c != r.c ? c < r.c : d < r.d;    /*    return a != r.a ? a > r.a : b != r.b ? b > r.b : c != r.c ? c > r.c : d > r.d;*/    }
