#define MAX_N (100)
#define MAX_T (200)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, ts[MAX_N], vs[MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    scanf("%d", &ts[i]);
  }
  for (int i = 0; i < N; i++) {
    scanf("%d", &vs[i]);
  }

  // calculate accumulated time
  int taccs[MAX_N + 1];
  taccs[0] = 0;
  for (int i = 0; i < N; i++) {
    taccs[i + 1] = taccs[i] + ts[i];
  }

  // calculate the maximum velocity for each time step
  int max_velocities[MAX_N * MAX_T + 1], limit_velocities[MAX_N * MAX_T + 1];
  int segment = N - 1;
  max_velocities[taccs[N]] = 0;
  limit_velocities[taccs[N]] = vs[segment];
  for (int t = taccs[N] - 1; t >= 0; t--) {
    int limit_velocity;
    if (segment > 0 && t == taccs[segment]) {
      limit_velocity = min(vs[segment], vs[segment - 1]);
      segment--;
    } else {
      limit_velocity = vs[segment];
    }
    max_velocities[t] = min(max_velocities[t + 1] + 1, limit_velocity);
    limit_velocities[t] = limit_velocity;
  }

  // determine the velocity for each time step
  int velocities[MAX_N * MAX_T + 1], count = 0;
  velocities[0] = 0;
  for (int t = 1; t <= taccs[N]; t++) {
    velocities[t] = min(velocities[t - 1] + 1, max_velocities[t]);
  }

  // for (int t = 0; t <= taccs[N]; t++) {
  //   printf("t = %5d, v = %5d, max_v = %5d, limit_v = %d\n", t, velocities[t],
  //          max_velocities[t], limit_velocities[t]);
  // }

  // calculate the distance traveled
  double d = 0;
  for (int t = 1; t <= taccs[N]; t++) {
    d += velocities[t] + velocities[t - 1];
    if ((velocities[t - 1] == max_velocities[t - 1] - 1 &&
         velocities[t - 1] == max_velocities[t]) ||
        (velocities[t - 1] == max_velocities[t - 1] &&
         velocities[t] == max_velocities[t] && 
         velocities[t - 1] == velocities[t] && 
         velocities[t] < limit_velocities[t])) {
      // printf("invoked at t = %d\n", t);
      d += 0.5;  // because it gets divided by 2
    }
  }
  d *= 0.5;
  printf("%.5lf\n", d);

  return 0;
}

