int main() {
    int N;
    cin >> N;
    int T[N+2], accT[N+2], V[N+2], ti, vi, total_t = 0;
    T[0] = T[N+1] = 0;
    rep(i, N) cin >> ti, T[i+1] = ti, total_t += ti;
    accT[0] = T[0];
    for (int i=1; i<N+2; i++) accT[i] = accT[i-1] + T[i];
    V[0] = V[N+1] = 0;
    rep(i, N) cin >> vi, V[i+1] = vi;

    int Vmax[total_t] = {};
    bool limit[total_t] = {};

    Vmax[0] = 0;
    for (int i=1; i<N+2; i++) {
        int startT = accT[i-1], endT = accT[i];
        for (int t=startT+1; t<=endT; t++) {
            if (Vmax[t-1] < V[i]) Vmax[t] = Vmax[t-1] + 1;
            else Vmax[t] = Vmax[t-1];
            for (int j=i+1; j<N+2; j++) {
                Vmax[t] = min(Vmax[t], accT[j-1] - t + V[j]);
            }
            if (Vmax[t] < V[i]) limit[t] = false;
            else limit[t] = true;
        }
    }

    double ans = 0;
    rep(t, total_t) {
        ans += (((double) Vmax[t]) + ((double) Vmax[t+1]) ) / 2.0;
        if ((Vmax[t] == Vmax[t+1]) && (limit[t+1] == false)) ans += 0.25;
    }

    cout << ans << endl;

    return 0;
}

