  i32 *v = (i32 *) calloc (n, sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, v + i);
  }
  double ans = calc (t, v, n);
  printf ("%.7f\n", ans);
}

