	int liSecUse = 0;										// 現在速度を終了時の速度に合わせる時間
	int liSpdUD = siSpd;									// 加速＋減速部分用の初速度
	if (siSpd > liSpdEnd) {									// 最後に減速
		liSecUse = siSpd - liSpdEnd;							// 現在速度を終了時の速度に合わせる時間
		fAddLen((double)siSpd, -1, (double)liSecUse);			// 距離加算
	}
	else if (siSpd < liSpdEnd) {							// 最初に加速
		liSecUse = liSpdEnd - siSpd;							// 現在速度を終了時の速度に合わせる時間
		if (liSecUse > liSecLast) {								// 時間不足
			liSecUse = liSecLast;									// 全加速
			liSpdEnd = siSpd + liSecUse;							// 全加速後の速度
		}
		else {													// 時間内
			liSpdUD = siSpd + liSecUse;								// 加速＋減速部分用の初速度
		}
		fAddLen((double)siSpd, 1, (double)liSecUse);			// 距離加算
	}

	// 現在速度 - 更新
	siSpd = liSpdEnd;

	// 残り時間
	liSecLast -= liSecUse;
	if (liSecLast < 1) {									// なし
		return 0;
	}

	// 加速＋減速部分
	int liSecUD = (sz1Sct[piSNo].miSpd - liSpdUD) * 2;		// 加速＋減速時間
	if (liSecUD > 0) {										// あり

		// 残り時間をチェック
		if (liSecUD > liSecLast) {
			liSecUD = liSecLast;
		}

		// 加速部分
		double ldSec = (double)liSecUD / 2;					// 時間
		fAddLen((double)liSpdUD, 1, ldSec);					// 距離加算

		// 減速部分
		double ldSpd = (double)liSpdUD + ldSec;				// 速度
		fAddLen(ldSpd, -1, ldSec);							// 距離加算
	}

	// 残り時間
	liSecLast -= liSecUD;
	if (liSecLast < 1) {									// なし
		return 0;
	}

	// 最大速度部分
	fAddLen(sz1Sct[piSNo].miSpd, 0, (double)liSecLast);		// 距離加算

	return 0;
}

