    double sample[N+2];
    sample[N] = i;
    sample[N+1] = endtime-i;
    time = 0;
    for(int j = 0;j < N;j++){
      if(i < time) sample[j] = v[j]+(time-i);
      else if(time+t[j] < i) sample[j] = v[j]+(i-(time+t[j]));
      else sample[j] = v[j];
    time += t[j];
    }
    for(int j = 0;j < N+2;j++){
      if(speed[(int)(i*2)] > sample[j])
        speed[(int)(i*2)] = sample[j];
    }
  }

  for(int i = 0;i < 2*endtime;i++){
    ans += 0.25*(speed[i]+speed[i+1]);
  }

  printf("%lf\n",ans);
  return 0;
}

