int cantstop(int i, int tj, int cv) {
	cv -= t[i] - tj -1;
	for (i++; i < n; i++)
	{
		if (cv > v[i])
		{
			return 1;
		}
		cv -= t[i];
	}
	if (cv > v[n])
	{
		return 1;
	}
	return 0;
}
int main() {
	int cv = 0;
	double d = 0;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
