	for (int i = 0; i < n; i++) {
		scanf("%d", &v[i]);
	}
	v[n] = 0;
	for (int i = 0; i < n; i++) {
		for (int tj = 0; tj < t[i]; tj++)
		{
			if (cantstop(i, tj, cv))
			{
				cv--;
			}
			else if (cv < v[i])
			{
				cv++;
			}
			d += cv;
		}
	}
