class FastScanner {
    companion object {
        val input: InputStream = System.`in`
        val buffer = ByteArray(1024) { 0 }
        fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    var ptr = 0
    var buflen = 0
    private fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = input.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }

    private fun readByte(): Int = if (hasNextByte()) buffer[ptr++].toInt() else -1

    private fun skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
    }

    fun hasNext(): Boolean {
        skipUnprintable()
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextLong(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextDouble(): Double = next().toDouble()
}

fun main(args: Array<String>) {
    val n = readLine()!!.toInt()
    val tList = readLine()!!.split(' ').map(String::toInt)
    val vList = readLine()!!.split(' ').map(String::toInt)
    val startList = mutableListOf(0)
    (0..(n - 2)).forEach { startList.add(startList.last() + tList[it]) }
    val maxSpeed = mutableMapOf<Double, Double>()
    val totalTime = tList.sum().toDouble()
    var i = 0.0
    while (i <= totalTime) {
        maxSpeed[i] = i
        i += 0.5
    }
    i = totalTime
    while (i >= 0) {
        maxSpeed[i] = Math.min(totalTime - i, maxSpeed[i]!!)
        i -= 0.5
    }
    for (j in 0 until n) {
        val t = tList[j]
        val v = vList[j]
        val start = startList[j]
        i = 0.0
        while (i <= totalTime) {
            val curSpeed = if (i <= start) {
                v.toDouble() + (start - i)
            } else if (i >= start + t) {
                v.toDouble() + (i - (start + t))
            } else {
                v.toDouble()
            }
            maxSpeed[i] = Math.min(maxSpeed[i]!!, curSpeed)
            i += 0.5
        }
    }
    var ans = 0.0
    i = 0.0
    while (i < totalTime) {
        ans += (maxSpeed[i]!! + maxSpeed[i + 0.5]!!) * 0.5 * 0.5
        i += 0.5
    }
    println(ans)
}

