fun main(args: Array<String>) {
    PrintWriter(System.out).use { out ->
        solve(out)
        out.flush()
    }
}

fun solve(out: PrintWriter) {
    val n = readInteger()
    val tList = readIntegerList()
    val vList = readDoubleList()

    val times = tList.sum() * 2 + 1
    val maxVs = DoubleArray(times)
    var curT = 0
    for ((i, t) in tList.withIndex()) {
        for (j in 1..(2 * t)) {
            curT++
            maxVs[curT] = vList[i]
        }
    }
    maxVs[times - 1] = 0.0


    for (i in 0 until (times - 1)) {
        maxVs[i + 1] = Math.min(maxVs[i + 1], maxVs[i] + 0.5)
    }

    for (i in (times - 1) downTo 1) {
        maxVs[i - 1] = Math.min(maxVs[i - 1], maxVs[i] + 0.5)
    }

    var ans = 0.0
    var preV = maxVs.first()
    for (v in maxVs.drop(1)) {
        ans += (preV + v) / 4
        preV = v
    }
    println(ans)
}

