fun main(args: Array<String>) {
    val N = readLine()!!.toInt()
    val t = (listOf(0L) + readLine()!!.split(" ").map{it.toLong()} + listOf(0L)).toLongArray()
    val v = listOf(0L) + readLine()!!.split(" ").map{it.toLong()} + listOf(0L)

    for (i in 1 until t.size) {
        t[i] += t[i - 1]
    }

    var res = 0.0

    for (i in 1..N) {
        var l = 0L
        for (j in 1 .. i) {
            l = Math.min(l, v[j] - t[j - 1])
        }

        var r = 1e18.toLong()
        for (j in N + 1 downTo i) {
            r = Math.min(r, v[j] + t[j])
        }

        val x1 = (r - l) / 2.0
        val y1 = (r + l) / 2.0

        val list = ArrayList<Pair<Double, Double>>()

        list.add(Pair(t[i - 1].toDouble(), Math.min(l + t[i - 1], r - t[i - 1]).toDouble()))

        val x0 = v[i] - l
        if (t[i - 1] <= x0 && x0 <= t[i]) {
            list.add(Pair(x0.toDouble(), v[i].toDouble()))
        }

        if (t[i - 1] <= x1 && x1 <= t[i] && y1 <= v[i]) {
            list.add(Pair(x1, y1))
        }

        val x2 = r - v[i]
        if (t[i - 1] <= x2 && x2 <= t[i]) {
            list.add(Pair(x2.toDouble(), v[i].toDouble()))
        }

        list.add(Pair(t[i].toDouble(), Math.min(l + t[i], r - t[i]).toDouble()))

        for (j in 1 until list.size) {
            res += (list[j].second + list[j - 1].second) * (list[j].first - list[j - 1].first) / 2.0
        }
    }

    System.out.printf("%1.10f¥n")
}

