fun main(args: Array<String>) {
    val N = readLine()!!.toInt()
    val t = readLine()!!.split(" ").map { it.toInt() }
    val v = readLine()!!.split(" ").map { it.toDouble() }

    val T = t.sum()

    var now = 0
    val maxV = DoubleArray(2 * T + 1)
    // Initialize with v
    (0 until N).forEach {i ->
        (0 until t[i]).forEach { t ->
            val t1 = now + t * 2
            val t2 = now + t * 2 + 1
            maxV[t1] = Math.min(maxV[t1], v[i])
            maxV[t2] = Math.min(maxV[t2], v[i])
        }
        now = t[i] * 2
        maxV[now] = Math.min(maxV[now], v[i])
    }

    (0..2*T).forEach {
        maxV[it + 1] = Math.min(maxV[it + 1], maxV[it] + 0.5)
    }
    (2*T downTo 0).forEach {
        maxV[it + 1] = Math.min(maxV[it + 1], maxV[it] + 0.5)
    }

    var ans = 0.0
    (0..2*T).forEach { i ->
        ans += (maxV[i] + maxV[i + 1]) * 0.5 / 2.0
    }
    println(ans)
    return
}

