		}
		v[n] = 0;

		double ret = 0;
		double speed = 0;
		for (int i = 0; i < n; i++) {
			double retTime = t[i];
			while (true) {
				if (v[i + 1] == speed - retTime) {
					// speed down
					ret += -1 * retTime * retTime / 2 + retTime * speed;
					speed = speed - retTime;
					break;
				} else if (v[i] == speed) {
					double tmpTime = 0;
					if (speed <= v[i + 1]) {
						tmpTime = 0;
						ret += speed * (retTime - tmpTime);
						break;
					} else {
						tmpTime = speed - v[i + 1];
						ret += speed * (retTime - tmpTime);
					}
					retTime = tmpTime;
				} else {
					// speed up
					double tmpTime = Math.max(0, v[i] - speed);
					// speed up pause
					if (tmpTime - v[i + 1] + speed >= (retTime - v[i + 1] + speed) / 2) {
						tmpTime = retTime - ((retTime + speed) - v[i + 1]) / 2;
						ret += 0.5 * tmpTime * tmpTime + speed * tmpTime;
						retTime -= tmpTime;
						speed = speed + tmpTime;
						continue;
					}
					tmpTime = Math.min(retTime, tmpTime);
					ret += 0.5 * tmpTime * tmpTime + speed * tmpTime;
					retTime -= tmpTime;
					speed = speed + tmpTime;
					if (retTime == 0.0) {
						break;
					}
				}
			}
		}

		out.println(BigDecimal.valueOf(ret).toPlainString());
	}

