    static String INPUT = "";

    void solve() {
        int n = ni();
        int t[] = new int[n + 2];
        int v[] = new int[n + 2];
        for (int i = 0; i < n; ++i) t[i + 1] = ni();
        for (int i = 0; i < n; ++i) v[i + 1] = ni();
        for (int i = n; i > 0; --i) {
            v[i] = Math.min(v[i], v[i + 1] + t[i]);
        }
        for (int i = 1; i <= n; ++i) {
            v[i] = Math.min(v[i], v[i - 1] + t[i]);
        }
        double x = 0;
        for (int i = 0; i < n; ++i) {
            x += calc(Math.min(v[i], v[i + 1]), v[i + 2], t[i + 1], v[i + 1]);
        }
        out.println(x);
    }

    double calc(int s, int e, int t, int v) {
        double m = 0;
        if (e > v) e = v;
        for (int i = 0; i <= t * 2; ++i) {
            for (int j = i; j <= t * 2; ++j) {
                int r = j - i;
                int k = t * 2 - j;
                if ((v - s) * 2 < i) continue;
                if ((e - s) * 2 < i - k) continue;
                if (-s * 2 > i - k) continue;
                double b = i / 2.0;
                double p = 0;
                p += s * b + b * b / 2.0;
                p += (s + b) * (r / 2.0);
                b = k / 2.0;
                p += (s + i / 2.0 - k / 2.0) * b + b * b / 2.0;
                // tr(i, r, k, p, s * b + b * b / 2.0, (s + b) * (j / 2.0), e * b + b * b / 2.0);
                if (m < p) m = p;
            }
        }
        return m;
    }

