/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        DAtCoderExpress solver = new DAtCoderExpress();
        solver.solve(1, in, out);
        out.close();
    }

    static class DAtCoderExpress {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int n = in.ints(), sum = 0;
            int[] t = in.ints(n), v = in.ints(n);
            for (int i = 0; i < n; i++) {
                t[i] *= 2;
                v[i] *= 2;
                sum += t[i];
            }
            int[] a = new int[sum + 1];
            Arrays.fill(a, Integer.MAX_VALUE);
            a[0] = a[sum] = 0;

            // velocity limitation
            {
                int now = 0;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j <= t[i]; j++)
                        a[now + j] = Math.min(a[now + j], v[i]);
                    now += t[i];
                }
            }

            // left velocity angle limitation
            {
                for (int i = 1; i <= sum; i++)
                    a[i] = Math.min(a[i], a[i - 1] + 1);
            }

            // right velocity angle limitation
            {
                for (int i = sum - 1; i >= 0; i--)
                    a[i] = Math.min(a[i], a[i + 1] + 1);
            }

            long ans = 0;
            for (int i = 1; i < sum; i++) ans += a[i];
            out.ans(ans * 0.25, 12).ln();
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new OutputStreamWriter(new BufferedOutputStream(out), Charset.defaultCharset()));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(double x, int n) {
            if (!breaked) {
                print(' ');
            }
            if (x < 0) {
                print('-');
                x = -x;
            }
            x += Math.pow(10, -n) / 2;
            print(Long.toString((long) x)).print('.');
            x -= (long) x;
            for (int i = 0; i < n; i++) {
                x *= 10;
                print((char) ('0' + ((int) x)));
                x -= (int) x;
            }
            return this;
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public int[] ints(int length) {
            return IntStream.range(0, length).map(x -> ints()).toArray();
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

import static java.lang.Math.*;

public class Main {
    private static final double EPS = 1e-9;
    BufferedReader rd;

    Main() throws IOException {
        rd = new BufferedReader(new InputStreamReader(System.in));
        compute();
    }

    private void compute() throws IOException {
        int n = pint();
        int[] t = intarr();
        int[] p = intarr();

        double all = 0;
        for(int ts: t) {
            all += ts;
        }

        Node root = new Node();
        root.add(new Con(0, all/2, 0, 1));
        root.add(new Con(all/2, all, all/2, -1));
        double sum = 0;
        for(int i=0;i<n;i++) {
            Node node = new Node();
            node.addCon(0, sum, p[i] + sum, -1);
            node.addCon(sum, sum + t[i], p[i], 0);
            node.addCon(sum + t[i], all, p[i], 1);

            sum += t[i];

            root = merge(root, node);
        }

        double dist = 0;
        for(Con con: root.cons) {
            if(con.type == 0) {
                dist += con.v * con.time();
            } else {
                double b = min(con.v, con.last());
                double e = max(con.v, con.last());
                dist += acc(e) - acc(b);
            }
        }
        out(dist);
    }

    private double acc(double t) {
        return t * t / 2;
    }

    private class Node {
        List<Con> cons = new ArrayList<>();

        public void add(Con con) {
            cons.add(con);
        }


        public void addCon(double start, double end, double v, int type) {
            if(start + EPS < end) {
                cons.add(new Con(start, end, v, type));
            }
        }
    }

    private Node merge(Node a, Node b) {
        Node res = new Node();
        int i = 0;
        int j = 0;
        while(i < a.cons.size() && j < b.cons.size()) {
            Con ac = a.cons.get(i);
            Con bc = b.cons.get(j);
            double maxStart = max(ac.start, bc.start);
            double minEnd = min(ac.end, bc.end);
            if(maxStart < minEnd) {
                Con d = ac.slice(maxStart, minEnd);
                Con e = bc.slice(maxStart, minEnd);
                double p = d.crossPoint(e);
                if(p < 0) {
                    res.add(minCon(d,e));
                } else {
                    Con d1 = d.slice(maxStart, p);
                    Con d2 = d.slice(p, minEnd);
                    Con e1 = e.slice(maxStart, p);
                    Con e2 = e.slice(p, minEnd);

                    res.add(minCon(d1,e1));
                    res.add(minCon(d2,e2));
                }
                if(ac.end == bc.end) {
                    i++;
                    j++;
                } else if(ac.end == minEnd) {
                    i++;
                } else {
                    j++;
                }
            } else if(maxStart >= ac.end) {
                i++;
            } else {
                j++;
            }
        }
        if(i < a.cons.size()) {
            res.cons.addAll(a.cons.subList(i, a.cons.size()));
        }
        if(j < b.cons.size()) {
            res.cons.addAll(b.cons.subList(j, b.cons.size()));
        }
        return res;
    }

    private Con minCon(Con d, Con e) {
        boolean d1 = d.v <= e.v;
        boolean d2 = d.last() <= e.last();
        return d1 && d2 ? d : e;
    }

    private class Con {
        double start;
        double end;
        double v;
        int type;

        public Con(double start, double end, double v, int type) {
            this.start = start;
            this.end = end;
            this.v = v;
            this.type = type;
        }

        public Con slice(double maxStart, double minEnd) {
            if(type == 0) {
                return new Con(maxStart, minEnd, v, 0);
            } else if(type == 1) {
                return new Con(maxStart, minEnd, v + (maxStart - start), 1);
            }
            return new Con(maxStart, minEnd, v - (maxStart - start), -1);
        }

        public double crossPoint(Con other) {
            switch(type) {
                case 0:
                    switch(other.type) {
                        case 0:
                            return -1;
                        case -1:
                            if(v < other.v && last() > other.last()) {
                                return start + (other.v - v);
                            }
                            return -1;
                        case 1:
                            if(v > other.v && last() < other.last()) {
                                return start + (other.v - v);
                            }
                            return -1;
                    }
                case 1:
                    switch(other.type) {
                        case -1:
                            if(v < other.v && last() > other.last()) {
                                return (other.v - v) / 2 + start;
                            } else {
                                return -1;
                            }
                        case 0:
                            if(v < other.v && last() > other.last()) {
                                return other.v - v + start;
                            } else {
                                return -1;
                            }
                        case 1:
                            return -1;
                    }
                default:
                    if(other.type == -1) {
                        return -1;
                    }
                    return other.crossPoint(this);
            }
        }

        private double last() {
            if(type == 0) {
                return v;
            } else if(type == 1) {
                return v + (end - start);
            } else {
                return v - (end - start);
            }
        }

        public double time() {
            return end - start;
        }
    }

    private int pint() throws IOException {
        return pint(rd.readLine());
    }

    private int pint(String s) {
        return Integer.parseInt(s);
    }

    private int[] intarr() throws IOException {
        return intarr(rd.readLine());
    }

    private int[] intarr(String s) {
        String[] q = split(s);
        int n = q.length;
        int[] a = new int[n];
        for(int i=0;i<n;i++) {
            a[i] = Integer.parseInt(q[i]);
        }
        return a;
    }

    private String[] split(String s) {
        if(s == null) {
            return new String[0];
        }
        int n = s.length();
        int start = -1;
        int end = 0;
        int sp = 0;
        boolean lastWhitespace = true;
        for(int i=0;i<n;i++) {
            char c = s.charAt(i);
            if(isWhitespace(c)) {
                lastWhitespace = true;
            } else {
                if(lastWhitespace) {
                    sp++;
                }
                if(start == -1) {
                    start = i;
                }
                end = i;
                lastWhitespace = false;
            }
        }
        if(start == -1) {
            return new String[0];
        }
        String[] res = new String[sp];
        int last = start;
        int x = 0;
        lastWhitespace = true;
        for(int i=start;i<=end;i++) {
            char c = s.charAt(i);
            boolean w = isWhitespace(c);
            if(w && !lastWhitespace) {
                res[x++] = s.substring(last,i);
            } else if(!w && lastWhitespace) {
                last = i;
            }
            lastWhitespace = w;
        }
        res[x] = s.substring(last,end+1);
        return res;
    }

    private boolean isWhitespace(char c) {
        return c==' ' || c=='\t';
    }

    private static void out(Object x) {
        System.out.println(x);
    }

    public static void main(String[] args) throws IOException {
        new Main();
    }
}

import java.io.*;
import java.util.*;

class Main {

	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] t = new int[N];
		int T = 0;
		for (int i = 0; i < N; i++) {
			t[i] = sc.nextInt();
			T += t[i];
		}
		long[] v = new long[N];
		for (int i = 0; i < N; i++) {
			v[i] = sc.nextLong();
		}

		double[] maxA = new double[T * 2 + 1];
		double[] maxB = new double[T * 2 + 1];

		int passed = 0;
		for (int i = 0; i < N; i++) {
			for (int j = 0; j <= t[i]; j++) {
				int time = passed + j;
				maxA[time * 2] = Math.min(v[i],
						(time == 0) ? 0 : maxA[time * 2 - 1] + 0.5);
				if (j == 0 && i > 0) maxA[time * 2] = Math.min(maxA[time * 2], v[i - 1]);
				if (j == t[i]) continue;
				maxA[time * 2 + 1] = Math.min(v[i], maxA[time * 2] + 0.5);
			}
			passed += t[i];
		}

		passed = 0;
		for (int i = N - 1; i >= 0; i--) {
			for (int j = 0; j <= t[i]; j++) {
				int time = T - (passed + j);
				maxB[time * 2] = Math.min(v[i], (time == T) ? 0 : maxB[time * 2 + 1] + 0.5);
				if (j == 0 && i < N - 1) {
					maxB[time * 2] = Math.min(maxB[time * 2], v[i + 1]);
				}
				if (j == t[i]) continue;
				maxB[time * 2 - 1] = Math.min(v[i], maxB[time * 2] + 0.5);
			}
			passed += t[i];
		}

		double answer = 0;
		for (int i = 0; i < T * 2 + 1; i++) {
			answer += Math.min(maxA[i], maxB[i]) * 0.5;
		}

		System.out.println(answer);
	}
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int[] t = new int[N + 1];
    int[] v = new int[N + 2];

    for (int i = 0; i < N; i++) t[i + 1] = scanner.nextInt() * 2 + t[i];
    for (int i = 0; i < N; i++) v[i + 1] = scanner.nextInt() * 2;

    long dist = 0;
    long cv = 0;
    for (int i = 1; i <= N; i++) {
      for (int j = t[i - 1] + 1; j <= t[i]; j++) {
        long f = v[i];
        for (int k = 0; k < i; k++) f = Math.min(f, v[k] + j - t[k]);
        for (int k = i + 1; k <= N + 1; k++) f = Math.min(f, v[k] + t[k - 1] - j);
        dist += cv + f;
        cv = f;
      }
    }

    System.out.println(dist / 8.d);
  }
}

