    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int[] t = new int[N + 1];
    int[] v = new int[N + 2];

    for (int i = 0; i < N; i++) t[i + 1] = scanner.nextInt() * 2 + t[i];
    for (int i = 0; i < N; i++) v[i + 1] = scanner.nextInt() * 2;

