public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			int[] t = in.nextIntArray(n);
			int[] v = in.nextIntArray(n);

			int m = Arrays.stream(t).sum() * 2 + 1;

			double[] maxV = new double[m];
			Arrays.fill(maxV, INF);

			int prt = 0;
			for (int i = 0; i < n; i++) {
				for (int k = 0; k <= 2 * t[i]; k++, prt++) {
					maxV[prt] = Math.min(v[i], maxV[prt]);
				}
				prt--;
			}

			maxV[0] = 0;
			for (int i = 0; i < m-1; i++) {
				maxV[i+1] = Math.min(maxV[i]+0.5, maxV[i+1]);
			}

			maxV[m-1] = 0;
			for (int i = m-1; i > 0; i--) {
				maxV[i-1] = Math.min(maxV[i]+0.5, maxV[i-1]);
			}

			double ans = 0;
			for (int i = 0; i < m-1; i++) {
				ans += (maxV[i+1] + maxV[i]) * 0.5 / 2;
			}

			out.println(ans);
		}
	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer tok;

		public String nextString() {
			while (!tok.hasMoreTokens()) {
				try {
					tok = new StringTokenizer(in.readLine(), " ");
				} catch (IOException e) {
					throw new InputMismatchException();
				}
			}
			return tok.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(nextString());
		}

		public long nextLong() {
			return Long.parseLong(nextString());
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public long[] nextLongArray(int n) {
			long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public InputReader(InputStream inputStream) {
			in = new BufferedReader(new InputStreamReader(inputStream));
			tok = new StringTokenizer("");
		}
	}

}

