import java.util.*;

public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] times = new int[n + 1];
		int[] velocities = new int[n + 2];
		for (int i = 1; i <= n; i++) {
		    times[i] = sc.nextInt();
		}
		for (int i = 1; i <= n; i++) {
		    velocities[i] = sc.nextInt();
		}
		for (int i = n; i >= 1; i--) {
		    velocities[i] = Math.min(velocities[i], velocities[i + 1] + times[i]);
		}
		for (int i = 1; i <= n; i++) {
		    velocities[i] = Math.min(velocities[i], velocities[i - 1] + times[i]);
		}
		double total = 0;
		for (int i = 1; i <= n; i++) {
		    if (velocities[i - 1] < velocities[i]) {
		        if (velocities[i + 1] < velocities[i]) {
		            total += bothCalc(times[i], velocities[i - 1], velocities[i], velocities[i + 1]);
		        } else {
		            total += leftCalc(times[i], velocities[i - 1], velocities[i]);
		        }
		    } else {
		        if (velocities[i + 1] < velocities[i]) {
		            total += rightCalc(times[i], velocities[i], velocities[i + 1]);
		        } else {
		            total += velocities[i] * times[i];
		        }
		    }
		}
		System.out.println(total);
    }

    static double leftCalc(double time, double min, double max) {
        return (2 * time - (max - min)) / 2 * (max - min) + min * time;
    }

    static double rightCalc(double time, double max, double min) {
        return leftCalc(time, min, max);
    }

    static double bothCalc(double time, double left, double max, double right) {
        if (left > right) {
            return bothCalc(time, right, max, left);
        }
        if (max - left + max - right <= time) {
            return leftCalc(max - left, left, max) + rightCalc(time - (max - left), max, right);
        }
        return leftCalc(right - left, left, right) + Math.pow(time - (right - left), 2) / 4 + right * (time - (right - left));
    }


}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.OptionalDouble;
import java.util.function.Function;

public class Main {

	private interface F extends Function<Double, OptionalDouble> {
	}

	private static void setVMaxLine(int[] t, int[] v, List<F> vmaxs) {
		int n = t.length;
		int lastTime = 0;
		for (int i = 0; i < n; lastTime += t[i++]) {
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];
			// vmaxにラインを引いておく
			vmaxs.add(x -> {
				double dx = x - now;
				if (0 <= dx && dx <= time) {
					return OptionalDouble.of((double) vmax);
				}
				return OptionalDouble.empty();
			});
		}
	}

	private static void setUpLine(int[] t, int[] v, List<F> up) {
		int n = t.length;
		int lastTime = 0;
		double lastSpeed = 0;
		for (int i = 0; i < n; lastTime += t[i++]) {
			final double speed = lastSpeed;
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];

			final double needUpSpeed = vmax - speed;

			if (needUpSpeed > 0) {
				final double canUpSpeed = Math.min(needUpSpeed, time);
				up.add(x -> {
					double dx = x - now;
					if (0 <= dx) {
						return OptionalDouble.of(dx + speed);
					}
					return OptionalDouble.empty();
				});
				lastSpeed += canUpSpeed;
			} else {
				lastSpeed = vmax;
			}
		}
	}

	private static void setDownLine(int[] t, int[] v, int T, List<F> down) {
		final int n = t.length;
		int lastTime = T;
		double lastSpeed = 0;
		for (int i = n - 1; i >= 0; lastTime -= t[i--]) {
			final double speed = lastSpeed;
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];

			final double needUpSpeed = vmax - speed;

			if (needUpSpeed > 0) {
				final double canUpSpeed = Math.min(needUpSpeed, time);
				down.add(x -> {
					double dx = now - x;
					if (0 <= dx) {
						return OptionalDouble.of(dx + speed);
					}
					return OptionalDouble.empty();
				});
				lastSpeed += canUpSpeed;
			} else {
				lastSpeed = vmax;
			}
		}
	}

	public static void main(String[] args) throws IOException {
		try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
			br.readLine();
			int[] t = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
			int[] v = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();

			int T = Arrays.stream(t).sum();

			List<F> functions = new ArrayList<>();

			setVMaxLine(t, v, functions);
			setUpLine(t, v, functions);
			setDownLine(t, v, T, functions);

			// 0.5ごとにマッピングする
			double[] map = new double[2 * T + 1];
			for (int i = 0; i < 2 * T; i++) {
				double x = i / 2.0;
				// double a = up.f(x).orElse(Double.MAX_VALUE);
				// double b = down.f(x).orElse(Double.MAX_VALUE);
				// double c = vmaxs.f(x).orElse(Double.MAX_VALUE);
				OptionalDouble min = functions.stream().map(f -> f.apply(x)).filter(OptionalDouble::isPresent)
						.mapToDouble(OptionalDouble::getAsDouble).min();
				// double min = Math.min(a, Math.min(b, c));
				if (min.isPresent()) {
					map[i] = min.getAsDouble();
				}
			}
			System.out.println(ans(map));
		}
	}

	private static double ans(double[] map) {
		// 台形の面積を求める
		double sum = 0;
		for (int i = 1; i < map.length; i++) {
			sum += map[i - 1] + map[i];
		}
		return sum / 4.0;
	}
}

