				maxV = current+t[i];			
				current = maxV;
			}else{
				maxV = Math.min(v[i], (current+next+t[i])/2);
				ans -= (maxV-next)*(maxV-next)/2;
				current = next;
			}
			ans += maxV*t[i];
			ans -= (maxV-previous)*(maxV-previous)/2;
		}
