		sc.close();

		double[] gv = new double[N];
		gv[N-1] = 0;
		for(int i=N-2; i>=0; i--){
			gv[i] = Math.min(gv[i+1]+t[i+1],v[i+1]);
		}

		double ans = 0;
		double current = 0;
		for(int i=0; i<N; i++){
