				for(int i = 0; i < N; i++){
					if(i == 0){
						if(0 > t){
							v = Math.min(v, vs[i] + Math.abs(t));
						}else if(ts_sum[i] < t){
							v = Math.min(v, vs[i] + Math.abs(ts_sum[i] - t));
						}else{
							v = Math.min(v, vs[i]);
						}
					}else{
						if(ts_sum[i - 1] > t){
							v = Math.min(v, vs[i] + Math.abs(ts_sum[i - 1] - t));
						}else if(ts_sum[i] < t){
							v = Math.min(v, vs[i] + Math.abs(ts_sum[i] - t));
						}else{
							v = Math.min(v, vs[i]);
						}
					}
				}

				v = Math.min(v, Math.abs(sum - t));

				//System.out.println(t + " " + v);
				answer += v;
			}

			System.out.printf("%.08f\n", answer / 4.0);
		}
	}

