import java.io.*;
import java.util.*;

public class Main {
  private static double solve(int n, int[] ts, int[] vs) {
    double[] maxSpeedFromHead = new double[n + 1];
    maxSpeedFromHead[0] = 0.0;
    for (int i = 0; i < n; i++) {
      maxSpeedFromHead[i + 1] = Math.min(maxSpeedFromHead[i] + ts[i], vs[i]);
    }
    double[] maxSpeedFromTail = new double[n + 1];
    maxSpeedFromTail[n] = 0.0;
    for (int i = n-1; i >= 0; i--) {
      maxSpeedFromTail[i] = Math.min(maxSpeedFromTail[i + 1] + ts[i], vs[i]); 
    }
    double[] maxSpeedBorder = new double[n + 1];
    maxSpeedBorder[0] = 0;
    maxSpeedBorder[n] = 0;
    for (int i = 1; i < n; i++) {
      maxSpeedBorder[i] = Math.min(maxSpeedFromHead[i], maxSpeedFromTail[i]);
    }

    double totalDistance = 0.0;
    for (int i = 0; i < n; i++) {
      double startSpeed = maxSpeedBorder[i];
      double endSpeed = maxSpeedBorder[i+1];
      double time = ts[i];
      double maxSpeed = vs[i];
      double changeSpeedTime = Math.abs(startSpeed - endSpeed);
      double distance = (startSpeed + endSpeed) * changeSpeedTime / 2;
      double restTime = time - changeSpeedTime;
      if (restTime > 0) {
        double maxStartEndSpeed = Math.max(startSpeed, endSpeed);
        if ((maxSpeed - maxStartEndSpeed) * 2 < restTime) {
          distance += (maxSpeed - maxStartEndSpeed) * (maxSpeed + maxStartEndSpeed);
          distance += maxSpeed * (restTime - 2 * (maxSpeed - maxStartEndSpeed));
        } else {
          distance += maxStartEndSpeed * restTime;
          distance += (restTime / 2) * (restTime / 2);
        }
      }
      totalDistance += distance;
    }
    return totalDistance;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] ts = reader.nextIntArray(n);
    int[] vs = reader.nextIntArray(n);
    out.printf("%.20f\n", solve(n, ts, vs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

