/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] t = in.readIntArray(n);
            int[] v = in.readIntArray(n);

            int sum = IntStream.of(t).sum();
            double[] maxSpeed = new double[2 * sum + 1];
            Arrays.fill(maxSpeed, Double.MAX_VALUE);
            maxSpeed[0] = maxSpeed[2 * sum] = 0;
            int pos = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= 2 * t[i]; j++) {
                    maxSpeed[pos + j] = Math.min(maxSpeed[pos + j], v[i]);
                }
                pos += 2 * t[i];
            }

            for (int i = 0; i < 2 * sum; i++) {
                maxSpeed[i + 1] = Math.min(maxSpeed[i + 1], maxSpeed[i] + 0.5);
            }
            for (int i = 2 * sum - 1; i >= 0; i--) {
                maxSpeed[i] = Math.min(maxSpeed[i], maxSpeed[i + 1] + 0.5);
            }

            double ans = 0;
            for (int i = 0; i < 2 * sum; i++) {
                ans += (maxSpeed[i] + maxSpeed[i + 1]) / 4;
            }

            out.printLine(ans);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに実装したソースコード
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int[] t = IntStream.range(0, n).map(i -> scanner.nextInt()).toArray();
			// 時間制限区間の開始時間と終了時間
			int[] l = new int[n + 2], r = new int[n + 2];
			l[0] = r[0] = l[1] = 0;
			IntStream.range(0, n).forEach(i -> r[i + 1] = l[i + 2] = l[i + 1] + t[i]);
			r[n + 1] = l[n + 1];
			// 各区間の最大速度
			int[] v = new int[n + 2];
			v[0] = v[n + 1] = 0;
			IntStream.range(0, n).forEach(i -> v[i + 1] = scanner.nextInt());
			// 各時刻の最大速度(0.5秒刻み)
			double[] d = new double[r[n + 1] * 2 + 1];
			d[0] = 0.0d;
			System.out.println(IntStream.range(1, d.length).mapToDouble(i -> {
				d[i] = calcF(i, n, l, r, v);
				return (d[i - 1] + d[i]) / 4.0d;
			}).sum());
		}
	}

	/**
	 * 指定された時刻における走行可能の最大速度を取得する
	 * 
	 * @param index 時刻x2の値
	 * @param n     N
	 * @param l     時間帯のスタート時点
	 * @param r     時間帯のエンド時点
	 * @param v     時間帯の最大速度
	 * @return 指定された時刻における走行可能の最大速度
	 */
	private static double calcF(int index, int n, int[] l, int[] r, int[] v) {
		double time = index / 2.0d;
		return IntStream.range(0, n + 2).mapToDouble(i -> {
			if (time < l[i]) {
				return v[i] + (l[i] - time);
			} else if ((l[i] <= time) && (time <= r[i])) {
				return (double) v[i];
			} else {
				return v[i] + (time - r[i]);
			}
		}).min().getAsDouble();
	}
}

