	//static final long MOD = 1000000007L;
	//static final int INF = 1000000007;

	//static long[] factorial;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.ni();

		int T = 0;
		int[] times = new int[N];
		for (int i = 0; i < N; i++) {
			times[i] = 2*sc.ni();
			T += times[i];
		}
		int t = 0;
		int[] max = new int[T+1];
		int[] limit = new int[N];
		for (int i = 0; i < N; i++) {
			limit[i] = 2*sc.ni();
			for (int j = 0; j < times[i]; j++) {
				max[t] = limit[i];
				t++;
			}
		}
		//max[T-1] = 0;

		long ans = 0;
		int v = 0;
		for (int i = 0; i < T; i++) {
			boolean accelerate = true;

			for (int j = i; j < T; j++) {
				if ((v+1)-(j-i) > max[j] || (v+1)-(j-i) > max[j+1]) {
					accelerate = false;
					break;
				}
			}

			boolean steady = true;

			for (int j = i; j < T; j++) {
				if (v-(j-i) > max[j] || v-(j-i) > max[j+1]) {
					steady = false;
					break;
				}
			}

			if (accelerate) {
				v++;
			} else if (!steady) {
				v--;
			}
			ans += v;
		}

		pw.println((ans+0.0)/4);
		pw.close();
	}

	public static long dist(long[] p1, long[] p2) {
		return (Math.abs(p2[0]-p1[0])+Math.abs(p2[1]-p1[1]));
	}

	//Find the GCD of two numbers
	public static long gcd(long a, long b) {
		if (a < b) return gcd(b,a);
		if (b == 0)
			return a;
		else
			return gcd(b,a%b);
	}

	//Fast exponentiation (x^y mod m)
	public static long power(long x, long y, long m) { 
		if (y < 0) return 0L;
		long ans = 1;
		x %= m;
		while (y > 0) { 
			if(y % 2 == 1) 
				ans = (ans * x) % m; 
			y /= 2;  
			x = (x * x) % m;
		} 
		return ans; 
	}

