public class Main {
	public static void main(String[] args) {
		FS reader = new FS();
		// write reader
		int N = reader.nextInt();
		int[] T = new int[N];
		int[] V = new int[N];
		for(int i=0; i<N; i++) T[i] = reader.nextInt();
		for(int i=0; i<N; i++) V[i] = reader.nextInt();
		solver(N, T, V);
	}

	public static void solver(int N, int[] T, int[] V) {
		// write logic
		int[] fMax = new int[20001];
		int[] rMax = new int[20001];
		int[] ansV = new int[20001];
		int i    = 1;
		int it   = 0;
		int sum  = 0;
		int maxV = 0;
		while(true) {
		    if (sum < i) {
		        if (it == N) break;
		        sum += T[it];
		        maxV = V[it];
		        it++;
		    }
		    fMax[i] = Math.min(fMax[i-1]+1, maxV);
		    i++;
		}

		int tmpsum = 0;
		i = 1;
		it = 0;
		while(true) {
		    if (tmpsum < i) {
		        if (it == N) break;
		        tmpsum += T[N-it-1];
		        maxV = V[N-it-1];
		        it++;
		    }
		    rMax[sum-i] = Math.min(rMax[sum-i+1]+1, maxV);
		    i++;
		}

		int ans = 0;
		int cross = 0;
		for(int t=0; t<sum; t++) {
		    if (fMax[t] == rMax[t+1] && rMax[t] == fMax[t+1] && Math.abs(fMax[t]-fMax[t+1]) == 1) cross++;
		    ans += Math.min(fMax[t], rMax[t]) + Math.min(fMax[t+1], rMax[t+1]);
		}
		System.out.println((double)ans/2.0+(double)cross*0.25);
	}

	// Read Class
	static class FS {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
		private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
		private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

		public boolean hasNext() { skipUnprintable(); return hasNextByte();}
		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while(isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}
		public int nextInt() {
			return (int)nextLong();
		}
		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while(true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if(b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}

    static int bellmanford(int n, Edge[] edges, int s, int g) {
	    int[] distance = new int[n];
        int[] count    = new int[n];

        Arrays.fill(distance, Integer.MAX_VALUE);
        distance[s] = 0;

        for (int i=0; i<n-1; i++) {
            for (Edge e : edges) {
                if (distance[e.source] != Integer.MAX_VALUE && distance[e.source] + e.cost < distance[e.target]) {
                    distance[e.target] = distance[e.source] + e.cost;
                }
            }
        }
        int tmp = distance[g];
        for (int i=0; i<n-1; i++) {
            for (Edge e : edges) {
                if (distance[e.source] != Integer.MAX_VALUE && distance[e.source] + e.cost < distance[e.target]) {
                    distance[e.target] = distance[e.source] + e.cost;
                }
            }
        }

        // check logic
        if (tmp > distance[n-1]) return Integer.MIN_VALUE;
        else return distance[n-1];
    }

	static class Edge {
	    public int source = 0;
	    public int target = 0;
	    public int cost   = 0;

	    public Edge(int source, int target, int cost) {
	        this.source = source;
	        this.target = target;
	        this.cost   = cost;
	    }

	    public int compareTo(Edge e) {
	        return this.cost - e.cost;
	    }
	}
}

package D;

import java.io.*;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final InputStream inputStream = System.in;
        final OutputStream outputStream = System.out;
        final InputReader in = new InputReader(inputStream);
        final PrintWriter out = new PrintWriter(outputStream);
        final Solution solver = new Solution(in, out);
        solver.solve();
        out.close();
    }

    static class Solution {
        private static final int MAX_N = 100;
        private static final int MAX_T = 200;
        private static final int INF = 1145141919;
        private static final int MULTIPLIER = 2;
        private final InputReader in;
        private final PrintWriter out;

        private int N;
        private List<Integer> timePoints;
        private List<Integer> vLimits;
        private final int[] vLimitAtEachTimePoint = new int[MAX_N * MAX_T * 2 + 1];


        Solution(final InputReader in, final PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        void inputAndTransform() {
            N = in.nextInt();
            timePoints = IntStream.range(0, N)
                    .map(i -> MULTIPLIER * in.nextInt())
                    .boxed().collect(Collectors.toList());
            // Convert to a running total array
            for (int i = 1; i < timePoints.size(); i++) {
                timePoints.set(i, timePoints.get(i - 1) + timePoints.get(i));
            }

            vLimits = IntStream.range(0, N)
                    .map(i -> MULTIPLIER * in.nextInt())
                    .boxed().collect(Collectors.toList());
            vLimits.add(0); // the velocity must be 0 at the last time point.
        }

        void buildVLimitAtEachTimePoint() {
            Arrays.fill(vLimitAtEachTimePoint, INF);
            // manage linear function constraints
            for (int i = 0; i <= N; i++) {
                vLimitAtEachTimePoint[i > 0 ? timePoints.get(i - 1) : 0] = vLimits.get(i);
            }
            for (int i = vLimitAtEachTimePoint.length - 2; i >= 0; i--) {
                vLimitAtEachTimePoint[i] = Math.min(vLimitAtEachTimePoint[i], vLimitAtEachTimePoint[i + 1] + 1);
            }
            // manage horizontal line constraints
            for (int i = 0; i < N; i++) {
                for (int tp = (i > 0 ? timePoints.get(i - 1) : 0); tp <= timePoints.get(i); tp++) {
                    vLimitAtEachTimePoint[tp] = Math.min(vLimitAtEachTimePoint[tp], vLimits.get(i));
                }
            }
        }

        void solve() {
            inputAndTransform();
            buildVLimitAtEachTimePoint();

            int currentVelocity = 0;
            int totalDistance = 0;
            for (int i = 0; vLimitAtEachTimePoint[i] != 0; i++) {
                final int nextVelocity = Math.min(vLimitAtEachTimePoint[i + 1], currentVelocity + 1);
                totalDistance += currentVelocity + (nextVelocity - currentVelocity) / 2;
                currentVelocity = nextVelocity;
            }

            out.println((double) totalDistance / (MULTIPLIER * MULTIPLIER));
        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(final InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

