			{
				int lastTime = T;
				double lastSpeed = 0;
				for (int i = n - 1; i >= 0; i--) {
					final double speed = lastSpeed;
					final int now = lastTime;
					final int time = t[i];
					final int vmax = v[i];

					final double needUpSpeed = vmax - speed;

					if (needUpSpeed > 0) {
						final double canUpSpeed = Math.min(needUpSpeed, t[i]);
						down.add(x -> {
							double dx = now - x;
							if (0 <= dx && dx <= canUpSpeed) {
								// y=x+b
								return Optional.of(dx + speed);
							} else if (canUpSpeed < dx && dx <= time) {
								// y=b
								return Optional.of(canUpSpeed + speed);
							}
							return Optional.empty();
						});
						lastSpeed += canUpSpeed;
					} else {
						down.add(x -> {
							double dx = now - x;
							if (0 <= dx && dx <= time) {
								return Optional.of(speed);
							}
							return Optional.empty();

						});
					}
					lastTime -= time;
				}
			}

			double[] map = new double[2 * T + 1];
			for (int i = 0; i < 2 * T; i++) {
				double x = i / 2.0;
				Optional<Double> a = up.f(x);
				Optional<Double> b = down.f(x);

				if (a.isPresent() && b.isPresent()) {
					map[i] = Math.min(a.get(), b.get());
				} else if (a.isPresent()) {
					map[i] = a.get();
				} else if (b.isPresent()) {
					map[i] = b.get();
				}
			}
			System.out.println(ans(map));
		}
	}

	private static double ans(double[] map) {
		double sum = 0;

		for (int i = 1; i < map.length; i++) {
			sum += map[i - 1] + map[i];
		}

		return sum / 4.0;
	}

}

import java.util.Scanner;

class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int phase = sc.nextInt();
        int[] time = new int[phase];
        int[] speed = new int[phase];
        int totalTime = 0;
        for (int i = 0; i < phase; i++) {
            time[i] = sc.nextInt();
            totalTime += time[i];
        }
        for (int i = 0; i < phase; i++) {
            speed[i] = sc.nextInt();
        }
        double distance = solve(time, speed, totalTime);
        System.out.println(distance);
    }

    private static double solve(int[] time, int[] speed, int totalTime) {
        double[] actual = new double[totalTime * 2 + 1];
        int idx = 0;
        for (int i = 0; i < time.length; i++) {
            for (int j = 0; j < time[i]; j++) {
                actual[idx] = speed[i];
                idx++;
                actual[idx] = speed[i];
                idx++;
            }
        }
        actual[0] = 0;
        actual[actual.length - 1] = 0;
        for (int i = 1; i < actual.length; i++) {
            actual[i] = Math.min(actual[i], actual[i - 1] + 0.5);
        }
        for (int i = actual.length - 2; i > 1; i--) {
            actual[i] = Math.min(actual[i], actual[i + 1] + 0.5);
        }
        double distance = 0;
        for (int i = 1; i < actual.length; i++) {
            distance += (actual[i] + actual[i - 1]) / 4;
        }
        return distance;
    }
}

