        // -----------------------------------------
        // startV <= limitV が前提
        double[] calc(int startV, int endV, int limitV, int t) {
//        	prn("start = " + startV + "  end = " + endV + "  limit = " + limitV + "  t = " + t);
        	double len = 0;
        	int ansEnd = endV;
        	if(limitV <= endV) {							// リミットより　終了が大きい
        		int wkT = limitV - startV;
        		if(wkT >= t) {								// リミットまで届かない
        			len += (double)startV * t + t * t /2;
        			ansEnd = startV + t;
        		} else {									// リミットで終わる
        			len += (double)startV * t + wkT * wkT / 2 + (t - wkT) * (limitV - startV);
        			ansEnd = limitV;
        		}
        	} else {										// リミットが　終了より大きい
        		// 開始から　x 秒加速して、残りを減速すると　t 秒後に終了になる
        		double x = ((double)endV - startV + t) / 2;
        		if(x + startV <= limitV) {					// リミットに届かない
        			len += (double)startV * x + x * x / 2 
        					+ endV *(t - x) + (t - x) * (t - x) / 2;
        		} else {									// 開始　→　リミット　→　終了
        			double x2 = (double)limitV - startV;
        			double x3 = (double)limitV - endV;
        			len += (double)startV * x2 + (limitV - startV) * x2 / 2
        					+ limitV * (t - x2 - x3)
        					+ endV * x3 + (limitV - endV) * x3 / 2;
        		}
        	}
        	double[] ans = new double[2];
        	ans[0] = (double)ansEnd;
        	ans[1] = len;
        	return ans;
        }
        public void solve() {
        	int N = ni();
        	int[] T = ndi(N);
        	int[] V = new int[N+1];
        	for (int i = 0; i < N; i++) {
				V[i] = ni();
			}
        	List<PP> list = new ArrayList<>();
        	double ans = 0;
        	int sp = 0;
        	double[] wk;
        	for (int i = 0; i < N; i++) {
        		wk = calc(sp, V[i+1], V[i], T[i]);
        		ans += wk[1];
        		sp = (int)wk[0];
			}
        	prn(String.valueOf(ans));
        }

