/**
 * https://abc076.contest.atcoder.jp/tasks/abc076_c
 */
public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		double[] t = new double[N];
		double[] v = new double[N];
		for(int i=0; i<N; i++) t[i] = sc.nextDouble();
		for(int i=0; i<N; i++) v[i] = sc.nextDouble();
		sc.close();

		double ans = 0;
		double current = 0;
		for(int i=0; i<N; i++){
			double next = i<N-1 ? v[i+1] : 0;
			if(v[i]<=next){
				double ut = Math.min(t[i],v[i]-current);
				double mt = Math.max(0, t[i]-ut);
				ans += (current*ut)+((v[i]-current)*ut/2.0);
				ans += v[i]*mt;
				current = v[i];
			}else{
				double maxT = (t[i]-current)/2.0;
				double ut = Math.max(0, Math.min(maxT, v[i]-current));
				double maxV = current+ut;
				double et = Math.min(t[i]-maxT, maxV-next);
				double mt = Math.max(0, t[i]-ut-et);
				ans += (current*ut)+((maxV-current)*ut/2.0);
				ans += maxV*mt;
				ans += (next*et)+((maxV-next)*et/2.0);
				current = next;
			}
		}
		System.out.println(ans);
	}

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		final Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] time = new int[n + 3];
		int[] maxv = new int[n + 2];
		time[0] = 0;
		time[1] = 0;
		for (int i = 0, k = 2; i < n; i++, k++) {
			time[k] = sc.nextInt();
			time[k] += time[k-1];
		}
		time[n + 2] = time[n + 1];
		int totalTime = time[n+2];
		maxv[0] = 0;
		maxv[n + 1] = 0;
		for (int i = 1; i <= n; i++) {
			maxv[i] = sc.nextInt();
		}

//		System.out.println(Arrays.toString(time));
//		System.out.println(Arrays.toString(maxv));
//		System.out.println(totalTime);

		double[] maxV_Every_0_5_seconds = new double[totalTime * 2+1];
		Arrays.fill(maxV_Every_0_5_seconds, Integer.MAX_VALUE);
		for (double i = 0; i < totalTime * 2+1; i++) {
			for(int j = 0; j < n+2; j++) {
				//j個目の条件はtime[j+1]-time[j]の区間の最大速度はmax[v]
				if(i <= 2*time[j]) {
					maxV_Every_0_5_seconds[(int) i] = Math.min(maxV_Every_0_5_seconds[(int) i], maxv[j]+time[j]-(i/2));
				}
				if(i >= 2*time[j+1]) {
					maxV_Every_0_5_seconds[(int) i] = Math.min(maxV_Every_0_5_seconds[(int) i], maxv[j]-time[j+1]+(i/2));
				}
				if(i >= 2*time[j] && i <= 2*time[j+1]) {
					maxV_Every_0_5_seconds[(int) i] = Math.min(maxV_Every_0_5_seconds[(int) i], maxv[j]);
				}
			}
		}
		System.out.println(Arrays.toString(maxV_Every_0_5_seconds));
		double ans = 0;
		for(int i = 0; i < totalTime*2; i++) {
			ans += 0.25 * (maxV_Every_0_5_seconds[i]+maxV_Every_0_5_seconds[i+1]);
		}
		System.out.println(ans);
	}
}

