                        curHei++;
                        ttt++;
                    } else {
                        size += (curHei + prevHei) * ttt;
                        prevHei = curHei;
                        ttt = 0;
                        if (mv == curHei){
                            if (maxv[i + 1] == curHei - 1 && ctr[i + 1] > curHei){
                                btt += 1;
                            }
                            perform = 1;
                        } else {
                            perform = 2;
                        }
                        i--;
                    }
                    break;
                case 1:
