                                i++;
                                btt++;
                            }
                            perform = 2;
                        }
                        i--;
                    }
                    break;
                case 2:
                    if (mv == curHei - 1){
                        curHei--;
                        ttt++;
                    } else {
                        size += (prevHei + curHei) * ttt;
                        prevHei = curHei;
                        ttt = 0;
                        if (mv == curHei){
