import java.util.Scanner;
import java.util.Arrays;

public class Main{
  static final int INF = Integer.MAX_VALUE / 2;
  static int n;
  static int[] t, v;
  static final boolean DEBUG = true;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    t = new int[n];
    for(int i = 0; i < n; i++){
      t[i] = sc.nextInt();
    }
    v = new int[n];
    for(int i = 0; i < n; i++){
      v[i] = sc.nextInt();
    }

    int[] st = new int[n + 1];
    for(int i = 1; i <= n; i++){
      st[i] = st[i - 1] + t[i - 1];
    }

    double[] mv = new double[2 * st[n] + 1];
    for(int i = 0; i <= 2 * st[n]; i++){
      double k = 0.5 * i;
      double min = Math.min(k, (double)st[n] - k);
      for(int j = 0; j < n; j++){
        min = Math.min(min, f(j, st, k));
      }
      mv[i] = min;
    }

    double sum = 0;
    for(int i = 0; i < 2 * st[n]; i++){
      sum += 0.25 * (mv[i] + mv[i + 1]);
    }

    System.out.println(sum);
  }

  static double f(int i, int[] st, double k){
    if(k < st[i]){
      return (double)v[i] + ((double)st[i] - k);
    }
    else if(k > st[i + 1]){
      return (double)v[i] + (k - (double)st[i + 1]);
    }
    else{
      return v[i];
    }
  }
}

import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

public class Main {

    public static void main(String[] args) {
        final Scanner scanner = new Scanner(System.in);
        solve(scanner);
    }

    static void solve(Scanner scanner) {
        int N = Integer.parseInt(scanner.nextLine());
        int[] ts = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        for (int i = 1; i < N; i++) {
            ts[i] += ts[i - 1];
        }
        int[] vs = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        BigDecimal[] dp = new BigDecimal[200 * 100 + 1];
        Arrays.fill(dp, BigDecimal.ZERO);
        int curr = 0;
        for (int i = 1; i < 200 * 100 + 1; i++) {
            if (i >= 2 * ts[N - 1] && dp[i - 1].compareTo(BigDecimal.ZERO) == 0) {
                break;
            }
            BigDecimal vNext = curr == N - 1 ? BigDecimal.ZERO : BigDecimal.valueOf(vs[curr + 1]);
            if (dp[i - 1].subtract(vNext).compareTo(BigDecimal.valueOf(ts[curr]).subtract(BigDecimal.valueOf(i - 1).divide(BigDecimal.valueOf(2)))) == 0) {
                dp[i] =  dp[i - 1].subtract(BigDecimal.valueOf(0.5));
            } else if (BigDecimal.valueOf(vs[curr]).compareTo(dp[i - 1]) > 0) {
                dp[i] =  dp[i - 1].add(BigDecimal.valueOf(0.5));
            } else if (BigDecimal.valueOf(vs[curr]).compareTo(dp[i - 1]) == 0) {
                dp[i] =  dp[i - 1];
            }
            // System.out.printf("%.1f %.1f \n", i / 2.0, dp[i].doubleValue());
            if (curr != N - 1 && 2 * ts[curr] == i) {
                curr++;
            }
        }
        BigDecimal ans = BigDecimal.ZERO;
        for (int i = 0; i < 200 * 100; i++) {
            ans = ans.add(dp[i].add(dp[i + 1]).multiply(BigDecimal.valueOf(0.25)));
        }
        System.out.printf("%.6f\n", ans.doubleValue());
    }

}

import java.io.OutputStream;
