		for(int i = 0; i < n; i++){
		    for(int j = 0; j < t[i]; j++){
		        index++;
		        if(index == sumT) continue;
		        if(j < t[i]-1){
		            minV[index] = v[i];
		        }else{
		            minV[index] = min(v[i], v[i+1]);
		        }
		    }
		}
