        for(int v0 = 0; v0 <= v[i - 1]; v0++){
          if(dist[i - 1][v0] == -INF){
            continue;
          }
          if(Math.abs(vn - v0) <= t[i - 1]){
            int ta = vn - v0;
            int tb = v[i - 1] - vn;
            double d = v[i - 1] * (t[i - 1] - (ta + tb)) +
              v0 * ta + (double)(ta * ta) / 2.0 +
              vn * tb + (double)(tb * tb) / 2.0;
            max = Math.max(max, dist[i - 1][v0] + d);
          }
        }
        dist[i][vn] = max;
      }
    }

    System.out.println(dist[n][0]);
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.OptionalDouble;
import java.util.function.DoubleFunction;

public class Main {

	private interface F extends DoubleFunction<OptionalDouble> {
	}

	private static void setVMaxLine(int[] t, int[] v, List<F> vmaxs) {
		int n = t.length;
		int lastTime = 0;
		for (int i = 0; i < n; lastTime += t[i++]) {
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];
			// vmaxにラインを引いておく
			vmaxs.add(x -> {
				double dx = x - now;
				if (0 <= dx && dx <= time) {
					return OptionalDouble.of(vmax);
				}
				return OptionalDouble.empty();
			});
		}
	}

	private static void setUpLine(int[] t, int[] v, List<F> up) {
		int n = t.length;
		int lastTime = 0;
		double lastSpeed = 0;
		for (int i = 0; i < n; lastTime += t[i++]) {
			final double speed = lastSpeed;
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];

			final double needUpSpeed = vmax - speed;

			if (needUpSpeed > 0) {
				final double canUpSpeed = Math.min(needUpSpeed, time);
				up.add(x -> {
					double dx = x - now;
					if (0 <= dx) {
						return OptionalDouble.of(dx + speed);
					}
					return OptionalDouble.empty();
				});
				lastSpeed += canUpSpeed;
			} else {
				lastSpeed = vmax;
			}
		}
	}

	private static void setDownLine(int[] t, int[] v, int T, List<F> down) {
		final int n = t.length;
		int lastTime = T;
		double lastSpeed = 0;
		for (int i = n - 1; i >= 0; lastTime -= t[i--]) {
			final double speed = lastSpeed;
			final int now = lastTime;
			final int time = t[i];
			final int vmax = v[i];

			final double needUpSpeed = vmax - speed;

			if (needUpSpeed > 0) {
				final double canUpSpeed = Math.min(needUpSpeed, time);
				down.add(x -> {
					double dx = now - x;
					if (0 <= dx) {
						return OptionalDouble.of(dx + speed);
					}
					return OptionalDouble.empty();
				});
				lastSpeed += canUpSpeed;
			} else {
				lastSpeed = vmax;
			}
		}
	}

	public static void main(String[] args) throws IOException {
		try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
			br.readLine();
			int[] t = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
			int[] v = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();

			int T = Arrays.stream(t).sum();

			List<F> functions = new ArrayList<>();

			setVMaxLine(t, v, functions);
			setUpLine(t, v, functions);
			setDownLine(t, v, T, functions);

			// 0.5ごとにマッピングする
			double[] map = new double[2 * T + 1];
			for (int i = 0; i <= 2 * T; i++) {
				double x = i / 2.0;
				OptionalDouble min = functions.stream().map(f -> f.apply(x)).filter(OptionalDouble::isPresent)
						.mapToDouble(OptionalDouble::getAsDouble).min();

				if (min.isPresent()) {
					map[i] = min.getAsDouble();
				}
			}
			System.out.println(ans(map));
		}
	}

	private static double ans(double[] map) {
		// 台形の面積を求める
		double sum = 0;
		for (int i = 1; i < map.length; i++) {
			sum += map[i - 1] + map[i];
		}
		return sum / 4.0;
	}
}

import java.io.*;
import java.util.StringTokenizer;

public class ExpressB76D {
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner();
        int n = in.nextInt();
        int[] time = new int[n];
        for (int i = 0; i < n; i++) time[i] = in.nextInt();
        int[] maxV = new int[n + 1];
        for (int i = 0; i < n; i++) maxV[i] = in.nextInt();
        maxV[n] = 0;
        double distance = 0;
        double curV = 0;
        int tOld = 0;
        for (int i = 0; i < n; i++) {
            //Train will accelerate for some period of time, reach the cap for some period of time, and decelerate.
            int tNew = tOld; //tTerm = terminal velocity
            double tTerm = tOld + maxV[i] - curV;
            double accTime = tOld + time[i];
            for (int j = i + 1; j <= n; j++) { //When do we need to decelerate to reach this speed?
                tNew += time[j - 1];
                int newGoal = maxV[j]; //Need to be at newGoal by time tNew
                //curV + (tRes - tOld) - (tNew - tRes) = newGoal.  2 * tRes = newGoal + tOld + tNew - curV
                double tRes = -1 * curV;
                tRes += tOld + tNew + newGoal;
                tRes /= 2;
                if (tRes > tTerm) {
                    //curV + (tTerm - tOld) - (tNew - tRes) = newGoal.
                    //tRes = newGoal + tOld + tNew - curV - tTerm
                    tRes = -1 * curV + -1 *  tTerm;
                    tRes += newGoal + tOld + tNew;
                }

                if (tRes < accTime) accTime = tRes;
            }
            tNew = tOld + time[i];
            if (accTime > tTerm) {
                //Accelerating tOld through tTerm
                //No change tTerm through accTime
                //Decelerating accTime through tNew
                distance += curV * (tTerm - tOld) + (tTerm - tOld) * (tTerm - tOld) / 2;
                curV += tTerm - tOld;
                distance += curV * (accTime - tTerm);
                distance += curV * (tNew - accTime) - (tNew - accTime) * (tNew - accTime) / 2;
                curV -= tNew - accTime;
            } else {
                //Accelerating tOld through accTime
                //Decelerating accTime through tNew
                distance += curV * (accTime - tOld) + (accTime - tOld) * (accTime - tOld) / 2;
                curV += accTime - tOld;
                distance += curV * (tNew - accTime) - (tNew - accTime) * (tNew - accTime) / 2;
                curV -= tNew - accTime;
            }

        }
        System.out.println(distance);
    }

