namespace Competitive
{
    internal class Solution
    {
        public int N;
        public int[] T, V;
        public long MOD = 1000000007;

        public void Run()
        {
            N = Input.ReadInt();
            T = Input.ReadIntArray();
            V = Input.ReadIntArray();
            int[] S = new int[N+1];

            for (int a = 0; a <= N; a++)
            {
                S[a] = 1000000;
            }

            for (int a = 0; a <= N; a++)
            {
                if (a == 0 || a == N) S[a] = 0;
                else
                {
                    S[a] = Math.Min(S[a], S[a-1] + T[a-1]);
                    S[a] = Math.Min(S[a], V[a]);
                    S[a] = Math.Min(S[a], V[a-1]);
                }
            }
            for (int a = N; a >= 0; a--)
            {
                if (a == 0 || a == N) S[a] = 0;
                else
                {
                    S[a] = Math.Min(S[a], S[a + 1] + T[a]);
                    S[a] = Math.Min(S[a], V[a]);
                    S[a] = Math.Min(S[a], V[a - 1]);
                }
            }

            double ret = 0;
            for (int i = 0; i < N; i++)
            {
                ret += area(V[i], T[i], S[i], S[i + 1]);
            }
            Console.Error.WriteLine(string.Join(", ", S));
            Console.WriteLine(ret);
        }

        public double area(int v, int t, int s, int e)
        {
            double mx = Math.Min((s + e + t) / 2.0, v);
            double a = mx - s;
            double c = mx - e;
            double b = t - a - c;

            double ret = 0;
            ret += a * (s + mx) / 2.0;
            ret += b * mx;
            ret += c * (e + mx) / 2.0;
            return ret;
        }
    }

