{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];
            var Ti = Sarray();
            var Vi = Sarray();
            Vi = Vi.Concat(new long[] { 0 }).ToArray();
            for (var i = N - 1; 0 <= i; --i)
                Vi[i] = Min(Vi[i], Vi[i + 1] + Ti[i]);

            decimal Vl = 0, Vr = 0, sum = 0;
            for (var i = 0; i < N; ++i)
            {
                decimal men = 0;
                var t = Ti[i];
                if (Vi[i] <= Vi[i+1])
                {
                    Vr = Min(Vl + t, Vi[i]);
                    var Adt = Vr - Vl;
                    var Cst = t - Adt;
                    men = (Vl + Vr) * Adt / (decimal)2.0 + Cst * Vr;
                    if (Adt < (decimal)-0.1 || Cst < (decimal)-0.1) throw new Exception();
                }
                else
                {
                    Vr = Vi[i + 1];
                    decimal Vm = Vi[i];
                    decimal Adt = Vm - Vl;
                    decimal Dst = Vm - Vr;
                    if (Adt < (decimal)-0.1 || Dst < (decimal)(-0.1)) throw new Exception();
                    if (t < Adt + Dst)
                    {
                        Adt = (t + Vr - Vl) / (decimal)2.0;//Vl+Adt=Dst+Vr,Adt+Dst=t
                        Dst = t - Adt;
                        Vm = Vl + Adt;
                    }
                    if (Adt < (decimal)-0.1 || Dst < (decimal)(-0.1)) throw new Exception();
                    men = (Vl + Vm) * Adt / (decimal)2.0 + Vm * (t - Adt - Dst) + (Vm + Vr) * Dst / (decimal)2.0;
                }
                Vl = Vr;
                sum += men;
            }
            WriteLine($"{sum:f5}");
        }
    }
}

