public class Program
{
    int N;
    int[] T, V;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        T = sc.IntArray();
        V = sc.IntArray();
        int sum = T.Sum();
        // 時間 速度　距離
        var dp = new double[sum + 1, 201];
        for (int i = 0; i <= sum; i++)
        {
            for (int j = 0; j <= 200; j++)
            {
                dp[i, j] = double.MinValue;
            }
        }

        dp[0, 0] = 0;
        int index = 0;
        int p = 0;
        for (int i = 0; i < sum; i++)
        {
            if (i - p >= T[index])
            {

                p += T[index];
                index++;
            }
            for (int j = 0; j <= 200; j++)
            {
                if (j <= V[index])
                {
                    // 加速
                    if (j + 1 <= V[index])
                    {
                        dp[i + 1, j + 1] = Math.Max(dp[i + 1, j + 1], dp[i, j] + ((double)j + 0.5));
                    }
                    if (j - 1 >= 0)
                    {
                        dp[i + 1, j - 1] = Math.Max(dp[i + 1, j - 1], dp[i, j] + ((double)j - 0.5));
                    }

                    dp[i + 1, j] = Math.Max(dp[i + 1, j], dp[i, j] + j);
                    if (j < V[index])
                    {
                        dp[i + 1, j] = Math.Max(dp[i + 1, j], dp[i, j] + j + 0.25);
                    }
                }
            }
        }

        Console.WriteLine(dp[sum, 0]);
    }

    public static void Main(string[] args) => new Program().Solve();
}

