public class Program
{

    public void Proc()
    {
        int areaCount = int.Parse(Reader.ReadLine());
        int[] timeList = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        int[] spdList = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        this.BlockList = new Block[areaCount];
        for (int i = 0; i < areaCount; i++) {
            this.BlockList[i] = new Block(timeList[i], spdList[i]);
            if(i>0) {
                this.BlockList[i - 1].NextBlock = this.BlockList[i];
                this.BlockList[i].PrevBlock = this.BlockList[i - 1];
            }
        }
        decimal ans = this.BlockList[0].GetKyori;
        Console.WriteLine(ans);

    }

    private Block[] BlockList;

    private class Block {
        public int Time;
        public int MaxSpeed;
        public Block PrevBlock;
        public Block NextBlock;
        public Block(int tm, int spd) {
            this.Time = tm;
            this.MaxSpeed = spd;
        }
        public int SpeedAtExit {
            get {
                if(SpeedAtExitValue == null) {
                    SetSpeed();
                }
                return this.SpeedAtExitValue.Value;
            }            
        }

        private int SpeedAtEnter {
            get {
                if(SpeedAtEnterValue == null) {
                    SetSpeed();
                }
                return this.SpeedAtEnterValue.Value;
            }
        }

        public decimal GetKyori {
            get {
                int maxTime = MaxSpeedTime(0, this.Time);
                int max = Math.Min(this.MaxSpeed, this.SpeedAtEnter + maxTime);
                decimal ans = 0;
                // kasoku
                int kasokuTime = max - this.SpeedAtEnter;
                ans += kasokuTime * this.SpeedAtEnter;
                ans += (kasokuTime * kasokuTime / 2m);
                // iji
                int getnsokuKaisi = this.Time - (max - this.SpeedAtExit);
                ans += (getnsokuKaisi - kasokuTime) * max;
                // gensoku
                int gensokuTime = this.Time - getnsokuKaisi;
                ans += (gensokuTime*gensokuTime) / 2m;
                ans += (gensokuTime * this.SpeedAtExit);
                if(this.NextBlock != null) {
                    ans += this.NextBlock.GetKyori;
                }
                return ans;
            }
        }


        private int MaxSpeedTime(int min, int max) {
            if(max-min<=1) {
                if(this.SpeedAtEnter+max<=this.SpeedAtExit+(this.Time-max)) {
                    return max;
                } else {
                    return min;
                }
            }
            int mid = (max + min) / 2;
            if(this.SpeedAtEnter+mid<=this.SpeedAtExit+(this.Time-mid)) {
                return MaxSpeedTime(mid, max);
            } else {
                return MaxSpeedTime(min, mid);
            }
        }

        public void SetSpeed() {
            if(this.NextBlock == null) {
                this.SpeedAtExitValue = 0;
            } else {
                int ent = this.NextBlock.SpeedAtEnter;
                this.SpeedAtExitValue = Math.Min(ent, this.MaxSpeed);
            }

            this.SpeedAtEnterValue = Math.Min(this.MaxSpeed, this.Time + this.SpeedAtExitValue.Value);
            if(this.PrevBlock != null) {
                this.SpeedAtEnterValue = Math.Min(this.PrevBlock.MaxSpeed, this.SpeedAtEnterValue.Value);
            } else {
                this.SpeedAtEnterValue = 0;
            }
        }

        private Nullable<int> SpeedAtExitValue = null;
        private Nullable<int> SpeedAtEnterValue = null;
    }


    public class Reader
    {
        private static StringReader sr;
        public static bool IsDebug = false;
        public static string ReadLine()
        {
            if (IsDebug)
            {
                if (sr == null)
                {
                    sr = new StringReader(InputText.Trim());
                }
                return sr.ReadLine();
            }
            else
            {
                return Console.ReadLine();
            }
        }
        private static string InputText = @"



3
