		static void Main(string[] args)
		{
			var n = In;
			var t = Ins;
			var v = Ins;
			int sum = 0;
			var li = new List<Func<double, double>>();
			li.Add(f(0, 0, 0));
			for (int i = 0; i < n; i++)
			{
				li.Add(f(sum, sum + t[i], v[i]));
