    public void calc_ABC076D()
    {
        int n = cin.nextInt();
        int[] t = new int[n + 1]; for (int i = 0; i < n; i++) t[i] = cin.nextInt();
        int[] v = new int[n + 1]; for (int i = 0; i < n; i++) v[i] = cin.nextInt();
        t[n] = 0; v[n] = 0;

        //k番目の拘束条件(t = Σti(i=0 ~ k-1) ~ Σti + tk) Σti(i=0 ~ k-1) を stk とかく
        //          (言い換えればk番目の拘束が始まる時間)
        //  は、言い換えればt = x において (v(x)を実際の速度として) 
        //  x <= stk-1 ⇒ v(x) <= vk + (stk-1 + x) 
        //  x >= stk ⇒ v(x) ∈ [vk - (stk - x), vk + (stk + x) ]

        int[] sumt = new int[n+2]; for (int i = 1; i < n + 2; i++) sumt[i] = sumt[i - 1] + t[i-1];
        int[] maxv = new int[sumt[n+1]+1];

        for(int tt = 1; tt < sumt[n+1]; tt++) 
        {
            maxv[tt] = maxv[tt - 1] + 1;
            for(int i = 0; i < n+1; i++)
            {
                if (tt <= sumt[i]) maxv[tt] = Math.Min(maxv[tt], v[i] + (sumt[i] - tt));
                else if( tt <= sumt[i] + t[i]) maxv[tt] = Math.Min(maxv[tt], v[i]);
            }
        }

        double ans = 0;
        int imadokonokousoku = 0;
        int tempt = 1;
        for (int tt = 1; tt < sumt[n]; tt++)
        {
            if(tempt == t[imadokonokousoku]) { tempt = 0; imadokonokousoku++; }
            ans += ((double)maxv[tt] + maxv[tt - 1]) / 2;
            if (maxv[tt] < v[imadokonokousoku] &&  maxv[tt] == maxv[tt + 1])
            {
                ans += 0.25;//t= a.5 に最大値がくる場合の補正
            }
            tempt++;
        }
        ans += 0.5;//最後の一秒 v = 1 to 0なので
        showL(ans);

    }
