                {
                    Vr = Min(Vl + t, Vi[i]);
                    var Adt = Vr - Vl;
                    var Cst = t - Adt;
                    men = (Vl + Vr) * Adt / (decimal)2.0 + Cst * Vr;
                }
                else
                {
                    Vr = Min(Vi[i + 1], Vl + t);
                    decimal Vm = Vi[i];
                    decimal Adt = Vm - Vl;
                    decimal Dst = Vm - Vr;
                    if (t < Adt + Dst)
                    {
                        Adt = (t + Vr - Vl) / (decimal)2.0;//Vl+Adt'=Dst'+Vr,Adt'+Dst'=t
                        Dst = t - Adt;
                        Vm = Vl + Adt;
                    }
                    men = (Vl + Vm) * Adt / (decimal)2.0 + Vm * (t - Adt - Dst) + (Vm + Vr) * Dst / (decimal)2.0;
                }
                Vl = Vr;
                sum += men;
            }
            WriteLine($"{sum:f5}");
        }
    }
}

