			for (int i = 0; i < n; i++)
			{
				if (i == 0) n_sum[i] = t[i];
				else n_sum[i] = n_sum[i - 1] + t[i];
			}
			{
				var tt = new List<int>(v);
				tt.Add(0);
				v = tt.ToArray();
			}
			var sum = t.Sum();
			var a = new int[sum + 1];
			var lim = new int[sum+1];
			{
