class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int[] T = re.ia();
        int[] V = re.ia();
        double[] border = new double[N+1];
        for(int i=1;i<N;i++){
            border[i] = Math.Min(V[i],V[i-1]);
        }
        for(int i=1;i<=N;i++){
            border[i] = Math.Min(border[i],border[i-1]+T[i-1]);
        }
        for(int i=N-1;i>=0;i--){
            border[i] = Math.Min(border[i],border[i+1]+T[i]);
        }
        double count = 0;
        for(int i=0;i<N;i++){
            double add = V[i] - border[i];
            double minus = V[i] - border[i+1];
            if(add + minus <= T[i]){
                count += (border[i] + V[i]) * (add) / 2;
                count += (border[i+1] + V[i]) * (minus) / 2;
                count += V[i] * (T[i] - add - minus);
            }
            else{
                double exceed = add + minus - T[i];
                add -= exceed/2;
                minus -= exceed/2;
                count += (2*border[i] + add) * (add) / 2;
                count += (2*border[i+1] + minus) * (minus) / 2;
            }
        }
        sb.Append(count+"\n");
    }
}
