using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace atcoder
{
	class Program
	{
		static int In => int.Parse(Console.ReadLine());
		static int[] Ins => Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
		static void Out(bool b) => Console.WriteLine(b ? "Yes" : "No");

		static void Main(string[] args)
		{
			var n = In;
			var t = Ins;
			var v = Ins;
			var n_sum = new int[n];
			for (int i = 0; i < n; i++)
			{
				if (i == 0) n_sum[i] = t[i];
				else n_sum[i] = n_sum[i - 1] + t[i];
			}
			{
				var tt = new List<int>(v);
				tt.Add(0);
				v = tt.ToArray();
			}
			var sum = t.Sum();
			var a = new int[sum + 1];
			var lim = new int[sum+1];
			{
				int cc = 0;
				for (int i = 0; i < a.Length; i++)
				{
					if (i <= n_sum[cc]) a[i] = v[cc];
					else
					{
						cc++;
						i--;
					}
				}
			}
			int qu = 0;
			{
				int cc = 0;
				for (int i = 0; i < lim.Length; i++)
				{
					if (n_sum[cc] < i) cc++;
					if (i == 0) lim[i] = 0;
					else
					{
						var pre = lim[i - 1];
						lim[i] = Math.Min(lim[i - 1] + 1, a[i]);
						for (int j = cc; j < n; j++)
						{
							if (n_sum[j] - i < pre - v[j + 1])
							{
								lim[i] = pre - 1;
							}
							else if (n_sum[j] - i == pre - v[j + 1])
							{
								lim[i] = pre;
								if (a[i - 1] > lim[i - 1]) qu++;
							}
						}
					}
				}
			}
			Console.WriteLine(lim.Sum() + qu * 0.25);
			//Console.ReadLine();
		}
	}
}

