    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];
            var Ti = Sarray();
            var Vi = Sarray();
            Vi = Vi.Concat(new long[] { 0 }).ToArray();
            for (var i = N - 1; 0 <= i; --i)
                Vi[i] = Min(Vi[i], Vi[i + 1] + Ti[i]);

            double Vl = 0, Vr = 0, sum = 0;
            for (var i = 0; i < N; ++i)
            {
                double men = 0;
                var t = Ti[i];
                if (Vi[i] + 0.1 < Vl) throw new Exception();
                if (Vi[i] <= Vi[i + 1])
                {
                    Vr = Min(Vl + t, Vi[i]);
                    var Adt = Vr - Vl;
                    var Cst = t - Adt;
                    men = (Vl + Vr) * Adt / 2.0 + Cst * Vr;
                }
                else
                {
                    Vr = Min(Vi[i + 1], Vl + t);
                    double Vm = Vi[i];
                    double Adt = Vm - Vl;
                    double Dst = Vm - Vr;
                    if (t < Adt + Dst)
                    {
                        Adt = (t + Vr - Vl) / 2.0;//Vl+Adt'=Dst'+Vr,Adt'+Dst'=t
                        Dst = t - Adt;
                        Vm = Vl + Adt;
                    }
                    men = (Vl + Vm) * Adt / 2.0 + Vm * (t - Adt - Dst) + (Vm + Vr) * Dst / 2.0;
                }
                Vl = Vr;
                sum += men;
            }
            WriteLine($"{sum:f5}");
        }
    }
}

