class K
{
	int F() => int.Parse(ReadLine());
	long FL() => long.Parse(ReadLine());
	int[] G() => ReadLine().Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();
	long[] GL() => ReadLine().Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();
	public const int MOD = 1000000007;
	public K()
	{
		SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
		Solve();
		Out.Flush();
	}
	void Solve()
	{
		var N = F();
		var t = G();
		var v = G().ToList();
		var V = v.Max();
		// dp[n, v] = t[0]+...+t[n-1] を走り終えたときに速度が v/2 である場合の、そこまでの最大の走行距離 * 16
		// それが無理なら dp[n, v]=-1 とする
		// dp[n, v] >= 0 となる v はある区間をなす => 0 <= v <= M[n] とする
		// 答えは dp[N, 0] / 8
		var dp = new int[N + 1, 2 * V + 1];
		dp[0, 0] = 0;
		var M = new int[N + 1];
		for (var i = 1; i <= 2 * V; i++) dp[0, i] = -1;
		for (var n = 0; n < N; n++)
		{
			M[n + 1] = Min(M[n] + 2 * t[n], 2 * v[n]);
			for (var w = M[n + 1] + 1; w <= 2 * V; w++) dp[n, w] = -1;
			for (var w = 0; w <= M[n + 1]; w++)
			{
				for (var u = 0; u <= M[n]; u++)
				{
					if (u - 2 * t[n] > w || u + 2 * t[n] < w) continue;
					var au = 2 * v[n] - u;
					var bw = 2 * v[n] - w;
					var run = 0;
					if (au + bw <= 2 * t[n]) run = 2 * (8 * t[n] * v[n] - au * au - bw * bw);
					else
					{
						var x = 2 * t[n] + u + w;
						run = x * x - 2 * (u * u + w * w);
					}
					dp[n + 1, w] = Max(dp[n + 1, w], dp[n, u] + run);
				}
			}
		}
		WriteLine(dp[N, 0] / 16m);
	}
}

