    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var t = consoleReader.Split.Double;
            var v = new List<double>(consoleReader.Split.Double) { 0 }.ToArray();
            for (int i = N - 1; i >= 0; i--)
                v[i] = Math.Min(v[i], v[i + 1] + t[i]);

            double distance = 0;
            double velocityStart = 0;
            double velocityEnd;
            for (int i = 0; i < t.Length; i++)
            {
                if (v[i] <= v[i + 1])
                {
                    if (velocityStart + t[i] < v[i])
                    {
                        velocityEnd = velocityStart + t[i];
                        distance += (velocityStart + velocityEnd) * t[i] / 2;
                    }
                    else
                    {
                        velocityEnd = v[i];
                        var accTime = velocityEnd - velocityStart;
                        distance += (velocityStart + velocityEnd) * accTime / 2 + (t[i] - accTime) * velocityEnd;
                    }
                }
                else
                {
                    if (velocityStart + t[i] < v[i + 1])
                    {
                        velocityEnd = velocityStart + t[i];
                        distance += (velocityStart + velocityEnd) * t[i] / 2;
                    }
                    else
                    {
                        var t1 = v[i] - velocityStart;
                        var t2 = t[i] + v[i + 1] - v[i];
                        velocityEnd = v[i + 1];
                        if (t1 <= t2)
                        {
                            distance += (velocityStart + v[i]) * t1 / 2;
                            distance += v[i] * (t2 - t1);
                            distance += (velocityEnd + v[i]) * (t[i] - t2) / 2;
                        }
                        else
                        {
                            var tx = (v[i] - velocityStart) / 2;
                            var vx = velocityStart + tx;

                            distance += (velocityStart + vx) * tx / 2;
                            distance += (velocityEnd + vx) * (t[i] - tx) / 2;
                        }
                    }
                }
                velocityStart = velocityEnd;
            }
            return distance;
        }

