					int x = 2 * t[n] + u + w, run;
					if (x >= 4 * v[n]) run = 2 * (8 * t[n] * v[n] - P(2 * v[n] - u) - P(2 * v[n] - w));
					else run = P(x) - 2 * (P(u) + P(w));
					dp[n + 1][w] = Max(dp[n + 1][w], dp[n][u] + run);
				}
			}
		}
