namespace Kujikatsu008.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc076/tasks/abc076_d
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            _ = inputStream.ReadInt();
            var t = inputStream.ReadIntArray();
            var v = inputStream.ReadIntArray();
            var totalSeconds = t.Sum();
            var maxSpeed = new double[totalSeconds + 1];

            for (int i = 0; i < maxSpeed.Length; i++)
            {
                maxSpeed[i] = Math.Min(i, totalSeconds - i);
            }

            var beginTime = 0;
            for (int section = 0; section < t.Length; section++)
            {
                var endTime = beginTime + t[section];
                var baseSpeed = v[section];
                for (int time = 0; time < maxSpeed.Length; time++)
                {
                    var timeToBegin = beginTime - time;
                    var timeSinceEnd = time - endTime;
                    if (timeToBegin > 0)
                    {
                        maxSpeed[time] = Math.Min(maxSpeed[time], timeToBegin + baseSpeed);
                    }
                    else if (timeSinceEnd > 0)
                    {
                        maxSpeed[time] = Math.Min(maxSpeed[time], timeSinceEnd + baseSpeed);
                    }
                    else
                    {
                        maxSpeed[time] = Math.Min(maxSpeed[time], baseSpeed);
                    }
                }
                beginTime += t[section];
            }

            double total = 0;
            for (int time = 0; time + 1 < maxSpeed.Length; time++)
            {
                total += (maxSpeed[time] + maxSpeed[time + 1]) / 2.0;
            }

            yield return total;
        }
    }
}

