                        nex[k] = Math.Max(nex[k], dp[k - 1] + k - 0.5);
                    if (k < v[i])
                        nex[k] = Math.Max(nex[k], dp[k + 1] + k + 0.5);
                    if (j > 0 && k < v[i] || j == 0 && i > 0 && k < v[i - 1] && k < v[i])
                        nex[k] = Math.Max(nex[k], dp[k] + k + 0.25);
                    else
                        nex[k] = Math.Max(nex[k], dp[k] + k);
                }
                dp = nex;
            }
        }
        Prt(dp[0]);
        sw.Flush();
    }

    static void DBG(string a) => Console.WriteLine(a);
    static void DBG<T>(IEnumerable<T> a) => DBG(string.Join(" ", a));
