	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc
		{
			public void Solve() {
				int N = NextInt();
				var T = NextIntList();
				var sum = T.Sum() * 2;

				var a = Generate.Repeat(i => double.MaxValue, sum+1);
				var t = 0;
				a[0] = 0;
				a[sum] = 0;
				N.REP(i =>
				{
