					});
				});

				for (int i = 1; i < sum; i++) a[i] = EMin(a[i], a[i - 1] + 0.5, a[i + 1] + 0.5);
				for (int i = sum - 1; i >= 1; i--) a[i] = EMin(a[i], a[i - 1] + 0.5, a[i + 1] + 0.5);

				var ans = 0.0;
				sum.REP(i => { ans += (a[i] + a[i + 1]) / 4.0; });
