								lim[i] = pre - 1;
							}
							else if (n_sum[j] - i == pre - v[j + 1])
							{
								lim[i] = pre;
								if (a[i] > lim[i] && a[i - 1] > lim[i - 1]) qu++;
							}
						}
					}
				}
			}
			Console.WriteLine(lim.Sum() + qu * 0.25);
			//Console.ReadLine();
		}
	}
}

