                    area += vs[i] * stableTime;
                    area += (vs[i] + vs[i + 1]) * downTime * 0.5;
                }
                else
                {
                    stableTime *= -1;
                    upTime -= stableTime / 2;
                    downTime -= stableTime / 2;
                    if (stableTime % 2 == 0)
                    {
                        area += (spd * 2 + upTime) * upTime * 0.5;
                        area += ((spd + upTime) * 2 - downTime) * downTime * 0.5;
