        var p = 0;
        for (int i = 0; i < n; i++)
            foreach (var x in Enumerable.Repeat(ve[i], ti[i] * 2))
                ret[p++] = x;
        ret[0] = 0;
        var wp = 0;
        for (int i = 0; i < n-1; i++)
        {
            wp += ti[i] * 2;
            ret[wp] = Math.Min(ve[i], ve[i + 1]);
        }
        return ret;
    }
}

