import "fmt"

func run(bv, v, ev, time float64) (float64, float64) {
	cv := bv
	acc := v - bv
	dec := v - ev
	if dec < 0 {
		dec = 0
	}
	con := time - acc - dec
	if con < 0.0 {
		acc += con / 2.0
		dec += con / 2.0
		con = 0.0
	}

	ret := acc*acc/2.0 + acc*cv
	cv += acc
	ret += con * cv
	cv -= dec
	ret += dec*dec/2.0 + dec*cv
	return ret, cv
}

func main() {
	var n int
	fmt.Scan(&n)
	t := make([]float64, n)
	v := make([]float64, n)
	for i := range t {
		fmt.Scan(&t[i])
	}
	for i := range v {
		fmt.Scan(&v[i])
	}
	v = append(v, 0)

	cv := 0.0
	ans := 0.0

	for i := 0; i < n; i++ {
		l, ev := run(cv, v[i], v[i+1], t[i])
		cv = ev
		ans += l
	}

	fmt.Println(ans)
}

