        x += v[i]*(t[i]-0.5*v[i]+u) - 0.5*u*u
        u = v[i]
      } else {
        x += t[i]*(u+0.5*t[i])
        u += t[i]
      }
    } else {
      if 0.5*(u+t[i]+v[i+1]) <= v[i] {
        x += 0.25*(u+t[i]+v[i+1])*(u+t[i]+v[i+1]) - 0.5*(u*u+v[i+1]*v[i+1])
      } else {
        x += v[i]*(t[i]-v[i]+u+v[i+1]) - 0.5*(u*u+v[i+1]*v[i+1])

      }
      u = v[i+1]
    }
  }
  if 0.5*(u+t[n-1]) <= v[n-1] {
    x += 0.25*(u+t[n-1])*(u+t[n-1]) - 0.5*u*u
  } else {
