	for i := 0; i < n; i++ {
		fmt.Scan(&t[i])
	}
	//
	v := make([]float64, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&v[i])
	}

	// velocity limit set to maxv
	tdx := 1
	vdx := 0
	maxv[0] = 0
	for _, tm := range t {
		if maxv[tdx-1] > v[vdx] { // overlap point
			maxv[tdx-1] = v[vdx]
		}
		for i := 0; i < int(tm); i++ {
			maxv[tdx] = v[vdx]
			maxv[tdx+1] = v[vdx]
			tdx += 2
		}
		vdx += 1
	}

	endp := tdx - 1
	maxv[endp] = 0

	// scan from start to end
	for i := 1; i <= endp; i++ {
		maxv[i] = math.Min(maxv[i], maxv[i-1]+0.5)
	}

	// scan from end to start
	for i := endp - 1; i >= 0; i-- {
		maxv[i] = math.Min(maxv[i], maxv[i+1]+0.5)
	}

	//for debug
	//fmt.Println(t, v)
