	//  fmt.Println(i, maxv[i])
	//}

	// calc area
	area := float64(0)
	for i := 0; i < endp; i++ {
		area += maxv[i] + maxv[i+1]
	}

	fmt.Printf("%f\n", 0.25*area)
}

