func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	tt := make([]float64, n)
	vv := make([]float64, n+1)
	for i := 0; i < n; i++ {
		tt[i] = float64(getNextInt(scanner))
	}
	for i := 0; i < n; i++ {
		vv[i] = float64(getNextInt(scanner))
	}
	vv[n] = 0
	ans := solve(n, tt, vv)
	fmt.Fprintln(writer, ans)

	writer.Flush()
}

func solve(n int, tt, vv []float64) float64 {
	ans := 0.0
	xx := make([]float64, n+1)
	for i := 0; i < n; i++ {
		xx[i+1] = xx[i] + tt[i]
	}

	// 終端まで考慮した時の減速対象区間インデックス
	limits := make([]int, n+1)
	for s := 1; s <= n; s++ {
		limits[s] = s
		for t := s + 1; t <= n; t++ {
			if xx[t]+vv[t] < xx[limits[s]]+vv[limits[s]] {
				limits[s] = t
			}
		}
	}

	y := 0.0

	for i := 1; i <= n; i++ {
		// y=x+a
		a := y - xx[i-1]
		nexty := vv[limits[i]] + xx[limits[i]] - xx[i]
		// y=-x+b
		b := nexty + xx[i]

		// 加速直線と減速直線が交わるx座標
		cross := (b - a) / 2.0
		// 加速区間
		// 制限速度に達するまで
		incx := vv[i-1] - a
		// 制限速度に達する前に次の区間に到達
		if incx > xx[i] {
			incx = xx[i]
		}
		// 制限速度に達する前に減速開始
		if incx > cross {
			incx = cross
		}

		// 減速区間
		// 制限速度から
		decx := b - vv[i-1]
		// 制限速度に達する前に減速開始
		if decx < cross {
			decx = cross
		}
		// 減速の必要がない場合
		if decx > xx[i] {
			decx = xx[i]
		}
		ans += (incx - xx[i-1]) * (y*2 + incx - xx[i-1]) / 2.0
		ans += (decx - incx) * (y + incx - xx[i-1])
		nexty = y + (incx - xx[i-1]) - (xx[i] - decx)
		ans += (xx[i] - decx) * (nexty*2 + xx[i] - decx) / 2.0

		y = nexty
	}

	return ans
}

