func run(bv, v, ev, time float64) (float64, float64) {
	cv := bv
	acc := v - bv
	dec := v - ev
	if dec < 0 {
		dec = 0
	}
	con := time - acc - dec
	if con < 0.0 {
		acc += con / 2.0
		dec += con / 2.0
		con = 0.0
	}

	ret := acc*acc/2.0 + acc*cv
	cv += acc
	ret += con * cv
	cv -= dec
	ret += dec*dec/2.0 + dec*cv
	return ret, cv
}

