		nowSpeed := 10000.0
		for _, l := range L {
			var tmpSpeed float64
			if t < l.start {
				tmpSpeed = float64(l.maxspeed) + float64(l.start-t)/2
			} else if l.end < t {
				tmpSpeed = float64(l.maxspeed) + float64(t-l.end)/2
			} else {
				tmpSpeed = float64(l.maxspeed)
			}
			nowSpeed = math.Min(nowSpeed, tmpSpeed)
		}
		v[t] = nowSpeed
	}

	ans := 0.0
	for t := 1; t <= T; t++ {
		ans += (v[t] + v[t-1]) / 4
	}

