	maxv[t] = 0.0
	for i := 0; i < t; i++ {
		if maxv[i+1] > maxv[i]+0.5 {
			maxv[i+1] = maxv[i] + 0.5
		}
	}
	for i := t; i > 0; i-- {
		if maxv[i-1] > maxv[i]+0.5 {
			maxv[i-1] = maxv[i] + 0.5
		}
	}
	ans := 0.0
