const dt = 0.5

type train struct {
	v float64
	l float64
}

func (train *train) Accelerate() {
	train.l += (train.v * dt) + (math.Pow(dt, 2.0) / 2)
	train.v += dt
}

func (train *train) Constant() {
	train.l += train.v * dt
}

func (train *train) Decelerate() {
	train.l += (train.v * dt) - (math.Pow(dt, 2.0) / 2)
	train.v -= dt
}

func main() {
	var n int
	fmt.Scan(&n)

	tArray, vArray := make([]float64, n+1), make([]float64, n+1)
	for i := 0; i < n; i++ {
		fmt.Scan(&tArray[i])
	}
	tArray[n] = 0.0
	for i := 0; i < n; i++ {
		fmt.Scan(&vArray[i])
	}
	vArray[n] = 0.0

	var train = train{0.0, 0.0}
	for i := 0; i < n; i++ {
		for t := 0.0; t < tArray[i]; t += dt {
			switch {
			case tArray[i]-t <= train.v-vArray[i+1]:
				train.Decelerate()
			case train.v == vArray[i]:
				train.Constant()
			default:
				train.Accelerate()
			}
		}
	}

	fmt.Println(train.l)
}

