auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	input.popFront;
	auto ts = input.front.split.to!( long[] );
	input.popFront;
	auto vs = input.front.split.to!( long[] );
	return tuple( ts, vs );
}

auto solve( long[] ts, long[] vs )
{
	// 速度上限配列から時間基準の速度配列を作成
	auto ss = new double[ 100 * 200 * 2 + 2 ];
	auto tt = 1L;
	ss[ 0 ] = 0;
	foreach( t, v; lockstep( ts, vs ) )
	{
		auto t2 = t * 2;		// 奇数秒を2で割る場合があるので、時間を0.5秒区切りにして整数で扱えるようにする
		ss[ tt - 1 ] = min( ss[ tt - 1 ], v );
		ss[ tt .. tt + t2 ] = v;
		tt += t2;
	}
	ss.length = tt;
	ss[ $ - 1 ] = 0;

	// 加速を計算
	for( auto i = 0L; i < ss.length.signed - 1; i++ )
	{
		if( ss[ i ] < ss[ i + 1 ] ) ss[ i + 1 ] = ss[ i ] + 0.5;		// 時間が0.5秒区切りなので1m/s^2の半分を加算
	}

	// 減速を計算
	for( auto i = ss.length.signed - 1; 0 < i; i-- )
	{
		if( ss[ i ] < ss[ i - 1 ] ) ss[ i - 1 ] = ss[ i ] + 0.5;		// 時間が0.5秒区切りなので1m/s^2の半分を加算
	}

	// 合計距離を計算
	auto ans = ss.sum / 2;		// 時間を0.5秒区切りから1秒区切りに戻す
	return format( "%0.3f", ans );
}

void main(){
  import std.stdio, std.string, std.conv, std.algorithm;

  int n; rd(n);
  auto ts=readln.split.to!(int[]);
  auto vs=readln.split.to!(int[]);

  foreach(i; 1..n) ts[i]+=ts[i-1];

  int T=100*200*2+1, V=100*2+1;
  auto dp=new double[][](T, V);
  foreach(i; 0..T)foreach(j; 0..V) dp[i][j]=-1;
  dp[0][0]=0;
  int t=0;
  foreach(i; 0..n){
    do{
      for(int v=0; v<=vs[i]*2; v++)if(dp[t][v]>=0){
        chmax(dp[t+1][v], dp[t][v]+v);
        if(v+1<=vs[i]*2) chmax(dp[t+1][v+1], dp[t][v]+(v+(v+1))/2.0);
        if(v-1>=0) chmax(dp[t+1][v-1], dp[t][v]+(v+(v-1))/2.0);
      }
    }while((++t)<ts[i]*2);
  }

  writefln("%.18f", dp[ts[$-1]*2][0]/4.0);
}

void chmax(T)(ref T l, T r){if(l<r)l=r;}

