struct Factor
{
    long n;
    long c;
}

Factor[] factors(long n)
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        int c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
long[] primes(long n)
{
    if(n<2)return [];
    auto table = new long[n+1];
    long[] res;
    for(int i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(int a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
bool isPrime(long n)
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

void main() {
  import std.stdio, std.string, std.conv, std.algorithm;

  int n;
  rd(n);
  auto t = readln.split.to!(int[]);
  auto v = readln.split.to!(int[]);

  t.each!((ref _t) => (_t *= 2));
  v.each!((ref _v) => (_v *= 2));
  auto T = reduce!"a+b"(t), V = reduce!(max)(v);
  auto dp = new int[][](T + 1, V + 1);
  for (int i = 0; i <= T; i++) {
    for (int j = 0; j <= V; j++) {
      dp[i][j] = -1;
    }
  }
  dp[0][0] = 0;
  int tm = 0;
  foreach (i; 0 .. n) {
    foreach (j; tm .. (tm + t[i])) {
      for (int k = 0; k <= v[i]; k++) {
        if (dp[j][k] >= 0) {
          chmax(dp[j + 1][k], dp[j][k] + k * 2);
          if (k + 1 <= v[i]) {
            chmax(dp[j + 1][k + 1], dp[j][k] + k * 2 + 1);
          }
          if (k - 1 >= 0) {
            chmax(dp[j + 1][k - 1], dp[j][k] + k * 2 - 1);
          }
        }
      }
    }
    tm += t[i];
  }
