void solve(){
    int n = scan!int;
    int[] ts = scan!int(n);
    int[] vs = scan!int(n);

    int[] hs = new int[](ts.sum * 2 + 1);
    hs.fill(200);

    int tsum = 0;
    foreach(int i; 0 .. n){
        int t = ts[i] * 2, v = vs[i] * 2;
        foreach(int k; 0 .. hs.length.to!int){
            if(k < tsum) hs[k].lowerTo(v + tsum - k);
            else if(k < tsum + t) hs[k].lowerTo(v);
            else hs[k].lowerTo(v + k - tsum - t);
        }
        tsum += t;
    }
    foreach(int k; 0 .. hs.length.to!int){
        hs[k].lowerTo(k);
        hs[k].lowerTo(tsum - k);
    }
    log("hs:", hs);
    log("hs:", iota((tsum + 1) / 2).map!(i => hs[i * 2] / 2).array);

    real ans = 0.0;
    foreach(k; 0 .. hs.length - 1){
        ans += (hs[k].to!real + hs[k + 1].to!real) / 8.0;
    }
    ans.writeln;

}

