void endCalc(Data[] datas, long endSpeed){
    if(datas.empty) return;

    auto data = datas[$-1];

    datas[$-1].endSpeed = endSpeed;

    endCalc(datas[0..$-1], min(endSpeed + data.time, data.maxSpeed));
}

real func(Data[] datas, real speed, real allRun){
    if(datas.empty) return allRun;

    auto data = datas[0];
    auto maxSpeed = (data.time - abs(data.endSpeed - speed)) / 2.0 + max(speed, data.endSpeed);
    maxSpeed = min(maxSpeed, speed+data.time);
    maxSpeed = min(maxSpeed, data.maxSpeed);


    real time1, time2, time3;
    time1 = maxSpeed - speed;
    time3 = max(0, maxSpeed - data.endSpeed);
    time2 = data.time - time1 - time3;
    allRun += speed * time1 + 0.5 * time1 * time1;
    allRun += maxSpeed * time2;
    allRun += maxSpeed * time3 + 0.5 * time3 * time3 * -1;
    return func(datas[1..$], speed + time1 - time3, allRun);
}

