void main()
{
	auto N = RD!long;
	auto t = 0 ~ RDR.split.to!(long[]) ~ 0;
	auto v = 0 ~ RDR.split.to!(double[]) ~ 0;

	double ans = 0.0;
	foreach (i; 1..N+1)
	{
		auto diff1 = v[i] > v[i-1] ? cast(double)abs(v[i] - v[i-1]) : 0.0;
		auto diff2 = v[i] > v[i+1] ? cast(double)abs(v[i+1] - v[i]) : 0.0;
		auto mid   = t[i] - diff1 - diff2;
		if (mid < 0)
		{
			auto l = min(v[i-1], v[i]);
			auto r = min(l + t[i], v[i+1]);
			auto diff3 = l - r;
			auto top = (t[i] + abs(diff3)) / 2.0 - max(0, diff3);
			diff1 = top;
			diff2 = t[i] - top;
			v[i]  = v[i-1] + top;
			mid = 0;
		}
		if (diff1 > 0.0)
			ans += v[i-1] * diff1 + pow(diff1, 2) / 2;
		if (diff2 > 0.0)
			ans += v[i+1] * diff2 + pow(diff2, 2) / 2;
		ans += v[i] * mid;
		stderr.writeln(ans);
	}

	writeln(ans);
	stdout.flush();
}

