auto velocity(real x, int[] t, int[] v, int end)
{
    return t.length.iota.map!(i => limit(i, x, t, v)).reduce!min
        .min(x).min(end-x);
}

auto limit(size_t i, real x, int[] t, int[] v)
{
    int pos;
    int[] start, end;
    foreach (ts; t)
    {
        start ~= pos;
        pos += ts;
        end ~= pos;
    }
    stderr.writeln("start = ", start);
    stderr.writeln("end = ", end);

    if (x < start[i])
    {
        return v[i] + (start[i] - x);
    }
    if (end[i] < x)
    {
        return v[i] + (x - end[i]);
    }
    return v[i];
}

