auto velocity(real x, int[] start, int[] end, int[] v)
{
    return v.length.iota.map!(i => limit(x, start[i], end[i], v[i])).reduce!min
        .min(x).min(end[$-1]-x);
}

auto limit(real x, int start, int end, int v)
{

    if (x < start)
    {
        return v + (start - x);
    }
    if (end < x)
    {
        return v + (x - end);
    }
    return v;
}

