auto solve( long[] ts, long[] vs )
{
	// 速度上限配列から時間基準の速度配列を作成
	auto ss = new double[ 100 * 200 * 2 + 2 ];
	auto tt = 1L;
	ss[ 0 ] = 0;
	foreach( t, v; lockstep( ts, vs ) )
	{
		auto t2 = t * 2;		// 奇数秒を2で割る場合があるので、時間を0.5秒区切りにして整数で扱えるようにする
		ss[ tt - 1 ] = min( ss[ tt - 1 ], v );
		ss[ tt .. tt + t2 ] = v;
		tt += t2;
	}
	ss.length = tt;
	ss[ 0 ] = 0;
	ss[ $ - 1 ] = 0;

	// 加速を計算
	for( auto i = 0L; i < ss.length.signed - 1; i++ )
	{
		if( ss[ i ] < ss[ i + 1 ] ) ss[ i + 1 ] = ss[ i ] + 0.5;		// 時間が0.5秒区切りなので1m/s^2の半分を加算
	}

	// 減速を計算
	for( auto i = ss.length.signed - 1; 0 < i; i-- )
	{
		if( ss[ i ] < ss[ i - 1 ] ) ss[ i - 1 ] = ss[ i ] + 0.5;
	}

	// 速度変更のタイミングを抽出
	double[] pts;
	double[] pvs;
	double[] pas;
	auto a = 2.0;
	foreach( i, s; ss[ 0L .. $ - 1 ] )
	{
		auto b = sgn( ss[ i + 1 ] - ss[ i ] );
		if( a == b ) continue;
		pts ~= i / 2.0;		// 時間を0.5秒区切りから1秒区切りに戻す
		pvs ~= ss[ i ];
		pas ~= b;
		a = b;
	}
	pts ~= ( ss.length.signed - 1 ) / 2;
	pvs ~= 0;
	pas ~= 0;

	// 合計距離を計算
	auto ans = 0.0;
	for( auto i = 0L; i < pts.length.signed - 1; i++ )
	{
		auto t = pts[ i + 1 ] - pts[ i ];
		ans += pvs[ i ] * t + 0.5 * pas[ i ] * ( t ^^ 2 );
	}
	return format( "%0.3f", ans );
}

