int main() {
    Scanner sc = new Scanner(stdin);
    int n;
    sc.read(n);
    int[] t;
    sc.read(t);
    int[] v;
    sc.read(v);

    int[] le = new int[n+1];
    int[] ri = new int[n+1];

    le[0] = 0;
    foreach (i; 0..n) {
        le[i+1] = min(le[i] + t[i], v[i]);
    }
    ri[n] = 0;
    foreach_reverse (i; 0..n) {
        ri[i] = min(ri[i+1] + t[i], v[i]);
    }

//    writeln(le);
//    writeln(ri);
    foreach (i; 0..n+1) {
        le[i] = min(le[i], ri[i]);
    }

    double calc(int l, int r, int v, int t) {
        assert(l <= v && r <= v);
        int us = (v-l) + (v-r);
        if (t <= us) {
            double md = v - (us - t) / 2.0;
            return ((l+md) * (md-l) + (r+md) * (md-r)) / 2.0;
        }
        return ((l+v) * (v-l) + (r+v) * (v-r)) / 2.0 + v * (t - us);
    }

    double sm = 0;
    foreach (i; 0..n) {
//        writeln(le[i], " ", le[i+1], " ", v[i], " ", t[i], " : ", calc(le[i], le[i+1], v[i], t[i]));
        sm += calc(le[i], le[i+1], v[i], t[i]);
    }
//    writeln(le);
    writefln("%.20f", sm);
    return 0;
}
