import std.concurrency;
import core.bitop : popcnt;
alias Generator = std.concurrency.Generator;

void main() {
    int N;
    scanln(N);
    double[] ts = readln.split.to!(double[]).cumulativeFold!"a+b"(0.0).array;
    double[] vs = readln.split.to!(double[]);
    ts = [.0]~ts~ts.back;
    vs = [.0]~vs~[.0];
    float T = ts.back;

    auto f = (N+2).iota.map!(
        i => (
            (double t) => vs[i] + max(0, ts[max(0, i-1)]-t, t-ts[i])
        )
    ).fold!(
        (g, h) => (double t) => min(g(t), h(t))
    );

    new Generator!double({
        int M = 1000000;
        foreach(i; 0..M) {
            double l = T*i/M;
            double r = T*(i+1)/M;
            double lv = f(l);
            double rv = f(r);
            double w = T/M;
            yield(w*min(lv, rv) + w*abs(rv - lv)/2);
        }
    }).sum.pipe!(a => writefln("%.5f", a));

}

