// cumulativeFold was added in D 2.072.0
static if (__VERSION__ < 2072) {
    template cumulativeFold(fun...)
    if (fun.length >= 1)
    {
        import std.meta : staticMap;
        private alias binfuns = staticMap!(binaryFun, fun);

        auto cumulativeFold(R)(R range)
        if (isInputRange!(Unqual!R))
        {
            return cumulativeFoldImpl(range);
        }

        auto cumulativeFold(R, S)(R range, S seed)
        if (isInputRange!(Unqual!R))
        {
            static if (fun.length == 1)
                return cumulativeFoldImpl(range, seed);
            else
                return cumulativeFoldImpl(range, seed.expand);
        }

        private auto cumulativeFoldImpl(R, Args...)(R range, ref Args args)
        {
            import std.algorithm.internal : algoFormat;

            static assert(Args.length == 0 || Args.length == fun.length,
                algoFormat("Seed %s does not have the correct amount of fields (should be %s)",
                    Args.stringof, fun.length));

            static if (args.length)
                alias State = staticMap!(Unqual, Args);
            else
                alias State = staticMap!(ReduceSeedType!(ElementType!R), binfuns);

            foreach (i, f; binfuns)
            {
                static assert(!__traits(compiles, f(args[i], e)) || __traits(compiles,
                        { args[i] = f(args[i], e); }()),
                    algoFormat("Incompatible function/seed/element: %s/%s/%s",
                        fullyQualifiedName!f, Args[i].stringof, E.stringof));
            }

            static struct Result
            {
            private:
                R source;
                State state;

                this(R range, ref Args args)
                {
                    source = range;
                    if (source.empty)
                        return;

                    foreach (i, f; binfuns)
                    {
                        static if (args.length)
                            state[i] = f(args[i], source.front);
                        else
                            state[i] = source.front;
                    }
                }

            public:
                @property bool empty()
                {
                    return source.empty;
                }

                @property auto front()
                {
                    assert(!empty, "Attempting to fetch the front of an empty cumulativeFold.");
                    static if (fun.length > 1)
                    {
                        import std.typecons : tuple;
                        return tuple(state);
                    }
                    else
                    {
                        return state[0];
                    }
                }

                void popFront()
                {
                    assert(!empty, "Attempting to popFront an empty cumulativeFold.");
                    source.popFront;

                    if (source.empty)
                        return;

                    foreach (i, f; binfuns)
                        state[i] = f(state[i], source.front);
                }

                static if (isForwardRange!R)
                {
                    @property auto save()
                    {
                        auto result = this;
                        result.source = source.save;
                        return result;
                    }
                }

                static if (hasLength!R)
                {
                    @property size_t length()
                    {
                        return source.length;
                    }
                }
            }

            return Result(range, args);
        }
    }
}

// minElement/maxElement was added in D 2.072.0
static if (__VERSION__ < 2072) {
    auto minElement(alias map, Range)(Range r)
    if (isInputRange!Range && !isInfinite!Range)
    {
        alias mapFun = unaryFun!map;
        auto element = r.front;
        auto minimum = mapFun(element);
        r.popFront;
        foreach(a; r) {
            auto b = mapFun(a);
            if (b < minimum) {
                element = a;
                minimum = b;
            }
        }
        return element;
    }
    auto maxElement(alias map, Range)(Range r)
    if (isInputRange!Range && !isInfinite!Range)
    {
        alias mapFun = unaryFun!map;
        auto element = r.front;
        auto maximum = mapFun(element);
        r.popFront;
        foreach(a; r) {
            auto b = mapFun(a);
            if (b > maximum) {
                element = a;
                maximum = b;
            }
        }
        return element;
    }
}

import std.stdio, std.string, std.conv, std.algorithm;

void main() {
	int N = readln().chomp().to!(int);
	int t[] = readln().chomp().split().to!(int[]);
	int v[] = readln().chomp().split().to!(int[]);
	v ~= 0;

	long [210][2] dp;
	dp[0][0] = 1;
	foreach(int i; 0..N) {t[i] *= 2; v[i] *= 2;}
	foreach(int i; 1..N) {
		t[i] += t[i-1];
	}
	int s = t[N-1];
	int k = 0;
	foreach(int i; 1..(s+1)) {
		while(t[k] < i) k++;
		foreach(int j; 0..210) dp[i&1][j] = 0;

		int vv = v[k];
		if(t[k] == i) vv = min(vv, v[k+1]);
		foreach(int j; 0..(vv+1)) {
			if(dp[1^i&1][j] != 0)
				dp[i&1][j] = max(dp[i&1][j], dp[1^i&1][j] + j*2);
			if(dp[1^i&1][j+1] != 0)
				dp[i&1][j] = max(dp[i&1][j], dp[1^i&1][j+1] + j*2+1);
			if(j-1>=0 && dp[1^i&1][j-1] != 0)
				dp[i&1][j] = max(dp[i&1][j], dp[1^i&1][j-1] + j*2-1);
		}
	}
	writeln((dp[s&1][0]-1) / 8.0);
}

void main(){
  import std.stdio, std.string, std.conv, std.algorithm;
  import std.typecons, std.math;

  int n; rd(n);
  auto _t=readln.split.to!(int[]);
  auto _v=readln.split.to!(int[]);

  alias S=Tuple!(int, "l", int, "r");
  auto seq=new S[](n);
  foreach(ref e; seq) e.l=-1, e.r=-1;
  alias Data=Tuple!(int, "v", int, "t", int, "i");
  auto data=new Data[](0);
  foreach(i; 0..n) data~=Data(_v[i], _t[i], i);
  sort(data);
  seq[0].l=seq[$-1].r=0;
  double sum=0;
  foreach(e; data){
    auto i=e.i, v=e.v, t=e.t;
    if(seq[i].l>=0 && seq[i].r>=0){
      auto u1=min(seq[i].l, seq[i].r);
      auto u2=max(seq[i].l, seq[i].r);
      sum+=u1*t;
      if((v-u1)+(v-u2)<=t){
        sum+=(v-u1)*(v-u1)*0.5;
        sum+=((u2-u1)+(v-u1))*(v-u2)*0.5;
        sum+=(v-u1)*(t-((v-u1)+(v-u2)));
      }else{
        auto x=(t+u2-u1)*0.5;
        sum+=x*x*0.5+(x+(u2-u1))*(t-x)*0.5;
      }
    }else if(seq[i].l<0 && seq[i].r<0){
      sum+=v*t;
      if(i-1>=0) seq[i-1].r=v;
      if(i+1<n) seq[i+1].l=v;
    }else{
      auto u=max(seq[i].l, seq[i].r);
      sum+=u*t;
      if(v-u<=t) sum+=(t-(v-u)+t)*(v-u)*0.5;
      else sum+=t*t*0.5;
      if(seq[i].l<0 && i-1>=0) seq[i-1].r=min(v, t+u);
      if(seq[i].r<0 && i+1<n) seq[i+1].l=min(v, t+u);
    }
  }
  writefln("%.10f", sum);
}

void rd(T...)(ref T x){
  import std.stdio, std.string, std.conv;
  auto l=readln.split;
  foreach(i, ref e; x){
    e=l[i].to!(typeof(e));
  }
}

