import std.stdio, std.conv, std.string;
import std.algorithm, std.array, std.container, std.typecons;
import std.numeric, std.math;
import core.bitop;

T RD(T = string)() { static string[] ss; while(!ss.length) ss = readln.chomp.split; string res = ss[0]; ss.popFront; return res.to!T; }
string RDR()() { return readln.chomp; }
T[] ARR(T)(in string str) { return str.split.to!(T[]); }
size_t[] MAKE_IDX(alias less = "a < b", Range)(Range range) { auto idx = new size_t[](range.length); makeIndex!(less)(range, idx); return idx;}
size_t MIN_POS(alias less = "a < b", Range)(Range range) { auto r = minPos!(less)(range); return range.length - r.length; }

bool INSIDE(T)(T x, T b, T e) { return x >= b && x < e; }

long mod = pow(10, 9) + 7;
void moda(ref long x, long y) { x = (x + y) % mod; }
void mods(ref long x, long y) { x = ((x + mod) - (y % mod)) % mod; }
void modm(ref long x, long y) { x = (x * y) % mod; }

struct UnionFind
{
	void init(long n) { par = new long[](n); foreach (i; 0..n) par[i] = i; }
	long root(long i) { return par[i] == i ? i : (par[i] = root(par[i])); }
	bool same(long i, long j) { return root(i) == root(j); }
	void unite(long i, long j) { i = root(i); j = root(j); if (i == j) return; par[i] = j; }
	long[] par;
}

void main()
{
	auto N = RD!long;
	auto t = 0 ~ RDR.split.to!(long[]) ~ 0;
	auto v = 0 ~ RDR.split.to!(double[]) ~ 0;

	double ans = 0.0;
	foreach (i; 1..N+1)
	{
		auto upT   = v[i] > v[i-1] ? cast(double)abs(v[i] - v[i-1]) : 0.0;
		auto downT = v[i] > v[i+1] ? cast(double)abs(v[i+1] - v[i]) : 0.0;
		auto consT = t[i] - upT - downT;
		if (consT < 0)
		{
			auto lv = min(v[i-1], v[i]);
			auto rv = min(lv + t[i], v[i+1]);
			auto diff = lv - rv;
			auto top = (t[i] + abs(diff)) / 2.0;
			upT = top - max(0, diff);
			downT = t[i] - upT;
			v[i]  = v[i-1] + upT;
			consT = 0.0;
		}
		if (upT > 0.0)
			ans += v[i-1] * upT + pow(upT, 2) / 2;
		if (downT > 0.0)
			ans += v[i+1] * downT + pow(downT, 2) / 2;
		ans += v[i] * consT;
		stderr.writeln(ans);
	}

	writefln("%.18f", ans);
	stdout.flush();
}

