		if (upT > 0.0)
			ans += v[i-1] * upT + pow(upT, 2) / 2;
		if (downT > 0.0)
			ans += v[i+1] * downT + pow(downT, 2) / 2;
		ans += v[i] * consT;
		stderr.writeln(ans);
	}

	writeln(ans);
	stdout.flush();
}

