import scipy.integrate as itgr
#積分用のvの関数
def vfunc(t,vin, vout, supv, T):
    if 2*t <= (T + vout - vin):
        v = t + vin
    else:
        v = - t + T + vout
    if v > supv:
        v = supv
    return v

