def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, T, V):

    T.append(0)
    V.append(0)

    # t, v
    vs = [0] * (sum(T)*2 + 1)

    i = 1
    for t, v in zip(T, V):
        if vs[i-1] > v:
            diff = vs[i-1]-v
            for j in range(int(diff/0.5)):
                vs[i-1-j] = min(vs[i-1-j], v + j*0.5)
        for _ in range(t*2):
            vs[i] += min(vs[i-1]+0.5, v)
            i += 1

    ans = 0
    for i in range(len(vs)-1):
        d = vs[i+1] - vs[i]
        ans += vs[i]*0.5
        ans += (d*0.5)/2
    # print(vs)
    return ans


