    mod=10**9+7
    N=I()
    t=LI()
    mv=LI()
    mv.append(0)



    #v0で始まってv1でおわる,最高vmまで出して良い,t廟の区間
    def calc(v0,v1,vm,t):
        vv = (t-abs(v1-v0))/2+max(v0,v1) #vmを気にしなければどこまで上がれるか

        if abs(v1-v0)==t:
            return (v0+v1)*t/2
        elif v1==vm or v0==vm:
            return (v1+v0)*(v1-v0)/2 +v1*(t-abs((v1-v0)))
        elif vv<vm:
            return (vv+v0)*(vv-v0)/2 + (vv+v1)*(vv-v1)/2
        else:
            return (v0+vm)*(vm-v0)/2 + vm*(t-(vm-v0)-(vm-v1)) + (vm+v1)*(vm-v1)/2 


    #区間端での速度,手前から決めていき，無理が生じたら手前を下げていく(Nが小さいので)
    v=[1000]*(N+1)
    v[0]=0
