def calculate_distance(v0,v1,v2,t):
    if v0+t <= v1 and v0+t <= v2:
        return ((v0 + t) * t) - ((t**2) / 2), v0 + t
    elif v0 + t >= v1 and v0 + t <= v2:
        return (v1 * t) - (((v1 - v0) ** 2) / 2), v1
    elif v0 + t >= v2 and v2 >= v1:
        return (v1 * t) - (((v1 - v0) ** 2) / 2), v1
    else:
        t1 = v1 - v0
        t2 = t - v1 + v2
        if t1 <= t2:
            return (v1 * t) - ((t1 ** 2) / 2) - (((t - t2) ** 2) / 2), v2
        else:
            t3 = (t1 + t2) / 2
            if t3 <= 0:
                return (t * v0) / 2, v2
            else:
                return ((v0 + t3) * t) - ((t3 ** 2) / 2) - (((t - t3) ** 2) / 2), v2

