def slv(N, T, V):

    T.append(0)
    V.append(0)

    df = 0.1
    # t, v
    vs = [0] * int(sum(T)*(1/df) + 1)

    i = 1
    for t, v in zip(T, V):
        if vs[i-1] > v:
            diff = vs[i-1]-v
            for j in range(int(diff/df)):
                vs[i-1-j] = min(vs[i-1-j], v + j*df)
        for _ in range(t*int(1/df)):
            vs[i] += min(vs[i-1]+df, v)
            i += 1

    ans = 0
    for i in range(len(vs)-1):
        d = vs[i+1] - vs[i]
        ans += vs[i]*df
        ans += (d*df)/2
    # print(vs)
    return ans


