def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, T, V):

    T.append(0)
    V.append(0)

    df = 0.5
    # t, v
    vs = [0] * int(sum(T)*(1/df) + 2)

    i = 1
    for t, v in zip(T, V):
        # error_print(vs)
        if vs[i-1] > v:
            diff = vs[i-1]-v
            for j in range(0, int(diff/df)):
                if vs[i-1-j] <= v + j*df:
                    break
                vs[i-1-j] = min(vs[i-1-j], v + j*df)
        for _ in range(t*int(1/df)):
            vs[i] = min(vs[i-1]+df, v)
            i += 1

    ans = 0
    for i in range(len(vs)-1):
        d = vs[i+1] - vs[i]
        ans += vs[i]*df
        ans += (d*df)/2
    return ans


