def getDistanceSegment(sStart, sEnd, length, sMax):
    tresult = [0]
    vresult = [sStart]

    decelPoint = (length + sEnd - sStart)/2
    decel = (length + sEnd + sStart)/2

    sMaxPoint = sMax - sStart
    decelFromMax = length - sMax + sEnd

    if sMaxPoint < decelPoint:
        tresult += [sMaxPoint]
        vresult += [sMax]
        if sEnd >= sMax:
            tresult += [length]
            vresult += [sMax]
        else:
            tresult += [decelFromMax, length]
            vresult += [sMax, sEnd]
    else:
        tresult += [decelPoint, length]
        vresult += [decel, sEnd]

    return solveDistance(tresult,vresult)

