fn minf(a:f64,b:f64) -> f64 {
    if a<b { a } else { b }
}
fn solve() {
    input! {
        N: usize,
        T: [usize;N],
        V: [f64;N],
    }
    let mut t_sum = 0;
    for &t in &T {
        t_sum += t;
    }
    let mut dp = vec![100000000000000.0 as f64; t_sum*2+1];
    let mut acc = 0;
    for i in 0..N {
        let t = T[i];
        let v = V[i];
        for i in acc..acc+t*2+1 {
            dp[i] = minf(dp[i], v);
        }
        acc += t*2;
    }
    // dbg!(&dp);

    for i in 0..T[0]*2+1 {
        dp[i] = minf(dp[i],0.5*(i as f64));
    }

    let mut acc = 0;
    for i in 0..N-1 {
        acc += T[i]*2;
        let left_v = V[i];
        let left_t = T[i];
        let right_v = V[i+1];
        let right_t = T[i+1];
        if left_v < right_v {
            for i in 0..right_t*2+1 {
                dp[acc+i] = minf(dp[acc+i],left_v+(i as f64)*0.5);
            }
        } else {
            for i in 0..left_t*2+1 {
                dp[acc-i] = minf(dp[acc-i],right_v+(i as f64)*0.5);
            }
        }
    }

    acc += T[N-1]*2;
    for i in 0..T[N-1]*2+1 {
        dp[acc-i] = minf(dp[acc-i],0.5*(i as f64));
    }
    // dbg!(&dp);

    // dbg!(&dp);

    let mut ans: f64 = 0.0;
    for i in 0..t_sum*2 {
        let v0 = dp[i];
        let v1 = dp[i+1];
        ans += (v0+v1)*0.5/2.0;
    }
    dbg!(ans);
