    }

    let mut lim = vec![];

    for i in 0..n {
        for _ in 0..t[i] {
            lim.push(v[i]);
        }
    }

    let mut tbl = vec![vec![None; lim.len()]; 100 + 1];
    let ans = solve(0, 0, &lim, &mut tbl);
    println!("{}", ans);
}

fn solve(t: i64, v: i64, lim: &[i64], tbl: &mut Vec<Vec<Option<f64>>>) -> f64 {
    if t as usize  >= lim.len() {
        return if v == 0 { 0.0 } else { -1.0 };
    }

    if v < 0 || t > 0 && v > lim[t as usize] {
        return -1.0;
    }

    if let Some(ret) = tbl[v as usize][t as usize] {
        return ret;
    }

    let mut ans = -1.0_f64;
    for &dv in &[-1, 0, 1] {
        if v + dv > lim[t as usize] {
            continue;
        }

        let cur = solve(t + 1, v + dv, lim, tbl);
        if cur < 0.0 {
            continue;
        }

        let dd = (v + v + dv) as f64 / 2.0 +
            if dv == 0 && v + 1 <= lim[t as usize] {0.25} else {0.0};

        ans = ans.max(cur + dd);
    }

    tbl[v as usize][t as usize] = Some(ans);
    ans
}

