fn minf(x: f64, y: f64) -> f64 {
  use std::cmp::Ordering::*;
  match x.partial_cmp(&y) {
    Some(Less) => x,
    Some(Equal) => x,
    Some(Greater) => y,
    _ => unreachable!(),
  }
}

