fn max_v(s:u32, e:u32, v: u32, t: f32) -> f32 {
    let s = s as f32;
    let e = e as f32;
    let v = v as f32;

    if t < s {
        v + (s-t) 
    } else if e < t {
        v + (t - e)
    } else {
        v
    }
}

use std::collections::VecDeque;

fn solve(mut ts: VecDeque<u32>, mut vs: VecDeque<u32>) -> f32 {
    let a = 0;

    ts.push_front(0);
    ts.push_back(0);
    vs.push_front(0);
    vs.push_back(0);

    let total_t: u32 = ts.iter().cloned().sum();
    let mut dist = 0.0;
    let mut last_v = 0.0;

    for t in 1..(total_t*2+1) {
        let t = t as f32 / 2.0;

        let mut min_v = std::f32::MAX;
        let mut acc_t = 0;
        for i in 0..vs.len() {
            let v = vs[i];
            let rt = ts[i];

            let mv = max_v(acc_t, acc_t + rt, v, t);
            if mv < min_v {
                min_v = mv;
            }
            acc_t += rt;
        }
        dist += 0.25*(last_v + min_v);
        last_v = min_v;
    }

    dist
}

