                // debug!(vs[i]);
            }
        }
    }
    // d = v0*t + t*t/2
    let mut v0 = 0.0;
    let mut ans = 0.0;
    for i in 0..n {
        let t = ts[i];
        let v1 = vs[i];
        let v2 = vs[i+1].min(v1);
        assert!(v1 >= v0);

        let mut t1 = (v2 + t - v0) / 2.0;
        t1 = t1.min(t);

        let t2 = t - t1;
        let nx_v = v0 + t1 - t2;

        // 左側
        let mut dist = v0 * t1 + t1*t1/2.0;

        // 右側
        dist += (v0 + t1) * t2 - t2*t2/2.0;

        // 超過した分
        if v1 <= v0 + t1 {
            let t3 = v0 + t1 - v1;
            dist += t3 * v1 * 2.0;
            dist -= (v1 * t3 + (t3*t3)/2.0) * 2.0;
        }
        // debug!(dist, v0, v1, v2, nx_v, t, t1, t2);

        v0 = v0 + t1 - t2;
        ans += dist;
    }
    puts!("{}\n", ans);
}

