use input::*;

fn get_limit(p: f64, t: &Vec<f64>, v: &Vec<f64>) -> f64 {
    let mut res = 999999999.0;

    let mut offset = 0.0;
    for i in 0..t.len() {
        let buf = (offset - p).abs() + v[i];
        if res > buf {
            res = buf;
        }
        let buf = (offset - p + t[i]).abs() + v[i];
        if res > buf {
            res = buf;
        }
        if offset <= p && p <= offset + t[i] {
            let buf = v[i];
            if res > buf {
                res = buf;
            }
        }
        offset += t[i];
    }

    res
}

fn main() {
    let n: usize;
    input!(n);

    let mut t = input_vector::<f64>();
    let mut v = input_vector::<f64>();
    t.push(0.0);
    v.push(0.0);
    t.insert(0, 0.0);
    v.insert(0, 0.0);

    let sum_t = t.iter().sum::<f64>();

    let mut time = 0.0;
    let mut ans = 0.0;

    while time < sum_t {
        let l1 = get_limit(time, &t, &v);
        let l2 = get_limit(time + 0.5, &t, &v);
        //println!("{} {}", time, l1);
        ans += (l1 * 0.5 + l2 * 0.5) / 2.0;

        time += 0.5;
    }
    println!("{}", ans);
}

