fn main() {
  let n = get::val::<usize>();
  let ts = get::vec::<usize>();
  let vs = get::vec::<usize>();

  let t_end = ts.iter().sum::<usize>();

  let lrs = {
    let mut buf = vec![];
    let mut acc = 0;
    buf.push((0,0));
    for t in ts {
      buf.push((acc,acc+t));
      acc += t
    }
    buf.push((acc,acc));
    buf
  };

  let mut ans = 0.0;
