use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      ts: [f64; n],
      mut vs: [f64; n],
    }

    vs.push(0.0);
    let mut v2s = vec![0.0; n];
    for i in 0..n {
        let mut v0 = if i == 0 { 0.0 } else { v2s[i-1] };
        let t = ts[i];
        let v1 = vs[i];
        let mut v2 = v0 + t;
        v2 = v2.min(v1).min(vs[i+1]);

        if v0 > v2 && v0-v2 > t {
            v0 = v2 + t;
            v2s[i-1] = v0;
        }
        v2s[i] = v2;
    }

    // d = v0*t + t*t/2
    let mut v0 = 0.0;
    let mut ans = 0.0;
    for i in 0..n {
        let t = ts[i];
        let v1 = vs[i];
        let v2 = v2s[i];
        assert!(v1 >= v0);

        // debug!(t, v0, v1, v2);

        let mut t1 = (v2 + t - v0) / 2.0;
        t1 = t1.min(t);

        let t2 = t - t1;
        let nx_v = v0 + t1 - t2;

        // 左側
        let mut dist = v0 * t1 + t1*t1/2.0;

        // 右側
        dist += (v0 + t1) * t2 - t2*t2/2.0;

        // 超過した分
        if v1 <= v0 + t1 {
            let t3 = v0 + t1 - v1;
            dist += t3 * v1 * 2.0;
            dist -= (v1 * t3 + (t3*t3)/2.0) * 2.0;
        }
        // debug!(dist, v0, v1, v2, nx_v, t, t1, t2);

        v0 = v0 + t1 - t2;
        ans += dist;
    }
    puts!("{}\n", ans);
}

use std::io::{BufRead, Write};
use std::io;
use std::iter;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let n: usize = buf.trim_right().parse().unwrap();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let t: Vec<usize> = buf.split_whitespace().map(|x| x.parse().unwrap()).chain(iter::once(0)).collect();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let v: Vec<usize> = buf.split_whitespace().map(|x| x.parse().unwrap()).chain(iter::once(0)).collect();
    assert!(n == t.len() - 1 && n == v.len() - 1);
    let mut result = 0.;
    let mut current_speed = 0.;
    for i in 0..n {
        let mut accu = 0;
        let target_speed = (i + 1..n + 1).map(|j| {
            let ret = v[j] + accu;
            accu += t[j];
            ret
        }).min().unwrap();
        let max_speed = (v[i] as f64).min((t[i] as f64 + current_speed + target_speed as f64) / 2.); // derived from (time-diff)/2+max
        let goal_speed = max_speed.min(target_speed as f64);
        let accel = max_speed - current_speed;
        let decel = max_speed - goal_speed;
        let keep = t[i] as f64 - accel - decel;
        eprintln!("{} {} {} {} {}", max_speed, goal_speed, accel, keep, decel);
        result += (current_speed + max_speed) * accel / 2. + keep * max_speed + (goal_speed + max_speed) * decel / 2.;
        current_speed = goal_speed;
    }
    writeln!(output, "{:.15}", result).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

