#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();
    let mut tseq = vec![0 as i32; n + 2];
    let mut vseq = vec![0 as i32; n + 2];
    tseq[0] = 1;
    tseq[n + 1] = 1;
    for i in 0..n {
        tseq[i + 1] = read();
    }
    for i in 0..n {
        vseq[i + 1] = read();
    }
    let mut dp = vec![vec![-1e+9 as f32; 101]; 101 * 202];
    dp[0][0] = 0f32;
    let mut t = 0;
    let n = n + 2;
    for i in 0..n {
        for _iter in 0..tseq[i] {
            for v in 0..vseq[i] + 1 {
                for &dv in [-1, 0, 1].iter() {
                    let nv = v + dv;
                    if nv < 0 || vseq[i] < nv {
                        continue;
                    }
                    let mut sum = dp[t][v as usize] + (v + nv) as f32 / 2.0;
                    if dv == 0 && nv < vseq[i] {
                        sum += 0.25;
                    }
                    dp[t + 1][nv as usize] = dp[t + 1][nv as usize].max(sum);
                }
            }
            t += 1;
        }
    }
    println!("{:.8}", dp[t][0]);
}

