fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, t: [usize; n], v: [usize; n]);
    let st: usize = t.iter().sum();
    let mut vt = vec![std::usize::MAX / 10; 2 * st + 1];
    let m = vt.len();
    let mut l = 0;
    for i in 0..n {
        let r = l + 2 * t[i];
        for j in l..=r {
            vt[j] = min(vt[j], 2 * v[i]);
        }
        l = r;
    }
    vt[0] = 0;
    vt[m - 1] = 0;
    for i in 1..vt.len() {
        vt[i] = min(vt[i], vt[i - 1] + 1);
    }
    for i in (0..(vt.len() - 1)).rev() {
        vt[i] = min(vt[i], vt[i + 1] + 1);
    }
    let mut ret = 0;
    for i in 0..(vt.len() - 1) {
        ret += vt[i] + vt[i + 1]
    }
    println!("{}", ret as f64 / 8.);
    for i in 0..vt.len() {
        debug!("{:?}", (i, vt[i])); // DEBUG
    }
}

