use std::f64;
use std::iter::once;

fn main() {
    read_chunk!(_ = (), ts = Vec<f64>, vs = Vec<f64>);
    let t_sum: f64 = ts.iter().sum();
    let t_prefsums: Vec<f64> = ts.iter().copied().lscan1(|&acc, t| acc + t).unwrap().collect();
    let mut intercepts: Vec<f64> = ts.iter().zip(&vs)
        .scan(0.0, |t_acc, (&t, &v)| {
            let res = v + *t_acc;
            *t_acc += t;
            Some(res)
        })
        .chain(once(t_sum))
        .collect();
    intercepts.reverse();
    let mut intercept_mins: Vec<f64> = intercepts.into_iter()
        .lscan(f64::INFINITY, |&acc, x| f64::min(acc, x))
        .collect();
    intercept_mins.pop();
    intercept_mins.reverse();

    let vs: Vec<f64> = iterate(0.5, |&t| t + 0.5)
        .take_while(|&t| t <= t_sum)
        .lscan((0.0, 0), |(v, mut i), t| {
            if t_prefsums[i] < t {
                i += 1;
            }
            let v_max1 = vs[i];
            let v_max2 = intercept_mins[i] - t;
            let v_max3 = v + 0.5;
            (v_max1.min(v_max2).min(v_max3), i)
        })
        .map(|(v, _)| v)
        .collect();
    let xs = vs.windows(2).map(|w| 0.25 * (w[0] + w[1]));
    let ans: f64 = xs.sum();
    println!("{}", ans);
}

