fn main() {
    let n = read::<usize>();
    let ts = read_vec::<i64>();
    let vs = read_vec::<i64>();

    let mut v_limits = vec![0; n];
    for i in (0..n - 1).rev() {
        v_limits[i] = std::cmp::min(vs[i], vs[i + 1]);
        v_limits[i] = std::cmp::min(v_limits[i], v_limits[i + 1] + ts[i + 1]);
    }
    let ts = ts.iter().map(|&x| x as f64).collect::<Vec<_>>();
    let vs = vs.iter().map(|&x| x as f64).collect::<Vec<_>>();
    let v_limits = v_limits.iter().map(|&x| x as f64).collect::<Vec<_>>();
    let mut cur_v = 0.0;
    let mut ans = 0.0;
    for i in 0..n {
        // accel whole span
        if cur_v + ts[i] <= v_limits[i] {
            ans += cur_v * ts[i] + 0.5 * ts[i] * ts[i];
            cur_v += ts[i];
        } else {
            // we need decel
            let cross_t = 0.5 * (v_limits[i] - cur_v + ts[i]);
            let cross_v = cur_v + cross_t;
            if cross_v <= vs[i] as f64 {
                ans += cur_v * cross_t;
                ans += 0.5 * cross_t * cross_t;
                ans += v_limits[i] * (ts[i] - cross_t);
                ans += 0.5 * (ts[i] - cross_t) * (ts[i] - cross_t);
            } else {
                let cross_t1 = vs[i] - cur_v;
                let cross_t2 = ts[i] - (vs[i] - v_limits[i]);
                ans += cross_t1 * cur_v;
                ans += 0.5 * cross_t1 * cross_t1;
                ans += (cross_t2 - cross_t1) * vs[i];
                ans += v_limits[i] * (ts[i] - cross_t2);
                ans += 0.5 * (ts[i] - cross_t2) * (ts[i] - cross_t2);
            }
            cur_v = v_limits[i];
        }
        // println!("{} {}", ans, cur_v);
    }
    println!("{}", ans);
}

