    }
    let mut time = vec![0; N+2];
    for ind in 0..N {
        time[ind+1] = time[ind] + 2*t[ind];
    }
    v.push(0.0);

    let mut max_speed = vec![ vec![0f64; N+2]; time[N]+1];
    for step in 0..N+1 {
        for current_time in 0..time[N]+1 {
            max_speed[current_time][step] =
                if current_time <= time[step] {
                    v[step] + (time[step] - current_time) as f64 * 0.5
                } else if current_time >= time[step+1] {
                    v[step] + (current_time - time[step+1]) as f64 * 0.5
                } else {
                    v[step]
                };
        }
    }

    for current_time in 0..time[N] + 1 {
        max_speed[current_time][N+1] = current_time as f64 * 0.5;
    }

    let mut dist = 0.0;
    let mut current_speed = 0.0 as f64;
    for current_time in 1..time[N]+1 { 
