        for step in 1..N+2 {
            if ms > max_speed[current_time][step] {
                ms = max_speed[current_time][step]
            }
        }
        dist += (current_speed + ms) * 0.5 / 2.0;
        current_speed = ms;
    }
    println!("{:?}", dist);
}

