use std::io::{BufRead, Write};
use std::io;
use std::iter;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let n: usize = buf.trim_right().parse().unwrap();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let t: Vec<usize> = buf.split_whitespace().map(|x| x.parse().unwrap()).chain(iter::once(0)).collect();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let v: Vec<usize> = buf.split_whitespace().map(|x| x.parse().unwrap()).chain(iter::once(0)).collect();
    assert!(n == t.len() - 1 && n == v.len() - 1);
    let mut result = 0.;
    let mut current_speed = 0.;
    for i in 0..n {
        let mut accu = 0;
        let target_speed = (i + 1..n + 1).map(|j| {
            let ret = v[j] + accu;
            accu += t[j];
            ret
        }).min().unwrap();
        let max_speed = (v[i] as f64).min((t[i] as f64 + current_speed + target_speed as f64) / 2.); // derived from (time-diff)/2+max
        let goal_speed = max_speed.min(target_speed as f64);
        let accel = max_speed - current_speed;
        let decel = max_speed - goal_speed;
        let keep = t[i] as f64 - accel - decel;
        assert!(accel >= 0.);
        assert!(decel >= 0.);
        assert!(keep >= 0.);
        result += (current_speed + max_speed) * accel / 2. + keep * max_speed + (goal_speed + max_speed) * decel / 2.;
        current_speed = goal_speed;
    }
    writeln!(output, "{}", result).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

