fn solve() {
    let n = get!(usize);
    let mut t = get!([f64]);
    let mut v = get!([f64]);
    t.insert(0, 0.0);
    t.insert(0, 0.0);
    t.push(0.0);
    v.insert(0, 0.0);
    v.insert(0, 0.0);
    v.push(0.0);

    for i in 0..n+2 {
        t[i+1] += t[i];
    }

    let mut dist = 0.0;
    let mut before = 0.0;
    for i in 0..2*t[n+2] as usize + 1 {
        let now = i as f64 / 2.0;
        let mut mn = std::f64::MAX;
        for j in 0..n+2 {
            let tmp = if now <= t[j] {
                v[j+1]+(t[j]-now)
            } else if now <= t[j+1] {
                v[j+1]
            } else {
                v[j+1]+(now-t[j+1])
            };
            if mn > tmp {
                mn = tmp;
            }
        }
        dist += 0.25*(before+mn);
        before = mn;
    }
    println!("{}", dist);
}
